function addCacheBusterToUrl(value = "") {
  const url = new URL(value);
  url.searchParams.set("_sn_retry", String(Date.now()));
  return url.toString();
}

function isTrustedIsznrRoPdfUrl(value = "", recordId = "") {
  return isTrustedIsznrRecordPdfUrl(value, recordId, "ro");
}

function isTrustedIsznrRecordPdfUrl(value = "", recordId = "", recordKind = "ro") {
  const normalizedRecordId = normalizeInputValue(recordId);
  const normalizedKind = normalizeInputValue(recordKind).toLowerCase() === "fc" ? "fc" : "ro";
  if (!normalizedRecordId) {
    return false;
  }

  try {
    const url = new URL(value);
    const trustedHost = ["isznr.gov.hr", "isznrtest.gov.hr"].includes(url.hostname.toLowerCase());
    const expectedPath = `/record/${normalizedKind}/${encodeURIComponent(normalizedRecordId)}/generate-record`;
    return url.protocol === "https:" && trustedHost && url.pathname === expectedPath;
  } catch {
    return false;
  }
}

function buildIsznrLoginUrlFromPdfUrl(value = "") {
  const url = new URL(value);
  url.pathname = "/login";
  url.search = "";
  url.hash = "";
  return url.toString();
}

function buildIsznrLoginUrlFromRoPdfUrl(value = "") {
  return buildIsznrLoginUrlFromPdfUrl(value);
}

function buildIsznrRoRecordPdfBridgePage({
  recordId = "",
  pdfUrl = "",
  recordKind = "ro",
} = {}) {
  const normalizedKind = normalizeInputValue(recordKind).toLowerCase() === "fc" ? "FC" : "RO";
  const loginUrl = buildIsznrLoginUrlFromPdfUrl(pdfUrl);
  const retryUrl = addCacheBusterToUrl(pdfUrl);
  const safeRecordId = escapeEmailHtml(recordId);
  const safeKind = escapeEmailHtml(normalizedKind);
  const safePdfUrl = escapeEmailHtml(pdfUrl);
  const safeLoginUrl = escapeEmailHtml(loginUrl);
  return `<!doctype html>
<html lang="hr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>IS ZNR ${safeKind} zapisnik ${safeRecordId}</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --card: #ffffff;
      --text: #0f172a;
      --muted: #64748b;
      --line: #dbe7ff;
      --blue: #2563eb;
      --green: #059669;
      --orange: #b45309;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 22px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: radial-gradient(circle at 18% 12%, #dbeafe 0, transparent 32%), var(--bg);
      color: var(--text);
    }
    main {
      width: min(100%, 620px);
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: 24px;
      padding: 26px;
      box-shadow: 0 24px 80px rgba(15, 23, 42, 0.12);
    }
    .badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 7px 12px;
      border-radius: 999px;
      background: #ecfdf5;
      color: var(--green);
      font-size: 13px;
      font-weight: 800;
    }
    h1 { margin: 16px 0 8px; font-size: clamp(30px, 7vw, 42px); line-height: 1.05; letter-spacing: 0; }
    p { margin: 0; color: var(--muted); font-size: 16px; line-height: 1.55; }
    .status {
      margin-top: 20px;
      padding: 16px;
      border: 1px solid #bfdbfe;
      border-radius: 18px;
      background: #eff6ff;
      color: #1e3a8a;
      font-weight: 700;
      line-height: 1.45;
    }
    .countdown {
      display: grid;
      place-items: center;
      width: 96px;
      height: 96px;
      margin: 22px auto 8px;
      border-radius: 50%;
      background: conic-gradient(var(--blue) var(--progress, 100%), #e2e8f0 0);
      color: var(--blue);
      font-size: 34px;
      font-weight: 900;
      box-shadow: inset 0 0 0 10px #ffffff;
    }
    .actions { display: grid; gap: 10px; margin-top: 22px; }
    a.button, button.button {
      min-height: 52px;
      border: 0;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 13px 16px;
      background: var(--blue);
      color: white;
      text-decoration: none;
      font-weight: 850;
      font-size: 16px;
      cursor: pointer;
    }
    a.secondary, button.secondary {
      background: #ffffff;
      color: var(--blue);
      border: 1px solid #bfdbfe;
    }
    .hint {
      margin-top: 16px;
      padding: 12px 14px;
      border-radius: 14px;
      background: #fff7ed;
      color: var(--orange);
      font-size: 14px;
      line-height: 1.45;
    }
    .raw {
      margin-top: 12px;
      overflow-wrap: anywhere;
      font-size: 12px;
      color: #475569;
    }
    iframe { position: fixed; width: 1px; height: 1px; opacity: 0; pointer-events: none; border: 0; }
  </style>
</head>
<body>
  <main>
    <span class="badge">✓ IS ZNR ${safeKind} zapisnik ${safeRecordId}</span>
    <h1>Provjera prijave i preuzimanje</h1>
    <p>Ako već postoji aktivna IS ZNR prijava, zapisnik će se otvoriti ili preuzeti odmah. Ako prijava ne postoji, otvara se IS ZNR prijava i Safe Nexus će pokušati ponovno za 60 sekundi.</p>
    <div id="status" class="status">Pokušavam otvoriti PDF zapisnik...</div>
    <div id="countdown" class="countdown">60</div>
    <div class="actions">
      <button id="retryNow" class="button" type="button">Pokušaj odmah ponovno</button>
      <a id="loginLink" class="button secondary" href="${safeLoginUrl}" target="isznr-ro-record" rel="noopener">Otvori IS ZNR prijavu</a>
      <a class="secondary button" href="${safePdfUrl}" target="isznr-ro-record" rel="noopener">Direktni IS ZNR PDF link</a>
    </div>
    <p class="hint">Ostavi ovu Safe Nexus stranicu otvorenu nakon prijave. Kad se prijaviš u IS ZNR, automatski retry će ponovno zatražiti zapisnik.</p>
    <p class="raw">${safePdfUrl}</p>
  </main>
  <iframe id="probe" title="IS ZNR provjera prijave"></iframe>
  <script>
    const pdfUrl = ${JSON.stringify(pdfUrl)};
    const loginUrl = ${JSON.stringify(loginUrl)};
    const retryUrl = ${JSON.stringify(retryUrl)};
    const statusNode = document.getElementById("status");
    const countdownNode = document.getElementById("countdown");
    const probe = document.getElementById("probe");
    let remaining = 60;
    let attempt = 0;
    let timer = null;

    function withRetry(value) {
      const url = new URL(value);
      url.searchParams.set("_sn_retry", String(Date.now()));
      return url.toString();
    }

    function setStatus(text) {
      statusNode.textContent = text;
    }

    function openTarget(value) {
      const popup = window.open(value, "isznr-ro-record");
      if (!popup) {
        probe.src = withRetry(value);
        return false;
      }
      popup.focus?.();
      return true;
    }

    function tryDownload() {
      attempt += 1;
      const opened = openTarget(attempt === 1 ? pdfUrl : withRetry(pdfUrl));
      setStatus(opened
        ? "Pokušaj " + attempt + ": ako nisi prijavljen, IS ZNR prozor će te odvesti na prijavu. Nakon prijave retry kreće automatski."
        : "Pokušaj " + attempt + ": preglednik je blokirao novi prozor pa pokušavam u pozadini. Ako treba, klikni 'Otvori IS ZNR prijavu'.");
      remaining = 60;
      updateCountdown();
    }

    function updateCountdown() {
      countdownNode.textContent = String(remaining);
      countdownNode.style.setProperty("--progress", Math.max(0, Math.min(100, remaining / 60 * 100)) + "%");
    }

    function tick() {
      remaining -= 1;
      updateCountdown();
      if (remaining <= 0) {
        tryDownload();
      }
    }

    document.getElementById("retryNow").addEventListener("click", tryDownload);
    document.getElementById("loginLink").addEventListener("click", () => {
      setStatus("Otvori IS ZNR prijavu, prijavi se i ostavi ovu stranicu otvorenu. Retry ide automatski.");
    });

    tryDownload();
    timer = window.setInterval(tick, 1000);
  </script>
</body>
</html>`;
}

async function writeAndroidApkDownload(response, {
  contentType = MOBILE_ANDROID_APK_CONTENT_TYPE,
  fileName = MOBILE_ANDROID_APK_PUBLIC_FILE_NAME,
} = {}) {
  const rootApkPath = resolve(rootDir, "assets", "mobile", MOBILE_ANDROID_APK_FILE_NAME);
  const distApkPath = resolve(staticRoot, "assets", "mobile", MOBILE_ANDROID_APK_FILE_NAME);
  const apkPath = existsSync(rootApkPath) ? rootApkPath : distApkPath;
  const apkBuffer = await readFile(apkPath);
  const safeFileName = String(fileName || MOBILE_ANDROID_APK_PUBLIC_FILE_NAME).replace(/"/g, "");
  writeBufferResponse(response, 200, apkBuffer, {
    contentType,
    headers: {
      ...MOBILE_ANDROID_APK_CACHE_HEADERS,
      "Content-Disposition": `attachment; filename="${safeFileName}"; filename*=UTF-8''${encodeURIComponent(safeFileName)}`,
    },
  });
}

function normalizeRiskStructureText(value = "") {
  return String(value ?? "")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\r\n?/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function cleanRiskStructureLine(value = "") {
  return normalizeRiskStructureText(value)
    .replace(/^[•*\-\u2013\u2014]+\s*/, "")
    .replace(/^\d+(?:[.)]|\.\d+)*\s*/, "")
    .replace(/^(organizacijska jedinica|ustrojstvena jedinica|radno mjesto|naziv radnog mjesta|posao)\s*[:\-]\s*/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function getRiskStructureWorkerCount(line = "") {
  const source = String(line || "");
  const labeled = source.match(/\b(\d{1,4})\s*(?:radnika|zaposlenih|izvršitelja|izvrsitelja|osoba)\b/i);
  if (labeled) {
    return labeled[1];
  }
  const trailing = source.match(/\b(?:broj\s*)?(?:radnika|zaposlenih|izvršitelja|izvrsitelja)\s*[:\-]?\s*(\d{1,4})\b/i);
  return trailing?.[1] || "";
}

function getRiskStructureResponsiblePerson(line = "") {
  const match = String(line || "").match(/\b(?:odgovorna osoba|voditelj|rukovoditelj)\s*[:\-]\s*([^;|,\n]{3,80})/i);
  return match?.[1]?.trim() || "";
}

function isRiskStructureLikelyUnit(line = "") {
  const text = cleanRiskStructureLine(line);
  const lower = text.toLocaleLowerCase("hr-HR");
  if (!text || text.length > 90) {
    return false;
  }
  if (/\b(uprava|direkcija|sektor|služba|sluzba|odjel|pogon|proizvodnja|skladište|skladiste|održavanje|odrzavanje|administracija|računovodstvo|racunovodstvo|logistika|prodaja|nabava|laboratorij|kvaliteta|zaštita|zastita)\b/i.test(lower)) {
    return true;
  }
  const letters = text.replace(/[^A-Za-zČĆŽŠĐčćžšđ]/g, "");
  const upper = letters.replace(/[^A-ZČĆŽŠĐ]/g, "");
  return letters.length >= 4 && upper.length / letters.length > 0.76 && text.length <= 60;
}

function isRiskStructureLikelyWorkplace(line = "") {
  const text = cleanRiskStructureLine(line);
  const lower = text.toLocaleLowerCase("hr-HR");
  if (!text || text.length > 110) {
    return false;
  }
  return /\b(radnik|radnica|referent|tajnica|direktor|predsjednik|voditelj|rukovatelj|operater|serviser|skladištar|skladistar|vozač|vozac|monter|tehničar|tehnicar|inženjer|inzenjer|majstor|čistač|cistac|administrator|knjigovođa|knjigovoda)\b/i.test(lower)
    || /\b\d{1,4}\s*(?:radnika|zaposlenih|izvršitelja|izvrsitelja|osoba)\b/i.test(lower);
}

function buildRiskAssessmentStructureUnitsFromText(text = "") {
  const lines = normalizeRiskStructureText(text)
    .split(/\n+/)
    .map(cleanRiskStructureLine)
    .filter((line) => line.length >= 2 && line.length <= 140)
    .filter((line) => !/^(stranica|page|red\.?\s*br|rb\.?|sistematizacija radnih mjesta)$/i.test(line))
    .slice(0, 220);

  const units = [];
  const known = new Set();
  let currentRootId = "";
  let currentParentId = "";

  const addUnit = ({ name = "", type = "unit", parentId = "", sourceLine = "" } = {}) => {
    const cleanName = cleanRiskStructureLine(name).replace(/\s+\d{1,4}\s*(?:radnika|zaposlenih|izvršitelja|izvrsitelja|osoba)\b/i, "").trim();
    if (!cleanName || cleanName.length < 2) {
      return null;
    }
    const key = `${parentId}:${type}:${cleanName.toLocaleLowerCase("hr-HR")}`;
    if (known.has(key)) {
      return units.find((unit) => `${unit.parentId}:${unit.type}:${unit.name.toLocaleLowerCase("hr-HR")}` === key) || null;
    }
    known.add(key);
    const unit = {
      id: randomUUID(),
      parentId,
      type,
      name: cleanName.slice(0, 120),
      responsiblePerson: getRiskStructureResponsiblePerson(sourceLine),
      workerCount: getRiskStructureWorkerCount(sourceLine),
      shortDescription: "",
      description: "",
      detailedDescription: "",
      note: sourceLine && sourceLine !== cleanName ? `Prepoznato iz dokumenta: ${sourceLine.slice(0, 240)}` : "",
    };
    units.push(unit);
    return unit;
  };

  for (const line of lines) {
    if (units.length >= 80) {
      break;
    }
    const lower = line.toLocaleLowerCase("hr-HR");
    if (isRiskStructureLikelyUnit(line) && !isRiskStructureLikelyWorkplace(line)) {
      const isSubunit = Boolean(currentRootId) && /\b(odjel|služba|sluzba|tim|grupa|radionica)\b/i.test(lower);
      const unit = addUnit({
        name: line,
        type: isSubunit ? "subunit" : "unit",
        parentId: isSubunit ? currentRootId : "",
        sourceLine: line,
      });
      if (unit) {
        if (isSubunit) {
          currentParentId = unit.id;
        } else {
          currentRootId = unit.id;
          currentParentId = unit.id;
        }
      }
      continue;
    }
    if (isRiskStructureLikelyWorkplace(line)) {
      const unit = addUnit({
        name: line.replace(/\b(?:broj\s*)?(?:radnika|zaposlenih|izvršitelja|izvrsitelja)\s*[:\-]?\s*\d{1,4}\b/gi, "").trim(),
        type: "workplace",
        parentId: currentParentId || currentRootId || "",
        sourceLine: line,
      });
      if (unit && !currentParentId && !currentRootId) {
        currentRootId = unit.id;
      }
    }
  }

  return units;
}
const requestUserSymbol = Symbol("requestUser");
