function normalizeEnvBoolean(value, fallback = false) {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (!normalized) {
    return fallback;
  }
  if (["1", "true", "yes", "on"].includes(normalized)) {
    return true;
  }
  if (["0", "false", "no", "off"].includes(normalized)) {
    return false;
  }
  return fallback;
}

function getOpenAiRuntimeConfig() {
  const apiBaseUrl = String(process.env.OPENAI_API_BASE_URL || OPENAI_DEFAULT_API_BASE_URL).trim().replace(/\/+$/, "");
  const dryRun = normalizeEnvBoolean(process.env.OPENAI_DRY_RUN, true);
  const liveCallsEnabled = normalizeEnvBoolean(process.env.OPENAI_ENABLE_LIVE_CALLS, false) && !dryRun;

  return {
    provider: "openai",
    keyConfigured: Boolean(String(process.env.OPENAI_API_KEY || "").trim()),
    dryRun,
    liveCallsEnabled,
    apiBaseUrl,
    endpoint: `${apiBaseUrl}${OPENAI_RESPONSES_PATH}`,
    model: String(process.env.OPENAI_MODEL || "").trim(),
  };
}

function normalizeOpenAiModelTier(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return OPENAI_MODEL_TIERS.some((option) => option.value === normalized) ? normalized : "standard";
}

function getOpenAiModelTierOption(value = "") {
  const normalized = normalizeOpenAiModelTier(value);
  return OPENAI_MODEL_TIERS.find((option) => option.value === normalized) || OPENAI_MODEL_TIERS[1];
}

function normalizeOpenAiModelSlug(value = "") {
  const normalized = String(value || "").trim();
  return OPENAI_MODEL_SLUG_REPLACEMENTS[normalized] || normalized;
}

function getOpenAiModelForTier(tier = "standard", config = getOpenAiRuntimeConfig()) {
  const option = getOpenAiModelTierOption(tier);
  return normalizeOpenAiModelSlug(process.env[option.env] || config.model || OPENAI_DEFAULT_MODEL_BY_TIER[option.value] || "");
}

function buildOpenAiModelTierPayload(config = getOpenAiRuntimeConfig()) {
  return OPENAI_MODEL_TIERS.map((option) => ({
    value: option.value,
    label: option.label,
    strength: option.strength,
    modelConfigured: Boolean(getOpenAiModelForTier(option.value, config)),
  }));
}

function buildOpenAiStatusPayload() {
  const config = getOpenAiRuntimeConfig();
  return {
    ok: true,
    provider: config.provider,
    keyConfigured: config.keyConfigured,
    dryRun: config.dryRun,
    liveCallsEnabled: config.liveCallsEnabled,
    endpointReady: config.keyConfigured && (config.dryRun || config.liveCallsEnabled),
    model: normalizeOpenAiModelSlug(config.model || OPENAI_DEFAULT_MODEL_BY_TIER.standard),
    modelTiers: buildOpenAiModelTierPayload(config),
    endpoint: config.endpoint,
    tokenSpend: config.liveCallsEnabled ? "enabled" : "disabled",
  };
}

function getOpenWeatherRuntimeConfig() {
  const apiBaseUrl = String(process.env.OPENWEATHER_API_BASE_URL || OPENWEATHER_DEFAULT_API_BASE_URL)
    .trim()
    .replace(/\/+$/, "");
  const geoBaseUrl = String(process.env.OPENWEATHER_GEO_BASE_URL || OPENWEATHER_DEFAULT_GEO_BASE_URL)
    .trim()
    .replace(/\/+$/, "");
  const apiKey = String(process.env.OPENWEATHER_API_KEY || "").trim();
  return {
    apiBaseUrl,
    geoBaseUrl,
    apiKey,
    keyConfigured: Boolean(apiKey),
  };
}

function normalizeOpenWeatherCityName(value = "") {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, 80);
}

function parseOpenWeatherGeoCityToken(value = "") {
  const normalized = normalizeOpenWeatherCityName(value);
  const match = normalized.match(/^geo:([-+]?\d+(?:\.\d+)?),([-+]?\d+(?:\.\d+)?)(?::(.+))?$/i);
  if (!match) {
    return null;
  }
  const lat = Number(match[1]);
  const lon = Number(match[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    return null;
  }
  return {
    lat,
    lon,
    label: normalizeOpenWeatherCityName(match[3] || ""),
    query: normalized,
  };
}

function getOpenWeatherRequestedCities(url) {
  const repeatedCities = url.searchParams.getAll("city");
  const packedCities = String(url.searchParams.get("cities") || "")
    .split("|")
    .map((item) => item.trim());
  const seen = new Set();
  return [...repeatedCities, ...packedCities]
    .map(normalizeOpenWeatherCityName)
    .filter((city) => {
      const key = city.toLowerCase();
      if (!city || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, OPENWEATHER_MAX_CITIES);
}

function titleCaseOpenWeatherDescription(value = "") {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  return `${text.charAt(0).toUpperCase()}${text.slice(1)}`;
}

function getOpenWeatherCondition(weather = {}) {
  const weatherId = Number(weather.id);
  const main = String(weather.main || "").trim().toLowerCase();
  if (weatherId >= 200 && weatherId < 300) return "thunderstorm";
  if (weatherId >= 300 && weatherId < 400) return "drizzle";
  if (weatherId >= 500 && weatherId < 600) return "rain";
  if (weatherId >= 600 && weatherId < 700) return "snow";
  if (weatherId >= 700 && weatherId < 800) return main || "mist";
  if (weatherId === 800 || main === "clear") return "clear";
  if (weatherId > 800 || main === "clouds") return "clouds";
  return main || "clear";
}

function isOpenWeatherNightIcon(icon = "") {
  return String(icon || "").trim().toLowerCase().endsWith("n");
}

function isOpenWeatherCurrentNight(payload = {}, weather = {}) {
  const icon = String(weather?.icon || "").trim();
  if (icon) {
    return isOpenWeatherNightIcon(icon);
  }

  const observedAt = Number(payload.dt ?? 0);
  const sunrise = Number(payload.sys?.sunrise ?? 0);
  const sunset = Number(payload.sys?.sunset ?? 0);
  if (observedAt && sunrise && sunset) {
    return observedAt < sunrise || observedAt >= sunset;
  }

  return false;
}

function buildOpenWeatherUrl(path, params = {}) {
  const config = getOpenWeatherRuntimeConfig();
  const url = new URL(`${config.apiBaseUrl}${path}`);
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") {
      url.searchParams.set(key, String(value));
    }
  });
  url.searchParams.set("appid", config.apiKey);
  url.searchParams.set("units", "metric");
  url.searchParams.set("lang", "hr");
  return url;
}

function buildOpenWeatherGeoUrl(path, params = {}) {
  const config = getOpenWeatherRuntimeConfig();
  const url = new URL(`${config.geoBaseUrl}${path}`);
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") {
      url.searchParams.set(key, String(value));
    }
  });
  url.searchParams.set("appid", config.apiKey);
  return url;
}

async function fetchOpenWeatherJson(url) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), OPENWEATHER_TIMEOUT_MS);
  try {
    const result = await fetch(url, {
      headers: { accept: "application/json" },
      signal: controller.signal,
    });
    const responseText = await result.text();
    let payload = null;
    if (responseText) {
      try {
        payload = JSON.parse(responseText);
      } catch {
        payload = null;
      }
    }

    if (!result.ok) {
      const error = new Error(payload?.message || "OpenWeather poziv nije uspio.");
      error.statusCode = result.status === 401 ? 503 : result.status || 502;
      throw error;
    }

    return payload || {};
  } catch (error) {
    if (error?.name === "AbortError") {
      const timeoutError = new Error("OpenWeather se nije javio na vrijeme.");
      timeoutError.statusCode = 504;
      throw timeoutError;
    }
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

function createRequestError(statusCode = 400, message = "Request failed.") {
  const error = new Error(message);
  error.statusCode = statusCode;
  return error;
}

function normalizeIsznrApiBaseUrl(value = "") {
  const raw = String(value ?? "").trim().replace(/\/+$/, "");
  const candidate = raw || ISZNR_DEFAULT_API_BASE_URL;
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(candidate)
    ? candidate
    : `https://${candidate}`;

  let parsed;
  try {
    parsed = new URL(withProtocol);
  } catch {
    throw createRequestError(400, "ISZNR API URL nije ispravan.");
  }

  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw createRequestError(400, "ISZNR API URL mora koristiti http ili https.");
  }

  return parsed.toString().replace(/\/+$/, "");
}

function normalizeIsznrApiUsername(value = "") {
  return String(value ?? "").trim().replace(/\s+/g, "");
}

function buildIsznrResourceUrl(baseUrl = "", resourcePath = "") {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const resourceParts = String(resourcePath || "")
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);
  const url = new URL(normalizedBaseUrl);

  if (resourceParts.length === 0) {
    return url;
  }

  const baseParts = url.pathname
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);
  const lowerBaseParts = baseParts.map((part) => part.toLowerCase());
  const lowerResourceParts = resourceParts.map((part) => part.toLowerCase());
  const alreadyTargetsResource = lowerResourceParts.every((part, index) => {
    const offset = lowerBaseParts.length - lowerResourceParts.length + index;
    return offset >= 0 && lowerBaseParts[offset] === part;
  });

  if (!alreadyTargetsResource) {
    url.pathname = `/${[...baseParts, ...resourceParts].join("/")}`;
  }

  return url;
}

function normalizeIsznrOib(value = "") {
  return String(value ?? "").replace(/\D/g, "");
}

function createIsznrRequestHeaders(username = "", password = "") {
  return {
    accept: "application/ld+json, application/json",
    authorization: createIsznrBasicAuthHeader(username, password),
  };
}

function getIsznrDisplayPath(url) {
  if (!(url instanceof URL)) {
    return "";
  }
  return `${url.pathname}${url.search}`.replace(/^\/api\/v3\/?/, "/");
}

function parseIsznrJsonPayload(text = "") {
  if (!String(text || "").trim()) {
    return null;
  }
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

async function fetchIsznrResourceProbe({
  baseUrl = "",
  username = "",
  password = "",
  resourcePath = "",
  searchParams = {},
  timeoutMs = ISZNR_RESOURCE_TEST_TIMEOUT_MS,
  parseJson = false,
} = {}) {
  const requestUrl = buildIsznrResourceUrl(baseUrl, resourcePath);
  Object.entries(searchParams || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") {
      requestUrl.searchParams.set(key, String(value));
    }
  });

  try {
    const result = await requestIsznrText(requestUrl, {
      headers: {
        ...createIsznrRequestHeaders(username, password),
        "user-agent": "SafeNexus/1.0",
      },
      preferIpv4: true,
      timeoutMs,
    });
    const responseText = result.text || "";
    const payload = parseJson ? parseIsznrJsonPayload(responseText) : null;
    return {
      ok: result.ok,
      status: result.status,
      contentType: getResponseHeaderValue(result.headers, "content-type"),
      path: getIsznrDisplayPath(requestUrl),
      transport: result.transport || "",
      payload,
      responseText: responseText.slice(0, 1000),
    };
  } catch (error) {
    const timeoutError = isNetworkTimeoutError(error);
    return {
      ok: false,
      status: 0,
      contentType: "",
      path: getIsznrDisplayPath(requestUrl),
      errorCode: timeoutError ? "timeout" : "network",
      message: timeoutError
        ? "ISZNR API se nije javio na vrijeme."
        : "ISZNR API nije dostupan s poslužitelja.",
    };
  }
}

function isIsznrAuthFailure(probe = {}) {
  return probe?.status === 401 || probe?.status === 403;
}

function isIsznrResourceActive(probe = {}, resource = {}) {
  if (probe?.ok) {
    return true;
  }
  if (resource.acceptsClientError && [400, 422].includes(Number(probe?.status))) {
    return true;
  }
  return false;
}

function getIsznrResourceProbeMessage(probe = {}, resource = {}) {
  if (probe?.ok) {
    return `Dostupno (${probe.status})`;
  }
  if (resource.acceptsClientError && [400, 422].includes(Number(probe?.status))) {
    return `Endpoint postoji, ali traži dokumentirani filter (${probe.status})`;
  }
  if (isIsznrAuthFailure(probe)) {
    return `Autentikacija nije prošla (${probe.status})`;
  }
  if (probe?.errorCode === "timeout") {
    return "Timeout";
  }
  if (probe?.errorCode === "network") {
    return "Nedostupno s poslužitelja";
  }
  return probe?.status ? `Odgovor ${probe.status}` : "Nema odgovora";
}

function getIsznrResourceSearchParams(resource = {}, context = {}) {
  if (resource.path === "companies" && context.organizationOib) {
    return { oib: context.organizationOib };
  }
  return {};
}

async function mapIsznrWithConcurrency(items = [], limit = 6, worker = async () => null) {
  const results = new Array(items.length);
  let cursor = 0;
  const workerCount = Math.min(Math.max(1, Number(limit) || 1), items.length || 1);
  await Promise.all(Array.from({ length: workerCount }, async () => {
    while (cursor < items.length) {
      const index = cursor;
      cursor += 1;
      results[index] = await worker(items[index], index);
    }
  }));
  return results;
}

function normalizeIsznrAuthorizedCompanyRecord(source = {}) {
  if (!source || typeof source !== "object") {
    return null;
  }
  return {
    id: String(pickIsznrValue(source, ["id"]) || extractIsznrId(source) || "").trim(),
    oib: normalizeIsznrOib(pickIsznrValue(source, ["oib", "OIB"])),
    internationalIdentifier: String(pickIsznrValue(source, ["internationalIdentifier"]) || "").trim(),
    name: String(pickIsznrValue(source, ["name", "title", "naziv"]) || "").trim(),
  };
}

function findIsznrAuthorizedCompanyByOib(payload = {}, expectedOib = "") {
  const normalizedOib = normalizeIsznrOib(expectedOib);
  if (!normalizedOib) {
    return null;
  }
  return getIsznrPayloadArray(payload)
    .map((item) => normalizeIsznrAuthorizedCompanyRecord(item))
    .find((item) => item?.oib === normalizedOib)
    || null;
}

function summarizeIsznrAuthorizedCompanyProbe({ id = "", expectedOib = "", byIdProbe = null, byOibProbe = null } = {}) {
  const byIdRecord = normalizeIsznrAuthorizedCompanyRecord(byIdProbe?.payload);
  const matchedByOib = byOibProbe?.ok ? findIsznrAuthorizedCompanyByOib(byOibProbe.payload, expectedOib) : null;
  const byIdOibMatches = Boolean(expectedOib && byIdRecord?.oib && byIdRecord.oib === expectedOib);
  const resolvedId = matchedByOib?.id || byIdRecord?.id || id;

  return {
    id: resolvedId,
    requestedId: id,
    expectedOib,
    resolvedRecord: matchedByOib || byIdRecord || null,
    byId: byIdProbe
      ? {
        ok: Boolean(byIdProbe.ok),
        status: byIdProbe.status,
        path: byIdProbe.path,
        record: byIdRecord,
        oibMatches: byIdOibMatches,
        message: byIdProbe.ok
          ? (expectedOib
            ? (byIdOibMatches ? "ID dohvat radi i OIB odgovara." : "ID dohvat radi, ali OIB ne odgovara očekivanom OIB-u.")
            : "ID dohvat radi.")
          : getIsznrResourceProbeMessage(byIdProbe),
      }
      : null,
    byOib: expectedOib
      ? {
        ok: Boolean(byOibProbe?.ok && matchedByOib),
        status: byOibProbe?.status ?? 0,
        path: byOibProbe?.path || "/authorized_companies",
        record: matchedByOib || null,
        message: byOibProbe?.ok
          ? (matchedByOib
            ? "OIB je pronađen filtriranjem kolekcije ovlaštenih osoba."
            : "Kolekcija je dohvaćena, ali OIB nije pronađen među dostupnim ovlaštenim osobama.")
          : getIsznrResourceProbeMessage(byOibProbe),
      }
      : null,
  };
}

async function testIsznrAuthorizedCompanyProbe({
  baseUrl = "",
  username = "",
  password = "",
  authorizedCompanyId = ISZNR_AUTHORIZED_COMPANY_PROBE_ID,
  authorizedCompanyOib = "",
} = {}) {
  const id = String(authorizedCompanyId || "").replace(/[^\d]/g, "");
  const expectedOib = normalizeIsznrOib(authorizedCompanyOib);
  const byOibProbe = expectedOib
    ? await fetchIsznrResourceProbe({
      baseUrl,
      username,
      password,
      resourcePath: "authorized_companies",
      timeoutMs: ISZNR_TEST_TIMEOUT_MS,
      parseJson: true,
    })
    : null;
  const matchedByOib = byOibProbe?.ok ? findIsznrAuthorizedCompanyByOib(byOibProbe.payload, expectedOib) : null;
  const resolvedId = String(matchedByOib?.id || id || "").replace(/[^\d]/g, "");
  const byIdProbe = resolvedId
    ? await fetchIsznrResourceProbe({
      baseUrl,
      username,
      password,
      resourcePath: `authorized_companies/${resolvedId}`,
      timeoutMs: ISZNR_TEST_TIMEOUT_MS,
      parseJson: true,
    })
    : null;

  return summarizeIsznrAuthorizedCompanyProbe({
    id: resolvedId,
    expectedOib,
    byIdProbe,
    byOibProbe,
  });
}

async function testIsznrApiConnection({
  baseUrl = "",
  username = "",
  password = "",
  organizationOib = "",
  authorizedCompanyId = ISZNR_AUTHORIZED_COMPANY_PROBE_ID,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");
  const normalizedOrganizationOib = normalizeIsznrOib(organizationOib);

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "Upiši ISZNR lozinku ili prvo spremi postojeću lozinku u Settings.");
  }

  const authorizedCompany = await testIsznrAuthorizedCompanyProbe({
    baseUrl: normalizedBaseUrl,
    username: normalizedUsername,
    password: safePassword,
    authorizedCompanyId,
    authorizedCompanyOib: normalizedOrganizationOib,
  });
  const authProbe = authorizedCompany?.byOib || authorizedCompany?.byId;
  if (isIsznrAuthFailure(authProbe)) {
    throw createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
  }
  if (authProbe?.status === 0) {
    throw createRequestError(
      authProbe?.message === "Timeout" ? 504 : 502,
      authProbe?.message === "Timeout"
        ? "ISZNR API se nije javio na vrijeme."
        : "ISZNR API nije dostupan s poslužitelja.",
    );
  }

  const context = {
    organizationOib: normalizedOrganizationOib,
  };
  const connectionTestResources = ISZNR_DOCUMENTED_GET_RESOURCES.filter((resource) => (
    ISZNR_CONNECTION_TEST_RESOURCE_PATHS.has(resource.path)
  ));
  const resources = await mapIsznrWithConcurrency(
    connectionTestResources,
    ISZNR_RESOURCE_TEST_CONCURRENCY,
    async (resource) => {
      const probe = await fetchIsznrResourceProbe({
        baseUrl: normalizedBaseUrl,
        username: normalizedUsername,
        password: safePassword,
        resourcePath: resource.path,
        searchParams: getIsznrResourceSearchParams(resource, context),
        timeoutMs: Math.min(ISZNR_RESOURCE_TEST_TIMEOUT_MS, 2500),
      });
      return {
        group: resource.group,
        label: resource.label,
        path: probe.path || `/${resource.path}`,
        status: probe.status,
        contentType: probe.contentType,
        active: isIsznrResourceActive(probe, resource),
        authFailure: isIsznrAuthFailure(probe),
        message: getIsznrResourceProbeMessage(probe, resource),
      };
    },
  );

  if (resources.some((item) => item.authFailure)) {
    throw createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
  }

  const activeCount = resources.filter((item) => item.active).length;
  const failedCount = resources.length - activeCount;
  const criticalResourcePaths = new Set(["/authorized_companies", "/instruments"]);
  const criticalFailures = resources.filter((item) => (
    criticalResourcePaths.has(String(item.path || "").split("?")[0])
    && !item.active
  ));
  const connectionOk = criticalFailures.length === 0;
  const groups = resources.reduce((accumulator, item) => {
    if (!accumulator[item.group]) {
      accumulator[item.group] = {
        group: item.group,
        total: 0,
        active: 0,
        failed: 0,
      };
    }
    accumulator[item.group].total += 1;
    if (item.active) {
      accumulator[item.group].active += 1;
    } else {
      accumulator[item.group].failed += 1;
    }
    return accumulator;
  }, {});

  return {
    ok: connectionOk,
    status: authProbe?.status || (failedCount === 0 ? 200 : 207),
    baseUrl: normalizedBaseUrl,
    checkedAt: new Date().toISOString(),
    authorizedCompany,
    summary: {
      total: resources.length,
      active: activeCount,
      failed: failedCount,
      groups: Object.values(groups),
    },
    resources,
    message: !connectionOk
      ? "ISZNR prijava radi, ali ključni resursi za SafeNexus nisu dostupni."
      : failedCount === 0
        ? `ISZNR API radi. Aktivno je ${activeCount}/${resources.length} ključnih GET resursa.`
        : `ISZNR API veza radi. ${failedCount}/${resources.length} ključnih GET resursa nije prošlo detaljni test.`,
  };

}

function createIsznrBasicAuthHeader(username = "", password = "") {
  return `Basic ${Buffer.from(`${normalizeIsznrApiUsername(username)}:${String(password ?? "")}`, "utf8").toString("base64")}`;
}

function getResponseHeaderValue(headers, name = "") {
  if (!headers || !name) {
    return "";
  }
  if (typeof headers.get === "function") {
    return String(headers.get(name) || "").trim();
  }
  return String(headers[String(name).toLowerCase()] || headers[name] || "").trim();
}

function isNetworkTimeoutError(error = {}) {
  return error?.name === "AbortError"
    || error?.code === "ETIMEDOUT"
    || error?.code === "UND_ERR_CONNECT_TIMEOUT"
    || error?.cause?.code === "ETIMEDOUT"
    || error?.cause?.code === "UND_ERR_CONNECT_TIMEOUT";
}

function summarizeNetworkError(error = {}) {
  return {
    name: error?.name || "",
    code: error?.code || error?.cause?.code || "",
    message: error?.message || error?.cause?.message || "",
  };
}

function requestTextWithHttpsIpv4(requestUrl, {
  method = "GET",
  headers = {},
  body = null,
  timeoutMs = ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
} = {}) {
  return new Promise((resolveRequest, rejectRequest) => {
    const bodyText = body === null || body === undefined ? null : String(body);
    const requestOptions = {
      method: String(method || "GET").toUpperCase(),
      headers: bodyText
        ? {
          ...headers,
          "content-length": Buffer.byteLength(bodyText),
        }
        : headers,
      timeout: timeoutMs,
      lookup(hostname, options, callback) {
        dnsLookup(hostname, { ...options, family: 4 }, callback);
      },
    };
    const clientRequest = httpsRequest(requestUrl, requestOptions, (clientResponse) => {
      const chunks = [];
      clientResponse.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
      clientResponse.on("end", () => {
        const status = Number(clientResponse.statusCode || 0);
        resolveRequest({
          ok: status >= 200 && status < 300,
          status,
          headers: clientResponse.headers || {},
          text: Buffer.concat(chunks).toString("utf8"),
          transport: "https-ipv4",
        });
      });
    });
    clientRequest.on("timeout", () => {
      const timeoutError = new Error("ISZNR HTTPS IPv4 request timed out.");
      timeoutError.code = "ETIMEDOUT";
      clientRequest.destroy(timeoutError);
    });
    clientRequest.on("error", rejectRequest);
    if (bodyText) {
      clientRequest.write(bodyText);
    }
    clientRequest.end();
  });
}

function requestBufferWithHttpsIpv4(requestUrl, {
  method = "GET",
  headers = {},
  body = null,
  timeoutMs = ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
} = {}) {
  return new Promise((resolveRequest, rejectRequest) => {
    const bodyBuffer = Buffer.isBuffer(body)
      ? body
      : (body === null || body === undefined ? null : Buffer.from(String(body), "utf8"));
    const requestOptions = {
      method: String(method || "GET").toUpperCase(),
      headers: bodyBuffer
        ? {
          ...headers,
          "content-length": bodyBuffer.length,
        }
        : headers,
      timeout: timeoutMs,
      lookup(hostname, options, callback) {
        dnsLookup(hostname, { ...options, family: 4 }, callback);
      },
    };
    const clientRequest = httpsRequest(requestUrl, requestOptions, (clientResponse) => {
      const chunks = [];
      clientResponse.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
      clientResponse.on("end", () => {
        const status = Number(clientResponse.statusCode || 0);
        resolveRequest({
          ok: status >= 200 && status < 300,
          status,
          headers: clientResponse.headers || {},
          buffer: Buffer.concat(chunks),
          transport: "https-ipv4",
        });
      });
    });
    clientRequest.on("timeout", () => {
      const timeoutError = new Error("ISZNR HTTPS IPv4 binary request timed out.");
      timeoutError.code = "ETIMEDOUT";
      clientRequest.destroy(timeoutError);
    });
    clientRequest.on("error", rejectRequest);
    if (bodyBuffer) {
      clientRequest.write(bodyBuffer);
    }
    clientRequest.end();
  });
}

async function requestIsznrText(requestUrl, {
  method = "GET",
  headers = {},
  body = null,
  timeoutMs = ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
  preferIpv4 = false,
} = {}) {
  if (preferIpv4 && requestUrl?.protocol === "https:") {
    return requestTextWithHttpsIpv4(requestUrl, { method, headers, body, timeoutMs });
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const result = await fetch(requestUrl, {
      method: String(method || "GET").toUpperCase(),
      headers,
      body: body === null || body === undefined ? undefined : String(body),
      signal: controller.signal,
    });
    const text = await result.text().catch(() => "");
    return {
      ok: result.ok,
      status: result.status,
      headers: result.headers,
      text,
      transport: "fetch",
    };
  } catch (fetchError) {
    try {
      return await requestTextWithHttpsIpv4(requestUrl, { method, headers, body, timeoutMs });
    } catch (fallbackError) {
      console.warn("[isznr] request failed", {
        path: requestUrl.pathname,
        search: requestUrl.search,
        fetchError: summarizeNetworkError(fetchError),
        fallbackError: summarizeNetworkError(fallbackError),
      });
      throw isNetworkTimeoutError(fetchError) ? fetchError : fallbackError;
    }
  } finally {
    clearTimeout(timeout);
  }
}

async function requestIsznrBuffer(requestUrl, {
  method = "GET",
  headers = {},
  body = null,
  timeoutMs = ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
  preferIpv4 = false,
} = {}) {
  if (preferIpv4 && requestUrl?.protocol === "https:") {
    return requestBufferWithHttpsIpv4(requestUrl, { method, headers, body, timeoutMs });
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const result = await fetch(requestUrl, {
      method: String(method || "GET").toUpperCase(),
      headers,
      body: body === null || body === undefined ? undefined : body,
      signal: controller.signal,
    });
    const buffer = Buffer.from(await result.arrayBuffer().catch(() => new ArrayBuffer(0)));
    return {
      ok: result.ok,
      status: result.status,
      headers: result.headers,
      buffer,
      transport: "fetch",
    };
  } catch (fetchError) {
    try {
      return await requestBufferWithHttpsIpv4(requestUrl, { method, headers, body, timeoutMs });
    } catch (fallbackError) {
      console.warn("[isznr] binary request failed", {
        path: requestUrl.pathname,
        search: requestUrl.search,
        fetchError: summarizeNetworkError(fetchError),
        fallbackError: summarizeNetworkError(fallbackError),
      });
      throw isNetworkTimeoutError(fetchError) ? fetchError : fallbackError;
    }
  } finally {
    clearTimeout(timeout);
  }
}

function getIsznrPayloadArray(payload = {}) {
  if (Array.isArray(payload)) {
    return payload;
  }
  if (!payload || typeof payload !== "object") {
    return [];
  }

  const candidates = [
    payload["hydra:member"],
    payload.member,
    payload.members,
    payload.items,
    payload.results,
    payload.data,
    payload.content,
  ];
  for (const candidate of candidates) {
    if (Array.isArray(candidate)) {
      return candidate;
    }
  }
  return [];
}

function getIsznrPayloadTotal(payload = {}) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return null;
  }
  const value = payload["hydra:totalItems"]
    ?? payload.totalItems
    ?? payload.total
    ?? payload.count
    ?? payload.pagination?.totalItems
    ?? null;
  const total = Number(value);
  return Number.isFinite(total) ? total : null;
}

function pickIsznrValue(source = {}, keys = []) {
  if (!source || typeof source !== "object") {
    return "";
  }
  for (const key of keys) {
    if (source[key] !== undefined && source[key] !== null && source[key] !== "") {
      return source[key];
    }
  }
  return "";
}

function extractIsznrId(source = {}) {
  const directId = pickIsznrValue(source, ["id", "instrumentId", "instrumentID"]);
  if (directId !== "") {
    return String(directId).trim();
  }
  const iri = String(source?.["@id"] || source?.iri || source?.url || "").trim();
  const match = iri.match(/\/([^/]+)$/);
  return match ? match[1] : "";
}

function normalizeIsznrInstrumentRecord(source = {}) {
  const attributes = source?.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record);
  return {
    id,
    isznrId: id,
    name: String(pickIsznrValue(record, ["name", "title", "naziv"]) || "").trim(),
    serialNumber: String(pickIsznrValue(record, ["serialNumber", "serial", "serijskiBroj"]) || "").trim(),
    measurementDateFrom: String(pickIsznrValue(record, ["measurementDateFrom", "measurementFrom", "datumUmjeravanjaOd"]) || "").trim(),
    measurementDateTo: String(pickIsznrValue(record, ["measurementDateTo", "measurementTo", "datumUmjeravanjaDo"]) || "").trim(),
    removed: String(pickIsznrValue(record, ["removed", "removedAt", "rashodovano"]) || "").trim(),
  };
}

function getMeasurementEquipmentIsznrInstrumentId(item = {}) {
  return normalizeInputValue(item?.isznrInstrumentId || item?.isznrId || item?.externalIsznrId);
}

function normalizeIsznrInstrumentImportItems(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : [])
    .map((item) => normalizeIsznrInstrumentRecord(item))
    .filter((item) => item.isznrId || item.serialNumber || item.name)
    .filter((item) => {
      const key = [
        normalizeInputValue(item.isznrId),
        normalizeInputValue(item.serialNumber),
        normalizeInputValue(item.name),
      ].join("|").toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, ISZNR_MOBILE_INSTRUMENT_MAX_RECORDS);
}

function dedupeIsznrInstrumentRecords(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : [])
    .map((item) => normalizeIsznrInstrumentRecord(item))
    .filter((item) => item.isznrId || item.serialNumber || item.name)
    .filter((item) => {
      const key = [
        normalizeInputValue(item.isznrId || item.id),
        normalizeInputValue(item.serialNumber),
        normalizeInputValue(item.name),
      ].join("|").toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function findMeasurementEquipmentForIsznrInstrument(localItems = [], isznrItem = {}) {
  const isznrId = normalizeInputValue(isznrItem.isznrId || isznrItem.id).toLowerCase();
  const serialNumber = normalizeInputValue(isznrItem.serialNumber).toLowerCase();
  const name = normalizeInputValue(isznrItem.name).toLowerCase();

  return localItems.find((item) => (
    isznrId && getMeasurementEquipmentIsznrInstrumentId(item).toLowerCase() === isznrId
  )) || localItems.find((item) => (
    serialNumber && normalizeInputValue(item?.serialNumber).toLowerCase() === serialNumber
  )) || localItems.find((item) => (
    name && normalizeInputValue(item?.name).toLowerCase() === name
  )) || null;
}

function mergeMeasurementEquipmentNoteLines(...values) {
  const seen = new Set();
  const lines = [];
  values
    .flatMap((value) => normalizeInputValue(value).split(/\r?\n/g))
    .map((value) => normalizeInputValue(value))
    .filter(Boolean)
    .forEach((line) => {
      const key = line.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        lines.push(line);
      }
    });
  return lines.join("\n");
}

function buildMeasurementEquipmentPayloadFromIsznrInstrument(isznrItem = {}, {
  organizationId = "",
  current = null,
  nowValue = new Date().toISOString(),
} = {}) {
  const isznrInstrumentId = normalizeInputValue(isznrItem.isznrId || isznrItem.id);
  const name = normalizeInputValue(isznrItem.name) || (isznrInstrumentId ? `ISZNR oprema ${isznrInstrumentId}` : "ISZNR mjerna oprema");
  const calibrationDate = normalizeInputValue(isznrItem.measurementDateFrom).slice(0, 10);
  const validUntil = normalizeInputValue(isznrItem.measurementDateTo).slice(0, 10);
  const hasCalibration = Boolean(calibrationDate || validUntil || current?.requiresCalibration);
  const isznrNote = isznrInstrumentId ? `ISZNR ID: ${isznrInstrumentId}` : "";
  const removedNote = normalizeInputValue(isznrItem.removed)
    ? `ISZNR rashodovano: ${normalizeInputValue(isznrItem.removed).slice(0, 10)}`
    : "";

  return {
    organizationId: normalizeInputValue(current?.organizationId || organizationId),
    name: normalizeInputValue(current?.name) || name,
    equipmentKind: normalizeInputValue(current?.equipmentKind) || "combined",
    manufacturer: normalizeInputValue(current?.manufacturer),
    deviceType: normalizeInputValue(current?.deviceType),
    deviceCode: normalizeInputValue(current?.deviceCode),
    serialNumber: normalizeInputValue(current?.serialNumber) || normalizeInputValue(isznrItem.serialNumber),
    inventoryNumber: normalizeInputValue(current?.inventoryNumber),
    isznrInstrumentId,
    isznrSyncedAt: nowValue,
    enteredBy: normalizeInputValue(current?.enteredBy),
    approvedBy: normalizeInputValue(current?.approvedBy),
    entryDate: normalizeInputValue(current?.entryDate),
    requiresCalibration: hasCalibration,
    calibrationDate: normalizeInputValue(current?.calibrationDate) || calibrationDate || null,
    calibrationPeriod: normalizeInputValue(current?.calibrationPeriod),
    validUntil: normalizeInputValue(current?.validUntil) || validUntil || null,
    note: mergeMeasurementEquipmentNoteLines(current?.note, isznrNote, removedNote),
    linkedServiceCatalogIds: Array.isArray(current?.linkedServiceCatalogIds) ? current.linkedServiceCatalogIds : [],
    linkedTemplateIds: Array.isArray(current?.linkedTemplateIds) ? current.linkedTemplateIds : [],
    documents: Array.isArray(current?.documents) ? current.documents : [],
    activityItems: Array.isArray(current?.activityItems) ? current.activityItems : [],
    measurementSpecs: Array.isArray(current?.measurementSpecs) ? current.measurementSpecs : [],
  };
}

async function syncIsznrInstrumentsToMeasurementEquipment({
  items = [],
  scopedSnapshot = {},
  canCreate = false,
  canEdit = false,
} = {}) {
  const nowValue = new Date().toISOString();
  const organizationId = normalizeInputValue(scopedSnapshot.activeOrganizationId);
  let localItems = Array.isArray(scopedSnapshot.measurementEquipment) ? [...scopedSnapshot.measurementEquipment] : [];
  const result = {
    received: items.length,
    created: 0,
    updated: 0,
    skipped: 0,
  };

  for (const item of items) {
    const current = findMeasurementEquipmentForIsznrInstrument(localItems, item);
    if (current) {
      if (!canEdit) {
        result.skipped += 1;
        continue;
      }
      const updated = await domainRepository.updateMeasurementEquipmentItem(current.id, buildMeasurementEquipmentPayloadFromIsznrInstrument(item, {
        organizationId,
        current,
        nowValue,
      }));
      if (updated) {
        result.updated += 1;
        localItems = localItems.map((entry) => String(entry.id) === String(updated.id) ? updated : entry);
      } else {
        result.skipped += 1;
      }
      continue;
    }

    if (!canCreate) {
      result.skipped += 1;
      continue;
    }
    const created = await domainRepository.createMeasurementEquipmentItem(buildMeasurementEquipmentPayloadFromIsznrInstrument(item, {
      organizationId,
      nowValue,
    }));
    result.created += 1;
    localItems = [created, ...localItems];
  }

  return result;
}

async function fetchIsznrInstruments({
  baseUrl = "",
  username = "",
  password = "",
  page = 1,
  pagination = true,
  serialNumber = "",
  removedBefore = "",
  removedStrictlyBefore = "",
  removedAfter = "",
  removedStrictlyAfter = "",
  timeoutMs = ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "ISZNR lozinka nije spremljena. Spremi ju u Settings prije dohvata opreme.");
  }

  const requestUrl = buildIsznrResourceUrl(normalizedBaseUrl, "instruments");
  const pageNumber = Math.max(1, Number(page) || 1);
  requestUrl.searchParams.set("page", String(pageNumber));
  requestUrl.searchParams.set("pagination", pagination === false ? "false" : "true");
  if (String(serialNumber || "").trim()) {
    requestUrl.searchParams.set("serialNumber", String(serialNumber).trim());
  }
  if (String(removedBefore || "").trim()) {
    requestUrl.searchParams.set("removed[before]", String(removedBefore).trim());
  }
  if (String(removedStrictlyBefore || "").trim()) {
    requestUrl.searchParams.set("removed[strictly_before]", String(removedStrictlyBefore).trim());
  }
  if (String(removedAfter || "").trim()) {
    requestUrl.searchParams.set("removed[after]", String(removedAfter).trim());
  }
  if (String(removedStrictlyAfter || "").trim()) {
    requestUrl.searchParams.set("removed[strictly_after]", String(removedStrictlyAfter).trim());
  }

  let result;
  const requestHeaders = {
    accept: "application/ld+json, application/json",
    authorization: createIsznrBasicAuthHeader(normalizedUsername, safePassword),
    "user-agent": "SafeNexus/1.0",
  };
  try {
    result = await requestIsznrText(requestUrl, {
      headers: requestHeaders,
      timeoutMs,
    });
  } catch (error) {
    if (isNetworkTimeoutError(error)) {
      throw createRequestError(504, "ISZNR oprema se nije dohvatila na vrijeme.");
    }
    throw createRequestError(502, "ISZNR API za opremu nije dostupan s poslužitelja.");
  }

  const responseText = result.text || "";
  let payload = null;
  if (responseText) {
    try {
      payload = JSON.parse(responseText);
    } catch {
      payload = null;
    }
  }

  if (!result.ok) {
    if (result.status === 401 || result.status === 403) {
      throw createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
    }
    throw createRequestError(result.status || 502, `ISZNR API je odgovorio statusom ${result.status || "nepoznato"}.`);
  }

  const rawItems = getIsznrPayloadArray(payload);
  const items = rawItems.map((item) => normalizeIsznrInstrumentRecord(item));
  return {
    ok: true,
    page: pageNumber,
    count: items.length,
    totalItems: getIsznrPayloadTotal(payload),
    items,
    fetchedAt: new Date().toISOString(),
  };
}

async function fetchIsznrInstrumentCollection(options = {}) {
  const maxPages = Math.max(1, Number(options.maxPages) || ISZNR_MOBILE_INSTRUMENT_MAX_PAGES);
  const maxRecords = Math.max(20, Number(options.maxRecords) || ISZNR_MOBILE_INSTRUMENT_MAX_RECORDS);

  const unpaginated = await fetchIsznrInstruments({
    ...options,
    page: 1,
    pagination: false,
    timeoutMs: ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
  });
  const unpaginatedItems = dedupeIsznrInstrumentRecords(unpaginated.items);
  const unpaginatedLooksComplete = (
    (unpaginated.totalItems !== null && unpaginatedItems.length >= unpaginated.totalItems)
    || unpaginated.count === 0
    || unpaginated.count > ISZNR_INSTRUMENT_PAGE_SIZE_GUESS
    || (unpaginated.count < ISZNR_INSTRUMENT_PAGE_SIZE_GUESS && unpaginated.totalItems === null)
  );

  if (unpaginatedLooksComplete) {
    const limitedItems = unpaginatedItems.slice(0, maxRecords);
    return {
      ok: true,
      page: 1,
      count: limitedItems.length,
      totalItems: unpaginated.totalItems ?? unpaginatedItems.length,
      items: limitedItems,
      fetchedAt: unpaginated.fetchedAt || new Date().toISOString(),
      pagesFetched: 1,
      fetchMode: "unpaginated",
      recordsLimited: unpaginatedItems.length > maxRecords || (unpaginated.totalItems !== null && unpaginated.totalItems > maxRecords),
    };
  }

  const items = [...unpaginatedItems];
  let totalItems = unpaginated.totalItems;
  let fetchedAt = unpaginated.fetchedAt || "";
  let pagesFetched = 1;
  let lastPageCount = unpaginated.count;
  const pageSize = Math.max(1, unpaginated.count || ISZNR_INSTRUMENT_PAGE_SIZE_GUESS);

  if (totalItems !== null && totalItems > items.length && items.length < maxRecords) {
    const totalPages = Math.ceil(totalItems / pageSize);
    const maxPagesByRecords = Math.ceil(maxRecords / pageSize);
    const lastPageToFetch = Math.min(totalPages, maxPages, maxPagesByRecords);
    const remainingPages = Array.from(
      { length: Math.max(0, lastPageToFetch - 1) },
      (_, index) => index + 2,
    );
    const pageResults = await mapIsznrWithConcurrency(
      remainingPages,
      ISZNR_INSTRUMENT_PAGE_CONCURRENCY,
      async (currentPage) => fetchIsznrInstruments({
        ...options,
        page: currentPage,
        pagination: true,
        timeoutMs: ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
      }),
    );
    pageResults
      .sort((left, right) => Number(left.page || 0) - Number(right.page || 0))
      .forEach((pageResult) => {
        pagesFetched += 1;
        lastPageCount = pageResult.count;
        fetchedAt = pageResult.fetchedAt || fetchedAt;
        totalItems = pageResult.totalItems ?? totalItems;
        items.push(...pageResult.items);
      });
  } else {
    for (let currentPage = 2; currentPage <= maxPages && items.length < maxRecords; currentPage += 1) {
      const pageResult = await fetchIsznrInstruments({
        ...options,
        page: currentPage,
        pagination: true,
        timeoutMs: ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
      });
      pagesFetched += 1;
      lastPageCount = pageResult.count;
      fetchedAt = pageResult.fetchedAt || fetchedAt;
      totalItems = pageResult.totalItems ?? totalItems;
      items.push(...pageResult.items);

      if (pageResult.count === 0) {
        break;
      }
      if (totalItems !== null && items.length >= totalItems) {
        break;
      }
      if (totalItems === null && pageResult.count < ISZNR_INSTRUMENT_PAGE_SIZE_GUESS) {
        break;
      }
    }
  }

  const dedupedItems = dedupeIsznrInstrumentRecords(items);
  const limitedItems = dedupedItems.slice(0, maxRecords);
  return {
    ok: true,
    page: 1,
    count: limitedItems.length,
    totalItems: totalItems ?? dedupedItems.length,
    items: limitedItems,
    fetchedAt: fetchedAt || new Date().toISOString(),
    pagesFetched,
    fetchMode: "paged",
    recordsLimited: dedupedItems.length > maxRecords
      || (totalItems !== null && totalItems > maxRecords)
      || (pagesFetched >= maxPages && lastPageCount >= ISZNR_INSTRUMENT_PAGE_SIZE_GUESS && (totalItems === null || dedupedItems.length < totalItems)),
  };
}

async function fetchMobileIsznrInstrumentList(options = {}) {
  const maxRecords = Math.max(20, Number(options.maxRecords) || ISZNR_MOBILE_INSTRUMENT_MAX_RECORDS);
  const requestedPage = Math.max(1, Number(options.page) || 1);
  const requestedPagination = options.pagination !== false;
  const shouldFetchCollection = options.fetchAll !== false && requestedPage <= 1;

  if (shouldFetchCollection) {
    return fetchIsznrInstrumentCollection({
      ...options,
      maxRecords,
    });
  }

  const result = await fetchIsznrInstruments({
    ...options,
    page: requestedPage,
    pagination: requestedPagination,
    timeoutMs: ISZNR_INSTRUMENT_FETCH_TIMEOUT_MS,
  });
  return {
    ...result,
    recordsLimited: result.items.length >= maxRecords,
    pagesFetched: 1,
    fetchMode: requestedPagination ? "page" : "unpaginated",
    items: dedupeIsznrInstrumentRecords(result.items).slice(0, maxRecords),
  };
}

async function fetchIsznrJsonResource({
  baseUrl = "",
  username = "",
  password = "",
  resourcePath = "",
  searchParams = {},
  timeoutMs = ISZNR_WORK_EQUIPMENT_FETCH_TIMEOUT_MS,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "ISZNR lozinka nije spremljena. Spremi ju u Settings prije dohvata.");
  }

  const requestUrl = buildIsznrResourceUrl(normalizedBaseUrl, resourcePath);
  Object.entries(searchParams || {}).forEach(([key, value]) => {
    if (Array.isArray(value)) {
      value
        .map((entry) => normalizeInputValue(entry))
        .filter(Boolean)
        .forEach((entry) => requestUrl.searchParams.append(key, entry));
      return;
    }
    if (value !== undefined && value !== null && value !== "") {
      requestUrl.searchParams.set(key, String(value));
    }
  });

  let result;
  try {
    result = await requestIsznrText(requestUrl, {
      headers: {
        ...createIsznrRequestHeaders(normalizedUsername, safePassword),
        "user-agent": "SafeNexus/1.0",
      },
      preferIpv4: true,
      timeoutMs,
    });
  } catch (error) {
    if (isNetworkTimeoutError(error)) {
      throw createRequestError(504, "ISZNR API se nije javio na vrijeme.");
    }
    throw createRequestError(502, "ISZNR API nije dostupan s poslužitelja.");
  }

  const responseText = result.text || "";
  const payload = parseIsznrJsonPayload(responseText);
  if (!result.ok) {
    if (result.status === 401 || result.status === 403) {
      throw createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
    }
    throw createRequestError(result.status || 502, `ISZNR API je odgovorio statusom ${result.status || "nepoznato"}.`);
  }

  return {
    ok: true,
    status: result.status,
    path: getIsznrDisplayPath(requestUrl),
    payload,
    fetchedAt: new Date().toISOString(),
  };
}

function getIsznrApiErrorMessage(payload = null, responseText = "") {
  if (payload && typeof payload === "object") {
    const direct = normalizeInputValue(
      payload["hydra:description"]
      || payload.detail
      || payload.message
      || payload.error
      || payload.title,
    );
    const violations = Array.isArray(payload.violations)
      ? payload.violations
        .map((item) => [item.propertyPath, item.message].map(normalizeInputValue).filter(Boolean).join(": "))
        .filter(Boolean)
      : [];
    return [direct, violations.slice(0, 4).join("; ")].filter(Boolean).join(" - ");
  }
  return normalizeInputValue(responseText).slice(0, 500);
}

async function mutateIsznrJsonResource({
  baseUrl = "",
  username = "",
  password = "",
  resourcePath = "",
  method = "POST",
  payload = {},
  timeoutMs = ISZNR_WORK_EQUIPMENT_POST_TIMEOUT_MS,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "ISZNR lozinka nije spremljena. Spremi ju u Settings prije slanja.");
  }

  const requestUrl = buildIsznrResourceUrl(normalizedBaseUrl, resourcePath);
  const body = JSON.stringify(payload ?? {});
  let result;
  try {
    result = await requestIsznrText(requestUrl, {
      method,
      body,
      headers: {
        ...createIsznrRequestHeaders(normalizedUsername, safePassword),
        "content-type": "application/ld+json; charset=utf-8",
        "user-agent": "SafeNexus/1.0",
      },
      preferIpv4: true,
      timeoutMs,
    });
  } catch (error) {
    if (isNetworkTimeoutError(error)) {
      throw createRequestError(504, "ISZNR API se nije javio na vrijeme kod slanja.");
    }
    throw createRequestError(502, "ISZNR API nije dostupan s poslužitelja kod slanja.");
  }

  const responseText = result.text || "";
  const responsePayload = parseIsznrJsonPayload(responseText);
  if (!result.ok) {
    if (result.status === 401 || result.status === 403) {
      throw createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
    }
    const apiMessage = getIsznrApiErrorMessage(responsePayload, responseText);
    throw createRequestError(
      result.status || 502,
      apiMessage ? `ISZNR API je odbio slanje (${result.status}): ${apiMessage}` : `ISZNR API je odbio slanje (${result.status || "nepoznato"}).`,
    );
  }

  return {
    ok: true,
    status: result.status,
    path: getIsznrDisplayPath(requestUrl),
    payload: responsePayload,
    responseText,
    submittedAt: new Date().toISOString(),
  };
}

async function mutateIsznrMultipartResource({
  baseUrl = "",
  username = "",
  password = "",
  resourcePath = "",
  method = "POST",
  fields = {},
  files = [],
  timeoutMs = ISZNR_WORK_EQUIPMENT_POST_TIMEOUT_MS,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "ISZNR lozinka nije spremljena. Spremi ju u Settings prije slanja privitaka.");
  }

  const requestUrl = buildIsznrResourceUrl(normalizedBaseUrl, resourcePath);
  const formData = new FormData();
  Object.entries(fields || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") {
      formData.append(key, String(value));
    }
  });
  (Array.isArray(files) ? files : []).forEach((file) => {
    if (!file?.fieldName || !Buffer.isBuffer(file.buffer) || file.buffer.length === 0) {
      return;
    }
    formData.append(
      file.fieldName,
      new Blob([file.buffer], { type: file.mimeType || "application/octet-stream" }),
      file.fileName || "prilog",
    );
  });

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  let result;
  try {
    result = await fetch(requestUrl, {
      method: String(method || "POST").toUpperCase(),
      headers: {
        ...createIsznrRequestHeaders(normalizedUsername, safePassword),
        "user-agent": "SafeNexus/1.0",
      },
      body: formData,
      signal: controller.signal,
    });
  } catch (error) {
    if (isNetworkTimeoutError(error)) {
      throw createRequestError(504, "ISZNR API se nije javio na vrijeme kod slanja privitka.");
    }
    throw createRequestError(502, "ISZNR API nije dostupan s poslužitelja kod slanja privitka.");
  } finally {
    clearTimeout(timeout);
  }

  const responseText = await result.text().catch(() => "");
  const responsePayload = parseIsznrJsonPayload(responseText);
  if (!result.ok) {
    if (result.status === 401 || result.status === 403) {
      throw createRequestError(400, "ISZNR autentikacija nije uspjela kod slanja privitka.");
    }
    const apiMessage = getIsznrApiErrorMessage(responsePayload, responseText);
    throw createRequestError(
      result.status || 502,
      apiMessage ? `ISZNR API je odbio privitak (${result.status}): ${apiMessage}` : `ISZNR API je odbio privitak (${result.status || "nepoznato"}).`,
    );
  }

  return {
    ok: true,
    status: result.status,
    path: getIsznrDisplayPath(requestUrl),
    payload: responsePayload,
    responseText,
    submittedAt: new Date().toISOString(),
  };
}

function normalizeIsznrRelatedRecord(source = {}) {
  if (!source || typeof source !== "object") {
    return { id: "", name: "", oib: "" };
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  return {
    id: extractIsznrId(record),
    name: normalizeInputValue(pickIsznrValue(record, ["name", "title", "naziv", "fullName", "displayName"])),
    oib: normalizeIsznrOib(pickIsznrValue(record, ["oib", "OIB", "companyOib", "personOib"])),
  };
}

function normalizeIsznrRelatedArray(value = []) {
  const items = Array.isArray(value) ? value : (value && typeof value === "object" ? [value] : []);
  return items
    .map((item) => normalizeIsznrRelatedRecord(item))
    .filter((item) => item.id || item.name || item.oib);
}

function normalizeIsznrFinalGrade(value) {
  const numeric = Number(value);
  if (numeric === 1) {
    return { value: "1", label: "Zadovoljava" };
  }
  if (numeric === 0) {
    return { value: "0", label: "Ne zadovoljava" };
  }
  return { value: normalizeInputValue(value), label: "" };
}

function normalizeIsznrWorkEquipmentUnit(source = {}, index = 0) {
  const attributes = source?.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record) || String(index + 1);
  return {
    id,
    serialNumber: normalizeInputValue(pickIsznrValue(record, ["serialNumber", "serial", "tvornickiBroj"])),
    name: normalizeInputValue(pickIsznrValue(record, ["name", "title", "naziv"])),
    manufacturer: normalizeInputValue(pickIsznrValue(record, ["manufacturer", "proizvodac"])),
    model: normalizeInputValue(pickIsznrValue(record, ["model", "type", "tip"])),
    inventoryNumber: normalizeInputValue(pickIsznrValue(record, ["inventoryNumber", "inventory", "inventarskiBroj"])),
    note: normalizeInputValue(pickIsznrValue(record, ["note", "description", "napomena"])),
  };
}

function normalizeIsznrRoRecord(source = {}) {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record);
  const company = normalizeIsznrRelatedRecord(record.company);
  const authorizedCompany = normalizeIsznrRelatedRecord(record.authorizedCompany);
  const equipments = (Array.isArray(record.equipments) ? record.equipments : [])
    .map((item, index) => normalizeIsznrWorkEquipmentUnit(item, index))
    .filter((item) => item.id || item.name || item.serialNumber || item.inventoryNumber);
  const finalGrade = normalizeIsznrFinalGrade(record.finalGrade ?? record.finalScore);
  const mechanicalItems = normalizeIsznrRoAssessmentItemsFromRecord(
    record,
    [
      "roMechanicalEngineerings",
      "roMechanicalEngineering",
      "mechanicalEngineerings",
      "mechanicalItems",
      "mechanicalChecks",
      "ro_mechanical_engineerings",
    ],
    "ro_mechanical_engineering_registers",
    [
      "roMechanicalEngineeringRegister",
      "mechanicalEngineeringRegister",
      "register",
    ],
  );
  const electricalItems = normalizeIsznrRoAssessmentItemsFromRecord(
    record,
    [
      "roElectricals",
      "roElectrical",
      "electricals",
      "electricalItems",
      "electricalChecks",
      "ro_electricals",
    ],
    "ro_electrical_registers",
    [
      "roElectricalRegister",
      "electricalRegister",
      "register",
    ],
  );

  return {
    id,
    isznrId: id,
    sourceKind: "ro_records",
    sourceLabel: "RO zapisnik",
    recordNumber: normalizeInputValue(pickIsznrValue(record, ["recordNumber", "identifier", "internalId"])),
    internalId: normalizeInputValue(record.internalId),
    company,
    authorizedCompany,
    location: normalizeInputValue(record.location),
    startDate: normalizeInputValue(record.startDate).slice(0, 10),
    endDate: normalizeInputValue(record.endDate).slice(0, 10),
    deadlineForNextExamination: normalizeInputValue(record.deadlineForNextExamination).slice(0, 10),
    deadlineForNextExaminationNote: normalizeInputValue(record.deadlineForNextExaminationNote),
    finalGrade,
    roObligationRegister: normalizeIsznrRelatedArray(record.roObligationRegister),
    roHealthRequirementRegister: normalizeIsznrRelatedArray(record.roHealthRequirementRegister),
    roHealthRequirementOther: normalizeInputValue(record.roHealthRequirementOther),
    equipmentsTechnicalData: normalizeInputValue(record.equipmentsTechnicalData),
    equipmentsPurposeDescription: normalizeInputValue(record.equipmentsPurposeDescription),
    equipmentsWorkspacePosition: normalizeInputValue(record.equipmentsWorkspacePosition),
    workingSubstancesAndRawMaterials: normalizeInputValue(record.workingSubstancesAndRawMaterials),
    useAndMaintenance: normalizeInputValue(record.useAndMaintenance),
    methodsProceduresAndNorms: normalizeInputValue(record.methodsProceduresAndNorms),
    experts: normalizeIsznrRelatedArray(record.experts),
    signedBy: normalizeIsznrRelatedArray(record.signedBy),
    instruments: normalizeIsznrRelatedArray(record.instruments),
    deficiencies: normalizeInputValue(record.deficiencies),
    measuresToEliminateDeficiencies: normalizeInputValue(record.measuresToEliminateDeficiencies),
    mechanicalItems,
    electricalItems,
    equipments,
  };
}

function normalizeIsznrRegisterRecord(source = {}, resource = {}) {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record);
  const description = normalizeInputValue(pickIsznrValue(record, ["description", "name", "title", "naziv"]));
  return {
    id,
    isznrId: id,
    group: resource.group || "",
    label: resource.label || "",
    path: resource.path || "",
    description,
    activeFrom: normalizeInputValue(record.activeFrom).slice(0, 10),
    activeTo: normalizeInputValue(record.activeTo).slice(0, 10),
  };
}

function buildIsznrWorkEquipmentSearchParams(filters = {}) {
  const entries = {
    "company.oib": normalizeIsznrOib(filters.companyOib || filters["company.oib"]),
    "startDate[before]": normalizeInputValue(filters.startDateBefore || filters["startDate[before]"]),
    "startDate[after]": normalizeInputValue(filters.startDateAfter || filters["startDate[after]"]),
    "endDate[before]": normalizeInputValue(filters.endDateBefore || filters["endDate[before]"]),
    "endDate[after]": normalizeInputValue(filters.endDateAfter || filters["endDate[after]"]),
  };
  return Object.fromEntries(Object.entries(entries).filter(([, value]) => value));
}

async function fetchIsznrPagedCollection({
  baseUrl = "",
  username = "",
  password = "",
  resourcePath = "",
  searchParams = {},
  maxPages = ISZNR_WORK_EQUIPMENT_MAX_PAGES,
  maxRecords = ISZNR_MOBILE_WORK_EQUIPMENT_MAX_RECORDS,
  timeoutMs = ISZNR_WORK_EQUIPMENT_FETCH_TIMEOUT_MS,
} = {}) {
  const items = [];
  let totalItems = null;
  let fetchedAt = "";
  let pagesFetched = 0;
  let lastPageCount = 0;
  const safeMaxPages = Math.max(1, Number(maxPages) || ISZNR_WORK_EQUIPMENT_MAX_PAGES);
  const safeMaxRecords = Math.max(1, Number(maxRecords) || ISZNR_MOBILE_WORK_EQUIPMENT_MAX_RECORDS);

  for (let page = 1; page <= safeMaxPages && items.length < safeMaxRecords; page += 1) {
    const result = await fetchIsznrJsonResource({
      baseUrl,
      username,
      password,
      resourcePath,
      searchParams: {
        ...searchParams,
        page,
      },
      timeoutMs,
    });
    const pageItems = getIsznrPayloadArray(result.payload);
    pagesFetched += 1;
    lastPageCount = pageItems.length;
    totalItems = getIsznrPayloadTotal(result.payload) ?? totalItems;
    fetchedAt = result.fetchedAt || fetchedAt;
    items.push(...pageItems);

    if (pageItems.length === 0) {
      break;
    }
    if (totalItems !== null && items.length >= totalItems) {
      break;
    }
    if (totalItems === null && pageItems.length < ISZNR_INSTRUMENT_PAGE_SIZE_GUESS) {
      break;
    }
  }

  const limitedItems = items.slice(0, safeMaxRecords);
  return {
    ok: true,
    count: limitedItems.length,
    totalItems: totalItems ?? items.length,
    items: limitedItems,
    fetchedAt: fetchedAt || new Date().toISOString(),
    pagesFetched,
    recordsLimited: items.length > safeMaxRecords
      || (totalItems !== null && totalItems > safeMaxRecords)
      || (pagesFetched >= safeMaxPages && lastPageCount >= ISZNR_INSTRUMENT_PAGE_SIZE_GUESS && (totalItems === null || items.length < totalItems)),
  };
}

async function fetchIsznrWorkEquipmentRegisters({
  baseUrl = "",
  username = "",
  password = "",
} = {}) {
  const groups = await mapIsznrWithConcurrency(
    ISZNR_WORK_EQUIPMENT_REGISTER_RESOURCES,
    3,
    async (resource) => {
      try {
        const result = await fetchIsznrJsonResource({
          baseUrl,
          username,
          password,
          resourcePath: resource.path,
          timeoutMs: ISZNR_WORK_EQUIPMENT_FETCH_TIMEOUT_MS,
        });
        const items = getIsznrPayloadArray(result.payload)
          .map((item) => normalizeIsznrRegisterRecord(item, resource))
          .filter(Boolean);
        return {
          ok: true,
          ...resource,
          count: items.length,
          items,
          fetchedAt: result.fetchedAt,
        };
      } catch (error) {
        return {
          ok: false,
          ...resource,
          count: 0,
          items: [],
          error: error?.message || "ISZNR šifrarnik nije dohvaćen.",
        };
      }
    },
  );

  return groups;
}

function buildIsznrWorkEquipmentItemsFromRoRecord(record = {}) {
  const normalized = normalizeIsznrRoRecord(record);
  if (!normalized) {
    return [];
  }
  if (!normalized.equipments.length) {
    return [{
      ...normalized,
      equipment: null,
      equipmentType: normalized.recordNumber || "Radna oprema iz RO zapisnika",
    }];
  }
  return normalized.equipments.map((equipment, index) => ({
    ...normalized,
    id: `${normalized.id || "record"}:${equipment.id || index + 1}`,
    isznrId: normalized.id,
    equipment,
    equipmentType: [
      equipment.name,
      equipment.manufacturer,
      equipment.model,
      equipment.serialNumber ? `Ser. ${equipment.serialNumber}` : "",
      equipment.inventoryNumber ? `Inv. ${equipment.inventoryNumber}` : "",
    ].filter(Boolean).join(" - "),
  }));
}

function dedupeIsznrWorkEquipmentItems(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : [])
    .filter(Boolean)
    .filter((item) => {
      const equipment = item.equipment || {};
      const key = [
        normalizeInputValue(item.sourceKind),
        normalizeInputValue(item.isznrId || item.id),
        normalizeInputValue(item.recordNumber),
        normalizeInputValue(item.equipmentType),
        normalizeInputValue(equipment.serialNumber),
        normalizeInputValue(equipment.inventoryNumber),
      ].join("|").toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

async function fetchIsznrWorkEquipmentList({
  baseUrl = "",
  username = "",
  password = "",
  filters = {},
  includeRegisters = false,
  maxPages = ISZNR_WORK_EQUIPMENT_MAX_PAGES,
  maxRecords = ISZNR_MOBILE_WORK_EQUIPMENT_MAX_RECORDS,
} = {}) {
  const searchParams = buildIsznrWorkEquipmentSearchParams(filters);
  const safeMaxRecords = Math.max(1, Number(maxRecords) || ISZNR_MOBILE_WORK_EQUIPMENT_MAX_RECORDS);
  const currentRecords = await fetchIsznrPagedCollection({
    baseUrl,
    username,
    password,
    resourcePath: "ro_records",
    searchParams,
    maxPages,
    maxRecords: safeMaxRecords,
  });

  const identifierFilter = normalizeInputValue(filters.identifier).toLowerCase();
  const recordItems = currentRecords.items
    .flatMap(buildIsznrWorkEquipmentItemsFromRoRecord)
    .filter((item) => {
      if (!identifierFilter) {
        return true;
      }
      return [
        item.recordNumber,
        item.internalId,
        item.equipmentType,
        item.equipment?.serialNumber,
        item.equipment?.inventoryNumber,
      ].map((value) => normalizeInputValue(value).toLowerCase()).some((value) => value.includes(identifierFilter));
    });
  const items = dedupeIsznrWorkEquipmentItems(recordItems).slice(0, safeMaxRecords);
  const registers = includeRegisters
    ? await fetchIsznrWorkEquipmentRegisters({ baseUrl, username, password })
    : [];

  return {
    ok: true,
    count: items.length,
    totalItems: currentRecords.totalItems ?? recordItems.length,
    items,
    registers,
    fetchedAt: new Date().toISOString(),
    pagesFetched: currentRecords.pagesFetched,
    recordsLimited: currentRecords.recordsLimited || items.length >= safeMaxRecords,
    sources: {
      records: {
        count: recordItems.length,
        totalItems: currentRecords.totalItems,
        recordsLimited: currentRecords.recordsLimited,
      },
    },
  };
}

function buildMobileIsznrWorkEquipmentRecord(item = {}) {
  const finalGrade = item.finalGrade?.label || "";
  const equipment = item.equipment || {};
  const title = normalizeInputValue(item.equipmentType)
    || normalizeInputValue(equipment.name)
    || normalizeInputValue(item.recordNumber)
    || "IS ZNR radna oprema";
  const date = normalizeInputValue(item.dateOfTest || item.endDate || item.dateOfDocument || item.startDate);
  const companyName = normalizeInputValue(item.company?.name);
  const location = normalizeInputValue(item.location);
  const subtitle = [
    item.recordNumber ? `Zapisnik ${item.recordNumber}` : "",
    companyName,
    location,
    date,
  ].filter(Boolean).join(" - ");
  const experts = normalizeIsznrRelatedArray(item.experts).map((entry) => entry.name).filter(Boolean);
  const signedBy = normalizeIsznrRelatedArray(item.signedBy).map((entry) => entry.name).filter(Boolean);

  return {
    id: `isznr-work-equipment:${normalizeInputValue(item.id || item.isznrId || item.recordNumber || title)}`,
    title,
    subtitle,
    status: finalGrade || item.sourceLabel || "IS ZNR",
    kind: "isznr_work_equipment",
    date,
    relatedId: normalizeInputValue(item.isznrId || item.id),
    coordinates: "",
    meta: {
      isznrWorkEquipmentId: normalizeInputValue(item.isznrId || item.id),
      isznrRecordId: normalizeInputValue(item.isznrId || item.id),
      isznrSource: normalizeInputValue(item.sourceKind),
      isznrSourceLabel: normalizeInputValue(item.sourceLabel),
      isznrLinked: "true",
      recordNumber: normalizeInputValue(item.recordNumber),
      companyName,
      companyOib: normalizeInputValue(item.company?.oib),
      authorizedCompanyName: normalizeInputValue(item.authorizedCompany?.name),
      location,
      dateOfTest: normalizeInputValue(item.dateOfTest),
      dateOfDocument: normalizeInputValue(item.dateOfDocument),
      startDate: normalizeInputValue(item.startDate),
      endDate: normalizeInputValue(item.endDate),
      deadlineForNextExamination: normalizeInputValue(item.deadlineForNextExamination),
      finalGrade,
      equipmentName: normalizeInputValue(equipment.name),
      serialNumber: normalizeInputValue(equipment.serialNumber),
      inventoryNumber: normalizeInputValue(equipment.inventoryNumber),
      manufacturer: normalizeInputValue(equipment.manufacturer),
      model: normalizeInputValue(equipment.model),
      note: normalizeInputValue(equipment.note),
      equipmentsTechnicalData: normalizeInputValue(item.equipmentsTechnicalData),
      equipmentsPurposeDescription: normalizeInputValue(item.equipmentsPurposeDescription),
      equipmentsWorkspacePosition: normalizeInputValue(item.equipmentsWorkspacePosition),
      workingSubstancesAndRawMaterials: normalizeInputValue(item.workingSubstancesAndRawMaterials),
      useAndMaintenance: normalizeInputValue(item.useAndMaintenance),
      methodsProceduresAndNorms: normalizeInputValue(item.methodsProceduresAndNorms),
      deficiencies: normalizeInputValue(item.deficiencies),
      measuresToEliminateDeficiencies: normalizeInputValue(item.measuresToEliminateDeficiencies),
      experts: experts.join(", "),
      signedBy: signedBy.join(", "),
    },
  };
}

function buildWorkOrderIsznrWorkEquipmentOption(item = {}) {
  const record = buildMobileIsznrWorkEquipmentRecord(item);
  if (!record?.id || !record?.title) {
    return null;
  }
  const meta = record.meta || {};
  return buildMobileDocumentationOption(
    record.id,
    record.title,
    [
      meta.recordNumber ? `Zapisnik ${meta.recordNumber}` : "",
      meta.serialNumber ? `Ser. ${meta.serialNumber}` : "",
      meta.inventoryNumber ? `Inv. ${meta.inventoryNumber}` : "",
      meta.deadlineForNextExamination ? `Vrijedi do ${formatOfferDocumentDate(meta.deadlineForNextExamination)}` : "",
    ].filter(Boolean).join(" · "),
    record.status,
    meta,
  );
}

function buildWorkOrderIsznrWorkEquipmentOptions(items = []) {
  return (Array.isArray(items) ? items : [])
    .map((item) => buildWorkOrderIsznrWorkEquipmentOption(item))
    .filter(Boolean)
    .sort((left, right) => left.label.localeCompare(right.label, "hr", { numeric: true, sensitivity: "base" }));
}

function getIsznrNestedArray(source = {}, keys = []) {
  if (!source || typeof source !== "object") {
    return [];
  }
  for (const key of keys) {
    const value = source[key];
    if (Array.isArray(value)) {
      return value;
    }
    if (value && typeof value === "object") {
      if (Array.isArray(value.data)) {
        return value.data;
      }
      if (Array.isArray(value.items)) {
        return value.items;
      }
      if (Array.isArray(value["hydra:member"])) {
        return value["hydra:member"];
      }
    }
  }
  return [];
}

function normalizeIsznrWorkEnvironmentText(value = "") {
  return normalizeInputValue(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeIsznrWorkEnvironmentFinalGrade(value = "") {
  const base = normalizeIsznrFinalGrade(value);
  const raw = normalizeInputValue(base.label || base.value || value);
  const normalized = normalizeIsznrWorkEnvironmentText(raw);
  if (!raw) {
    return { value: "", label: "" };
  }
  if (normalized === "da" || normalized.includes("zadovoljava") && !normalized.includes("ne zadovoljava")) {
    return { value: raw, label: "Zadovoljava" };
  }
  if (normalized === "ne" || normalized.includes("ne zadovoljava") || normalized.includes("nezadovoljava")) {
    return { value: raw, label: "Ne zadovoljava" };
  }
  return { value: raw, label: raw };
}

function normalizeIsznrWorkEnvironmentSpace(source = {}, index = 0) {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record) || normalizeInputValue(record.id) || String(index + 1);
  const code = normalizeInputValue(pickIsznrValue(record, ["code", "oznaka", "mark", "spaceCode", "internalCode"]));
  const name = normalizeInputValue(pickIsznrValue(record, ["name", "title", "naziv", "spaceName"]));
  const description = normalizeInputValue(pickIsznrValue(record, ["description", "opis", "purposeDescription"]));
  const processDescription = normalizeInputValue(pickIsznrValue(record, [
    "workProcessDescription",
    "workProcessesDescription",
    "processDescription",
    "processesDescription",
  ]));
  const equipmentDescription = normalizeInputValue(pickIsznrValue(record, [
    "workEquipmentDescription",
    "equipmentDescription",
    "equipmentsDescription",
  ]));
  return {
    id,
    code,
    name: name || code || `Prostor ${index + 1}`,
    description,
    processDescription,
    equipmentDescription,
  };
}

function normalizeIsznrWorkEnvironmentMeasurement(source = {}, kind = "", index = 0) {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const relatedSpace = normalizeIsznrRelatedRecord(
    record.fcSpace || record.kcSpace || record.space || record.workingEnvironmentSpace || record.room,
  );
  const id = extractIsznrId(record) || normalizeInputValue(record.id) || `${kind || "measurement"}-${index + 1}`;
  const measured = normalizeInputValue(pickIsznrValue(record, [
    "measuredValue",
    "measured",
    "value",
    "result",
    "measurementResult",
    "equivalentNoiseLevel",
    "airTemperature",
    "airFlowSpeed",
    "relativeAirHumidity",
    "illumination",
    "vibration",
  ]));
  const allowed = normalizeInputValue(pickIsznrValue(record, [
    "allowedValue",
    "permittedValue",
    "prescribedValue",
    "limitValue",
    "gvi",
    "kgvi",
  ]));
  const finalGrade = normalizeIsznrWorkEnvironmentFinalGrade(
    record.finalGrade || record.satisfies || record.resultSatisfies || record.complies || record.grade,
  );
  return {
    id,
    kind,
    spaceId: normalizeInputValue(relatedSpace.id),
    spaceName: normalizeInputValue(
      relatedSpace.name
        || record.spaceName
        || record.roomName
        || record.placeName
        || record.workplaceName,
    ),
    measuringPlace: normalizeInputValue(pickIsznrValue(record, [
      "measuringPlace",
      "measurementPlace",
      "place",
      "name",
      "description",
    ])),
    harmfulness: normalizeInputValue(pickIsznrValue(record, ["harmfulness", "harmfulnessName", "chemicalAgent", "agentName"])),
    unit: normalizeInputValue(pickIsznrValue(record, ["unit", "measurementUnit"])),
    measured,
    allowed,
    note: normalizeInputValue(pickIsznrValue(record, ["note", "remark", "napomena"])),
    finalGrade,
  };
}

function normalizeIsznrWorkEnvironmentRecord(source = {}, sourceKind = "fc_records") {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const isChemical = sourceKind === "kc_records";
  const id = extractIsznrId(record);
  const sourceLabel = isChemical ? "Kemijski čimbenici" : "Fizikalni čimbenici";
  const company = normalizeIsznrRelatedRecord(record.company || record.legalEntity);
  const authorizedCompany = normalizeIsznrRelatedRecord(record.authorizedCompany);
  const spaces = getIsznrNestedArray(record, isChemical
    ? ["kcSpaces", "kc_spaces", "spaces", "workingEnvironmentSpaces"]
    : ["fcSpaces", "fc_spaces", "spaces", "workingEnvironmentSpaces"])
    .map((item, index) => normalizeIsznrWorkEnvironmentSpace(item, index))
    .filter(Boolean);
  const measurementSpecs = isChemical
    ? [
      { keys: ["kcHarmfulnesses", "kc_harmfulnesses", "harmfulnesses"], label: "Štetnost" },
    ]
    : [
      { keys: ["fcIlluminations", "fc_illuminations", "illuminations"], label: "Osvijetljenost" },
      { keys: ["fcNoises", "fc_noises", "noises"], label: "Buka" },
      { keys: ["fcMicroClimaticConditions", "fc_micro_climatic_conditions", "microClimaticConditions"], label: "Mikroklimatski uvjeti" },
      { keys: ["fcVibrations", "fc_vibrations", "vibrations"], label: "Vibracije" },
    ];
  const measurements = measurementSpecs.flatMap((spec) =>
    getIsznrNestedArray(record, spec.keys)
      .map((item, index) => normalizeIsznrWorkEnvironmentMeasurement(item, spec.label, index))
      .filter(Boolean),
  );
  const finalGradeSources = getIsznrNestedArray(record, isChemical
    ? ["kcFinalGrades", "kc_final_grades", "finalGrades"]
    : ["fcFinalGrades", "fc_final_grades", "finalGrades"]);
  const finalGrades = finalGradeSources
    .map((item) => normalizeIsznrWorkEnvironmentFinalGrade(item?.finalGrade || item?.grade || item?.result || item?.value || item))
    .filter((item) => item.label || item.value);
  const directFinalGrade = normalizeIsznrWorkEnvironmentFinalGrade(
    record.finalGrade || record.finalScore || record.grade || record.satisfies,
  );
  const finalGrade = finalGrades.find((item) => item.label) || directFinalGrade;
  const typeLabels = normalizeIsznrRelatedArray(record.typesOfExamination || record.examinationTypes || record.types)
    .map((item) => item.name)
    .filter(Boolean);
  const measurementKinds = [...new Set(measurements.map((item) => item.kind).filter(Boolean))];
  return {
    id,
    isznrId: id,
    sourceKind,
    sourceLabel,
    environmentKind: isChemical ? "chemical" : "physical",
    recordNumber: normalizeInputValue(pickIsznrValue(record, ["recordNumber", "identifier", "internalId", "number"])),
    internalId: normalizeInputValue(record.internalId),
    company,
    authorizedCompany,
    location: normalizeInputValue(record.location || record.placeOfTesting || record.testingLocation),
    startDate: normalizeInputValue(record.startDate).slice(0, 10),
    endDate: normalizeInputValue(record.endDate).slice(0, 10),
    deadlineForNextExamination: normalizeInputValue(record.deadlineForNextExamination).slice(0, 10),
    finalGrade,
    harmfulness: Array.isArray(record.harmfulness) ? record.harmfulness : [],
    harmfulnessOther: normalizeInputValue(record.harmfulnessOther),
    typesOfExamination: Array.isArray(record.typesOfExamination) ? record.typesOfExamination : [],
    technicalDocumentation: normalizeInputValue(record.technicalDocumentation),
    airTemperature: normalizeInputValue(record.airTemperature),
    relativeAirHumidity: normalizeInputValue(record.relativeAirHumidity),
    airFlowSpeed: normalizeInputValue(record.airFlowSpeed),
    deadlineForNextExaminationNote: normalizeInputValue(record.deadlineForNextExaminationNote),
    measuresToEliminateDeficiencies: normalizeInputValue(record.measuresToEliminateDeficiencies),
    types: typeLabels.length ? typeLabels : measurementKinds,
    instruments: normalizeIsznrRelatedArray(record.instruments),
    experts: normalizeIsznrRelatedArray(record.experts),
    signedBy: normalizeIsznrRelatedArray(record.signedBy),
    healthRequirementRegisters: normalizeIsznrRelatedArray(
      record.fcHealthRequirementRegister
        || record.kcHealthRequirementRegister
        || record.healthRequirementRegister,
    ),
    obligationRegisters: normalizeIsznrRelatedArray(
      record.workingEnvironmentObligationRegister
        || record.obligationRegister,
    ),
    methodsProceduresAndNorms: normalizeInputValue(record.methodsProceduresAndNorms),
    externalConditionsOther: normalizeInputValue(record.externalConditionsOther),
    workProcessConditions: normalizeInputValue(record.workProcessConditions),
    spaces,
    measurements,
  };
}

function buildIsznrWorkEnvironmentSearchParams(filters = {}) {
  const entries = {
    "company.oib": normalizeIsznrOib(filters.companyOib || filters["company.oib"]),
    "startDate[before]": normalizeInputValue(filters.startDateBefore || filters["startDate[before]"]),
    "startDate[after]": normalizeInputValue(filters.startDateAfter || filters["startDate[after]"]),
    "endDate[before]": normalizeInputValue(filters.endDateBefore || filters["endDate[before]"]),
    "endDate[after]": normalizeInputValue(filters.endDateAfter || filters["endDate[after]"]),
  };
  return Object.fromEntries(Object.entries(entries).filter(([, value]) => value));
}

function dedupeIsznrWorkEnvironmentItems(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : [])
    .filter(Boolean)
    .filter((item) => {
      const key = [
        normalizeInputValue(item.sourceKind),
        normalizeInputValue(item.id || item.isznrId),
        normalizeInputValue(item.recordNumber),
        normalizeInputValue(item.location),
        normalizeInputValue(item.endDate || item.startDate),
      ].join("|").toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

async function fetchIsznrWorkEnvironmentList({
  baseUrl = "",
  username = "",
  password = "",
  filters = {},
  maxPages = ISZNR_WORK_EQUIPMENT_MAX_PAGES,
  maxRecords = ISZNR_MOBILE_WORK_ENVIRONMENT_MAX_RECORDS,
} = {}) {
  const searchParams = buildIsznrWorkEnvironmentSearchParams(filters);
  const safeMaxRecords = Math.max(1, Number(maxRecords) || ISZNR_MOBILE_WORK_ENVIRONMENT_MAX_RECORDS);
  const sources = [
    { path: "kc_records", sourceKind: "kc_records", label: "Kemijski čimbenici" },
    { path: "fc_records", sourceKind: "fc_records", label: "Fizikalni čimbenici" },
  ];
  const results = await Promise.all(sources.map(async (source) => {
    try {
      const result = await fetchIsznrPagedCollection({
        baseUrl,
        username,
        password,
        resourcePath: source.path,
        searchParams,
        maxPages,
        maxRecords: safeMaxRecords,
      });
      return { ok: true, source, result };
    } catch (error) {
      return {
        ok: false,
        source,
        error: error?.message || "IS ZNR radni okoliš nije dohvaćen.",
      };
    }
  }));
  const failures = results.filter((item) => !item.ok);
  if (failures.length === results.length) {
    throw new Error(failures[0]?.error || "IS ZNR radni okoliš nije dohvaćen.");
  }
  const items = dedupeIsznrWorkEnvironmentItems(results
    .filter((item) => item.ok)
    .flatMap((item) => (item.result.items || [])
      .map((record) => normalizeIsznrWorkEnvironmentRecord(record, item.source.sourceKind))
      .filter(Boolean)))
    .slice(0, safeMaxRecords);
  const totalItems = results
    .filter((item) => item.ok)
    .reduce((sum, item) => sum + (item.result.totalItems ?? item.result.count ?? 0), 0);
  return {
    ok: true,
    count: items.length,
    totalItems,
    items,
    fetchedAt: new Date().toISOString(),
    pagesFetched: Math.max(0, ...results.filter((item) => item.ok).map((item) => item.result.pagesFetched || 0)),
    recordsLimited: results.some((item) => item.ok && item.result.recordsLimited) || items.length >= safeMaxRecords,
    sources: {
      physical: {
        ok: results.find((item) => item.source.path === "fc_records")?.ok === true,
        count: items.filter((item) => item.environmentKind === "physical").length,
        error: results.find((item) => item.source.path === "fc_records")?.error || "",
      },
      chemical: {
        ok: results.find((item) => item.source.path === "kc_records")?.ok === true,
        count: items.filter((item) => item.environmentKind === "chemical").length,
        error: results.find((item) => item.source.path === "kc_records")?.error || "",
      },
    },
    warnings: failures.map((item) => `${item.source.label}: ${item.error}`),
  };
}

function buildMobileIsznrWorkEnvironmentRecord(item = {}) {
  const finalGrade = item.finalGrade?.label || "";
  const title = normalizeInputValue(item.recordNumber)
    || `${item.sourceLabel || "Radni okoliš"} ${item.endDate || item.startDate || ""}`.trim()
    || "IS ZNR radni okoliš";
  const date = normalizeInputValue(item.endDate || item.startDate);
  const companyName = normalizeInputValue(item.company?.name);
  const location = normalizeInputValue(item.location);
  const spacesCount = Array.isArray(item.spaces) ? item.spaces.length : 0;
  const measurementsCount = Array.isArray(item.measurements) ? item.measurements.length : 0;
  const typesLabel = (Array.isArray(item.types) ? item.types : []).map(normalizeInputValue).filter(Boolean).join(", ");
  const subtitle = [
    item.sourceLabel,
    companyName,
    location,
    spacesCount ? `${spacesCount} prostora` : "",
    measurementsCount ? `${measurementsCount} mjerenja` : "",
    date,
  ].filter(Boolean).join(" - ");
  return {
    id: `isznr-work-environment:${normalizeInputValue(item.id || item.recordNumber || title)}`,
    title,
    subtitle,
    status: finalGrade || item.sourceLabel || "IS ZNR",
    kind: "isznr_work_environment",
    date,
    relatedId: normalizeInputValue(item.isznrId || item.id),
    coordinates: "",
    meta: {
      isznrWorkEnvironmentId: normalizeInputValue(item.isznrId || item.id),
      isznrRecordId: normalizeInputValue(item.isznrId || item.id),
      isznrSource: normalizeInputValue(item.sourceKind),
      isznrSourceLabel: normalizeInputValue(item.sourceLabel),
      isznrLinked: "true",
      environmentKind: normalizeInputValue(item.environmentKind),
      recordNumber: normalizeInputValue(item.recordNumber),
      companyName,
      companyOib: normalizeInputValue(item.company?.oib),
      authorizedCompanyName: normalizeInputValue(item.authorizedCompany?.name),
      location,
      startDate: normalizeInputValue(item.startDate),
      endDate: normalizeInputValue(item.endDate),
      deadlineForNextExamination: normalizeInputValue(item.deadlineForNextExamination),
      finalGrade,
      typesLabel,
      spacesCount: String(spacesCount),
      measurementsCount: String(measurementsCount),
      spacesLabel: (Array.isArray(item.spaces) ? item.spaces : [])
        .slice(0, 4)
        .map((space) => space.name || space.code)
        .filter(Boolean)
        .join(", "),
      experts: normalizeIsznrRelatedArray(item.experts).map((entry) => entry.name).filter(Boolean).join(", "),
      signedBy: normalizeIsznrRelatedArray(item.signedBy).map((entry) => entry.name).filter(Boolean).join(", "),
      methodsProceduresAndNorms: normalizeInputValue(item.methodsProceduresAndNorms),
    },
  };
}

function buildWorkOrderIsznrWorkEnvironmentOption(item = {}) {
  const record = buildMobileIsznrWorkEnvironmentRecord(item);
  if (!record?.id || !record?.title) {
    return null;
  }
  const meta = record.meta || {};
  return buildMobileDocumentationOption(
    record.id,
    [
      meta.recordNumber || (meta.environmentKind === "chemical" ? "Kemijski čimbenici" : "Fizikalni čimbenici"),
      meta.location,
    ].filter(Boolean).join(" - "),
    [
      meta.isznrSourceLabel,
      meta.spacesCount ? `${meta.spacesCount} prostora` : "",
      meta.measurementsCount ? `${meta.measurementsCount} mjerenja` : "",
      meta.deadlineForNextExamination ? `Vrijedi do ${formatOfferDocumentDate(meta.deadlineForNextExamination)}` : "",
    ].filter(Boolean).join(" · "),
    record.status,
    meta,
  );
}

function buildWorkOrderIsznrWorkEnvironmentOptions(items = []) {
  return (Array.isArray(items) ? items : [])
    .map((item) => buildWorkOrderIsznrWorkEnvironmentOption(item))
    .filter(Boolean)
    .sort((left, right) => left.label.localeCompare(right.label, "hr", { numeric: true, sensitivity: "base" }));
}

async function fetchIsznrPhysicalFactorsRegisters({
  baseUrl = "",
  username = "",
  password = "",
} = {}) {
  return mapIsznrWithConcurrency(
    ISZNR_PHYSICAL_FACTORS_REGISTER_RESOURCES,
    2,
    async (resource) => {
      try {
        const result = await fetchIsznrJsonResource({
          baseUrl,
          username,
          password,
          resourcePath: resource.path,
          timeoutMs: ISZNR_WORK_EQUIPMENT_FETCH_TIMEOUT_MS,
        });
        const items = getIsznrPayloadArray(result.payload)
          .map((item) => normalizeIsznrRegisterRecord(item, resource))
          .filter(Boolean);
        return {
          ok: true,
          ...resource,
          count: items.length,
          items,
          fetchedAt: result.fetchedAt,
        };
      } catch (error) {
        return {
          ok: false,
          ...resource,
          count: 0,
          items: [],
          error: error?.message || "ISZNR FC šifrarnik nije dohvaćen.",
        };
      }
    },
  );
}

function buildIsznrPhysicalFactorsRecordSelectionKeys(item = {}) {
  return [
    item?.id,
    item?.isznrId,
    item?.recordNumber,
    item?.internalId,
    item?.id ? `isznr-work-environment:${item.id}` : "",
    item?.isznrId ? `isznr-work-environment:${item.isznrId}` : "",
  ]
    .map((value) => normalizeInputValue(value))
    .filter(Boolean);
}

function matchesIsznrPhysicalFactorsSelection(item = {}, selectedKeys = new Set()) {
  if (!selectedKeys || selectedKeys.size === 0) {
    return false;
  }
  return buildIsznrPhysicalFactorsRecordSelectionKeys(item)
    .some((key) => selectedKeys.has(key) || selectedKeys.has(key.toLowerCase()));
}

function normalizeIsznrPhysicalFactorsSelection(values = []) {
  return new Set((Array.isArray(values) ? values : [values])
    .flatMap((value) => String(value ?? "").split("|"))
    .map((value) => normalizeInputValue(value))
    .filter(Boolean)
    .flatMap((value) => [value, value.toLowerCase()]));
}

function normalizeIsznrIntegerValue(value, fallback = "") {
  const normalized = normalizeInputValue(value);
  if (!normalized) {
    return fallback;
  }
  const parsed = Number.parseInt(normalized.replace(",", "."), 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function normalizeIsznrGradeValue(value, fallback = 1) {
  if (typeof value === "boolean") {
    return value ? 1 : 0;
  }
  const normalized = normalizeIsznrWorkEnvironmentText(value);
  if (!normalized) {
    return fallback;
  }
  if (normalized === "0" || normalized === "ne" || normalized.includes("ne zadovoljava") || normalized.includes("nezadovoljava")) {
    return 0;
  }
  return 1;
}

function normalizeIsznrIntegerArray(values = []) {
  return Array.from(new Set((Array.isArray(values) ? values : [values])
    .map((value) => {
      if (value && typeof value === "object") {
        return normalizeIsznrIntegerValue(value.id || value.value || value.type || value.code, "");
      }
      return normalizeIsznrIntegerValue(value, "");
    })
    .filter((value) => Number.isFinite(value))));
}

function inferIsznrPhysicalTypesFromRecord(record = {}) {
  const direct = normalizeIsznrIntegerArray(record.typesOfExamination);
  if (direct.length > 0) {
    return direct;
  }
  const labels = (Array.isArray(record.types) ? record.types : [])
    .map((value) => normalizeIsznrWorkEnvironmentText(value));
  const types = [];
  labels.forEach((label) => {
    if (label.includes("mikro")) types.push(1);
    if (label.includes("osvijet") || label.includes("osvjet")) types.push(2);
    if (label.includes("buka")) types.push(3);
    if (label.includes("vibr")) types.push(4);
  });
  return Array.from(new Set(types.length ? types : [1, 2, 3]));
}

function inferIsznrPhysicalHarmfulnessFromTypes(types = []) {
  const harmfulness = [];
  (Array.isArray(types) ? types : []).forEach((type) => {
    if (type === 1) harmfulness.push(4);
    if (type === 2) harmfulness.push(7);
    if (type === 3) harmfulness.push(1);
    if (type === 4) harmfulness.push(2);
  });
  return Array.from(new Set(harmfulness));
}

function getIsznrRelatedId(source = {}, keys = []) {
  for (const key of keys) {
    const value = source?.[key];
    if (value && typeof value === "object") {
      const id = extractIsznrId(value);
      if (id) return id;
    }
    const normalized = normalizeInputValue(value);
    if (/^\d+$/.test(normalized)) {
      return normalized;
    }
  }
  return "";
}

async function fetchIsznrPhysicalFactorsRecordDetails({
  baseUrl = "",
  username = "",
  password = "",
  record = {},
} = {}) {
  const recordId = normalizeInputValue(record?.isznrId || record?.id);
  if (!recordId) {
    return null;
  }
  const spacesResult = await fetchIsznrPagedCollection({
    baseUrl,
    username,
    password,
    resourcePath: "fc_spaces",
    searchParams: { "fcRecord.id": recordId },
    maxPages: 10,
    maxRecords: 200,
  }).catch(() => ({ items: [] }));
  const spaces = getIsznrPayloadArray(spacesResult).length ? getIsznrPayloadArray(spacesResult) : (spacesResult.items || []);
  const spaceDetails = [];
  for (const rawSpace of spaces) {
    const spaceId = extractIsznrId(rawSpace);
    const [finalGrades, microClimaticConditions, illuminations, noises] = await Promise.all([
      fetchIsznrPagedCollection({
        baseUrl,
        username,
        password,
        resourcePath: "fc_final_grades",
        searchParams: { "fcSpace.id": spaceId },
        maxPages: 5,
        maxRecords: 100,
      }).then((result) => result.items || []).catch(() => []),
      fetchIsznrPagedCollection({
        baseUrl,
        username,
        password,
        resourcePath: "fc_micro_climatic_conditions",
        searchParams: { "fcSpace.id": spaceId },
        maxPages: 5,
        maxRecords: 200,
      }).then((result) => result.items || []).catch(() => []),
      fetchIsznrPagedCollection({
        baseUrl,
        username,
        password,
        resourcePath: "fc_illuminations",
        searchParams: { "fcSpace.id": spaceId },
        maxPages: 5,
        maxRecords: 300,
      }).then((result) => result.items || []).catch(() => []),
      fetchIsznrPagedCollection({
        baseUrl,
        username,
        password,
        resourcePath: "fc_noises",
        searchParams: { "fcSpace.id": spaceId },
        maxPages: 5,
        maxRecords: 200,
      }).then((result) => result.items || []).catch(() => []),
    ]);
    spaceDetails.push({
      id: spaceId,
      raw: rawSpace,
      finalGrades,
      microClimaticConditions,
      illuminations,
      noises,
    });
  }
  const vibrations = await fetchIsznrPagedCollection({
    baseUrl,
    username,
    password,
    resourcePath: "fc_vibrations",
    searchParams: { "fcRecord.id": recordId },
    maxPages: 5,
    maxRecords: 120,
  }).then((result) => result.items || []).catch(() => []);

  return {
    recordId,
    spaces: spaceDetails,
    vibrations,
  };
}

function buildIsznrFcSpacePayload(space = {}) {
  const raw = space?.raw && typeof space.raw === "object" ? space.raw : space;
  return {
    name: normalizeInputValue(raw.name || raw.title || "Prostor"),
    description: normalizeInputValue(raw.description || raw.purposeDescription) || "Opis prostora nije posebno naveden.",
    workProcess: normalizeInputValue(raw.workProcess || raw.workProcessDescription || raw.processDescription) || "Opis radnih procesa nije posebno naveden.",
    workEquipment: normalizeInputValue(raw.workEquipment || raw.workEquipmentDescription || raw.equipmentDescription) || "Popis radne opreme nije posebno naveden.",
  };
}

function buildIsznrFcFinalGradePayload(item = {}) {
  return {
    typesOfExamination: normalizeIsznrIntegerValue(item.typesOfExamination || item.type, 1),
    grade: normalizeIsznrGradeValue(item.grade || item.finalGrade, 1),
  };
}

function buildIsznrFcMicroPayload(item = {}) {
  return compactIsznrPayload({
    measuringPlace: normalizeInputValue(item.measuringPlace || item.measurementPlace || item.name) || "Mjerno mjesto",
    airTemperature: normalizeInputValue(item.airTemperature) || "0",
    allowedAirTemperature: normalizeInputValue(item.allowedAirTemperature) || "-",
    relativeAirHumidity: normalizeInputValue(item.relativeAirHumidity) || "0",
    allowedRelativeAirHumidity: normalizeInputValue(item.allowedRelativeAirHumidity) || "-",
    airFlowSpeed: normalizeInputValue(item.airFlowSpeed),
    allowedAirFlowSpeed: normalizeInputValue(item.allowedAirFlowSpeed),
    grade: normalizeIsznrGradeValue(item.grade || item.finalGrade, 1),
  });
}

function buildIsznrFcIlluminationPayload(item = {}) {
  return compactIsznrPayload({
    measuringPlace: normalizeInputValue(item.measuringPlace || item.measurementPlace || item.name) || "Mjerno mjesto",
    generalIllumination: normalizeIsznrIntegerValue(item.generalIllumination, 0),
    additionalIllumination: normalizeIsznrIntegerValue(item.additionalIllumination, ""),
    prescribedIllumination: normalizeIsznrIntegerValue(item.prescribedIllumination, 0),
    grade: normalizeIsznrGradeValue(item.grade || item.finalGrade, 1),
  });
}

function buildIsznrFcNoisePayload(item = {}) {
  return compactIsznrPayload({
    measuringPlace: normalizeInputValue(item.measuringPlace || item.measurementPlace || item.name) || "Mjerno mjesto",
    equivalentNoiseLevel: normalizeInputValue(item.equivalentNoiseLevel) || "0",
    permittedEquivalentNoiseLevel: normalizeInputValue(item.permittedEquivalentNoiseLevel) || "0",
    peakNoise: normalizeInputValue(item.peakNoise),
    noiseExposureTime: normalizeInputValue(item.noiseExposureTime),
    dailyExposureToNoise: normalizeInputValue(item.dailyExposureToNoise),
    customFields: Array.isArray(item.customFields) ? item.customFields : [],
    grade: normalizeIsznrGradeValue(item.grade || item.finalGrade, 1),
  });
}

function buildIsznrFcVibrationPayload(item = {}) {
  const measuringPoints = (Array.isArray(item.measuringPoints) ? item.measuringPoints : [])
    .map((point, index) => ({
      name: normalizeInputValue(point.name) || `Mjerno mjesto ${index + 1}`,
      measuredValueA8: normalizeInputValue(point.measuredValueA8) || "0",
      customFields: Array.isArray(point.customFields) ? point.customFields : [],
      grade: normalizeIsznrGradeValue(point.grade || point.finalGrade, 1),
    }))
    .filter((point) => point.name && point.measuredValueA8);
  return compactIsznrPayload({
    source: normalizeInputValue(item.source) || "Izvor vibracija",
    type: normalizeIsznrIntegerValue(item.type, 1),
    bodyPositions: normalizeIsznrIntegerArray(item.bodyPositions),
    measuringPoints,
  });
}

function buildIsznrPhysicalFactorsFollowUpDrafts(detailsByRecordId = new Map(), selectedRecords = []) {
  const spaceDrafts = [];
  const followUpDrafts = [];
  (Array.isArray(selectedRecords) ? selectedRecords : []).forEach((record) => {
    const recordId = normalizeInputValue(record?.isznrId || record?.id);
    const details = detailsByRecordId.get(recordId);
    if (!details) {
      return;
    }
    details.spaces.forEach((space, index) => {
      const sourceSpaceId = normalizeInputValue(space.id || extractIsznrId(space.raw || {})) || `${recordId}:space:${index + 1}`;
      spaceDrafts.push({
        sourceRecordId: recordId,
        sourceSpaceId,
        payload: buildIsznrFcSpacePayload(space),
      });
      space.finalGrades.forEach((item) => {
        followUpDrafts.push({
          resourcePath: "fc_final_grades",
          scope: "fcSpace",
          sourceSpaceId,
          payload: buildIsznrFcFinalGradePayload(item),
        });
      });
      space.microClimaticConditions.forEach((item) => {
        followUpDrafts.push({
          resourcePath: "fc_micro_climatic_conditions",
          scope: "fcSpace",
          sourceSpaceId,
          payload: buildIsznrFcMicroPayload(item),
        });
      });
      space.illuminations.forEach((item) => {
        followUpDrafts.push({
          resourcePath: "fc_illuminations",
          scope: "fcSpace",
          sourceSpaceId,
          payload: buildIsznrFcIlluminationPayload(item),
        });
      });
      space.noises.forEach((item) => {
        followUpDrafts.push({
          resourcePath: "fc_noises",
          scope: "fcSpace",
          sourceSpaceId,
          payload: buildIsznrFcNoisePayload(item),
        });
      });
    });
    details.vibrations.forEach((item) => {
      followUpDrafts.push({
        resourcePath: "fc_vibrations",
        scope: "fcRecord",
        sourceRecordId: recordId,
        payload: buildIsznrFcVibrationPayload(item),
      });
    });
  });
  return {
    spaceDrafts: spaceDrafts.filter((draft) => draft.payload.name && draft.payload.description && draft.payload.workProcess && draft.payload.workEquipment),
    followUpDrafts,
  };
}

function inferIsznrPhysicalTypesFromManualMeasurements(measurements = []) {
  const types = [];
  (Array.isArray(measurements) ? measurements : []).forEach((measurement) => {
    const type = normalizeIsznrWorkEnvironmentText(measurement?.type);
    if (type.includes("micro") || type.includes("mikro")) types.push(1);
    if (type.includes("illum") || type.includes("osvijet") || type.includes("osvjet")) types.push(2);
    if (type.includes("noise") || type.includes("buka")) types.push(3);
    if (type.includes("vibr")) types.push(4);
  });
  return Array.from(new Set(types));
}

function parseFirstPhysicalFactorNumber(value = "") {
  const match = String(value || "").match(/-?\d+(?:[,.]\d+)?/);
  if (!match) return null;
  const number = Number(match[0].replace(",", "."));
  return Number.isFinite(number) ? number : null;
}

function allowedAirFlowSpeedForAirTemperature(temperature = "") {
  const value = parseFirstPhysicalFactorNumber(temperature);
  if (value === null) return "";
  if (value < 10) return "0,5";
  if (value > 27) return "0,8";
  return "0,6";
}

function normalizeIsznrManualPhysicalFactors(source = {}) {
  const manual = source && typeof source === "object" ? source : {};
  const manualAirTemperature = normalizeInputValue(manual.airTemperature || manual.outsideTemperature);
  const manualRelativeAirHumidity = normalizeInputValue(manual.relativeAirHumidity || manual.relativeHumidity);
  const manualAirFlowSpeed = normalizeInputValue(manual.airFlowSpeed || manual.airflowSpeed);
  const allowedAirFlowSpeed = allowedAirFlowSpeedForAirTemperature(manualAirTemperature);
  const spaces = (Array.isArray(manual.spaces) ? manual.spaces : [])
    .map((space, index) => {
      const name = normalizeInputValue(space?.name || space?.label || space?.title);
      return {
        id: normalizeInputValue(space?.id) || `manual-space-${index + 1}`,
        name,
        description: normalizeInputValue(space?.description) || name || "Prostor",
        workProcess: normalizeInputValue(space?.workProcess || space?.processDescription) || "Redovni radni proces.",
        workEquipment: normalizeInputValue(space?.workEquipment || space?.equipmentDescription) || "Radna oprema prema zatecenom stanju.",
        finalGrade: normalizeIsznrGradeValue(space?.finalGrade || space?.grade, 1),
        temperatureAllowed: normalizeInputValue(space?.temperatureAllowed),
        temperatureMin: normalizeInputValue(space?.temperatureMin) || manualAirTemperature,
        temperatureMax: normalizeInputValue(space?.temperatureMax) || manualAirTemperature,
        humidityAllowed: normalizeInputValue(space?.humidityAllowed),
        humidityMin: normalizeInputValue(space?.humidityMin) || manualRelativeAirHumidity,
        humidityMax: normalizeInputValue(space?.humidityMax) || manualRelativeAirHumidity,
        airflowAllowed: normalizeInputValue(space?.airflowAllowed) || allowedAirFlowSpeed,
        airflowMin: normalizeInputValue(space?.airflowMin) || manualAirFlowSpeed,
        airflowMax: normalizeInputValue(space?.airflowMax) || manualAirFlowSpeed,
        illuminationAllowed: normalizeInputValue(space?.illuminationAllowed),
        illuminationMin: normalizeInputValue(space?.illuminationMin),
        illuminationMax: normalizeInputValue(space?.illuminationMax),
        noiseAllowed: normalizeInputValue(space?.noiseAllowed),
        noiseMin: normalizeInputValue(space?.noiseMin),
        noiseMax: normalizeInputValue(space?.noiseMax),
        handArmVibrationLimit: normalizeInputValue(space?.handArmVibrationLimit),
        handArmVibrationWarning: normalizeInputValue(space?.handArmVibrationWarning),
        handArmVibrationMin: normalizeInputValue(space?.handArmVibrationMin),
        handArmVibrationMax: normalizeInputValue(space?.handArmVibrationMax),
        wholeBodyVibrationLimit: normalizeInputValue(space?.wholeBodyVibrationLimit),
        wholeBodyVibrationWarning: normalizeInputValue(space?.wholeBodyVibrationWarning),
        wholeBodyVibrationMin: normalizeInputValue(space?.wholeBodyVibrationMin),
        wholeBodyVibrationMax: normalizeInputValue(space?.wholeBodyVibrationMax),
      };
    })
    .filter((space) => space.name);
  const measurements = (Array.isArray(manual.measurements) ? manual.measurements : [])
    .map((measurement, index) => ({
      id: normalizeInputValue(measurement?.id) || `manual-measurement-${index + 1}`,
      spaceId: normalizeInputValue(measurement?.spaceId || measurement?.space || measurement?.spaceName),
      type: normalizeIsznrWorkEnvironmentText(measurement?.type || measurement?.kind || "illumination"),
      measuringPlace: normalizeInputValue(measurement?.measuringPlace || measurement?.measurementPlace || measurement?.name) || "Mjerno mjesto",
      measuredValue: normalizeInputValue(measurement?.measuredValue || measurement?.measured || measurement?.value),
      allowedValue: normalizeInputValue(measurement?.allowedValue || measurement?.permittedValue || measurement?.prescribedValue),
      note: normalizeInputValue(measurement?.note),
      finalGrade: normalizeIsznrGradeValue(measurement?.finalGrade || measurement?.grade, 1),
    }))
    .filter((measurement) => measurement.measuringPlace && measurement.measuredValue);
  const typesOfExamination = normalizeIsznrIntegerArray(manual.typesOfExamination || manual.types || [])
    .concat(inferIsznrPhysicalTypesFromManualMeasurements(measurements))
    .filter((value, index, array) => Number.isFinite(value) && array.indexOf(value) === index);
  return {
    location: normalizeInputValue(manual.location),
    startDate: normalizeDateOnlyValue(manual.startDate || manual.inspectionDate),
    endDate: normalizeDateOnlyValue(manual.endDate || manual.issuedDate),
    deadlineForNextExamination: normalizeDateOnlyValue(manual.deadlineForNextExamination || manual.deadline),
    technicalDocumentation: normalizeInputValue(manual.technicalDocumentation),
    methodsProceduresAndNorms: normalizeInputValue(manual.methodsProceduresAndNorms),
    workProcessConditions: normalizeInputValue(manual.workProcessConditions),
    airTemperature: manualAirTemperature,
    relativeAirHumidity: manualRelativeAirHumidity,
    airFlowSpeed: manualAirFlowSpeed,
    typesOfExamination,
    spaces,
    measurements,
  };
}

function getIsznrManualMeasurementResourcePath(type = "") {
  const normalized = normalizeIsznrWorkEnvironmentText(type);
  if (normalized.includes("micro") || normalized.includes("mikro")) return "fc_micro_climatic_conditions";
  if (normalized.includes("noise") || normalized.includes("buka")) return "fc_noises";
  if (normalized.includes("vibr")) return "fc_vibrations";
  return "fc_illuminations";
}

function buildIsznrManualPhysicalMeasurementDraft(measurement = {}, space = {}) {
  const resourcePath = getIsznrManualMeasurementResourcePath(measurement.type);
  const base = {
    measuringPlace: measurement.measuringPlace,
    grade: measurement.finalGrade,
  };
  if (resourcePath === "fc_micro_climatic_conditions") {
    const noteLookup = normalizeIsznrWorkEnvironmentText(measurement.note || measurement.measuringPlace || "");
    const micro = { ...base };
    if (noteLookup.includes("struj") || noteLookup.includes("brzina") || noteLookup.includes("airflow")) {
      micro.airFlowSpeed = measurement.measuredValue;
      micro.allowedAirFlowSpeed = measurement.allowedValue || "-";
    } else if (noteLookup.includes("vlaz") || noteLookup.includes("vlag") || noteLookup.includes("humidity")) {
      micro.relativeAirHumidity = measurement.measuredValue;
      micro.allowedRelativeAirHumidity = measurement.allowedValue || "-";
    } else {
      micro.airTemperature = measurement.measuredValue;
      micro.allowedAirTemperature = measurement.allowedValue || "-";
    }
    return {
      resourcePath,
      scope: "fcSpace",
      payload: buildIsznrFcMicroPayload(micro),
    };
  }
  if (resourcePath === "fc_noises") {
    return {
      resourcePath,
      scope: "fcSpace",
      payload: buildIsznrFcNoisePayload({
        ...base,
        equivalentNoiseLevel: measurement.measuredValue,
        permittedEquivalentNoiseLevel: measurement.allowedValue || "0",
        customFields: measurement.note ? [{ name: "Napomena", value: measurement.note }] : [],
      }),
    };
  }
  if (resourcePath === "fc_vibrations") {
    return {
      resourcePath,
      scope: "fcRecord",
      payload: buildIsznrFcVibrationPayload({
        source: space?.name || measurement.measuringPlace || "Izvor vibracija",
        type: 1,
        measuringPoints: [{
          name: measurement.measuringPlace,
          measuredValueA8: measurement.measuredValue,
          customFields: measurement.note ? [{ name: "Napomena", value: measurement.note }] : [],
          grade: measurement.finalGrade,
        }],
      }),
    };
  }
  return {
    resourcePath,
    scope: "fcSpace",
    payload: buildIsznrFcIlluminationPayload({
      ...base,
      generalIllumination: measurement.measuredValue,
      prescribedIllumination: measurement.allowedValue || "0",
    }),
  };
}

function buildIsznrManualPhysicalFactorsFollowUpDrafts(source = {}) {
  const manual = normalizeIsznrManualPhysicalFactors(source);
  if (manual.measurements.length === 0) {
    return { manual, spaceDrafts: [], followUpDrafts: [] };
  }
  const fallbackSpace = manual.spaces[0] || {
    id: "manual-space-1",
    name: manual.location || "Prostor",
    description: "Prostor",
    workProcess: "Redovni radni proces.",
    workEquipment: "Radna oprema prema zatecenom stanju.",
    finalGrade: 1,
  };
  const spaces = manual.spaces.length ? manual.spaces : (manual.measurements.length ? [fallbackSpace] : []);
  const spaceById = new Map(spaces.map((space) => [normalizeInputValue(space.id || space.name), space]));
  const spaceDrafts = spaces.map((space, index) => ({
    sourceSpaceId: normalizeInputValue(space.id || space.name) || `manual-space-${index + 1}`,
    payload: {
      name: space.name,
      description: space.description,
      workProcess: space.workProcess,
      workEquipment: space.workEquipment,
    },
  }));
  const followUpDrafts = [];
  spaces.forEach((space, index) => {
    followUpDrafts.push({
      resourcePath: "fc_final_grades",
      scope: "fcSpace",
      sourceSpaceId: normalizeInputValue(space.id || space.name) || `manual-space-${index + 1}`,
      payload: buildIsznrFcFinalGradePayload({
        typesOfExamination: manual.typesOfExamination[0] || 2,
        grade: space.finalGrade,
      }),
    });
  });
  manual.measurements.forEach((measurement) => {
    const space = spaceById.get(normalizeInputValue(measurement.spaceId)) || fallbackSpace;
    const draft = buildIsznrManualPhysicalMeasurementDraft(measurement, space);
    followUpDrafts.push({
      ...draft,
      sourceSpaceId: normalizeInputValue(space.id || space.name) || "manual-space-1",
    });
  });
  return { manual, spaceDrafts, followUpDrafts };
}

function buildIsznrPhysicalFactorsPostDraft({
  workOrder = {},
  scopedSnapshot = {},
  isznrResult = {},
  selectedItemIds = [],
  selectAll = false,
  referenceIris = {},
  common = {},
  manualPhysicalFactors = {},
  detailsByRecordId = new Map(),
} = {}) {
  const items = Array.isArray(isznrResult.items) ? isznrResult.items : [];
  const registers = Array.isArray(isznrResult.registers) ? isznrResult.registers : [];
  const selectedKeys = normalizeIsznrPhysicalFactorsSelection(selectedItemIds);
  const selectedRecords = selectedKeys.size > 0
    ? items.filter((item) => matchesIsznrPhysicalFactorsSelection(item, selectedKeys))
    : (selectAll ? items : []);
  const manualFollowUps = buildIsznrManualPhysicalFactorsFollowUpDrafts(manualPhysicalFactors);
  const manual = manualFollowUps.manual;
  const hasManualPhysicalFactors = manualFollowUps.spaceDrafts.length > 0 || manualFollowUps.followUpDrafts.length > 0;
  const latestRecord = getLatestIsznrWorkEquipmentRecord(selectedRecords.length ? selectedRecords : items);
  const todayIso = new Date().toISOString().slice(0, 10);
  const startDate = normalizeDateOnlyValue(common.inspectionDate || manual.startDate || workOrder.executionDate || workOrder.openedDate || workOrder.createdAt) || todayIso;
  const endDate = normalizeDateOnlyValue(common.issuedDate || manual.endDate || workOrder.completionDate || workOrder.completedAt || startDate) || startDate;
  const deadline = normalizeDateOnlyValue(manual.deadlineForNextExamination)
    || normalizeDateOnlyValue(workOrder.dueDate)
    || normalizeDateOnlyValue(latestRecord.deadlineForNextExamination)
    || addMonthsToMobileDate(endDate, "36");
  const companyOib = getWorkOrderCompanyOib(workOrder, scopedSnapshot);
  const companyIri = buildIsznrApiIri("companies", latestRecord.company?.id)
    || normalizeInputValue(referenceIris.companyIri);
  const authorizedCompanyIri = buildIsznrApiIri("authorized_companies", latestRecord.authorizedCompany?.id)
    || normalizeInputValue(referenceIris.authorizedCompanyIri);
  const typesOfExamination = manual.typesOfExamination.length
    ? manual.typesOfExamination
    : inferIsznrPhysicalTypesFromRecord(latestRecord);
  const harmfulness = normalizeIsznrIntegerArray(latestRecord.harmfulness)
    .concat(inferIsznrPhysicalHarmfulnessFromTypes(typesOfExamination))
    .filter((value, index, array) => Number.isFinite(value) && array.indexOf(value) === index);
  const workingEnvironmentObligationRegister = buildIsznrApiIriList("working_environment_obligation_registers", latestRecord.obligationRegisters || latestRecord.workingEnvironmentObligationRegister)
    .concat(buildDefaultIsznrRegisterIris(registers, "working_environment_obligation_registers", 1))
    .filter((value, index, array) => value && array.indexOf(value) === index);
  const healthRequirementRegister = buildIsznrApiIriList("fc_health_requirement_registers", latestRecord.healthRequirementRegisters || latestRecord.healthRequirementRegister)
    .concat(buildDefaultIsznrRegisterIris(registers, "fc_health_requirement_registers", 1))
    .filter((value, index, array) => value && array.indexOf(value) === index);
  const expertPeople = getIsznrPeopleForWorkOrder(scopedSnapshot, workOrder, "expert");
  const signedByPeople = getIsznrPeopleForWorkOrder(scopedSnapshot, workOrder, "holder");
  const instruments = getIsznrMeasurementEquipmentIris(scopedSnapshot);
  const selectedFollowUps = buildIsznrPhysicalFactorsFollowUpDrafts(detailsByRecordId, selectedRecords);
  const followUps = {
    spaceDrafts: selectedFollowUps.spaceDrafts.concat(manualFollowUps.spaceDrafts),
    followUpDrafts: selectedFollowUps.followUpDrafts.concat(manualFollowUps.followUpDrafts),
  };
  const location = normalizeInputValue(common.testingLocation || manual.location || latestRecord.location) || resolveIsznrWorkOrderLocation(workOrder);
  const payload = {
    internalId: normalizeInputValue(workOrder.workOrderNumber || workOrder.number),
    authorizedCompany: authorizedCompanyIri,
    company: companyIri,
    location,
    workingEnvironmentObligationRegister,
    healthRequirementRegister,
    healthRequirementOther: normalizeInputValue(latestRecord.healthRequirementOther),
    harmfulness,
    harmfulnessOther: normalizeInputValue(latestRecord.harmfulnessOther),
    typesOfExamination,
    startDate,
    endDate,
    technicalDocumentation: normalizeInputValue(latestRecord.technicalDocumentation) || "Tehnička dokumentacija i podaci zatečeni na mjestu ispitivanja.",
    airTemperature: normalizeInputValue(common.outsideTemperature || latestRecord.airTemperature) || "0",
    relativeAirHumidity: normalizeInputValue(common.relativeHumidity || latestRecord.relativeAirHumidity) || "0",
    airFlowSpeed: normalizeInputValue(common.airflowSpeed || latestRecord.airFlowSpeed),
    externalConditionsOther: normalizeInputValue(common.externalConditionsOther || latestRecord.externalConditionsOther),
    methodsProceduresAndNorms: normalizeInputValue(latestRecord.methodsProceduresAndNorms) || "Ispitivanje je provedeno prema važećim propisima, normama i pravilima struke.",
    instruments,
    workProcessConditions: normalizeInputValue(latestRecord.workProcessConditions) || "Ispitivanje je provedeno u uvjetima redovitog procesa rada.",
    experts: expertPeople.iris,
    deadlineForNextExamination: deadline,
    deadlineForNextExaminationNote: normalizeInputValue(latestRecord.deadlineForNextExaminationNote),
    signedBy: signedByPeople.iris,
    measuresToEliminateDeficiencies: normalizeInputValue(latestRecord.measuresToEliminateDeficiencies),
  };
  if (manual.technicalDocumentation) payload.technicalDocumentation = manual.technicalDocumentation;
  if (manual.methodsProceduresAndNorms) payload.methodsProceduresAndNorms = manual.methodsProceduresAndNorms;
  if (manual.workProcessConditions) payload.workProcessConditions = manual.workProcessConditions;
  if (manual.airTemperature) payload.airTemperature = manual.airTemperature;
  if (manual.relativeAirHumidity) payload.relativeAirHumidity = manual.relativeAirHumidity;
  if (manual.airFlowSpeed) payload.airFlowSpeed = manual.airFlowSpeed;
  const checklist = [];
  addIsznrDraftChecklistItem(checklist, "authorizedCompany", "Ovlaštena osoba", payload.authorizedCompany, payload.authorizedCompany ? "IRI je preuzet iz FC/IS ZNR podataka." : "Nedostaje IS ZNR ID ovlaštene osobe.", payload.authorizedCompany);
  addIsznrDraftChecklistItem(checklist, "company", "Poslodavac u IS ZNR-u", payload.company, payload.company ? "IRI je preuzet za OIB tvrtke." : `Nedostaje IS ZNR company IRI${companyOib ? ` za OIB ${companyOib}` : ""}.`, payload.company);
  addIsznrDraftChecklistItem(checklist, "location", "Lokacija ispitivanja", payload.location, payload.location ? "Lokacija je popunjena." : "Upiši lokaciju ispitivanja.", payload.location);
  addIsznrDraftChecklistItem(checklist, "registers", "FC propisi i zahtjevi", payload.workingEnvironmentObligationRegister.length > 0 && payload.healthRequirementRegister.length > 0, "Potrebni su radni okoliš obligation i FC health requirement šifarnici.", `${payload.workingEnvironmentObligationRegister.length}/${payload.healthRequirementRegister.length}`);
  addIsznrDraftChecklistItem(checklist, "types", "Vrste FC ispitivanja", payload.typesOfExamination.length > 0, "Potrebno je barem jedno FC ispitivanje: mikroklima, osvijetljenost, buka ili vibracije.", payload.typesOfExamination.join(", "));
  addIsznrDraftChecklistItem(checklist, "dates", "Datumi i rok", Boolean(payload.startDate && payload.endDate && payload.deadlineForNextExamination), "Rok je po defaultu 36 mjeseci od završetka ako RN nema rok.", `${payload.startDate} - ${payload.endDate} / ${payload.deadlineForNextExamination}`);
  addIsznrDraftChecklistItem(checklist, "conditions", "Vanjski i procesni uvjeti", Boolean(payload.airTemperature && payload.relativeAirHumidity && payload.workProcessConditions), "Temperatura, relativna vlažnost i uvjeti procesa rada moraju biti popunjeni.", "");
  addIsznrDraftChecklistItem(checklist, "methods", "Metode i tehnička dokumentacija", Boolean(payload.technicalDocumentation && payload.methodsProceduresAndNorms), "Tehnička dokumentacija i metode/norme moraju biti popunjene.", "");
  addIsznrDraftChecklistItem(checklist, "experts", "Stručnjaci ZNR", payload.experts.length > 0, "Iz People modula se koriste osobe s IS ZNR expert oznakom.", String(payload.experts.length));
  addIsznrDraftChecklistItem(checklist, "signedBy", "Potpisnici zaključne ocjene", payload.signedBy.length > 0, "Iz People modula se koriste nositelji ovlaštenja.", String(payload.signedBy.length));
  addIsznrDraftChecklistItem(checklist, "sourceRecord", "Prethodni FC zapisnik ili novi unos", selectedRecords.length > 0 || hasManualPhysicalFactors, "Odaberi FC zapisnik ili unesi prostore i mjerenja za novi IS ZNR zapis.", selectedRecords.length ? String(selectedRecords.length) : `${manualFollowUps.spaceDrafts.length} prostora / ${manual.measurements.length} mjerenja`);

  const missing = checklist.filter((item) => !item.ready);
  return {
    mode: "post-ready",
    writeEnabled: true,
    ready: missing.length === 0,
    readyCount: checklist.length - missing.length,
    missingCount: missing.length,
    missingLabels: missing.map((item) => item.label),
    checklist,
    companyOib,
    sourceRecordId: normalizeInputValue(latestRecord.isznrId || latestRecord.id),
    sourceRecordNumber: normalizeInputValue(latestRecord.recordNumber),
    selectedItemIds: selectedRecords.flatMap(buildIsznrPhysicalFactorsRecordSelectionKeys).filter(Boolean),
    selectedRecordCount: selectedRecords.length,
    manualRecordCount: hasManualPhysicalFactors ? 1 : 0,
    people: {
      experts: expertPeople,
      signedBy: signedByPeople,
    },
    payload,
    spaceDrafts: followUps.spaceDrafts,
    followUpDrafts: followUps.followUpDrafts,
    followUp: {
      fcRecord: "POST /fc_records",
      spaces: "POST /fc_spaces nakon fcRecord.id",
      measurements: "POST /fc_micro_climatic_conditions, /fc_illuminations, /fc_noises, /fc_vibrations",
      finalGrades: "POST /fc_final_grades",
    },
  };
}

function getWorkOrderCompanyOib(workOrder = {}, scopedSnapshot = {}) {
  const company = (scopedSnapshot.companies ?? [])
    .find((item) => String(item?.id || "") === String(workOrder?.companyId || ""));
  return normalizeIsznrOib(
    workOrder.companyOib
    || workOrder.oib
    || workOrder.companyOIB
    || company?.oib
    || company?.OIB
    || company?.taxNumber
    || company?.vatNumber
    || "",
  );
}

async function fetchIsznrWorkEquipmentForWorkOrder({
  user = null,
  request = null,
  workOrder = {},
  scopedSnapshot = {},
  includeRegisters = false,
  maxRecords = 80,
  postDraftSelection = {},
} = {}) {
  void user;
  const companyOib = getWorkOrderCompanyOib(workOrder, scopedSnapshot);
  if (!companyOib) {
    return {
      ok: true,
      count: 0,
      totalItems: 0,
      items: [],
      registers: [],
      mobileRecords: [],
      options: [],
      companyOib: "",
      fetchedAt: new Date().toISOString(),
      pagesFetched: 0,
      recordsLimited: false,
      message: "RN nema OIB tvrtke pa IS ZNR radna oprema nije dohvaćena.",
    };
  }

  const activeOrganizationId = scopedSnapshot.activeOrganizationId || resolveLightweightRequestedOrganizationId(user, request);
  const storedSettings = await domainRepository.getIsznrApiSettings(activeOrganizationId);
  const result = await fetchIsznrWorkEquipmentList({
    baseUrl: storedSettings?.baseUrl || ISZNR_DEFAULT_API_BASE_URL,
    username: storedSettings?.username || "",
    password: storedSettings?.passwordSecret || "",
    filters: {
      companyOib,
    },
    includeRegisters,
    maxPages: 2,
    maxRecords,
  });
  const mobileRecords = result.items.map(buildMobileIsznrWorkEquipmentRecord);
  const latestRecord = getLatestIsznrWorkEquipmentRecord(result.items);
  const needsReferenceFallback = !latestRecord.company?.id || !latestRecord.authorizedCompany?.id;
  const activeOrganization = (scopedSnapshot.organizations ?? [])
    .find((item) => String(item?.id || "") === String(activeOrganizationId));
  const referenceIris = needsReferenceFallback
    ? await resolveIsznrWorkEquipmentReferenceIris({
      baseUrl: storedSettings?.baseUrl || ISZNR_DEFAULT_API_BASE_URL,
      username: storedSettings?.username || "",
      password: storedSettings?.passwordSecret || "",
      companyOib,
      organizationOib: activeOrganization?.oib || activeOrganization?.OIB || storedSettings?.username || "",
    })
    : {};
  const postDraft = buildIsznrWorkEquipmentPostDraft({
    workOrder,
    scopedSnapshot,
    isznrResult: {
      ...result,
      companyOib,
    },
    selectedItemIds: postDraftSelection.selectedItemIds || postDraftSelection.selectedEquipmentIds || [],
    manualEquipments: postDraftSelection.manualEquipments || postDraftSelection.manualEquipment || [],
    selectAll: Boolean(postDraftSelection.selectAll),
    referenceIris,
  });
  return {
    ...result,
    companyOib,
    mobileRecords,
    options: buildWorkOrderIsznrWorkEquipmentOptions(result.items),
    postDraft,
    message: result.count > 0
      ? ""
      : "IS ZNR nije vratio radnu opremu za OIB tvrtke na ovom RN-u.",
  };
}

