function scoreOpenAiExseMeasurementGroup(group = {}, searchLookup = "", targetKind = "") {
  const groupLookup = getOpenAiMeasurementGroupLookup(group);
  const labelLookup = normalizeOpenAiPolicyKey([
    group.fieldId,
    group.fieldKey,
    group.fieldLabel,
    group.fieldDescription,
  ].join(" "));
  let score = 0;
  if (targetKind === "static" && (
    labelLookup.includes("exse13")
    || labelLookup.includes("otporcijevi")
    || labelLookup.includes("savitljiv")
    || labelLookup.includes("statick")
  )) score += 14;
  if (targetKind === "earthing" && (
    labelLookup.includes("exse12")
    || labelLookup.includes("uzemljen")
  )) score += 14;
  if (groupLookup.includes("exse")) score += 9;
  if (groupLookup.includes("uzemljen")) score += targetKind === "static" ? 2 : 7;
  if (groupLookup.includes("otporcijevi") || groupLookup.includes("savitljiv") || groupLookup.includes("statick")) {
    score += targetKind === "earthing" ? 2 : 7;
  }
  if (groupLookup.includes("exse12")) score += targetKind === "static" ? 1 : 6;
  if (groupLookup.includes("exse13")) score += targetKind === "earthing" ? 1 : 6;
  if (searchLookup.includes("exse") || searchLookup.includes("otporuzemljenja") || searchLookup.includes("otporcijevi")) {
    score += 3;
  }
  return score;
}

function getOpenAiExseMeasurementTarget(columns = [], searchText = "", targetKind = "") {
  const groups = buildOpenAiMeasurementColumnGroups(columns);
  if (!groups.length) {
    return null;
  }
  const normalizedKind = normalizeInputValue(targetKind).toLowerCase();
  const searchLookup = normalizeOpenAiPolicyKey(searchText);
  const candidates = groups
    .map((group) => {
      const placeColumn = findOpenAiMeasurementColumn(group.columns, ["place", "mjernomjesto", "mjesto"]);
      const earthColumn = findOpenAiMeasurementColumn(group.columns, ["earthresistance", "otporuzemljenja", "uzemljenje"]);
      const pipeColumn = findOpenAiMeasurementColumn(group.columns, ["piperesistance", "otporcijevi", "cijevi", "savitljiv"]);
      const electrostaticColumn = findOpenAiMeasurementColumn(group.columns, ["electrostaticfield", "elektrostatickopolje", "statickopolje"]);
      const allowedColumn = findOpenAiMeasurementColumn(group.columns, ["allowedresistance", "dozvoljeniotpor", "dopusteniotpor"]);
      const passColumn = findOpenAiMeasurementColumn(group.columns, ["pass", "ocjena", "ocjenaispravnosti", "zadovoljava", "dane"]);
      const noteColumn = findOpenAiMeasurementColumn(group.columns, ["note", "napomena"]);
      return {
        group,
        placeColumn,
        earthColumn,
        pipeColumn,
        electrostaticColumn,
        allowedColumn,
        passColumn,
        noteColumn,
        score: scoreOpenAiExseMeasurementGroup(group, searchLookup, normalizedKind),
      };
    })
    .filter((candidate) => candidate.placeColumn && (candidate.earthColumn || candidate.pipeColumn));

  return candidates
    .filter((candidate) => candidate.score > 0)
    .sort((left, right) => right.score - left.score)[0] || null;
}

function scoreOpenAiExeiMeasurementGroup(group = {}, searchLookup = "", targetKind = "") {
  const groupLookup = getOpenAiMeasurementGroupLookup(group);
  const labelLookup = normalizeOpenAiPolicyKey([
    group.fieldId,
    group.fieldKey,
    group.fieldLabel,
    group.fieldDescription,
  ].join(" "));
  const normalizedKind = normalizeInputValue(targetKind).toLowerCase();
  const kindTerms = {
    ipk: ["exei12", "zoi1007", "ipk", "impedancijapetlje", "petljekvara"],
    oi: ["exei13", "zoi1003", "otporizolacije", "oi"],
    zuds: ["exei14", "zoi1008", "zuds", "fid", "rcd", "diferencijal"],
    pe: ["exei16", "zoi1005", "kontinuitet", "pevodica", "metalnemase"],
    motors: ["exei17", "zoi1014", "motor", "namoti", "praznoghoda", "agregat"],
    overloade: ["exei18", "bimetal", "preopterecenjemotora", "zastitaodpreopterecenjamotora"],
    overloadd: ["exei19", "exd", "bimetal", "preopterecenjemotora"],
  }[normalizedKind] || [];
  let score = 0;
  if (groupLookup.includes("exei")) score += 6;
  if (labelLookup.includes("cista")) score += 2;
  kindTerms.forEach((term) => {
    if (labelLookup.includes(term)) score += 9;
    else if (groupLookup.includes(term)) score += 5;
    else if (searchLookup.includes(term)) score += 1;
  });
  if (searchLookup.includes("jednopolnashema") || searchLookup.includes("groshema") || searchLookup.includes("razdjelnik")) {
    score += 2;
  }
  return score;
}

function getOpenAiExeiMeasurementTarget(columns = [], searchText = "", targetKind = "") {
  const groups = buildOpenAiMeasurementColumnGroups(columns);
  if (!groups.length) {
    return null;
  }
  const normalizedKind = normalizeInputValue(targetKind).toLowerCase();
  const searchLookup = normalizeOpenAiPolicyKey(searchText);
  const candidates = groups
    .map((group) => {
      const circuitColumn = findOpenAiMeasurementColumn(group.columns, [
        "circuit",
        "strujnikrug",
        "oznakastrujnogkruga",
        "oznakaeluredaja",
        "eluredaj",
        "elektricniuredaj",
      ]);
      const phaseColumn = findOpenAiMeasurementColumn(group.columns, [
        "phasecount",
        "1x3x",
        "jednofazno",
        "trofazno",
      ]);
      const protectionColumn = findOpenAiMeasurementColumn(group.columns, [
        "protectiontype",
        "tipikarakteristika",
        "karakteristika",
        "zastitniuredaj",
        "osigurac",
        "bimetal",
      ]);
      const boardColumn = findOpenAiMeasurementColumn(group.columns, [
        "board",
        "razdjelnik",
        "ormar",
        "gro",
      ]);
      const inColumn = findOpenAiMeasurementColumn(group.columns, [
        "incurrent",
        "nazivnastruja",
      ]);
      const idnColumn = findOpenAiMeasurementColumn(group.columns, [
        "idn",
        "ideltan",
        "diferencijalnastruja",
      ]);
      const testPoint1Column = findOpenAiMeasurementColumn(group.columns, [
        "testpoint1",
        "ispitnomjesto1",
      ]);
      const testPoint2Column = findOpenAiMeasurementColumn(group.columns, [
        "testpoint2",
        "ispitnomjesto2",
      ]);
      const deviceColumn = findOpenAiMeasurementColumn(group.columns, [
        "device",
        "mjerniuredaj",
        "agregat",
        "motor",
        "tvornickibrojagregata",
      ]);
      const manufacturerTypeColumn = findOpenAiMeasurementColumn(group.columns, [
        "manufacturertype",
        "proizvodactip",
        "proizvodac",
        "tip",
      ], [deviceColumn].filter(Boolean));
      const motorSerialColumn = findOpenAiMeasurementColumn(group.columns, [
        "motorserial",
        "tvornickibrojmotora",
        "serijskibroj",
      ]);
      const protectionCertificateColumn = findOpenAiMeasurementColumn(group.columns, [
        "protectioncertificate",
        "vrstazastite",
        "certifikat",
        "atex",
        "iecex",
      ]);
      const score = scoreOpenAiExeiMeasurementGroup(group, searchLookup, normalizedKind);
      return {
        group,
        circuitColumn,
        phaseColumn,
        protectionColumn,
        boardColumn,
        inColumn,
        idnColumn,
        testPoint1Column,
        testPoint2Column,
        deviceColumn,
        manufacturerTypeColumn,
        motorSerialColumn,
        protectionCertificateColumn,
        score,
      };
    })
    .filter((candidate) => {
      if (normalizedKind === "ipk") return candidate.circuitColumn;
      if (normalizedKind === "oi") return candidate.circuitColumn;
      if (normalizedKind === "zuds") return candidate.circuitColumn && (candidate.boardColumn || candidate.inColumn || candidate.idnColumn);
      if (normalizedKind === "pe") return candidate.testPoint1Column || candidate.testPoint2Column;
      if (normalizedKind === "motors") return candidate.deviceColumn;
      if (normalizedKind === "overloade" || normalizedKind === "overloadd") return candidate.circuitColumn || candidate.protectionColumn;
      return false;
    });

  return candidates
    .filter((candidate) => candidate.score > 0)
    .sort((left, right) => right.score - left.score)[0] || null;
}

function cleanOpenAiExeiTextValue(value = "") {
  return normalizeInputValue(value)
    .replace(/[\u2010-\u2015]/g, "-")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
}

function formatOpenAiExeiBoard(value = "") {
  const text = cleanOpenAiExeiTextValue(value).replace(/\s*-\s*/g, "-");
  if (!text) {
    return "";
  }
  return text.toUpperCase();
}

function extractOpenAiExeiBoard(searchText = "") {
  const source = String(searchText || "");
  const match = source.match(/\b(?:GRO|RO\s*-\s*[A-Z0-9]+|RO\s+[A-Z0-9]+|UPS)\b/iu);
  return match ? formatOpenAiExeiBoard(match[0]) : "";
}

function extractOpenAiExeiWireLabel(segment = "") {
  const match = String(segment || "").match(/\bW\s*[-]?\s*\d{1,4}(?:\s*[-]?\s*[A-Z0-9]+)?\b/iu);
  return match ? cleanOpenAiExeiTextValue(match[0]).replace(/\s+/g, "").toUpperCase() : "";
}

function extractOpenAiExeiCircuitReference(segment = "") {
  const text = String(segment || "");
  const patterns = [
    /\b\d+[A-Z]\s*-\s*[A-Z0-9]+(?:\s*-\s*[A-Z0-9]+)?\s*\/\s*\d+[A-Z]?\b/iu,
    /\b\d{1,3}\s*[FKQ]\s*\d{1,3}[A-Z]?\b/iu,
    /\bX\d+\s*[:.-]?\s*\d{1,4}\b/iu,
    /\b(?:K|F|QF|Q)\s*\d+[A-Z]?(?:[./-]\d+)?\b/iu,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) {
      return cleanOpenAiExeiTextValue(match[0]).replace(/\s*([:./-])\s*/g, "$1").toUpperCase();
    }
  }
  return "";
}

function extractOpenAiExeiCableLabel(segment = "") {
  const match = String(segment || "").match(/\b(?:NYY|N2XH|PP00\s*-\s*Y|PP\s*-\s*Y|PPY|H07RN)\s*[-A-Z0-9]*\s*\d+\s*x\s*\d+(?:[,.]\d+)?\s*(?:mm2|mm\^2|mm\u00b2)?\b/iu);
  return match
    ? cleanOpenAiExeiTextValue(match[0])
        .replace(/\s*x\s*/i, "X")
        .replace(/\s*(?:mm2|mm\^2|mm\u00b2)$/iu, "mm2")
        .toUpperCase()
    : "";
}

function extractOpenAiExeiProtectionReference(segment = "") {
  const text = String(segment || "");
  const match = text.match(/\b\d{1,3}\s*[FKQ]\s*\d{1,3}[A-Z]?\b|\b(?:QF|F|Q|K)\s*\d+[A-Z]?(?:[./-]\d+)?\b/iu);
  return match ? cleanOpenAiExeiTextValue(match[0]).replace(/\s+/g, "").toUpperCase() : "";
}

function formatOpenAiExeiBreakerType(value = "") {
  const text = cleanOpenAiExeiTextValue(value).replace(/\s+/g, "").toUpperCase();
  if (!text) {
    return "";
  }
  if (/^[BCD]\d{1,3}(?:A|\/[1234])?$/iu.test(text)) {
    return `Aut ${text}`;
  }
  if (/^[BCD]\d{1,3}\/[1234]A?$/iu.test(text)) {
    return `Aut ${text.replace(/A$/iu, "")}`;
  }
  if (/^(?:AUT|AUTO)\s*/iu.test(value)) {
    return cleanOpenAiExeiTextValue(value).replace(/^auto?\s*/iu, "Aut ");
  }
  return cleanOpenAiExeiTextValue(value);
}

function extractOpenAiExeiProtectionType(segment = "") {
  const text = cleanOpenAiExeiTextValue(segment);
  const rcdMatch = text.match(/\b(?:FID|FI|RCD|ZUDS|RCBO|RCCB|KZS)\s*[-:]?\s*(\d{1,3})\s*A?\s*[\/\\]\s*(\d{2,4})\s*m?A?\b/iu);
  if (rcdMatch) {
    return `${rcdMatch[1]}/${rcdMatch[2]}`;
  }
  const breakerMatch = text.match(/\b[BCD]\s*[-]?\s*\d{1,3}\s*A?(?:\s*[\/\\]\s*[1234])?\b/iu);
  if (breakerMatch) {
    return formatOpenAiExeiBreakerType(breakerMatch[0]);
  }
  const fuseMatch = text.match(/\b(?:osigurac|osigura[c\u010d]|sklopka|zastitni\s+uredaj|zastitni\s+ure[d\u0111]aj)\s*[:=-]?\s*([A-Z0-9./ -]{2,24})/iu);
  return fuseMatch ? formatOpenAiExeiBreakerType(fuseMatch[1]).slice(0, 40) : "";
}

function extractOpenAiExeiRcdRating(segment = "") {
  const text = cleanOpenAiExeiTextValue(segment);
  const match = text.match(/\b(?:FID|FI|RCD|ZUDS|RCBO|RCCB|KZS)?\s*(\d{1,3})\s*A?\s*[\/\\]\s*(\d{2,4})\s*m?A?\b/iu);
  if (!match) {
    return { inCurrent: "", idn: "" };
  }
  return {
    inCurrent: match[1],
    idn: match[2],
  };
}

function inferOpenAiExeiPhaseCount(segment = "") {
  const lookup = normalizeOpenAiPolicyKey(segment);
  if (/\b(?:3\s*~|3P|3-pol|3pol|tropol|trofaz|400\s*V)\b/iu.test(segment) || /\b(?:4|5)\s*x\s*\d/iu.test(segment) || /\b\/\s*3\b/iu.test(segment)) {
    return "3x";
  }
  if (/\b(?:1\s*~|1P|1-pol|1pol|jednopol|jednofaz|230\s*V)\b/iu.test(segment) || /\b2\s*x\s*\d/iu.test(segment) || lookup.includes("jednofaz")) {
    return "1x";
  }
  return "";
}

function mergeOpenAiExeiProtectionLabel(reference = "", type = "") {
  return formatOpenAiExeiBreakerType(type);
}

function isOpenAiExeiRelevantLabel(label = "", segment = "") {
  const lookup = normalizeOpenAiPolicyKey(`${label} ${segment}`);
  return [
    "mjerniuredaj",
    "agregat",
    "generator",
    "crpka",
    "pumpa",
    "procesoragregata",
    "rasvjetaagregata",
    "ump",
    "motor",
    "kompresor",
    "elektroventil",
    "ventil",
    "sonda",
    "senzor",
    "detektor",
    "istakaliste",
    "pretakaliste",
    "spremnik",
    "rezervoar",
    "separator",
    "ventilacija",
    "punionica",
    "gorivo",
    "eurosuper",
    "eurodiesel",
    "unplpg",
    "unp",
    "lpg",
    "exzona",
    "zona0",
    "zona1",
    "zona2",
    "rounp",
    "elektromotornipogon",
    "displaybrojilo",
  ].some((term) => lookup.includes(term));
}

function cleanOpenAiExeiCircuitLabel(value = "") {
  return cleanOpenAiExeiTextValue(value)
    .replace(/\bure[d\u0111]aj\b/giu, "uredaj")
    .replace(/\bRO\s*-\s*UNP\b/giu, "RO-UNP")
    .replace(/\s+/g, " ")
    .slice(0, 140)
    .trim();
}

function extractOpenAiExeiContextSegment(source = "", index = 0) {
  const text = String(source || "");
  const lineStart = Math.max(0, text.lastIndexOf("\n", index) + 1);
  const nextBreak = text.indexOf("\n", index);
  const lineEnd = nextBreak >= 0 ? nextBreak : text.length;
  const line = text.slice(lineStart, lineEnd);
  if (cleanOpenAiExeiTextValue(line)) {
    return line;
  }
  return text.slice(Math.max(0, index - 180), Math.min(text.length, index + 260));
}

function buildOpenAiExeiCircuitName(entry = {}) {
  const detailParts = [];
  const labelLookup = normalizeOpenAiPolicyKey(entry.label);
  if (entry.wire && !labelLookup.includes(normalizeOpenAiPolicyKey(entry.wire))) {
    detailParts.push(entry.wire);
  }
  if (entry.cable && !labelLookup.includes(normalizeOpenAiPolicyKey(entry.cable))) {
    detailParts.push(entry.cable);
  }
  const reference = entry.circuitReference || entry.protectionReference || "";
  if (reference && !labelLookup.includes(normalizeOpenAiPolicyKey(reference))) {
    detailParts.push(reference);
  }
  const consumer = cleanOpenAiExeiCircuitLabel(entry.label);
  const details = Array.from(new Set(detailParts.map(cleanOpenAiExeiTextValue).filter(Boolean))).join(", ");
  return [consumer, details].filter(Boolean).join("\n").slice(0, 180).trim();
}

function normalizeOpenAiExeiConsumerLabel(label = "", segment = "") {
  const text = cleanOpenAiExeiCircuitLabel(label);
  const segmentLookup = normalizeOpenAiPolicyKey(`${text} ${segment}`);
  const aggregateMatch = text.match(/\bagregat\s*(\d{1,3})\b/iu);
  if (aggregateMatch && (segmentLookup.includes("motor") || segmentLookup.includes("elektromotornipogon"))) {
    return `Agregat ${aggregateMatch[1]} - motor`;
  }
  if (aggregateMatch && segmentLookup.includes("rasvjeta")) {
    return `Agregat ${aggregateMatch[1]} - rasvjeta`;
  }
  if (aggregateMatch && segmentLookup.includes("display")) {
    return `Agregat ${aggregateMatch[1]} - display brojilo`;
  }
  return text;
}

function hasOpenAiExeiCircuitEvidence(entry = {}) {
  return Boolean(
    entry?.circuitReference
    || entry?.wire
    || entry?.cable
    || entry?.protectionReference
    || entry?.protectionType
  );
}

function extractOpenAiExeiEntriesFromText(searchText = "") {
  const source = String(searchText || "").replace(/\r/g, "\n");
  if (!source.trim() || !/(?:exei|jednopol|shema|gro|mjerni\s+ure[d\u0111]aj|agregat|pumpa|crpka|ump|motor|kompresor|elektroventil|sonda|senzor|detektor|punionica|ro\s*-\s*unp|unp|lpg|ex\s*zona)/iu.test(source)) {
    return [];
  }
  const board = extractOpenAiExeiBoard(source);
  const entries = [];
  const seen = new Set();
  const pushEntry = (rawLabel = "", segment = "", index = 0) => {
    const label = normalizeOpenAiExeiConsumerLabel(rawLabel, segment);
    if (!label || label.length < 3 || !isOpenAiExeiRelevantLabel(label, segment)) {
      return;
    }
    const circuitReference = extractOpenAiExeiCircuitReference(segment);
    const wire = extractOpenAiExeiWireLabel(segment);
    const cable = extractOpenAiExeiCableLabel(segment);
    const protectionReference = extractOpenAiExeiProtectionReference(segment);
    const protectionType = mergeOpenAiExeiProtectionLabel(protectionReference, extractOpenAiExeiProtectionType(segment));
    const rcd = extractOpenAiExeiRcdRating(segment);
    const phaseCount = inferOpenAiExeiPhaseCount(`${segment} ${cable} ${protectionType}`);
    const key = normalizeOpenAiPolicyKey(`${board} ${wire} ${label}`);
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    entries.push({
      label,
      board,
      circuitReference,
      wire,
      cable,
      protectionReference,
      circuit: "",
      protectionType,
      phaseCount,
      inCurrent: rcd.inCurrent,
      idn: rcd.idn,
      segment: cleanOpenAiExeiTextValue(segment),
      order: index,
    });
  };

  const patterns = [
    /\bmjerni\s+ure[d\u0111]aj\s+[0-9A-Z./-]+(?:\s*\([^)]+\))?(?:\s+\d{2,8})?/giu,
    /\b(?:procesor\s+agregata|rasvjeta\s+agregata|elektromotorni\s+pogon|display\s+brojilo|RO\s*-\s*UNP|agregat|generator|crpka|pumpa|UMP|motor|kompresor|elektroventil|ventil|sonda|senzor|detektor|punionica|istakali[s\u0161]te|pretakali[s\u0161]te|spremnik|rezervoar|separator|ventilacija|LPG|UNP|Ex\s+zona|zona\s*[012]|Eurosuper|Eurodiesel|gorivo)[^,;\n.]{0,80}/giu,
  ];
  patterns.forEach((pattern) => {
    Array.from(source.matchAll(pattern)).forEach((match) => {
      pushEntry(match[0], extractOpenAiExeiContextSegment(source, match.index || 0), match.index || 0);
    });
  });

  source
    .split(/\r?\n|[;]+/g)
    .map((segment) => cleanOpenAiExeiTextValue(segment))
    .filter(Boolean)
    .forEach((segment, index) => {
      if (!isOpenAiExeiRelevantLabel(segment, segment)) {
        return;
      }
      const labelMatch = segment.match(/\b(?:mjerni\s+ure[d\u0111]aj\s+[0-9A-Z./-]+(?:\s*\([^)]+\))?(?:\s+\d{2,8})?|RO\s*-\s*UNP|agregat\s+\d+|pumpa\s+\d+|crpka\s+\d+|motor\s+\d+|kompresor\s+\d+|elektroventil|ventil|sonda|senzor|detektor|punionica|spremnik|rezervoar|separator|ventilacija|LPG|UNP|Ex\s+zona|zona\s*[012])\b/iu);
      pushEntry(labelMatch ? labelMatch[0] : segment, segment, source.length + index);
    });

  return entries
    .sort((left, right) => left.order - right.order)
    .slice(0, 120)
    .map((entry) => ({
      ...entry,
      circuit: buildOpenAiExeiCircuitName(entry),
    }))
    .filter((entry) => entry.circuit || entry.label);
}

function buildOpenAiExeiRowsForTarget(target = {}, entries = [], targetKind = "", sourceFile = "") {
  const normalizedKind = normalizeInputValue(targetKind).toLowerCase();
  return entries
    .map((entry) => {
      const values = {};
      if (normalizedKind === "ipk") {
        if (!hasOpenAiExeiCircuitEvidence(entry)) {
          return null;
        }
        if (target.circuitColumn) values[target.circuitColumn.columnId || target.circuitColumn.key] = entry.circuit || entry.label;
        if (target.phaseColumn && entry.phaseCount) values[target.phaseColumn.columnId || target.phaseColumn.key] = entry.phaseCount;
        if (target.protectionColumn && entry.protectionType) values[target.protectionColumn.columnId || target.protectionColumn.key] = entry.protectionType;
      } else if (normalizedKind === "oi") {
        if (!hasOpenAiExeiCircuitEvidence(entry)) {
          return null;
        }
        if (target.circuitColumn) values[target.circuitColumn.columnId || target.circuitColumn.key] = entry.circuit || entry.label;
      } else if (normalizedKind === "zuds") {
        if (!entry.inCurrent && !entry.idn) {
          return null;
        }
        if (target.boardColumn && entry.board) values[target.boardColumn.columnId || target.boardColumn.key] = entry.board;
        if (target.circuitColumn) values[target.circuitColumn.columnId || target.circuitColumn.key] = entry.circuit || entry.label;
        if (target.inColumn && entry.inCurrent) values[target.inColumn.columnId || target.inColumn.key] = entry.inCurrent;
        if (target.idnColumn && entry.idn) values[target.idnColumn.columnId || target.idnColumn.key] = entry.idn;
      } else if (normalizedKind === "motors") {
        if (target.deviceColumn) values[target.deviceColumn.columnId || target.deviceColumn.key] = entry.label || entry.circuit;
      } else if (normalizedKind === "overloade" || normalizedKind === "overloadd") {
        const lookup = normalizeOpenAiPolicyKey(`${entry.label} ${entry.segment}`);
        if (!entry.protectionType && !lookup.includes("bimetal") && !lookup.includes("motor")) {
          return null;
        }
        if (target.circuitColumn) values[target.circuitColumn.columnId || target.circuitColumn.key] = entry.circuit || entry.label;
        if (target.protectionColumn && entry.protectionType) values[target.protectionColumn.columnId || target.protectionColumn.key] = entry.protectionType;
      }
      return Object.keys(values).length > 0
        ? {
            values,
            orderedValues: [],
            confidence: entry.protectionType || entry.phaseCount || entry.inCurrent ? "medium" : "low",
            sourceFile,
          }
        : null;
    })
    .filter(Boolean);
}

function buildOpenAiExeiMeasurementSuggestions(columns = [], searchText = "", sourceFile = "") {
  const entries = extractOpenAiExeiEntriesFromText(searchText);
  if (!entries.length) {
    return [];
  }
  return ["ipk", "oi", "zuds", "motors", "overloade", "overloadd"]
    .map((targetKind) => {
      const target = getOpenAiExeiMeasurementTarget(columns, searchText, targetKind);
      const rows = target ? buildOpenAiExeiRowsForTarget(target, entries, targetKind, sourceFile) : [];
      return target && rows.length
        ? {
            fieldId: target.group.fieldId,
            fieldKey: target.group.fieldKey,
            fieldLabel: target.group.fieldLabel,
            rows,
            confidence: "medium",
            sourceFile,
          }
        : null;
    })
    .filter(Boolean);
}

function capitalizeOpenAiMeasurementPlace(value = "") {
  const text = normalizeInputValue(value);
  if (!text) {
    return "";
  }
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function parseOpenAiSprPlaceEntry(value = "") {
  let text = normalizeInputValue(value)
    .replace(/[–—]/g, "-")
    .replace(/^(?:i|te|pa|zatim)\s+/i, "")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
  if (!text) {
    return null;
  }

  let lampCount = "";
  const countMatch = text.match(/^(.*?)(?:\s*[-:]\s*|\s+)(\d{1,4})\s*(?:kom(?:ada)?|lamp\w*|svjetilj\w*)?$/iu);
  if (countMatch && normalizeInputValue(countMatch[1])) {
    text = normalizeInputValue(countMatch[1]);
    lampCount = countMatch[2];
  }

  const place = capitalizeOpenAiMeasurementPlace(text);
  return place ? { place, lampCount } : null;
}

function splitOpenAiSprPlaceList(value = "") {
  const rawParts = normalizeInputValue(value)
    .replace(/[()]/g, "")
    .split(/[;,]/g)
    .flatMap((part) => {
      const cleanPart = normalizeInputValue(part);
      if (!cleanPart) {
        return [];
      }
      if (!/[\/-]/.test(cleanPart) && /\s+i\s+/i.test(cleanPart)) {
        return cleanPart.split(/\s+i\s+/i);
      }
      return [cleanPart];
    });

  const seen = new Set();
  return rawParts
    .map(parseOpenAiSprPlaceEntry)
    .filter(Boolean)
    .filter((entry) => {
      const key = normalizeOpenAiPolicyKey(entry.place);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function extractOpenAiSprPlacesFromText(searchText = "") {
  const source = String(searchText || "");
  const matches = [];
  const patterns = [
    /(?:mjerna|mjernih)\s+mjesta?[^()]{0,180}\(([^)]+)\)/giu,
    /tablici\s*1[^()]{0,220}\(([^)]+)\)/giu,
    /evidentiran\w*\s+su[^()]{0,180}\(([^)]+)\)/giu,
  ];
  patterns.forEach((pattern) => {
    Array.from(source.matchAll(pattern)).forEach((match) => {
      matches.push(...splitOpenAiSprPlaceList(match[1]));
    });
  });

  const seen = new Set();
  return matches.filter((entry) => {
    const key = normalizeOpenAiPolicyKey(entry.place);
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function parseOpenAiTzinPlaceEntry(value = "") {
  let text = normalizeInputValue(value)
    .replace(/[â€“â€”]/g, "-")
    .replace(/^(?:i|te|pa|zatim)\s+/i, "")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
  if (!text) {
    return null;
  }
  let buttonCount = "";
  const countMatch = text.match(/^(.*?)(?:\s*[-:]\s*|\s+)(\d{1,4})\s*(?:kom(?:ada)?|tipkal\w*|gljiv\w*)?$/iu);
  if (countMatch && normalizeInputValue(countMatch[1])) {
    text = normalizeInputValue(countMatch[1]);
    buttonCount = countMatch[2];
  }
  const place = capitalizeOpenAiMeasurementPlace(text);
  return place ? { place, buttonCount: buttonCount || "1" } : null;
}

function splitOpenAiTzinPlaceList(value = "") {
  const seen = new Set();
  return normalizeInputValue(value)
    .replace(/[()]/g, "")
    .split(/[;,]/g)
    .flatMap((part) => {
      const cleanPart = normalizeInputValue(part);
      if (!cleanPart) {
        return [];
      }
      if (!/[\/-]/.test(cleanPart) && /\s+i\s+/i.test(cleanPart)) {
        return cleanPart.split(/\s+i\s+/i);
      }
      return [cleanPart];
    })
    .map(parseOpenAiTzinPlaceEntry)
    .filter(Boolean)
    .filter((entry) => {
      const key = normalizeOpenAiPolicyKey(entry.place);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function extractOpenAiTzinPlacesFromText(searchText = "") {
  const source = String(searchText || "");
  if (!/(?:tzin|tipkal|isklop)/iu.test(source)) {
    return [];
  }
  const matches = [];
  const patterns = [
    /(?:mjerna|mjernih|mjesta)\s+(?:mjesta\s+)?tipkala[^()]{0,180}\(([^)]+)\)/giu,
    /tipkal\w*[^()]{0,220}\(([^)]+)\)/giu,
    /tablici\s*1[^()]{0,220}(?:tipkal|isklop)[^()]{0,120}\(([^)]+)\)/giu,
  ];
  patterns.forEach((pattern) => {
    Array.from(source.matchAll(pattern)).forEach((match) => {
      matches.push(...splitOpenAiTzinPlaceList(match[1]));
    });
  });
  return matches;
}

function extractOpenAiSzomRowsFromText(searchText = "") {
  const source = String(searchText || "");
  if (!/(?:szom|zastit[ae]\s+od\s+djelovanja\s+munje|riz|rdop|metaln\w+\s+mas)/iu.test(source)) {
    return [];
  }
  const rows = [];
  const seen = new Set();
  source
    .split(/\r?\n|[;]+/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment, index) => {
      const lookup = normalizeOpenAiPolicyKey(segment);
      const hasSzomValue = /\bRiz\d?\b|\bRdop\d?\b|\d{1,3}[,.]\d{1,3}\s*(?:ohm|oma|Ω)?/iu.test(segment);
      if (!hasSzomValue) {
        return;
      }
      const target = lookup.includes("povezanostmetalnihmasa") || lookup.includes("metalnemase")
        ? "metalMassBonding"
        : lookup.includes("skrivenispoj")
          ? "hiddenJoint"
          : "grounding";
      const cleaned = removeMobileSzomVoiceTargetWords(segment)
        .replace(/\bRiz\d?\b|\bRdop\d?\b/giu, " ")
        .replace(/[<>=]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      const parsed = parseMobileSzomVoiceValue(cleaned);
      const place = cleanMobileSzomVoicePlace(parsed.placeText);
      const key = normalizeOpenAiPolicyKey(`${target} ${place} ${parsed.value} ${index}`);
      if (!place || !key || seen.has(key)) {
        return;
      }
      seen.add(key);
      rows.push({ place, value: parsed.value, target });
    });
  return rows.slice(0, 120);
}

function cleanOpenAiSprMeasurementValue(value = "") {
  return normalizeInputValue(value)
    .replace(/[≥]/g, ">=")
    .replace(/[≤]/g, "<=")
    .replace(/\s+/g, "")
    .trim();
}

function extractOpenAiSprGlobalValues(searchText = "") {
  const text = String(searchText || "").replace(/\s+/g, " ");
  const eiMatch = text.match(/\bEi\b\s*(?:=|:)?\s*([<>≤≥]?\s*\d+(?:[,.]\d+)?)/iu);
  const eiminMatch = text.match(/\bEimin\b\s*(?:=|:)?\s*([<>≤≥]?\s*\d+(?:[,.]\d+)?)/iu);
  let pass = "";
  if (/\bne\s+zadovoljava\b|\bnije\s+zadovoljav|\bne\s+zadovoljavaju\b/iu.test(text)) {
    pass = "NE";
  } else if (/\bzadovoljava\b|\(da\)|\bocjenom\s+da\b/iu.test(text)) {
    pass = "DA";
  }
  return {
    ei: eiMatch ? cleanOpenAiSprMeasurementValue(eiMatch[1]) : "",
    eimin: eiminMatch ? cleanOpenAiSprMeasurementValue(eiminMatch[1]) : "",
    pass,
  };
}

function isOpenAiPdfFile(file = {}) {
  const name = String(file?.name || file?.fileName || "").toLowerCase();
  const type = String(file?.type || file?.fileType || "").toLowerCase();
  return Boolean(file?.contentDataUrl || file?.dataUrl) && (
    type.includes("pdf") ||
    name.endsWith(".pdf")
  );
}

function normalizeOpenAiPdfText(value = "") {
  return normalizeInputValue(value)
    .replace(/[\u2010-\u2015]/g, "-")
    .replace(/\u2212/g, "-")
    .replace(/\u2264/g, "<=")
    .replace(/\u2265/g, ">=")
    .replace(/\s+/g, " ")
    .trim();
}

async function extractOpenAiPdfTextRows(file = {}) {
  const dataUrl = file.contentDataUrl || file.dataUrl || "";
  const buffer = readOpenAiDataUrlBuffer(dataUrl);
  if (!buffer.length) {
    return [];
  }

  let pdf = null;
  try {
    pdf = await getPdfJsDocument({
      data: new Uint8Array(buffer),
      disableFontFace: true,
      useSystemFonts: true,
    }).promise;

    const rows = [];
    for (let pageIndex = 1; pageIndex <= pdf.numPages; pageIndex += 1) {
      const page = await pdf.getPage(pageIndex);
      const content = await page.getTextContent({ normalizeWhitespace: true });
      const items = (Array.isArray(content?.items) ? content.items : [])
        .map((item) => ({
          text: normalizeOpenAiPdfText(item?.str || ""),
          x: Number(item?.transform?.[4] || 0),
          y: Number(item?.transform?.[5] || 0),
        }))
        .filter((item) => item.text);

      items
        .sort((left, right) => Math.abs(right.y - left.y) > 2.2 ? right.y - left.y : left.x - right.x)
        .forEach((item) => {
          const existing = rows.find((row) => row.page === pageIndex && Math.abs(row.y - item.y) <= 2.2);
          if (existing) {
            existing.tokens.push(item);
            existing.y = (existing.y + item.y) / 2;
          } else {
            rows.push({ page: pageIndex, y: item.y, tokens: [item], text: "" });
          }
        });
    }

    return rows
      .map((row) => {
        const tokens = row.tokens
          .slice()
          .sort((left, right) => left.x - right.x)
          .map((token) => ({ ...token, text: normalizeOpenAiPdfText(token.text) }))
          .filter((token) => token.text);
        return {
          page: row.page,
          y: row.y,
          tokens,
          text: normalizeOpenAiPdfText(tokens.map((token) => token.text).join(" ")),
        };
      })
      .filter((row) => row.text)
      .sort((left, right) => left.page - right.page || right.y - left.y);
  } catch (error) {
    console.warn("SPR PDF parser skipped file:", file?.name || file?.fileName || "pdf", error?.message || error);
    return [];
  } finally {
    if (pdf?.destroy) {
      await pdf.destroy().catch(() => {});
    }
  }
}

function isOpenAiSprParserTableContext(text = "") {
  const lookup = normalizeOpenAiPolicyKey(text);
  return lookup.includes("sigurnosnerasvjete") ||
    lookup.includes("sigurnosnarasvjet") ||
    lookup.includes("protupanicnerasvjete") ||
    lookup.includes("protupanicnarasvjet") ||
    lookup.includes("mjernamjestasigurnosne") ||
    lookup.includes("tablica1mjernamjesta");
}

function isOpenAiSprMeasurementValue(value = "") {
  const text = String(value || "").trim();
  return /^[<>]=?\s*\d+(?:[,.]\d+)?$/i.test(text) ||
    /^\d+(?:[,.]\d+)?$/i.test(text);
}

function cleanOpenAiSprPassValue(value = "") {
  const text = normalizeOpenAiPdfText(value).replace(/\s+/g, "").toUpperCase();
  if (text === "DA" || text === "D") return "DA";
  if (text === "NE" || text === "N") return "NE";
  if (text === "NP" || text === "N/A") return text;
  return "";
}

function parseOpenAiSprMeasurementRowText(row = {}) {
  const text = normalizeOpenAiPdfText(row.text);
  if (!/^\d{1,4}\b/.test(text) || /\bR\.?\s*br\b/i.test(text) || /\bMjesto\s+ispitivanja\b/i.test(text)) {
    return null;
  }

  const valuePattern = "([<>]=?\\s*\\d+(?:[,.]\\d+)?|\\d+(?:[,.]\\d+)?)";
  const rowPattern = new RegExp(`^\\s*(\\d{1,4})\\s+(.+?)\\s+(\\d{1,4})\\s+${valuePattern}\\s+${valuePattern}\\s+(DA|NE|NP|N/A)\\b`, "iu");
  const match = text.match(rowPattern);
  if (match) {
    return {
      rowNumber: match[1],
      place: capitalizeOpenAiMeasurementPlace(match[2]),
      lampCount: match[3],
      ei: cleanOpenAiSprMeasurementValue(match[4]),
      eimin: cleanOpenAiSprMeasurementValue(match[5]),
      pass: cleanOpenAiSprPassValue(match[6]),
    };
  }

  const tokens = (Array.isArray(row.tokens) ? row.tokens : [])
    .map((token) => normalizeOpenAiPdfText(token.text))
    .filter(Boolean);
  if (tokens.length < 6 || !/^\d{1,4}$/.test(tokens[0])) {
    return null;
  }

  const passIndex = tokens.findLastIndex((token) => cleanOpenAiSprPassValue(token));
  if (passIndex < 5) {
    return null;
  }
  const beforePass = tokens.slice(1, passIndex);
  const measurementIndexes = beforePass
    .map((token, index) => ({ token, index }))
    .filter((item) => isOpenAiSprMeasurementValue(item.token));
  if (measurementIndexes.length < 3) {
    return null;
  }

  const [lampItem, eiItem, eiminItem] = measurementIndexes.slice(-3);
  const place = capitalizeOpenAiMeasurementPlace(beforePass.slice(0, lampItem.index).join(" "));
  if (!place || !/^\d{1,4}$/.test(lampItem.token)) {
    return null;
  }

  return {
    rowNumber: tokens[0],
    place,
    lampCount: lampItem.token,
    ei: cleanOpenAiSprMeasurementValue(eiItem.token),
    eimin: cleanOpenAiSprMeasurementValue(eiminItem.token),
    pass: cleanOpenAiSprPassValue(tokens[passIndex]),
  };
}

function parseOpenAiSprMeasurementRowsFromPdfRows(rows = []) {
  const allText = rows.map((row) => row.text).join("\n");
  if (!isOpenAiSprParserTableContext(allText)) {
    return [];
  }

  const seen = new Set();
  return rows
    .map(parseOpenAiSprMeasurementRowText)
    .filter(Boolean)
    .filter((row) => {
      const key = normalizeOpenAiPolicyKey(`${row.rowNumber} ${row.place} ${row.lampCount} ${row.ei} ${row.eimin} ${row.pass}`);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function buildOpenAiParserMeasurementRows(target = {}, parsedRows = [], sourceFile = "") {
  return parsedRows
    .map((row) => {
      const values = {};
      if (target.placeColumn) {
        values[target.placeColumn.columnId || target.placeColumn.key] = row.place;
      }
      if (target.lampColumn) {
        values[target.lampColumn.columnId || target.lampColumn.key] = row.lampCount;
      }
      if (target.eiColumn && row.ei) {
        values[target.eiColumn.columnId || target.eiColumn.key] = row.ei;
      }
      if (target.eiminColumn && row.eimin) {
        values[target.eiminColumn.columnId || target.eiminColumn.key] = row.eimin;
      }
      if (target.passColumn && row.pass) {
        values[target.passColumn.columnId || target.passColumn.key] = row.pass;
      }
      return {
        values,
        orderedValues: [],
        confidence: "high",
        sourceFile,
      };
    })
    .filter((row) => Object.keys(row.values).length > 0);
}

function parseOpenAiTzinMeasurementRowText(value = "") {
  const tokens = normalizeInputValue(value).split(/\s+/g).filter(Boolean);
  if (tokens.length < 4 || !/^\d{1,4}$/.test(tokens[0])) {
    return null;
  }
  const passIndex = tokens.findLastIndex((token) => cleanOpenAiSprPassValue(token));
  if (passIndex < 2) {
    return null;
  }
  const beforePass = tokens.slice(1, passIndex);
  const countIndex = beforePass.findLastIndex((token) => /^\d{1,4}$/.test(token));
  if (countIndex <= 0) {
    return null;
  }
  const place = capitalizeOpenAiMeasurementPlace(beforePass.slice(0, countIndex).join(" "));
  if (!place) {
    return null;
  }
  const type = normalizeInputValue(beforePass.slice(countIndex + 1).join(" ")) || "-";
  return {
    rowNumber: tokens[0],
    place,
    buttonCount: beforePass[countIndex],
    buttonType: type,
    pass: cleanOpenAiSprPassValue(tokens[passIndex]),
  };
}

function parseOpenAiTzinMeasurementRowsFromPdfRows(rows = []) {
  const allText = rows.map((row) => row.text).join("\n");
  if (!/(?:tzin|tipkal|isklop)/iu.test(allText)) {
    return [];
  }
  const seen = new Set();
  return rows
    .map((row) => parseOpenAiTzinMeasurementRowText(row.text))
    .filter(Boolean)
    .filter((row) => {
      const key = normalizeOpenAiPolicyKey(`${row.rowNumber} ${row.place} ${row.buttonCount} ${row.buttonType} ${row.pass}`);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function buildOpenAiTzinParserMeasurementRows(target = {}, parsedRows = [], sourceFile = "") {
  return parsedRows
    .map((row) => {
      const values = {};
      if (target.placeColumn) values[target.placeColumn.columnId || target.placeColumn.key] = row.place;
      if (target.buttonColumn) values[target.buttonColumn.columnId || target.buttonColumn.key] = row.buttonCount || "1";
      if (target.typeColumn) values[target.typeColumn.columnId || target.typeColumn.key] = row.buttonType || "-";
      if (target.passColumn) values[target.passColumn.columnId || target.passColumn.key] = row.pass || "DA";
      return {
        values,
        orderedValues: [],
        confidence: "high",
        sourceFile,
      };
    })
    .filter((row) => Object.keys(row.values).length > 0);
}

function parseOpenAiSzomMeasurementRowText(value = "") {
  const text = normalizeInputValue(value);
  if (!/^\d{1,4}\s+/.test(text) || !/\d{1,3}[,.]\d{1,3}/.test(text)) {
    return null;
  }
  const target = getMobileSzomVoiceTarget(text);
  const tokens = text.split(/\s+/g).filter(Boolean);
  const firstValueIndex = tokens.findIndex((token, index) => index > 0 && /^\d{1,3}[,.]\d{1,3}$/.test(token));
  if (firstValueIndex <= 1) {
    return null;
  }
  const place = capitalizeOpenAiMeasurementPlace(cleanMobileSzomVoicePlace(tokens.slice(1, firstValueIndex).join(" ")));
  const valueToken = tokens[firstValueIndex];
  if (!place || !valueToken) {
    return null;
  }
  return {
    rowNumber: tokens[0],
    place,
    value: valueToken.replace(".", ","),
    target,
  };
}

function parseOpenAiSzomMeasurementRowsFromPdfRows(rows = []) {
  const allText = rows.map((row) => row.text).join("\n");
  if (!/(?:szom|zastit[ae]\s+od\s+djelovanja\s+munje|riz|rdop)/iu.test(allText)) {
    return [];
  }
  const seen = new Set();
  return rows
    .map((row) => parseOpenAiSzomMeasurementRowText(row.text))
    .filter(Boolean)
    .filter((row) => {
      const key = normalizeOpenAiPolicyKey(`${row.rowNumber} ${row.target} ${row.place} ${row.value}`);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function buildOpenAiSzomParserMeasurementRows(target = {}, parsedRows = [], sourceFile = "") {
  return parsedRows
    .map((row) => {
      const values = {};
      if (row.target === "metalMassBonding") {
        if (target.massColumn) values[target.massColumn.columnId || target.massColumn.key] = row.place;
        if (target.riz3Column) values[target.riz3Column.columnId || target.riz3Column.key] = row.value;
        if (target.rdop3Column) values[target.rdop3Column.columnId || target.rdop3Column.key] = "<2";
      } else if (row.target === "hiddenJoint") {
        if (target.hiddenColumn) values[target.hiddenColumn.columnId || target.hiddenColumn.key] = row.place;
        if (target.riz2Column) values[target.riz2Column.columnId || target.riz2Column.key] = row.value;
        if (target.rdop2Column) values[target.rdop2Column.columnId || target.rdop2Column.key] = "<1";
      } else {
        if (target.placeColumn) values[target.placeColumn.columnId || target.placeColumn.key] = row.place;
        if (target.rizColumn) values[target.rizColumn.columnId || target.rizColumn.key] = row.value;
        if (target.rdopColumn) values[target.rdopColumn.columnId || target.rdopColumn.key] = "<10";
      }
      if (target.passColumn) values[target.passColumn.columnId || target.passColumn.key] = "DA";
      return {
        values,
        orderedValues: [],
        confidence: "high",
        sourceFile,
      };
    })
    .filter((row) => Object.keys(row.values).length > 0);
}

function cleanOpenAiExseMeasurementValue(value = "") {
  const text = normalizeOpenAiPdfText(value)
    .replace(/[=]/g, "")
    .replace(/\s+/g, "")
    .trim();
  if (!text || text === "-") {
    return "";
  }
  return text.replace(".", ",");
}

function inferOpenAiExseRowKind(row = {}) {
  const placeLookup = normalizeOpenAiPolicyKey(row.place);
  const pipeValue = cleanOpenAiExseMeasurementValue(row.pipeResistance);
  const allowedNumeric = Number.parseFloat(String(row.allowedResistance || "").replace(",", "."));
  if (
    pipeValue
    || placeLookup.includes("agregat")
    || placeLookup.includes("cijev")
    || placeLookup.includes("istak")
    || (Number.isFinite(allowedNumeric) && allowedNumeric <= 1)
  ) {
    return "static";
  }
  return "earthing";
}

function parseOpenAiExseMeasurementRowText(row = {}) {
  const text = normalizeOpenAiPdfText(row.text);
  if (
    !/^\d{1,4}\b/.test(text)
    || /\bR\.?\s*br\b/i.test(text)
    || /\bMjerno\s+mjesto\b/i.test(text)
    || /\bOtpor\s+(?:uzemljenja|cijevi)\b/i.test(text)
  ) {
    return null;
  }
  const tokens = text.split(/\s+/g).filter(Boolean);
  if (tokens.length < 7 || !/^\d{1,4}$/.test(tokens[0])) {
    return null;
  }
  const passIndex = tokens.findLastIndex((token) => cleanOpenAiSprPassValue(token));
  if (passIndex < 6) {
    return null;
  }
  const beforePass = tokens.slice(1, passIndex);
  if (beforePass.length < 5) {
    return null;
  }
  const valueTokens = beforePass.slice(-4);
  const place = normalizeInputValue(beforePass.slice(0, -4).join(" "));
  if (!place) {
    return null;
  }
  const parsed = {
    rowNumber: tokens[0],
    place: capitalizeOpenAiMeasurementPlace(place),
    earthResistance: cleanOpenAiExseMeasurementValue(valueTokens[0]),
    pipeResistance: cleanOpenAiExseMeasurementValue(valueTokens[1]),
    electrostaticField: cleanOpenAiExseMeasurementValue(valueTokens[2]),
    allowedResistance: cleanOpenAiExseMeasurementValue(valueTokens[3]),
    pass: cleanOpenAiSprPassValue(tokens[passIndex]) || "DA",
  };
  parsed.target = inferOpenAiExseRowKind(parsed);
  return parsed;
}

function parseOpenAiExseMeasurementRowsFromPdfRows(rows = []) {
  const allText = rows.map((row) => row.text).join("\n");
  if (!/(?:exse|otpor\s+uzemljenja|otpor\s+cijevi|elektrostatick|elektrostati[cč]k|savitljivih\s+cijevi)/iu.test(allText)) {
    return [];
  }
  const seen = new Set();
  return rows
    .map(parseOpenAiExseMeasurementRowText)
    .filter(Boolean)
    .filter((row) => {
      const key = normalizeOpenAiPolicyKey(`${row.target} ${row.rowNumber} ${row.place} ${row.earthResistance} ${row.pipeResistance}`);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function buildOpenAiExseParserMeasurementRows(target = {}, parsedRows = [], sourceFile = "") {
  return parsedRows
    .map((row) => {
      const values = {};
      if (target.placeColumn) values[target.placeColumn.columnId || target.placeColumn.key] = row.place;
      if (target.earthColumn && row.earthResistance) values[target.earthColumn.columnId || target.earthColumn.key] = row.earthResistance;
      if (target.pipeColumn && row.pipeResistance) values[target.pipeColumn.columnId || target.pipeColumn.key] = row.pipeResistance;
      if (target.electrostaticColumn && row.electrostaticField) values[target.electrostaticColumn.columnId || target.electrostaticColumn.key] = row.electrostaticField;
      if (target.allowedColumn) values[target.allowedColumn.columnId || target.allowedColumn.key] = row.allowedResistance || (row.target === "static" ? "1" : "10");
      if (target.passColumn) values[target.passColumn.columnId || target.passColumn.key] = row.pass || "DA";
      return {
        values,
        orderedValues: [],
        confidence: "high",
        sourceFile,
      };
    })
    .filter((row) => Object.keys(row.values).length > 0);
}

function getOpenAiParserProfilesForService(serviceCode = "") {
  const normalized = normalizeInputValue(serviceCode).toUpperCase();
  if (normalized === "SPR") return ["SPR"];
  if (normalized === "TZIN") return ["TZIN"];
  if (normalized === "SZOM") return ["SZOM"];
  if (normalized === "EXSE") return ["EXSE_EARTHING", "EXSE_STATIC"];
  if (normalized === "EXEI") return ["EXEI"];
  if (normalized) return [];
  return ["SPR", "TZIN", "SZOM", "EXSE_EARTHING", "EXSE_STATIC", "EXEI"];
}

async function buildOpenAiParserPlan(body = {}, user = null) {
  const columns = Array.isArray(body.columns) ? body.columns : [];
  const files = (Array.isArray(body.files) ? body.files : []).filter(isOpenAiPdfFile);
  if (!columns.length || !files.length) {
    return null;
  }

  const parsedByFile = [];
  for (const file of files.slice(0, OPENAI_MAX_INLINE_FILE_COUNT)) {
    const pdfRows = await extractOpenAiPdfTextRows(file);
    const searchText = pdfRows.map((row) => row.text).join("\n");
    const sprRows = parseOpenAiSprMeasurementRowsFromPdfRows(pdfRows);
    const tzinRows = parseOpenAiTzinMeasurementRowsFromPdfRows(pdfRows);
    const szomRows = parseOpenAiSzomMeasurementRowsFromPdfRows(pdfRows);
    const exseRows = parseOpenAiExseMeasurementRowsFromPdfRows(pdfRows);
    if (sprRows.length || tzinRows.length || szomRows.length || exseRows.length) {
      parsedByFile.push({
        fileName: normalizeInputValue(file?.name || file?.fileName || "zapisnik.pdf"),
        sprRows,
        tzinRows,
        szomRows,
        exseRows,
        searchText,
      });
    }
  }

  if (!parsedByFile.length) {
    return null;
  }

  const searchText = parsedByFile.map((item) => item.searchText).join("\n");
  const sourceFile = parsedByFile.map((item) => item.fileName).filter(Boolean).join(", ").slice(0, 240);
  let target = null;
  let profile = "";
  let rows = [];
  for (const candidateProfile of getOpenAiParserProfilesForService(getOpenAiDocumentationServiceCode(body))) {
    if (candidateProfile === "SPR") {
      const candidateTarget = getOpenAiSprMeasurementTarget(columns, searchText);
      const parsedRows = candidateTarget ? parsedByFile.flatMap((item) => item.sprRows) : [];
      const candidateRows = candidateTarget ? buildOpenAiParserMeasurementRows(candidateTarget, parsedRows, sourceFile) : [];
      if (candidateRows.length) {
        target = candidateTarget;
        profile = candidateProfile;
        rows = candidateRows;
        break;
      }
    }
    if (candidateProfile === "TZIN") {
      const candidateTarget = getOpenAiTzinMeasurementTarget(columns, searchText);
      const parsedRows = candidateTarget ? parsedByFile.flatMap((item) => item.tzinRows) : [];
      const candidateRows = candidateTarget ? buildOpenAiTzinParserMeasurementRows(candidateTarget, parsedRows, sourceFile) : [];
      if (candidateRows.length) {
        target = candidateTarget;
        profile = candidateProfile;
        rows = candidateRows;
        break;
      }
    }
    if (candidateProfile === "SZOM") {
      const candidateTarget = getOpenAiSzomMeasurementTarget(columns, searchText);
      const parsedRows = candidateTarget ? parsedByFile.flatMap((item) => item.szomRows) : [];
      const candidateRows = candidateTarget ? buildOpenAiSzomParserMeasurementRows(candidateTarget, parsedRows, sourceFile) : [];
      if (candidateRows.length) {
        target = candidateTarget;
        profile = candidateProfile;
        rows = candidateRows;
        break;
      }
    }
    if (candidateProfile === "EXSE_EARTHING" || candidateProfile === "EXSE_STATIC") {
      const targetKind = candidateProfile === "EXSE_STATIC" ? "static" : "earthing";
      const candidateTarget = getOpenAiExseMeasurementTarget(columns, searchText, targetKind);
      const targetLookup = normalizeOpenAiPolicyKey([
        candidateTarget?.group?.fieldId,
        candidateTarget?.group?.fieldKey,
        candidateTarget?.group?.fieldLabel,
        candidateTarget?.group?.fieldDescription,
      ].join(" "));
      const targetLooksStatic = targetLookup.includes("exse13")
        || targetLookup.includes("otporcijevi")
        || targetLookup.includes("savitljiv")
        || targetLookup.includes("statick");
      const targetLooksEarthing = targetLookup.includes("exse12") || targetLookup.includes("uzemljen");
      if ((targetKind === "earthing" && targetLooksStatic) || (targetKind === "static" && targetLooksEarthing && !targetLooksStatic)) {
        continue;
      }
      const parsedRows = candidateTarget
        ? parsedByFile.flatMap((item) => item.exseRows).filter((row) => row.target === targetKind)
        : [];
      const candidateRows = candidateTarget ? buildOpenAiExseParserMeasurementRows(candidateTarget, parsedRows, sourceFile) : [];
      if (candidateRows.length) {
        target = candidateTarget;
        profile = targetKind === "static" ? "EXSE otpor cijevi" : "EXSE uzemljenje";
        rows = candidateRows;
        break;
      }
    }
  }
  if (!rows.length) {
    return null;
  }

  const result = {
    fieldSuggestions: [],
    measurementSuggestions: [
      {
        fieldId: target.group.fieldId,
        fieldKey: target.group.fieldKey,
        fieldLabel: target.group.fieldLabel,
        rows,
        confidence: "high",
        sourceFile,
      },
    ],
    warnings: [
      `PDF parser je pronasao ${rows.length} ${profile} redaka. Provjeri preview prije upisa u Gridline.`,
    ],
    summary: `Parser je pripremio ${rows.length} redaka iz stare ${profile} PDF tablice.`,
  };

  return {
    ok: true,
    dryRun: false,
    tokenSpend: "none",
    provider: "parser",
    endpoint: "local-pdf-parser",
    model: "pdfjs-table-parser",
    modelTier: "parser",
    modelLabel: "PDF parser",
    preparedAt: new Date().toISOString(),
    actorId: user?.id ?? null,
    organizationId: String(body.organizationId || ""),
    summary: {
      files: files.length,
      parsedFiles: parsedByFile.length,
      fields: Array.isArray(body.fields) ? body.fields.length : 0,
      columns: columns.length,
      workOrderId: String(body.workOrderId || ""),
      purpose: String(body.purpose || "document-field-prefill").slice(0, 120),
    },
    result,
    outputText: JSON.stringify(result),
    nextStep: `Parser je nasao ${profile} tablicu. Prikazi preview i potvrdi upis u Gridline.`,
  };
}

function augmentOpenAiDocumentMeasurementSuggestions(result = null, body = {}, outputText = "") {
  const baseResult = result && typeof result === "object" && !Array.isArray(result)
    ? { ...result }
    : { summary: truncateOpenAiText(outputText, 1000) };
  if (hasOpenAiMeasurementSuggestionRows(baseResult)) {
    return baseResult;
  }

  const columns = Array.isArray(body.columns) ? body.columns : [];
  const searchText = buildOpenAiResultSearchText(baseResult, outputText);
  if (!columns.length) {
    return baseResult;
  }

  const sourceFile = (Array.isArray(body.files) ? body.files : [])
    .map((file) => normalizeInputValue(file?.name))
    .filter(Boolean)
    .join(", ")
    .slice(0, 240);
  const parserProfiles = getOpenAiParserProfilesForService(getOpenAiDocumentationServiceCode(body));
  if (!parserProfiles.length && getOpenAiDocumentationServiceCode(body)) {
    return baseResult;
  }
  let target = getOpenAiSprMeasurementTarget(columns, searchText);
  let label = "SPR";
  let rows = [];

  if (parserProfiles.includes("SPR") && target) {
    const places = extractOpenAiSprPlacesFromText(searchText);
    const globalValues = extractOpenAiSprGlobalValues(searchText);
    rows = places.map((entry) => {
      const values = {};
      values[target.placeColumn.columnId || target.placeColumn.key] = entry.place;
      if (target.lampColumn && entry.lampCount) {
        values[target.lampColumn.columnId || target.lampColumn.key] = entry.lampCount;
      }
      if (target.eiColumn && globalValues.ei) {
        values[target.eiColumn.columnId || target.eiColumn.key] = globalValues.ei;
      }
      if (target.eiminColumn && globalValues.eimin) {
        values[target.eiminColumn.columnId || target.eiminColumn.key] = globalValues.eimin;
      }
      if (target.passColumn && globalValues.pass) {
        values[target.passColumn.columnId || target.passColumn.key] = globalValues.pass;
      }
      return {
        values,
        confidence: "medium",
        sourceFile,
      };
    }).filter((row) => Object.keys(row.values).length > 0);
  }

  if (!rows.length && parserProfiles.includes("TZIN")) {
    target = getOpenAiTzinMeasurementTarget(columns, searchText);
    label = "TZIN";
    const places = target ? extractOpenAiTzinPlacesFromText(searchText) : [];
    const globalValues = extractOpenAiSprGlobalValues(searchText);
    rows = places.map((entry) => {
      const values = {};
      values[target.placeColumn.columnId || target.placeColumn.key] = entry.place;
      if (target.buttonColumn && entry.buttonCount) {
        values[target.buttonColumn.columnId || target.buttonColumn.key] = entry.buttonCount;
      }
      if (target.typeColumn) {
        values[target.typeColumn.columnId || target.typeColumn.key] = "-";
      }
      if (target.passColumn) {
        values[target.passColumn.columnId || target.passColumn.key] = globalValues.pass || "DA";
      }
      return {
        values,
        confidence: "medium",
        sourceFile,
      };
    }).filter((row) => Object.keys(row.values).length > 0);
  }

  if (!rows.length && parserProfiles.includes("SZOM")) {
    target = getOpenAiSzomMeasurementTarget(columns, searchText);
    label = "SZOM";
    const szomRows = target ? extractOpenAiSzomRowsFromText(searchText) : [];
    rows = szomRows.map((entry) => {
      const values = {};
      if (entry.target === "metalMassBonding") {
        if (target.massColumn) values[target.massColumn.columnId || target.massColumn.key] = entry.place;
        if (target.riz3Column && entry.value) values[target.riz3Column.columnId || target.riz3Column.key] = entry.value;
        if (target.rdop3Column) values[target.rdop3Column.columnId || target.rdop3Column.key] = "<2";
      } else if (entry.target === "hiddenJoint") {
        if (target.hiddenColumn) values[target.hiddenColumn.columnId || target.hiddenColumn.key] = entry.place;
        if (target.riz2Column && entry.value) values[target.riz2Column.columnId || target.riz2Column.key] = entry.value;
        if (target.rdop2Column) values[target.rdop2Column.columnId || target.rdop2Column.key] = "<1";
      } else {
        if (target.placeColumn) values[target.placeColumn.columnId || target.placeColumn.key] = entry.place;
        if (target.rizColumn && entry.value) values[target.rizColumn.columnId || target.rizColumn.key] = entry.value;
        if (target.rdopColumn) values[target.rdopColumn.columnId || target.rdopColumn.key] = "<10";
      }
      if (target.passColumn) {
        values[target.passColumn.columnId || target.passColumn.key] = "DA";
      }
      return {
        values,
        confidence: "medium",
        sourceFile,
      };
    }).filter((row) => Object.keys(row.values).length > 0);
  }

  if (!rows.length && parserProfiles.includes("EXEI")) {
    const exeiSuggestions = buildOpenAiExeiMeasurementSuggestions(columns, searchText, sourceFile);
    if (exeiSuggestions.length) {
      const rowCount = exeiSuggestions.reduce((total, suggestion) => total + (Array.isArray(suggestion.rows) ? suggestion.rows.length : 0), 0);
      baseResult.measurementSuggestions = [
        ...(Array.isArray(baseResult.measurementSuggestions) ? baseResult.measurementSuggestions : []),
        ...exeiSuggestions,
      ];
      baseResult.warnings = Array.from(new Set([
        ...(Array.isArray(baseResult.warnings) ? baseResult.warnings : []),
        `NexAI je iz EXEI sheme/opisa prepoznao ${rowCount} strukturnih redaka. Provjeri ih prije upisa jer slike sheme ne popunjavaju mjerne vrijednosti.`,
      ].map(normalizeInputValue).filter(Boolean)));
      if (!normalizeInputValue(baseResult.summary)) {
        baseResult.summary = `NexAI je pripremio EXEI strukturne retke iz sheme/opisa.`;
      }
      return baseResult;
    }
  }

  if (!target || !rows.length) {
    return baseResult;
  }

  const measurementSuggestion = {
    fieldId: target.group.fieldId,
    fieldKey: target.group.fieldKey,
    fieldLabel: target.group.fieldLabel,
    rows,
    confidence: "medium",
    sourceFile,
  };
  baseResult.measurementSuggestions = [
    ...(Array.isArray(baseResult.measurementSuggestions) ? baseResult.measurementSuggestions : []),
    measurementSuggestion,
  ];
  baseResult.warnings = Array.from(new Set([
    ...(Array.isArray(baseResult.warnings) ? baseResult.warnings : []),
    `NexAI je iz sazetka prepoznao ${rows.length} ${label} redaka za tablicu; provjeri prijenos iz starog PDF-a.`,
  ].map(normalizeInputValue).filter(Boolean)));
  if (!normalizeInputValue(baseResult.summary)) {
    baseResult.summary = `NexAI je prepoznao ${rows.length} ${label} redaka za Gridline tablicu.`;
  }
  return baseResult;
}

function buildOpenAiSafeErrorMessage(error) {
  const message = String(error?.message || "OpenAI poziv nije uspio.").replace(/sk-[A-Za-z0-9_\-]+/g, "[redacted]");
  return message.slice(0, 600);
}

async function buildOpenAiLivePlan(body = {}, user = null) {
  const startedAt = Date.now();
  const config = getOpenAiRuntimeConfig();
  if (!config.keyConfigured) {
    const error = new Error("OpenAI API ključ nije postavljen na serveru.");
    error.statusCode = 503;
    throw error;
  }
  if (!config.liveCallsEnabled) {
    const error = new Error("OpenAI live pozivi nisu uključeni.");
    error.statusCode = 409;
    throw error;
  }

  const modelTier = normalizeOpenAiModelTier(body.modelTier || body.modelPreference?.tier);
  const modelTierOption = getOpenAiModelTierOption(modelTier);
  const selectedModel = normalizeOpenAiModelSlug(body.model || body.modelPreference?.model || getOpenAiModelForTier(modelTier, config));
  const serviceCode = getOpenAiDocumentationServiceCode(body);
  const sourcePolicy = buildOpenAiSourcePolicy(
    Array.isArray(body.files) ? body.files : [],
    serviceCode,
  );
  if (!selectedModel) {
    const error = new Error("OpenAI model nije konfiguriran.");
    error.statusCode = 503;
    throw error;
  }

  const requestBody = {
    model: selectedModel,
    instructions: [
      "Ti si AI asistent za SafeNexus zapisnike.",
      "Analiziras stare zapisnike, PDF-ove, slike i tekst te predlazes vrijednosti za web polja i Excel tablice.",
      "Odgovori samo validnim JSON objektom. Ako nisi siguran, confidence mora biti low i vrijednost ne smije biti izmisljena.",
      "Ako korisnikov context sadrzi purpose-specific expectedJsonShape, vrati JSON tocno u tom obliku i koristi settings kao prioritetna pravila.",
      "Za polja ciji je fieldType longtext ili ciji ai.format trazi dugi opis nemoj vracati kratki sazetak. Postuj trazenu duljinu, broj odlomaka i strukturu iz aiDescription, ai.format i validationRules.",
      "Za obicna text polja fieldSuggestions[].value uvijek mora biti plain text string. Za longtext polja fieldSuggestions[].value mora biti jedan string: plain text ili, ako ai.format izricito trazi rich text/HTML, siguran HTML fragment s oznakama p, h2, h3, strong, em, ul, ol, li, table, tr, th, td i br. Nemoj vracati blocks, rows, markdown JSON ni objekt za longtext polja.",
      "Za polje fields[].type === system_description value u fieldSuggestions mora biti objekt oblika { blocks: [{ title, sectionSubtitle, rows: [{ subtitle, description, lineCount }] }] }. Razdvoji vece cjeline u vise blocks s jasnim naslovima. Koristi redove iz fields[].systemRows kada odgovaraju, npr. Proizvodac, Tip, Teh. podaci i opisni red, ali izostavi prazne/neprimjenjive redove. Opci blok smije imati samo opisni red. Nemoj vracati cijeli Opis sustava kao obican string ako su dostupni blokovi.",
      "Za Excel tablice measurementSuggestions.fieldId mora biti tocno jedan fieldId iz measurementColumns, a kljucevi u rows[].values moraju biti tocni columnId ili key iz measurementColumns. Popunjavaj samo kolone navedene u measurementColumns; sve druge kolone, formule i rucni unos ignoriraj. Nemoj vracati genericki kljuc columnKey.",
      "Ako u starom SPR zapisniku vidis tablicu mjernih mjesta sigurnosne/protupanicne rasvjete, obavezno vrati retke u measurementSuggestions; sazetak bez measurementSuggestions nije dovoljan.",
      "Ako u starom TZIN zapisniku vidis tablicu tipkala za isklop, obavezno vrati mjerna mjesta i broj tipkala u measurementSuggestions za TZIN Gridline tablicu.",
      "Ako u starom SZOM zapisniku vidis tablicu mjerenja sustava zastite od munje, obavezno vrati retke u measurementSuggestions. Elektricnu povezanost metalnih masa popuni samo kada izvor izricito navodi povezanost masa/metalne mase.",
      ...buildOpenAiDocumentationServiceInstructions(body),
      ...sourcePolicy.instructions,
      ...buildOpenAiPurposeInstructions(body),
      "Za hrvatske poslovne dokumente koristi hrvatski jezik i zadrzi strucne nazive.",
    ].join(" "),
    input: [
      {
        role: "user",
        content: buildOpenAiResponseInputContent(body, user, selectedModel),
      },
    ],
    max_output_tokens: getOpenAiMaxOutputTokens(modelTier, serviceCode, body.files),
  };

  const requestStartedAt = Date.now();
  const openAiResponse = await fetch(config.endpoint, {
    method: "POST",
    headers: {
      authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
      "content-type": "application/json",
    },
    body: JSON.stringify(requestBody),
  });
  const responseReceivedAt = Date.now();

  const responseText = await openAiResponse.text();
  let payload = null;
  try {
    payload = responseText ? JSON.parse(responseText) : {};
  } catch {
    payload = { output_text: responseText };
  }

  if (!openAiResponse.ok) {
    const errorMessage = payload?.error?.message || payload?.message || responseText || "OpenAI poziv nije uspio.";
    const error = new Error(buildOpenAiSafeErrorMessage({ message: errorMessage }));
    error.statusCode = openAiResponse.status || 502;
    throw error;
  }

  const outputText = extractOpenAiResponseText(payload);
  const parsedResult = parseOpenAiJsonObject(outputText);
  const augmentedResult = augmentOpenAiDocumentMeasurementSuggestions(parsedResult, body, outputText);
  const sanitizedResult = sanitizeOpenAiSourcePolicySuggestions(
    sanitizeOpenAiExeiMeasurementSuggestionKeys(augmentedResult, body),
    sourcePolicy,
  );
  const result = parsedResult || hasOpenAiMeasurementSuggestionRows(sanitizedResult)
    ? sanitizedResult
    : null;
  const parsedAt = Date.now();
  const fields = Array.isArray(body.fields) ? body.fields : [];
  const columns = Array.isArray(body.columns) ? body.columns : [];
  const files = Array.isArray(body.files) ? body.files : [];

  return {
    ok: true,
    dryRun: false,
    tokenSpend: "enabled",
    provider: config.provider,
    endpoint: config.endpoint,
    model: selectedModel,
    modelTier,
    modelLabel: modelTierOption.label,
    modelStrength: modelTierOption.strength,
    preparedAt: new Date().toISOString(),
    timings: {
      totalMs: parsedAt - startedAt,
      openAiMs: responseReceivedAt - requestStartedAt,
      parseMs: parsedAt - responseReceivedAt,
    },
    actorId: user?.id ?? null,
    organizationId: String(body.organizationId || ""),
    summary: {
      files: files.length,
      inlineFilesSent: files.filter((file) => file?.contentDataUrl).length,
      fields: fields.length,
      columns: columns.length,
      workOrderId: String(body.workOrderId || ""),
      purpose: String(body.purpose || "document-field-prefill").slice(0, 120),
    },
    result,
    outputText,
    sourcePolicy,
    usage: payload?.usage ?? null,
    nextStep: result
      ? "OpenAI je vratio JSON prijedloge. Provjeri ih prije finalnog exporta."
      : "OpenAI je odgovorio, ali JSON nije automatski parsiran. Provjeri outputText.",
  };
}

function canUseOpenAiIntegration(user) {
  return canManageMasterData(user) || canManageWorkOrders(user);
}

function canManagePeopleTrainingRecords(user) {
  return canManageMasterData(user) || isClientPortalUser(user);
}

function getActorOrganizationIds(user = {}) {
  const values = [
    user.organizationId,
    ...(Array.isArray(user.organizationIds)
      ? user.organizationIds
      : String(user.organizationIds || "")
        .split(",")
        .map((value) => value.trim())),
  ];
  return Array.from(new Set(values.map(normalizeInputValue).filter(Boolean)));
}

function resolveLightweightRequestedOrganizationId(user = {}, request = null) {
  const requestedOrganizationId = getRequestedOrganizationId(request);
  const actorOrganizationIds = getActorOrganizationIds(user);

  if (normalizeRole(user?.role) === ROLE_SUPER_ADMIN) {
    return requestedOrganizationId || actorOrganizationIds[0] || "";
  }

  if (requestedOrganizationId && actorOrganizationIds.includes(String(requestedOrganizationId))) {
    return requestedOrganizationId;
  }

  return actorOrganizationIds[0] || "";
}

async function getServiceCatalogMutationScope(user, request) {
  const activeOrganizationId = resolveLightweightRequestedOrganizationId(user, request);
  if (!activeOrganizationId) {
    return {
      activeOrganizationId: "",
      canManage: false,
      appRolePermissions: [],
    };
  }

  if (canManageMasterData(user) || Boolean(user?.appPermissions?.["serviceCatalog.create"])) {
    return {
      activeOrganizationId,
      canManage: true,
      appRolePermissions: [],
    };
  }

  const appRolePermissions = typeof domainRepository.getAppRolePermissionsForOrganization === "function"
    ? await domainRepository.getAppRolePermissionsForOrganization(activeOrganizationId)
    : (await getScopedState(user, request)).scopedSnapshot?.appRolePermissions ?? [];

  return {
    activeOrganizationId,
    canManage: hasAppPermission(user, appRolePermissions, "serviceCatalog.create"),
    appRolePermissions,
  };
}

async function getLightweightScopedPermissionScope(user, request, permissionKey = "") {
  const activeOrganizationId = resolveLightweightRequestedOrganizationId(user, request);
  if (!activeOrganizationId) {
    return {
      activeOrganizationId: "",
      canUse: false,
      appRolePermissions: [],
    };
  }

  if (canManageMasterData(user) || Boolean(user?.appPermissions?.[permissionKey])) {
    return {
      activeOrganizationId,
      canUse: true,
      appRolePermissions: [],
    };
  }

  const appRolePermissions = typeof domainRepository.getAppRolePermissionsForOrganization === "function"
    ? await domainRepository.getAppRolePermissionsForOrganization(activeOrganizationId)
    : (await getScopedState(user, request)).scopedSnapshot?.appRolePermissions ?? [];

  return {
    activeOrganizationId,
    canUse: hasAppPermission(user, appRolePermissions, permissionKey),
    appRolePermissions,
  };
}

async function getLightweightOrganizationContext(user, request) {
  const activeOrganizationId = resolveLightweightRequestedOrganizationId(user, request);
  if (!activeOrganizationId) {
    return {
      activeOrganizationId: "",
      currentOrganization: null,
      organizations: [],
    };
  }

  if (typeof tenantRepository.getOrganizationContext === "function") {
    return tenantRepository.getOrganizationContext(user, activeOrganizationId);
  }

  const organizations = Array.isArray(user?.organizations) ? user.organizations : [];
  return {
    activeOrganizationId,
    currentOrganization: organizations.find((item) => String(item.id) === String(activeOrganizationId)) ?? null,
    organizations,
  };
}

function buildPublicIsznrApiSettingsPayload(settings = {}) {
  return {
    baseUrl: String(settings?.baseUrl || "").trim(),
    username: String(settings?.username || "").trim(),
    hasPassword: Boolean(settings?.hasPassword || settings?.passwordSecret),
    updatedAt: settings?.updatedAt || null,
  };
}

async function canUseScopedAppPermission(user, request, permissionKey = "") {
  if (canManageMasterData(user)) {
    return true;
  }

  const { scopedSnapshot } = await getScopedState(user, request);
  return canUseScopedSnapshotAppPermission(user, scopedSnapshot, permissionKey);
}

function canUseScopedSnapshotAppPermission(user, scopedSnapshot, permissionKey = "") {
  return canManageMasterData(user)
    || Boolean(scopedSnapshot?.appPermissions?.[permissionKey])
    || hasAppPermission(user, scopedSnapshot?.appRolePermissions ?? [], permissionKey);
}

function canUseAnyScopedSnapshotAppPermission(user, scopedSnapshot, permissionKeys = []) {
  return (Array.isArray(permissionKeys) ? permissionKeys : [permissionKeys])
    .filter(Boolean)
    .some((permissionKey) => canUseScopedSnapshotAppPermission(user, scopedSnapshot, permissionKey));
}

async function canUseAnyScopedAppPermission(user, request, permissionKeys = []) {
  if (canManageMasterData(user)) {
    return true;
  }

  const { scopedSnapshot } = await getScopedState(user, request);
  return canUseAnyScopedSnapshotAppPermission(user, scopedSnapshot, permissionKeys);
}

function getMissingScopedSnapshotAppPermissions(user, scopedSnapshot, permissionKeys = []) {
  return Array.from(new Set(Array.isArray(permissionKeys) ? permissionKeys : [permissionKeys]))
    .filter(Boolean)
    .filter((permissionKey) => !canUseScopedSnapshotAppPermission(user, scopedSnapshot, permissionKey));
}

function normalizeWorkOrderStatusForPermission(value = "") {
  return normalizeInputValue(value) || "Otvoreni RN";
}

function getWorkOrderStatusPermissionKeys(currentStatus = "", nextStatus = "") {
  const current = normalizeWorkOrderStatusForPermission(currentStatus);
  const next = normalizeWorkOrderStatusForPermission(nextStatus);

  if (current === next) {
    return [];
  }

  const permissionKeys = [];
  if (current === "Storno RN" && next !== "Storno RN") {
    permissionKeys.push("workOrders.restoreCancelled");
  }
  if (next === "Storno RN") {
    permissionKeys.push("workOrders.cancel");
  }
  if (next === "Fakturiran RN") {
    permissionKeys.push("workOrders.markInvoiced");
  }
  if (permissionKeys.length === 0) {
    permissionKeys.push("workOrders.changeStatus");
  }

  return Array.from(new Set(permissionKeys));
}

function bodyHasOwnField(body = {}, fieldName = "") {
  return Object.prototype.hasOwnProperty.call(body, fieldName);
}

function workOrderFieldChanged(currentWorkOrder = {}, body = {}, fieldName = "") {
  return bodyHasOwnField(body, fieldName)
    && normalizeInputValue(body[fieldName]) !== normalizeInputValue(currentWorkOrder?.[fieldName]);
}

function getWorkOrderBillingPermissionKeys(currentWorkOrder = {}, body = {}) {
  return ["invoiceDate", "invoiceNote", "weight"].some((fieldName) => workOrderFieldChanged(currentWorkOrder, body, fieldName))
    ? ["workOrders.billing.write"]
    : [];
}

async function getActorWithScopedAppPermissions(user, request) {
  const { scopedSnapshot } = await getScopedState(user, request);
  return {
    ...user,
    appPermissions: {
      ...(scopedSnapshot.appPermissions ?? {}),
    },
  };
}

function sleep(durationMs) {
  return new Promise((resolveSleep) => {
    setTimeout(resolveSleep, durationMs);
  });
}

async function createRepositoryWithRetry() {
  const attempts = process.env.DATABASE_URL ? 6 : 1;
  let lastError = null;

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      const [domainRepository, tenantRepository] = await Promise.all([
        createSafetyRepository(),
        createTenantRepository(),
      ]);

      return {
        domainRepository,
        tenantRepository,
      };
    } catch (error) {
      lastError = error;

      if (attempt === attempts) {
        break;
      }

      console.warn(`Repository init failed (attempt ${attempt}/${attempts}). Retrying in 2s...`);
      await sleep(2_000);
    }
  }

  throw lastError;
}

