function normalizeLearningQuestionImportType(value = "") {
  const raw = normalizeInputValue(value);
  const key = normalizeLookupKey(raw);
  if (["multiplechoice", "multiple", "visestruki", "visestrukiodgovor", "viseodgovora", "vise", "multi"].includes(key)) {
    return "multiple_choice";
  }
  if (["orderedtext", "ordered", "redoslijed", "poredak", "pisanjebrojeva", "sortiranje", "redanje"].includes(key)) {
    return "ordered_text";
  }
  if (key.includes("multiple") || key.includes("visestruk") || key.includes("viseodgov")) {
    return "multiple_choice";
  }
  if (key.includes("ordered") || key.includes("redoslijed") || key.includes("poredak") || key.includes("redanje")) {
    return "ordered_text";
  }
  return "single_choice";
}

function normalizeLearningQuestionImportCorrectKeys(value = "", fallback = "A") {
  const source = Array.isArray(value) ? value.join(",") : String(value ?? "");
  const upperSource = source.toUpperCase();
  const explicitKeys = upperSource.match(/\b[A-D]\b/gu) ?? [];
  const keys = Array.from(new Set(
    (explicitKeys.length > 0 ? explicitKeys : (upperSource.replace(/[^A-D]/gu, "").match(/[A-D]/gu) ?? []))
      .map((entry) => entry.trim()),
  ));
  return keys.length > 0 ? keys : [fallback];
}

function normalizeLearningQuestionImportOrder(value, fallback = null) {
  const numeric = Number(String(value ?? "").replace(",", "."));
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return fallback;
  }
  return Math.max(1, Math.round(numeric));
}

function inferLearningQuestionImageTypeFromUrl(url = "") {
  const pathname = (() => {
    try {
      return new URL(url).pathname;
    } catch {
      return String(url || "");
    }
  })().toLowerCase();
  if (pathname.endsWith(".png")) return "image/png";
  if (pathname.endsWith(".webp")) return "image/webp";
  if (pathname.endsWith(".gif")) return "image/gif";
  if (pathname.endsWith(".svg")) return "image/svg+xml";
  if (pathname.endsWith(".bmp")) return "image/bmp";
  if (pathname.endsWith(".jpg") || pathname.endsWith(".jpeg")) return "image/jpeg";
  return "image/*";
}

function buildLearningQuestionImageDocumentFromUrl(url = "", rowIndex = 0) {
  const safeUrl = normalizeInputValue(url);
  if (!/^https?:\/\//i.test(safeUrl) && !/^data:image\//i.test(safeUrl)) {
    return null;
  }

  const fallbackName = `slika-pitanja-${rowIndex + 1}.jpg`;
  let fileName = fallbackName;
  try {
    const parsed = new URL(safeUrl);
    const segment = decodeURIComponent(parsed.pathname.split("/").filter(Boolean).pop() || "");
    if (segment) {
      fileName = segment;
    }
  } catch {
    fileName = fallbackName;
  }

  return {
    id: randomUUID(),
    fileName,
    fileType: inferLearningQuestionImageTypeFromUrl(safeUrl),
    fileSize: 0,
    documentCategory: "Slika pitanja",
    dataUrl: safeUrl,
    storageUrl: safeUrl,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}

function buildLearningQuestionImportItem(row = {}, rowIndex = 0) {
  const questionType = normalizeLearningQuestionImportType(getImportRowValue(row, ["vrsta pitanja", "tip pitanja", "question type", "type"]));
  const prompt = normalizeInputValue(getImportRowValue(row, ["pitanje", "tekst pitanja", "question", "prompt"]));
  const groupLabel = normalizeInputValue(getImportRowValue(row, ["grupa", "grupa pitanja", "kategorija"])) || "Pitanja";
  const code = normalizeInputValue(getImportRowValue(row, ["šifra pitanja", "sifra pitanja", "oznaka", "kod", "code"])) || `P${rowIndex + 1}`;
  const imageUrl = normalizeInputValue(getImportRowValue(row, ["slika url", "url slike", "image url", "slika"]));
  const correctSingle = normalizeLearningQuestionImportCorrectKeys(
    getImportRowValue(row, ["točan odgovor", "tocan odgovor", "correct answer", "correct"]),
    "A",
  )[0] || "A";
  const correctMultiple = normalizeLearningQuestionImportCorrectKeys(
    getImportRowValue(row, ["točni odgovori", "tocni odgovori", "correct answers", "multi correct"]),
    correctSingle,
  );

  const options = LEARNING_QUESTION_IMPORT_OPTION_KEYS.map((letter, optionIndex) => {
    const text = normalizeInputValue(getImportRowValue(row, [`odgovor ${letter}`, `answer ${letter}`, letter]));
    const orderIndex = questionType === "ordered_text"
      ? normalizeLearningQuestionImportOrder(
        getImportRowValue(row, [`redoslijed ${letter}`, `red ${letter}`, `order ${letter}`]),
        optionIndex + 1,
      )
      : null;
    return {
      id: randomUUID(),
      text,
      isCorrect: questionType === "multiple_choice"
        ? correctMultiple.includes(letter)
        : (questionType === "single_choice" ? correctSingle === letter : false),
      orderIndex,
    };
  }).filter((option) => option.text);

  if (!prompt || options.length === 0) {
    return null;
  }

  return {
    id: randomUUID(),
    code,
    groupLabel,
    prompt,
    explanation: normalizeInputValue(getImportRowValue(row, ["objašnjenje", "objasnjenje", "explanation"])),
    questionType,
    correctOptionKeys: questionType === "ordered_text" ? [] : (questionType === "multiple_choice" ? correctMultiple : [correctSingle]),
    imageDocument: buildLearningQuestionImageDocumentFromUrl(imageUrl, rowIndex),
    options,
  };
}

function buildLearningQuestionImportItems(body = {}) {
  const buffer = readDataUrlBuffer(body?.dataUrl);
  if (!buffer.length) {
    throw new Error("Excel datoteka s pitanjima nije učitana.");
  }

  const workbook = XLSX.read(buffer, {
    type: "buffer",
    cellDates: true,
  });
  const sheetName = (workbook.SheetNames ?? []).find((name) => normalizeLookupKey(name).includes("pitanj"))
    || workbook.SheetNames?.[0];
  const sheet = sheetName ? workbook.Sheets[sheetName] : null;
  if (!sheet) {
    return [];
  }

  return XLSX.utils.sheet_to_json(sheet, {
    defval: "",
    raw: false,
  })
    .map((row, index) => buildLearningQuestionImportItem(row, index))
    .filter(Boolean);
}

function formatPeopleTrainingImportCellDate(value = "") {
  return String(value || "").slice(0, 10);
}

function findPeopleTrainingImportTemplateItem(record = {}, option = {}) {
  const hints = [
    option.value,
    option.label,
    option.shortLabel,
    option.serviceCode,
    option.serviceName,
  ].map((value) => normalizeLookupKey(value)).filter(Boolean);
  return (record.trainingItems ?? []).find((item) => {
    const candidates = [
      item.type,
      item.label,
      item.shortLabel,
      item.serviceCode,
      item.serviceName,
      item.serviceId,
    ].map((value) => normalizeLookupKey(value)).filter(Boolean);
    return hints.some((hint) => candidates.some((candidate) => candidate === hint || candidate.includes(hint) || hint.includes(candidate)));
  }) ?? null;
}

function getPeopleTrainingImportPrimarySafeWorkItem(record = {}) {
  return (record.trainingItems ?? []).find((item) => {
    const lookup = normalizeLookupKey([
      item.type,
      item.label,
      item.shortLabel,
      item.serviceCode,
      item.serviceName,
    ].filter(Boolean).join(" "));
    return lookup.includes("safe_work") || lookup.includes("safework") || lookup.includes("znr") || lookup.includes("zos") || lookup.includes("radnasiguran");
  }) ?? null;
}

function getPeopleTrainingImportTrainingItemByHints(record = {}, hints = []) {
  const normalizedHints = hints.map((hint) => normalizeLookupKey(hint)).filter(Boolean);
  return (record.trainingItems ?? []).find((item) => {
    const lookup = normalizeLookupKey([
      item.type,
      item.label,
      item.shortLabel,
      item.serviceCode,
      item.serviceName,
    ].filter(Boolean).join(" "));
    return normalizedHints.some((hint) => lookup.includes(hint));
  }) ?? null;
}

function buildPeopleTrainingImportExportRow(record = {}, columns = [], typeOptions = [], scopedSnapshot = {}) {
  const company = (scopedSnapshot.companies ?? []).find((item) => String(item.id) === String(record.companyId));
  const location = (scopedSnapshot.locations ?? []).find((item) => String(item.id) === String(record.locationId));
  const safeWorkItem = getPeopleTrainingImportPrimarySafeWorkItem(record);
  const safeWorkDetails = safeWorkItem?.details ?? {};
  const fireItem = getPeopleTrainingImportTrainingItemByHints(record, ["pgp", "pozar", "fire", "fireinitial"]);
  const flammableItem = getPeopleTrainingImportTrainingItemByHints(record, ["spztp", "zapaljiv", "flammable"]);
  const adrItem = getPeopleTrainingImportTrainingItemByHints(record, ["adr"]);

  return columns.map((column) => {
    const key = normalizeLookupKey(column);
    if (key === "idzapisa" || key === "idevidencije" || key === "recordid") return record.id || "";
    if (key === "tvrtka") return company?.name || record.companyName || "";
    if (key === "lokacija") return location?.name || record.locationName || "";
    if (key === "ime") return record.firstName || "";
    if (key === "prezime") return record.lastName || "";
    if (key === "imeoca") return record.fatherName || "";
    if (key === "imeiprezime") return record.fullName || [record.firstName, record.lastName].filter(Boolean).join(" ");
    if (key === "oibosobe" || key === "oib") return record.oib || "";
    if (key === "jezik") return record.language || "";
    if (key === "datumrodenja") return formatPeopleTrainingImportCellDate(record.birthDate);
    if (key === "drzavarodenja") return record.birthCountry || "";
    if (key === "mjestorodenja") return record.birthPlace || "";
    if (key === "datumdolaska") return formatPeopleTrainingImportCellDate(record.arrivalDate);
    if (key === "mjestorada") return record.workPlace || location?.name || record.locationName || "";
    if (key === "aktivnost") return record.activityStatus || "DA";
    if (key === "email") return record.email || "";
    if (key === "mobitel") return record.phone || "";
    if (key === "brojrn") return safeWorkItem?.workOrderNumber || "";
    if (key.includes("sifrausluge")) return safeWorkItem?.serviceCode || safeWorkItem?.shortLabel || safeWorkItem?.type || "";
    if (key.includes("brojzapisnika")) return safeWorkItem?.recordNumber || safeWorkItem?.certificateNumber || "";
    if (key.includes("nazivradnogmjesta")) return safeWorkDetails.jobTitle || record.jobTitle || "";
    if (key.includes("opisposlova")) return safeWorkDetails.jobDescription || "";
    if (key.includes("teorijsko")) return safeWorkDetails.theoryPlace || "";
    if (key.includes("datumteorijski")) return formatPeopleTrainingImportCellDate(safeWorkDetails.theoryDate || safeWorkItem?.issuedOn || safeWorkItem?.passedOn);
    if (key.includes("nacinprovodenja")) return safeWorkDetails.theoryMethod || "";
    if (key.includes("poslodavcaovlastenika") && key.includes("imeiprezime")) return safeWorkDetails.employerRepresentativeName || company?.representative || "";
    if (key.includes("poslodavcaovlastenika") && key.includes("oib")) return safeWorkDetails.employerRepresentativeOib || company?.representativeOib || "";
    if (key.includes("ostaleosobe") && key.includes("imeiprezime")) return safeWorkDetails.additionalPersonName || "";
    if (key.includes("ostaleosobe") && key.includes("oib")) return safeWorkDetails.additionalPersonOib || "";
    if (key.includes("prakticno")) return safeWorkDetails.practicalPlace || "";
    if (key.includes("razdobljepracenja") && key.includes("od")) return formatPeopleTrainingImportCellDate(safeWorkDetails.safeWorkPeriodFrom);
    if (key.includes("razdobljepracenja") && key.includes("do")) return formatPeopleTrainingImportCellDate(safeWorkDetails.safeWorkPeriodTo);
    if (key.includes("pgpdatum")) return formatPeopleTrainingImportCellDate(fireItem?.passedOn || fireItem?.issuedOn);
    if (key.includes("spztpdatum")) return formatPeopleTrainingImportCellDate(flammableItem?.passedOn || flammableItem?.issuedOn);
    if (key.includes("spztpvrijedido")) return formatPeopleTrainingImportCellDate(flammableItem?.validUntil);
    if (key.includes("adrdatum")) return formatPeopleTrainingImportCellDate(adrItem?.passedOn || adrItem?.issuedOn);
    if (key.includes("adrvrijedido")) return formatPeopleTrainingImportCellDate(adrItem?.validUntil);
    if (key === "napomena") return record.note || "";

    const option = typeOptions.find((candidate) => {
      const label = candidate.serviceCode ? `${candidate.serviceCode} ${candidate.label}` : candidate.label;
      return key.startsWith(normalizeLookupKey(label));
    });
    if (option) {
      const item = findPeopleTrainingImportTemplateItem(record, option);
      if (!item) return "";
      if (key.includes("vrijeditrajno")) return item.validForever ? "DA" : "NE";
      if (key.includes("vrijedido")) return formatPeopleTrainingImportCellDate(item.validUntil);
      if (key.includes("brojuvjerenja")) return item.certificateNumber || item.recordNumber || "";
      if (key.includes("ustanova")) return item.provider || "";
      if (key.includes("datum")) return formatPeopleTrainingImportCellDate(item.issuedOn || item.passedOn);
    }

    return "";
  });
}

function escapeXlsxXml(value = "") {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function getExcelColumnName(index = 0) {
  let value = Math.max(0, Number(index) || 0) + 1;
  let label = "";
  while (value > 0) {
    const modulo = (value - 1) % 26;
    label = String.fromCharCode(65 + modulo) + label;
    value = Math.floor((value - modulo) / 26);
  }
  return label || "A";
}

function isPeopleTrainingJobTitleColumn(column = {}) {
  const key = normalizeLookupKey(column.key || column.label || column);
  return key === "jobtitle" || key === "nazivradnogmjesta" || key === "radnomjesto";
}

function addUniquePeopleTrainingJobTitle(target, value = "") {
  const title = normalizeInputValue(value).slice(0, 180);
  if (!title) {
    return;
  }
  const key = normalizeLookupKey(title);
  if (!key || target.has(key)) {
    return;
  }
  target.set(key, title);
}

function collectCompanyTrainingJobTitles(scopedSnapshot = {}, companyId = "") {
  const titles = new Map();
  const normalizedCompanyId = normalizeInputValue(companyId);
  (scopedSnapshot.peopleTrainingRecords ?? [])
    .filter((record) => !normalizedCompanyId || String(record.companyId) === normalizedCompanyId)
    .forEach((record) => {
      addUniquePeopleTrainingJobTitle(titles, record.jobTitle || record.workPlace);
      (record.trainingItems ?? []).forEach((item) => {
        addUniquePeopleTrainingJobTitle(titles, item?.details?.jobTitle);
        addUniquePeopleTrainingJobTitle(titles, item?.details?.medicalJobTitle);
      });
    });
  (scopedSnapshot.riskAssessments ?? [])
    .filter((assessment) => !normalizedCompanyId || String(assessment.companyId) === normalizedCompanyId)
    .forEach((assessment) => {
      (assessment.employerData?.workplaceJobs ?? []).forEach((job) => {
        addUniquePeopleTrainingJobTitle(titles, job?.jobTitle || job?.title || job?.name);
      });
      (assessment.organizationUnits ?? []).forEach((unit) => {
        const unitType = normalizeLookupKey(unit?.type);
        addUniquePeopleTrainingJobTitle(titles, unit?.jobTitle);
        if (unitType.includes("job") || unitType.includes("workplace") || unitType.includes("radnomjesto")) {
          addUniquePeopleTrainingJobTitle(titles, unit?.title);
          addUniquePeopleTrainingJobTitle(titles, unit?.name);
        }
        addUniquePeopleTrainingJobTitle(titles, unit?.workplace);
        (unit?.workplaceOptions ?? []).forEach((option) => addUniquePeopleTrainingJobTitle(titles, option));
        (unit?.clientInput?.workplaceOptions ?? []).forEach((option) => addUniquePeopleTrainingJobTitle(titles, option));
      });
      (assessment.jobs ?? []).forEach((job) => {
        addUniquePeopleTrainingJobTitle(titles, job?.jobTitle || job?.title || job?.name);
      });
    });
  return Array.from(titles.values()).sort((left, right) => left.localeCompare(right, "hr", { sensitivity: "base" })).slice(0, 500);
}

function addPeopleTrainingJobTitleSheet(workbook, jobTitles = []) {
  const rows = [
    ["Radno mjesto"],
    ...(jobTitles.length ? jobTitles.map((title) => [title]) : [["Nema radnih mjesta u procjeni rizika za ovu tvrtku"]]),
  ];
  const worksheet = XLSX.utils.aoa_to_sheet(rows);
  worksheet["!cols"] = [{ wch: 44 }];
  XLSX.utils.book_append_sheet(workbook, worksheet, "Radna mjesta");
}

async function addPeopleTrainingJobTitleDropdownsToXlsx(buffer, validations = [], jobTitleCount = 0) {
  const usableValidations = validations.filter((item) => item?.sheetName && item?.columnIndex >= 0 && jobTitleCount > 0);
  if (!usableValidations.length) {
    return buffer;
  }

  const zip = await JSZip.loadAsync(buffer);
  const workbookXmlPath = "xl/workbook.xml";
  const workbookRelsPath = "xl/_rels/workbook.xml.rels";
  const workbookXml = await zip.file(workbookXmlPath)?.async("string");
  const relsXml = await zip.file(workbookRelsPath)?.async("string");
  if (!workbookXml || !relsXml) {
    return buffer;
  }

  const sheetRidByName = new Map();
  const sheetRegex = /<sheet\b([^>]*)\/>/g;
  let sheetMatch;
  while ((sheetMatch = sheetRegex.exec(workbookXml)) !== null) {
    const attrs = sheetMatch[1] || "";
    const name = attrs.match(/\bname="([^"]*)"/)?.[1] || "";
    const rid = attrs.match(/\br:id="([^"]*)"/)?.[1] || "";
    if (name && rid) {
      sheetRidByName.set(name, rid);
    }
  }

  const targetByRid = new Map();
  const relRegex = /<Relationship\b([^>]*)\/>/g;
  let relMatch;
  while ((relMatch = relRegex.exec(relsXml)) !== null) {
    const attrs = relMatch[1] || "";
    const id = attrs.match(/\bId="([^"]*)"/)?.[1] || "";
    const target = attrs.match(/\bTarget="([^"]*)"/)?.[1] || "";
    if (id && target) {
      targetByRid.set(id, target.replace(/^\/?xl\//, ""));
    }
  }

  const formula = `'Radna mjesta'!$A$2:$A$${jobTitleCount + 1}`;
  for (const validation of usableValidations) {
    const rid = sheetRidByName.get(validation.sheetName);
    const target = targetByRid.get(rid);
    if (!target) {
      continue;
    }
    const sheetPath = `xl/${target}`;
    const file = zip.file(sheetPath);
    const sheetXml = await file?.async("string");
    if (!sheetXml) {
      continue;
    }
    const column = getExcelColumnName(validation.columnIndex);
    const firstRow = Math.max(2, Number(validation.firstDataRow) || 2);
    const lastRow = Math.max(firstRow, Number(validation.lastDataRow) || firstRow + 999);
    const node = `<dataValidation type="list" allowBlank="1" showErrorMessage="1" errorTitle="Radno mjesto" error="Odaberi radno mjesto iz liste." sqref="${column}${firstRow}:${column}${lastRow}"><formula1>${escapeXlsxXml(formula)}</formula1></dataValidation>`;
    let nextXml = sheetXml;
    if (nextXml.includes("<dataValidations")) {
      nextXml = nextXml.replace(/<dataValidations\b([^>]*)count="(\d+)"([^>]*)>/, (full, before, count, after) => (
        `<dataValidations${before}count="${Number(count || 0) + 1}"${after}>`
      ));
      nextXml = nextXml.replace("</dataValidations>", `${node}</dataValidations>`);
    } else {
      const wrapper = `<dataValidations count="1">${node}</dataValidations>`;
      if (nextXml.includes("<pageMargins")) {
        nextXml = nextXml.replace("<pageMargins", `${wrapper}<pageMargins`);
      } else if (nextXml.includes("</worksheet>")) {
        nextXml = nextXml.replace("</worksheet>", `${wrapper}</worksheet>`);
      } else {
        continue;
      }
    }
    zip.file(sheetPath, nextXml);
  }

  return zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
}

