function normalizeGeneratedDocumentRecordDate(value = "") {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return "";
  }

  const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }

  const localMatch = raw.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);
  if (localMatch) {
    const [, day, month, year] = localMatch;
    return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
  }

  return normalizeDateOnlyValue(raw);
}

const GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY = "__PERIODICS_TRACKED_DATES";
const MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY = "__mobileDocumentationAttachments";
const MOBILE_DOCUMENTATION_RECORD_TEMPLATE_ATTACHMENTS_KEY = "__mobileDocumentationTemplateAttachments";
const MOBILE_DOCUMENTATION_DRAFT_MARKER_KEY = "__mobileDocumentationDraft";
const MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_ID_KEY = "__mobileDocumentationDraftWorkOrderId";
const MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_NUMBER_KEY = "__mobileDocumentationDraftWorkOrderNumber";
const MOBILE_DOCUMENTATION_DRAFT_UPDATED_AT_KEY = "__mobileDocumentationDraftUpdatedAt";

function normalizeGeneratedDocumentExpirationDate(value = "") {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return "";
  }

  const isValidDateParts = (year, month, day) => {
    const parsed = new Date(Date.UTC(year, month - 1, day));
    return parsed.getUTCFullYear() === year
      && parsed.getUTCMonth() === month - 1
      && parsed.getUTCDate() === day;
  };
  const formatDate = (year, month, day) => (
    isValidDateParts(year, month, day)
      ? `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`
      : ""
  );

  const isoMatch = raw.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);
  if (isoMatch) {
    return formatDate(
      Number.parseInt(isoMatch[1], 10),
      Number.parseInt(isoMatch[2], 10),
      Number.parseInt(isoMatch[3], 10),
    );
  }

  const localMatch = raw.match(/\b(\d{1,2})[./](\d{1,2})[./](\d{4})\b/);
  if (localMatch) {
    return formatDate(
      Number.parseInt(localMatch[3], 10),
      Number.parseInt(localMatch[2], 10),
      Number.parseInt(localMatch[1], 10),
    );
  }

  return "";
}

function getGeneratedDocumentRecordValue(source = {}, keys = []) {
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    return "";
  }

  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(source, key)) {
      const value = source[key];
      if (value !== undefined && value !== null && String(value).trim()) {
        return value;
      }
    }
  }

  const normalizedKeys = keys.map((key) => normalizeLookupKey(key)).filter(Boolean);
  if (normalizedKeys.length === 0) {
    return "";
  }

  const entry = Object.entries(source).find(([key, value]) => (
    value !== undefined
    && value !== null
    && String(value).trim()
    && normalizedKeys.includes(normalizeLookupKey(key))
  ));

  return entry?.[1] ?? "";
}

function getGeneratedDocumentRecordWorkOrderNumber(record = {}, workOrder = {}) {
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  return String(
    record?.workOrderNumber
    || getGeneratedDocumentRecordValue(fieldValues, [
      "WORK_ORDER_NUMBER",
      "BROJ_RN",
      "RN",
      "RADNI_NALOG",
    ])
    || workOrder?.workOrderNumber
    || "",
  ).replace(/^RN\s*/i, "").trim();
}

function getMobileDocumentationDraftFieldValues(source = {}) {
  return source?.fieldValues && typeof source.fieldValues === "object" && !Array.isArray(source.fieldValues)
    ? source.fieldValues
    : {};
}

function isMobileDocumentationDraftRecord(source = {}) {
  const fieldValues = getMobileDocumentationDraftFieldValues(source);
  const marker = fieldValues[MOBILE_DOCUMENTATION_DRAFT_MARKER_KEY];
  return marker === true || marker === "true" || marker === "1" || marker === 1;
}

function getMobileDocumentationDraftWorkOrderId(source = {}) {
  return normalizeInputValue(getMobileDocumentationDraftFieldValues(source)[MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_ID_KEY]);
}

function getMobileDocumentationDraftWorkOrderNumber(source = {}) {
  const fieldValues = getMobileDocumentationDraftFieldValues(source);
  return normalizeInputValue(
    fieldValues[MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_NUMBER_KEY]
    || fieldValues.WORK_ORDER_NUMBER
    || source?.workOrderNumber,
  );
}

function mobileDocumentationDraftMatchesWorkOrder(source = {}, workOrder = {}) {
  if (!isMobileDocumentationDraftRecord(source)) {
    return false;
  }
  const draftWorkOrderId = getMobileDocumentationDraftWorkOrderId(source);
  const workOrderId = normalizeInputValue(workOrder?.id);
  if (draftWorkOrderId && workOrderId) {
    return draftWorkOrderId === workOrderId;
  }
  const draftWorkOrderNumber = getMobileDocumentationDraftWorkOrderNumber(source);
  const workOrderNumber = normalizeInputValue(workOrder?.workOrderNumber || workOrder?.number || workOrder?.displayNumber);
  return Boolean(draftWorkOrderNumber && workOrderNumber && draftWorkOrderNumber === workOrderNumber);
}

function stripMobileDocumentationDraftFields(fieldValues = {}) {
  if (!fieldValues || typeof fieldValues !== "object" || Array.isArray(fieldValues)) {
    return {};
  }
  const {
    [MOBILE_DOCUMENTATION_DRAFT_MARKER_KEY]: _draftMarker,
    [MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_ID_KEY]: _draftWorkOrderId,
    [MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_NUMBER_KEY]: _draftWorkOrderNumber,
    [MOBILE_DOCUMENTATION_DRAFT_UPDATED_AT_KEY]: _draftUpdatedAt,
    ...rest
  } = fieldValues;
  return rest;
}

function getGeneratedDocumentRecordTrackedExpirationDate(fieldValues = {}) {
  const trackedDates = Array.isArray(fieldValues?.[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY])
    ? fieldValues[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY]
    : [];

  for (const entry of trackedDates) {
    const expirationDate = normalizeGeneratedDocumentExpirationDate(entry?.value ?? entry?.date ?? entry?.validUntil);
    if (expirationDate) {
      return expirationDate;
    }
  }

  return "";
}

function normalizeGeneratedDocumentRecordExpirationFromPayload(payload = {}) {
  const fieldValues = payload?.fieldValues && typeof payload.fieldValues === "object" && !Array.isArray(payload.fieldValues)
    ? payload.fieldValues
    : {};
  return normalizeGeneratedDocumentExpirationDate(payload?.expirationDate ?? payload?.expiration_date)
    || getGeneratedDocumentRecordTrackedExpirationDate(fieldValues)
    || normalizeGeneratedDocumentExpirationDate(getGeneratedDocumentRecordValue(fieldValues, [
      "WORK_ORDER_SERVICE_VALID_UNTIL",
      "WORK_ORDER_VALID_UNTIL",
      "VRIJEDI_DO",
      "DATUM_VRIJEDI_DO",
      "VALID_UNTIL",
      "VALID_TO",
    ]));
}

function getGeneratedDocumentRecordValidityMonths(fieldValues = {}) {
  return normalizeMobileDocumentValidityMonths(getGeneratedDocumentRecordValue(fieldValues, [
    "WORK_ORDER_SERVICE_VALIDITY_MONTHS",
    "WORK_ORDER_VALIDITY_MONTHS",
    "VRIJEDI_MJESECI",
    "VALIDITY_MONTHS",
  ]));
}

function ensureGeneratedDocumentRecordPeriodicsFields(fieldValues = {}, {
  inspectionDate = "",
  issuedDate = "",
  expirationDate = "",
} = {}) {
  const source = fieldValues && typeof fieldValues === "object" && !Array.isArray(fieldValues)
    ? fieldValues
    : {};
  const currentExpirationDate = normalizeGeneratedDocumentExpirationDate(expirationDate);
  const validityMonths = getGeneratedDocumentRecordValidityMonths(source);
  const baseDate = normalizeGeneratedDocumentRecordDate(inspectionDate || issuedDate);
  const computedExpirationDate = currentExpirationDate || addMonthsToMobileDate(baseDate, validityMonths);

  if (!computedExpirationDate) {
    return {
      fieldValues: source,
      expirationDate: "",
    };
  }

  const nextFieldValues = {
    ...source,
  };
  if (!getGeneratedDocumentRecordTrackedExpirationDate(nextFieldValues)) {
    nextFieldValues[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY] = [{
      fieldId: "WORK_ORDER_VALID_UNTIL",
      fieldKey: "WORK_ORDER_VALID_UNTIL",
      label: "Vrijedi do",
      value: computedExpirationDate,
    }];
  }
  [
    "WORK_ORDER_VALID_UNTIL",
    "WORK_ORDER_SERVICE_VALID_UNTIL",
    "VRIJEDI_DO",
    "DATUM_VRIJEDI_DO",
  ].forEach((key) => {
    if (!String(nextFieldValues[key] ?? "").trim()) {
      nextFieldValues[key] = computedExpirationDate;
    }
  });

  return {
    fieldValues: nextFieldValues,
    expirationDate: computedExpirationDate,
  };
}

function buildGeneratedDocumentTemplateRecordPayload({
  entry = {},
  workOrder = {},
  template = {},
  scopedSnapshot = {},
} = {}) {
  const suppliedRecord = entry?.documentRecord && typeof entry.documentRecord === "object" && !Array.isArray(entry.documentRecord)
    ? entry.documentRecord
    : {};
  const suppliedFieldValues = suppliedRecord.fieldValues && typeof suppliedRecord.fieldValues === "object" && !Array.isArray(suppliedRecord.fieldValues)
    ? suppliedRecord.fieldValues
    : {};
  const placeholders = entry?.placeholders && typeof entry.placeholders === "object" && !Array.isArray(entry.placeholders)
    ? entry.placeholders
    : {};
  const renderModel = entry?.renderModel && typeof entry.renderModel === "object" && !Array.isArray(entry.renderModel)
    ? entry.renderModel
    : {};
  let fieldValues = {
    ...placeholders,
    ...suppliedFieldValues,
  };
  const workOrderNumber = String(workOrder?.workOrderNumber || renderModel.workOrderNumber || "").trim();

  if (workOrderNumber && !String(fieldValues.WORK_ORDER_NUMBER || "").trim()) {
    fieldValues.WORK_ORDER_NUMBER = workOrderNumber;
  }
  if (renderModel?.company?.name && !String(fieldValues.COMPANY_NAME || fieldValues.TVRTKA || "").trim()) {
    fieldValues.COMPANY_NAME = renderModel.company.name;
    fieldValues.TVRTKA = renderModel.company.name;
  }
  if (renderModel?.company?.headquarters && !String(fieldValues.COMPANY_HEADQUARTERS || fieldValues.SJEDISTE || "").trim()) {
    fieldValues.COMPANY_HEADQUARTERS = renderModel.company.headquarters;
    fieldValues.SJEDISTE = renderModel.company.headquarters;
  }
  if (renderModel?.company?.oib && !String(fieldValues.COMPANY_OIB || fieldValues.OIB || "").trim()) {
    fieldValues.COMPANY_OIB = renderModel.company.oib;
    fieldValues.OIB = renderModel.company.oib;
  }
  if (renderModel?.location?.name && !String(fieldValues.LOCATION_NAME || fieldValues.LOKACIJA || "").trim()) {
    fieldValues.LOCATION_NAME = renderModel.location.name;
    fieldValues.LOKACIJA = renderModel.location.name;
  }
  if (renderModel?.object?.name && !String(fieldValues.OBJECT_NAME || fieldValues.OBJEKT || "").trim()) {
    fieldValues.OBJECT_NAME = renderModel.object.name;
    fieldValues.OBJEKT = renderModel.object.name;
  }
  if (renderModel?.serviceCode && !String(fieldValues.SERVICE_SUMMARY || fieldValues.USLUGA || "").trim()) {
    fieldValues.SERVICE_SUMMARY = renderModel.serviceCode;
    fieldValues.USLUGA = renderModel.serviceCode;
  }

  const inspectionDate = normalizeGeneratedDocumentRecordDate(
    suppliedRecord.inspectionDate
    || entry.inspectionDate
    || getGeneratedDocumentRecordValue(fieldValues, ["WORK_ORDER_INSPECTION_DATE", "DATUM_ISPITIVANJA"]),
  );
  const issuedDate = normalizeGeneratedDocumentRecordDate(
    suppliedRecord.issuedDate
    || entry.issuedDate
    || getGeneratedDocumentRecordValue(fieldValues, ["WORK_ORDER_ISSUED_DATE", "DATUM_IZDAVANJA"]),
  );
  let expirationDate = normalizeGeneratedDocumentRecordExpirationFromPayload({
    expirationDate: suppliedRecord.expirationDate || entry.expirationDate,
    fieldValues,
  });
  const periodicsPayload = ensureGeneratedDocumentRecordPeriodicsFields(fieldValues, {
    inspectionDate,
    issuedDate,
    expirationDate,
  });
  expirationDate = periodicsPayload.expirationDate || expirationDate;
  fieldValues = periodicsPayload.fieldValues;
  const resolvedTemplateId = normalizeInputValue(suppliedRecord.templateId || entry.templateId || template.id);
  const recordAttachments = normalizeMobileDocumentationAttachments(
    suppliedRecord.attachments
      || entry.attachments
      || resolveMobileDocumentationAttachmentsForTemplate(entry.mobileCommon, resolvedTemplateId)
      || [],
  );
  if (recordAttachments.length > 0) {
    fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY] = recordAttachments;
  } else {
    delete fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY];
  }
  const objectName = String(
    suppliedRecord.objectName
    || entry.objectName
    || renderModel?.object?.name
    || getGeneratedDocumentRecordValue(fieldValues, ["OBJECT_NAME", "OBJEKT"])
    || getMobileWorkOrderLocationObjectName(workOrder)
    || "",
  ).trim();
  const objectId = String(
    suppliedRecord.objectId
    || entry.objectId
    || getMobileWorkOrderLocationObjectId(workOrder)
    || "",
  ).trim();

  const payload = {
    organizationId: String(
      suppliedRecord.organizationId
      || scopedSnapshot.activeOrganizationId
      || workOrder.organizationId
      || "",
    ).trim(),
    templateId: resolvedTemplateId,
    templateTitle: String(suppliedRecord.templateTitle || template.title || renderModel.title || template.documentType || "Zapisnik").trim(),
    documentType: String(suppliedRecord.documentType || template.documentType || renderModel.documentType || "Zapisnik").trim(),
    companyId: String(suppliedRecord.companyId || workOrder.companyId || "").trim(),
    locationId: String(suppliedRecord.locationId || workOrder.locationId || "").trim(),
    objectId,
    objectName,
    inspectionDate,
    issuedDate,
    expirationDate,
    fieldValues,
    fieldSheets: suppliedRecord.fieldSheets && typeof suppliedRecord.fieldSheets === "object" && !Array.isArray(suppliedRecord.fieldSheets)
      ? suppliedRecord.fieldSheets
      : {},
  };

  if (!payload.organizationId || !payload.templateId || !payload.companyId || !payload.locationId) {
    return null;
  }

  return payload;
}

function getScopedDocumentTemplateById(scopedSnapshot = {}, templateId = "") {
  const normalizedId = normalizeInputValue(templateId);
  if (!normalizedId) {
    return null;
  }
  return (Array.isArray(scopedSnapshot.documentTemplates) ? scopedSnapshot.documentTemplates : [])
    .find((template) => normalizeInputValue(template?.id) === normalizedId) || null;
}

function getWorkOrderServiceItemsForDocumentRecord(workOrder = {}) {
  return Array.isArray(workOrder.serviceItems) && workOrder.serviceItems.length > 0
    ? workOrder.serviceItems.map((item) => (item && typeof item === "object" ? item : { name: item }))
    : [{ name: workOrder.serviceLine || workOrder.displayService || "" }];
}

function findWorkOrderServiceForDocumentRecord(input = {}, workOrder = {}, scopedSnapshot = {}) {
  const serviceId = normalizeInputValue(input.serviceId || input.serviceCatalogId);
  const serviceCode = normalizeMobileTemplateLookupKey(input.serviceCode || input.code);
  const serviceName = normalizeMobileTemplateLookupKey(input.serviceName || input.name || input.title);
  const services = getWorkOrderServiceItemsForDocumentRecord(workOrder);
  const catalogByService = new Map(services.map((service) => [service, findMobileServiceCatalogItemForWorkOrderService(service, scopedSnapshot) || {}]));

  return services.find((service) => {
    const catalogItem = catalogByService.get(service) || {};
    const ids = [
      service?.serviceId,
      service?.id,
      service?.catalogServiceId,
      catalogItem?.id,
    ].map(normalizeInputValue).filter(Boolean);
    if (serviceId && ids.includes(serviceId)) {
      return true;
    }
    const codes = [
      service?.serviceCode,
      service?.code,
      catalogItem?.serviceCode,
      catalogItem?.code,
    ].map(normalizeMobileTemplateLookupKey).filter(Boolean);
    if (serviceCode && codes.includes(serviceCode)) {
      return true;
    }
    const names = [
      service?.name,
      service?.serviceName,
      service?.title,
      catalogItem?.name,
      catalogItem?.title,
    ].map(normalizeMobileTemplateLookupKey).filter(Boolean);
    return Boolean(serviceName && names.includes(serviceName));
  }) || services[0] || null;
}

function resolveWorkOrderDocumentRecordTemplate(input = {}, workOrder = {}, scopedSnapshot = {}) {
  const directTemplate = getScopedDocumentTemplateById(scopedSnapshot, input.templateId);
  if (directTemplate && isActiveMobileDocumentTemplate(directTemplate)) {
    return directTemplate;
  }

  const service = findWorkOrderServiceForDocumentRecord(input, workOrder, scopedSnapshot);
  const linkedTemplateIds = service ? getMobileWorkOrderServiceTemplateIds(service, scopedSnapshot) : [];
  for (const templateId of linkedTemplateIds) {
    const template = getScopedDocumentTemplateById(scopedSnapshot, templateId);
    if (template && isActiveMobileDocumentTemplate(template)) {
      return template;
    }
  }

  const lookup = normalizeMobileTemplateLookupKey([
    input.templateTitle,
    input.documentType,
    input.serviceCode,
    input.serviceName,
  ].filter(Boolean).join(" "));
  return (Array.isArray(scopedSnapshot.documentTemplates) ? scopedSnapshot.documentTemplates : [])
    .filter(isActiveMobileDocumentTemplate)
    .find((template) => {
      const templateLookup = normalizeMobileTemplateLookupKey([
        template?.title,
        template?.documentType,
        template?.documentName,
      ].filter(Boolean).join(" "));
      return Boolean(
        templateLookup
        && (
          (lookup && templateLookup.includes(lookup))
          || (lookup.includes("spr") && templateLookup.includes("spr"))
          || (lookup.includes("panik") && templateLookup.includes("panik"))
          || (lookup.includes("sigurnosna rasvjeta") && templateLookup.includes("sigurnosna rasvjeta"))
        ),
      );
    }) || null;
}

function getGenericDocumentationSprRecordSheet(fieldSheets = {}) {
  const source = fieldSheets && typeof fieldSheets === "object" && !Array.isArray(fieldSheets)
    ? fieldSheets
    : {};
  const preferredKeys = [
    "DOCUMENTATION_SPR_GRIDLINE_MODEL",
    "SPR_GRIDLINE_MODEL",
    "GRIDLINE_MODEL",
    "TABLICA_MJERENJA",
    "MJERENJA",
  ];
  for (const key of preferredKeys) {
    const sheet = normalizeWorkOrderMeasurementSheet(source[key]);
    if (sheet) {
      return sheet;
    }
  }
  for (const value of Object.values(source)) {
    const sheet = normalizeWorkOrderMeasurementSheet(value);
    if (sheet) {
      return sheet;
    }
  }
  return null;
}

function expandDocumentationSprRecordFieldSheetsForTemplate(fieldSheets = {}, template = {}) {
  const normalizedSheets = Object.fromEntries(
    Object.entries(fieldSheets && typeof fieldSheets === "object" && !Array.isArray(fieldSheets) ? fieldSheets : {})
      .map(([key, value]) => [normalizeInputValue(key), normalizeWorkOrderMeasurementSheet(value)])
      .filter(([key, value]) => key && value),
  );
  const genericSheet = getGenericDocumentationSprRecordSheet(normalizedSheets);
  if (!genericSheet) {
    return normalizedSheets;
  }

  (Array.isArray(template?.customFields) ? template.customFields : [])
    .filter((field) => normalizeInputValue(field?.type).toLowerCase() === "measurement_table")
    .forEach((field, index) => {
      [
        getMobileDocumentTemplateFieldTokenKey(field, index),
        field?.key,
        field?.id,
        field?.tokenKey,
        field?.label,
      ]
        .map(normalizeInputValue)
        .filter(Boolean)
        .forEach((key) => {
          if (!normalizedSheets[key]) {
            normalizedSheets[key] = genericSheet;
          }
        });
    });

  return normalizedSheets;
}

function buildWorkOrderDocumentRecordPayloadFromRequest(input = {}, workOrder = {}, scopedSnapshot = {}) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return null;
  }
  const template = resolveWorkOrderDocumentRecordTemplate(input, workOrder, scopedSnapshot);
  if (!template) {
    return null;
  }
  const fieldValues = input.fieldValues && typeof input.fieldValues === "object" && !Array.isArray(input.fieldValues)
    ? { ...input.fieldValues }
    : {};
  const templateAttachments = normalizeMobileDocumentationTemplateAttachments(
    input.templateAttachments
      || input.attachmentsByTemplate
      || fieldValues[MOBILE_DOCUMENTATION_RECORD_TEMPLATE_ATTACHMENTS_KEY]
      || {},
  );
  const scopedAttachments = getMobileDocumentationTemplateAttachments(templateAttachments, template.id, []);
  const recordAttachments = normalizeMobileDocumentationAttachments(
    scopedAttachments.length > 0
      ? scopedAttachments
      : (
        input.attachments
        || fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY]
        || input.documentAttachments
        || []
      ),
  );
  if (recordAttachments.length > 0) {
    fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY] = recordAttachments;
  } else {
    delete fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY];
  }
  delete fieldValues[MOBILE_DOCUMENTATION_RECORD_TEMPLATE_ATTACHMENTS_KEY];

  const fieldSheets = expandDocumentationSprRecordFieldSheetsForTemplate(input.fieldSheets, template);
  const workOrderNumber = normalizeInputValue(input.workOrderNumber || workOrder.workOrderNumber || workOrder.number);
  if (workOrderNumber && !normalizeInputValue(fieldValues.WORK_ORDER_NUMBER)) {
    fieldValues.WORK_ORDER_NUMBER = workOrderNumber;
  }

  return {
    organizationId: normalizeInputValue(scopedSnapshot.activeOrganizationId || workOrder.organizationId),
    templateId: normalizeInputValue(template.id),
    templateTitle: normalizeInputValue(input.templateTitle || template.title || template.documentType || "Zapisnik"),
    documentType: normalizeInputValue(input.documentType || template.documentType || "Zapisnik"),
    companyId: normalizeInputValue(input.companyId || workOrder.companyId),
    locationId: normalizeInputValue(input.locationId || workOrder.locationId),
    objectId: normalizeInputValue(input.objectId || workOrder.objectId || workOrder.locationObjectId),
    objectName: normalizeInputValue(input.objectName || workOrder.objectName || workOrder.locationObjectName),
    inspectionDate: normalizeGeneratedDocumentRecordDate(input.inspectionDate),
    issuedDate: normalizeGeneratedDocumentRecordDate(input.issuedDate || input.issueDate),
    expirationDate: normalizeGeneratedDocumentExpirationDate(input.expirationDate || input.validUntil),
    fieldValues,
    fieldSheets,
  };
}

async function persistWorkOrderDocumentRecordsFromRequest({
  body = {},
  workOrder = {},
  scopedSnapshot = {},
  user = null,
} = {}) {
  const rawRecords = [
    ...(Array.isArray(body.documentRecords) ? body.documentRecords : []),
    ...(body.documentRecord && typeof body.documentRecord === "object" && !Array.isArray(body.documentRecord)
      ? [body.documentRecord]
      : []),
  ];
  const savedRecords = [];
  const warnings = [];

  for (const rawRecord of rawRecords) {
    const payload = buildWorkOrderDocumentRecordPayloadFromRequest(rawRecord, workOrder, scopedSnapshot);
    if (!payload) {
      warnings.push("Nije pronađen povezani server predložak za spremanje prethodnog zapisnika.");
      continue;
    }
    try {
      const saved = await upsertDocumentRecordPayload(payload, user, workOrder);
      if (saved) {
        savedRecords.push(saved);
      }
    } catch (error) {
      warnings.push(error?.message || "Ne mogu spremiti zapisnik za ponovno korištenje.");
    }
  }

  return { savedRecords, warnings };
}

function getMobileDocumentationDraftTemplateIds(body = {}, scopedSnapshot = {}) {
  const ids = new Set();
  [
    body.templateId,
    body.documentTemplateId,
  ].map(normalizeInputValue).filter(Boolean).forEach((id) => ids.add(id));

  [
    body.templateFieldValues,
    body.templateFieldSheets,
    body.templateAttachments,
  ].forEach((source) => {
    if (source && typeof source === "object" && !Array.isArray(source)) {
      Object.keys(source).map(normalizeInputValue).filter(Boolean).forEach((id) => ids.add(id));
    }
  });

  const validIds = new Set(
    (Array.isArray(scopedSnapshot.documentTemplates) ? scopedSnapshot.documentTemplates : [])
      .filter(isActiveMobileDocumentTemplate)
      .map((template) => normalizeInputValue(template?.id))
      .filter(Boolean),
  );

  return Array.from(ids).filter((id) => validIds.has(id));
}

function buildMobileDocumentationDraftRecordInputs(body = {}, workOrder = {}, scopedSnapshot = {}) {
  const templateIds = getMobileDocumentationDraftTemplateIds(body, scopedSnapshot);
  if (templateIds.length === 0) {
    const fallbackTemplate = resolveWorkOrderDocumentRecordTemplate(body, workOrder, scopedSnapshot);
    if (fallbackTemplate?.id) {
      templateIds.push(normalizeInputValue(fallbackTemplate.id));
    }
  }

  const commonFieldValues = body.fieldValues && typeof body.fieldValues === "object" && !Array.isArray(body.fieldValues)
    ? body.fieldValues
    : {};
  const commonFieldSheets = body.fieldSheets && typeof body.fieldSheets === "object" && !Array.isArray(body.fieldSheets)
    ? body.fieldSheets
    : {};
  const templateFieldValues = body.templateFieldValues && typeof body.templateFieldValues === "object" && !Array.isArray(body.templateFieldValues)
    ? body.templateFieldValues
    : {};
  const templateFieldSheets = body.templateFieldSheets && typeof body.templateFieldSheets === "object" && !Array.isArray(body.templateFieldSheets)
    ? body.templateFieldSheets
    : {};
  const nowIso = new Date().toISOString();
  const workOrderNumber = normalizeInputValue(body.workOrderNumber || workOrder.workOrderNumber || workOrder.number);
  const workOrderId = normalizeInputValue(workOrder.id);

  return templateIds.map((templateId) => {
    const templateValues = templateFieldValues[templateId] && typeof templateFieldValues[templateId] === "object" && !Array.isArray(templateFieldValues[templateId])
      ? templateFieldValues[templateId]
      : {};
    const templateSheets = templateFieldSheets[templateId] && typeof templateFieldSheets[templateId] === "object" && !Array.isArray(templateFieldSheets[templateId])
      ? templateFieldSheets[templateId]
      : {};
    return {
      ...body,
      templateId,
      fieldValues: {
        ...commonFieldValues,
        ...templateValues,
        [MOBILE_DOCUMENTATION_DRAFT_MARKER_KEY]: "1",
        [MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_ID_KEY]: workOrderId,
        [MOBILE_DOCUMENTATION_DRAFT_WORK_ORDER_NUMBER_KEY]: workOrderNumber,
        [MOBILE_DOCUMENTATION_DRAFT_UPDATED_AT_KEY]: nowIso,
      },
      fieldSheets: {
        ...commonFieldSheets,
        ...templateSheets,
      },
      templateAttachments: body.templateAttachments,
      attachments: body.attachments,
    };
  });
}

async function persistMobileWorkOrderDocumentationDraft({
  body = {},
  workOrder = {},
  scopedSnapshot = {},
  user = null,
} = {}) {
  const recordInputs = buildMobileDocumentationDraftRecordInputs(body, workOrder, scopedSnapshot);
  const savedRecords = [];
  const warnings = [];

  for (const recordInput of recordInputs) {
    const payload = buildWorkOrderDocumentRecordPayloadFromRequest(recordInput, workOrder, scopedSnapshot);
    if (!payload) {
      warnings.push("Nije pronađen povezani predložak za spremanje mobilnog drafta.");
      continue;
    }
    try {
      const saved = await upsertDocumentRecordPayload(payload, user, workOrder);
      if (saved) {
        savedRecords.push(saved);
      }
    } catch (error) {
      warnings.push(error?.message || "Mobilni draft nije spremljen.");
    }
  }

  return { savedRecords, warnings };
}

function isSameGeneratedDocumentRecord(existing = {}, payload = {}, workOrder = {}) {
  if (!existing || !payload) {
    return false;
  }

  if (isMobileDocumentationDraftRecord(existing) || isMobileDocumentationDraftRecord(payload)) {
    return isMobileDocumentationDraftRecord(existing)
      && isMobileDocumentationDraftRecord(payload)
      && String(existing.templateId || "") === String(payload.templateId || "")
      && String(existing.companyId || "") === String(payload.companyId || "")
      && String(existing.locationId || "") === String(payload.locationId || "")
      && String(existing.objectId || "") === String(payload.objectId || "")
      && String(existing.objectName || "") === String(payload.objectName || "")
      && (
        (
          getMobileDocumentationDraftWorkOrderId(existing)
          && getMobileDocumentationDraftWorkOrderId(existing) === getMobileDocumentationDraftWorkOrderId(payload)
        )
        || (
          getMobileDocumentationDraftWorkOrderNumber(existing)
          && getMobileDocumentationDraftWorkOrderNumber(existing) === getMobileDocumentationDraftWorkOrderNumber(payload)
        )
      );
  }

  const existingObjectId = String(existing.objectId || "").trim();
  const payloadObjectId = String(payload.objectId || "").trim();
  if (payloadObjectId && existingObjectId && existingObjectId !== payloadObjectId) {
    return false;
  }

  const existingObjectName = String(existing.objectName || "").trim().toLowerCase();
  const payloadObjectName = String(payload.objectName || "").trim().toLowerCase();
  if (!payloadObjectId && payloadObjectName && existingObjectName && existingObjectName !== payloadObjectName) {
    return false;
  }

  const existingInspectionDate = normalizeGeneratedDocumentRecordDate(existing.inspectionDate);
  const payloadInspectionDate = normalizeGeneratedDocumentRecordDate(payload.inspectionDate);
  if (existingInspectionDate && payloadInspectionDate && existingInspectionDate !== payloadInspectionDate) {
    return false;
  }

  const existingIssuedDate = normalizeGeneratedDocumentRecordDate(existing.issuedDate);
  const payloadIssuedDate = normalizeGeneratedDocumentRecordDate(payload.issuedDate);
  if (existingIssuedDate && payloadIssuedDate && existingIssuedDate !== payloadIssuedDate) {
    return false;
  }

  const existingWorkOrderNumber = getGeneratedDocumentRecordWorkOrderNumber(existing, workOrder);
  const payloadWorkOrderNumber = getGeneratedDocumentRecordWorkOrderNumber(payload, workOrder);
  if (existingWorkOrderNumber && payloadWorkOrderNumber) {
    return existingWorkOrderNumber === payloadWorkOrderNumber;
  }

  return JSON.stringify(existing.fieldValues ?? {}) === JSON.stringify(payload.fieldValues ?? {});
}

function isGeneratedDocumentRecordPayloadCurrent(existing = {}, payload = {}) {
  if (!existing || !payload) {
    return false;
  }

  return String(existing.templateTitle || "") === String(payload.templateTitle || "")
    && String(existing.documentType || "") === String(payload.documentType || "")
    && String(existing.companyId || "") === String(payload.companyId || "")
    && String(existing.locationId || "") === String(payload.locationId || "")
    && String(existing.objectId || "") === String(payload.objectId || "")
    && String(existing.objectName || "") === String(payload.objectName || "")
    && normalizeGeneratedDocumentRecordDate(existing.inspectionDate) === normalizeGeneratedDocumentRecordDate(payload.inspectionDate)
    && normalizeGeneratedDocumentRecordDate(existing.issuedDate) === normalizeGeneratedDocumentRecordDate(payload.issuedDate)
    && normalizeGeneratedDocumentRecordExpirationFromPayload(existing) === normalizeGeneratedDocumentRecordExpirationFromPayload(payload)
    && JSON.stringify(existing.fieldValues ?? {}) === JSON.stringify(payload.fieldValues ?? {})
    && JSON.stringify(existing.fieldSheets ?? {}) === JSON.stringify(payload.fieldSheets ?? {});
}

async function upsertDocumentRecordPayload(payload = {}, user = null, workOrder = {}) {
  if (typeof domainRepository.createDocumentRecord !== "function") {
    return null;
  }

  const normalizedPayload = {
    ...payload,
    expirationDate: normalizeGeneratedDocumentRecordExpirationFromPayload(payload),
  };

  if (typeof domainRepository.listDocumentRecords === "function") {
    const existingRecords = await domainRepository.listDocumentRecords({
      organizationId: normalizedPayload.organizationId,
      templateId: normalizedPayload.templateId,
      companyId: normalizedPayload.companyId,
      locationId: normalizedPayload.locationId,
      objectId: normalizedPayload.objectId,
      limit: 50,
      periodics: true,
    });
    const existing = existingRecords.find((record) => isSameGeneratedDocumentRecord(record, normalizedPayload, workOrder));
    if (existing) {
      const existingExpirationDate = normalizeGeneratedDocumentRecordExpirationFromPayload(existing);
      let payloadForSave = normalizedPayload;
      if (!payloadForSave.expirationDate && existingExpirationDate) {
        const existingFieldValues = existing?.fieldValues && typeof existing.fieldValues === "object" && !Array.isArray(existing.fieldValues)
          ? existing.fieldValues
          : {};
        const payloadFieldValues = payloadForSave?.fieldValues && typeof payloadForSave.fieldValues === "object" && !Array.isArray(payloadForSave.fieldValues)
          ? payloadForSave.fieldValues
          : {};
        payloadForSave = {
          ...payloadForSave,
          expirationDate: existingExpirationDate,
          fieldValues: {
            ...payloadFieldValues,
            ...(!Array.isArray(payloadFieldValues[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY])
              && Array.isArray(existingFieldValues[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY])
              ? { [GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY]: existingFieldValues[GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY] }
              : {}),
          },
        };
      }
      if (
        typeof domainRepository.updateDocumentRecord === "function"
        && !isGeneratedDocumentRecordPayloadCurrent(existing, payloadForSave)
      ) {
        return await domainRepository.updateDocumentRecord(existing.id, payloadForSave, user) || existing;
      }
      return existing;
    }
  }

  return await domainRepository.createDocumentRecord(normalizedPayload, user);
}

async function ensureGeneratedDocumentTemplateRecord({
  entry = {},
  workOrder = {},
  template = {},
  scopedSnapshot = {},
  user = null,
} = {}) {
  if (
    typeof domainRepository.createDocumentRecord !== "function"
    || typeof domainRepository.listDocumentRecords !== "function"
  ) {
    return null;
  }

  const payload = buildGeneratedDocumentTemplateRecordPayload({
    entry,
    workOrder,
    template,
    scopedSnapshot,
  });

  if (!payload) {
    return null;
  }

  return await upsertDocumentRecordPayload(payload, user, workOrder);
}

function stripStoredDocumentPayloadForResponse(document = null) {
  if (!document || typeof document !== "object") {
    return document;
  }
  const { dataUrl, ...rest } = document;
  return rest;
}

function cleanupMobileDocumentGenerationJobs() {
  const now = Date.now();
  for (const [jobId, job] of mobileDocumentGenerationJobs.entries()) {
    if (!job || Number(job.expiresAtMs || 0) <= now) {
      mobileDocumentGenerationJobs.delete(jobId);
    }
  }
}

function flattenGeneratedDocumentSaveItems(items = []) {
  return (Array.isArray(items) ? items : []).flatMap((item) => {
    if (Array.isArray(item?.documents) && item.documents.length > 0) {
      return item.documents;
    }
    return item?.item ? [item.item] : [];
  }).filter(Boolean);
}

function buildMobileDocumentGenerationJobResponse(job = {}) {
  const status = String(job.status || "pending").trim() || "pending";
  const items = Array.isArray(job.items) ? job.items : [];
  const documents = flattenGeneratedDocumentSaveItems(items);
  const records = items.map((item) => item?.record).filter(Boolean);
  return {
    ok: status === "completed",
    jobId: String(job.id || "").trim(),
    status,
    workOrderId: String(job.workOrderId || "").trim(),
    entriesCount: Number(job.entriesCount || 0) || 0,
    generatedCount: items.length,
    documentCount: documents.length,
    recordCount: records.length,
    items: documents.map((item) => stripStoredDocumentPayloadForResponse(item)),
    entries: items.map((item) => stripStoredDocumentPayloadForResponse(item)),
    records,
    error: String(job.error || "").trim(),
    createdAt: job.createdAt || "",
    startedAt: job.startedAt || "",
    completedAt: job.completedAt || "",
    expiresAt: job.expiresAt || "",
  };
}

function getMobileDocumentGenerationJob(jobId = "", user = null, workOrderId = "") {
  cleanupMobileDocumentGenerationJobs();
  const normalizedJobId = String(jobId || "").trim();
  const job = mobileDocumentGenerationJobs.get(normalizedJobId);
  if (!job) {
    return null;
  }
  const expectedUserId = String(user?.id || "").trim();
  if (expectedUserId && String(job.userId || "").trim() !== expectedUserId) {
    return null;
  }
  const expectedWorkOrderId = String(workOrderId || "").trim();
  if (expectedWorkOrderId && String(job.workOrderId || "").trim() !== expectedWorkOrderId) {
    return null;
  }
  return job;
}

function startMobileDocumentGenerationJob({
  workOrderId = "",
  workOrder = null,
  wizardInput = {},
  entries = null,
  scopedSnapshot = {},
  user = null,
} = {}) {
  cleanupMobileDocumentGenerationJobs();
  const now = Date.now();
  const expiresAtMs = now + MOBILE_DOCUMENT_GENERATION_JOB_TTL_MS;
  const job = {
    id: randomUUID(),
    workOrderId: String(workOrderId || "").trim(),
    userId: String(user?.id || "").trim(),
    status: "pending",
    entriesCount: Array.isArray(entries) ? entries.length : 0,
    items: [],
    error: "",
    createdAt: new Date(now).toISOString(),
    startedAt: "",
    completedAt: "",
    expiresAtMs,
    expiresAt: new Date(expiresAtMs).toISOString(),
  };
  mobileDocumentGenerationJobs.set(job.id, job);

  setTimeout(() => {
    void (async () => {
      job.status = "running";
      job.startedAt = new Date().toISOString();
      try {
        const effectiveWizardInput = {
          ...(wizardInput && typeof wizardInput === "object" && !Array.isArray(wizardInput) ? wizardInput : {}),
          currentUserId: normalizeInputValue(wizardInput?.currentUserId) || normalizeInputValue(user?.id),
          currentUserLabel: normalizeInputValue(wizardInput?.currentUserLabel)
            || normalizeInputValue(user?.displayName || user?.fullName || user?.username || user?.email),
        };
        const jobEntries = Array.isArray(entries)
          ? entries
          : buildMobileWorkOrderGeneratedDocumentEntries(workOrder || {}, scopedSnapshot, effectiveWizardInput);
        job.entriesCount = jobEntries.length;
        if (jobEntries.length === 0) {
          throw new Error("Ovaj RN nema uslugu s povezanim templateom za izradu dokumentacije.");
        }
        const items = await saveGeneratedDocumentTemplatePdfDocuments(jobEntries, scopedSnapshot, user, {});
        job.items = items;
        job.status = items.length > 0 ? "completed" : "failed";
        job.error = items.length > 0 ? "" : "Nijedan zapisnik nije spremljen u dokumentaciju RN-a.";
      } catch (error) {
        job.status = "failed";
        job.error = error?.message || "Ne mogu izraditi dokumentaciju RN-a.";
        console.error("[mobile-document-generation-job] failed", {
          jobId: job.id,
          workOrderId: job.workOrderId,
          entries: job.entriesCount,
          error: job.error,
        });
      } finally {
        job.completedAt = new Date().toISOString();
        job.expiresAtMs = Date.now() + MOBILE_DOCUMENT_GENERATION_JOB_TTL_MS;
        job.expiresAt = new Date(job.expiresAtMs).toISOString();
      }
    })();
  }, 0);

  return job;
}

function waitForMobileDocumentGenerationJob(job = {}, timeoutMs = 20_000) {
  const deadline = Date.now() + Math.max(0, Number(timeoutMs) || 0);
  return new Promise((resolve) => {
    const poll = () => {
      if (!job || job.status === "completed" || job.status === "failed" || Date.now() >= deadline) {
        resolve(job);
        return;
      }
      setTimeout(poll, 500);
    };
    poll();
  });
}

function cleanupSignatureBridgeJobs() {
  const now = Date.now();
  for (const [token, job] of signatureBridgeJobs.entries()) {
    if (!job || Number(job.expiresAtMs || 0) <= now) {
      releaseSignatureBridgeJobLocks(job);
      signatureBridgeJobs.delete(token);
    }
  }
}

function cleanupSignatureBridgeLocks() {
  const now = Date.now();
  for (const [key, lock] of signatureBridgeLocks.entries()) {
    if (!lock || Number(lock.signingLockUntilMs || 0) <= now) {
      signatureBridgeLocks.delete(key);
    }
  }
}

function getSignatureBridgeItemLockKey(item = {}) {
  return [
    String(item.workOrderId || "").trim(),
    String(item.documentId || "").trim(),
    String(item.preferredField || item.fieldName || item.id || "").trim(),
  ].filter(Boolean).join(":");
}

function applySignatureBridgeLockToItem(item = {}, lock = {}, status = "locked") {
  item.signingStatus = status;
  item.signingLockByUserId = lock.signingLockByUserId || "";
  item.signingLockByUserName = lock.signingLockByUserName || "";
  item.signingLockUntil = lock.signingLockUntil || "";
  item.signingLockUntilMs = Number(lock.signingLockUntilMs || 0) || 0;
  item.signingLockToken = lock.signingLockToken || "";
  return item;
}

function acquireSignatureBridgeItemLock(item = {}, user = {}) {
  cleanupSignatureBridgeLocks();
  const key = getSignatureBridgeItemLockKey(item);
  if (!key) {
    return item;
  }
  const existing = signatureBridgeLocks.get(key);
  const userId = String(user?.id || "").trim();
  if (
    existing
    && Number(existing.signingLockUntilMs || 0) > Date.now()
    && String(existing.signingLockByUserId || "") !== userId
  ) {
    item.lockKey = key;
    item.lockedByOther = true;
    return applySignatureBridgeLockToItem(item, existing, "locked_by_other");
  }

  const untilMs = Date.now() + SIGNATURE_BRIDGE_LOCK_TTL_MS;
  const lock = {
    lockKey: key,
    signingLockByUserId: userId,
    signingLockByUserName: String(user?.fullName || user?.username || user?.email || "korisnik").trim(),
    signingLockUntilMs: untilMs,
    signingLockUntil: new Date(untilMs).toISOString(),
    signingLockToken: randomUUID(),
  };
  signatureBridgeLocks.set(key, lock);
  item.lockKey = key;
  item.lockedByOther = false;
  return applySignatureBridgeLockToItem(item, lock, "locked");
}

function releaseSignatureBridgeItemLock(item = {}) {
  cleanupSignatureBridgeLocks();
  const key = item.lockKey || getSignatureBridgeItemLockKey(item);
  if (!key) {
    return;
  }
  const existing = signatureBridgeLocks.get(key);
  if (!existing || !item.signingLockToken || existing.signingLockToken === item.signingLockToken) {
    signatureBridgeLocks.delete(key);
  }
}

function releaseSignatureBridgeJobLocks(job = {}) {
  if (!job || !Array.isArray(job.items)) {
    return;
  }
  job.items.forEach((item) => releaseSignatureBridgeItemLock(item));
}

function refreshSignatureBridgeItemLock(item = {}) {
  if (!item.signingLockToken || item.lockedByOther) {
    return;
  }
  const key = item.lockKey || getSignatureBridgeItemLockKey(item);
  const existing = key ? signatureBridgeLocks.get(key) : null;
  if (!existing || existing.signingLockToken !== item.signingLockToken) {
    return;
  }
  const untilMs = Date.now() + SIGNATURE_BRIDGE_LOCK_TTL_MS;
  existing.signingLockUntilMs = untilMs;
  existing.signingLockUntil = new Date(untilMs).toISOString();
  applySignatureBridgeLockToItem(item, existing, "locked");
}

function hashSignatureBridgeBuffer(buffer = Buffer.alloc(0)) {
  try {
    return createHash("sha256").update(Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer ?? [])).digest("hex");
  } catch {
    return "";
  }
}

function getSignatureBridgeJob(token = "") {
  cleanupSignatureBridgeJobs();
  const normalizedToken = String(token || "").trim();
  if (!normalizedToken) {
    return null;
  }

  const job = signatureBridgeJobs.get(normalizedToken);
  if (!job || Number(job.expiresAtMs || 0) <= Date.now()) {
    signatureBridgeJobs.delete(normalizedToken);
    return null;
  }

  return job;
}

function normalizeSignatureBridgeKey(value = "") {
  return String(value || "").trim().toLowerCase();
}

function markSignatureBridgeJobProgress(job = {}) {
  if (!job || !Array.isArray(job.items)) {
    return job;
  }
  const allSigned = job.items.length > 0 && job.items.every((item) => item?.signedAt || item?.savedDocumentId);
  if (allSigned) {
    job.status = "completed";
    job.completedAtMs = job.completedAtMs || Date.now();
  }
  return job;
}

function claimNextSignatureBridgeJob(bridgeKey = "") {
  cleanupSignatureBridgeJobs();
  const normalizedKey = normalizeSignatureBridgeKey(bridgeKey);
  if (!normalizedKey) {
    return null;
  }

  const now = Date.now();
  const jobs = Array.from(signatureBridgeJobs.values())
    .map((job) => markSignatureBridgeJobProgress(job))
    .filter((job) => (
      normalizeSignatureBridgeKey(job?.bridgeKey) === normalizedKey
      && job.status !== "completed"
      && job.status !== "cancelled"
      && Array.isArray(job.items)
      && job.items.some((item) => !item?.signedAt && !item?.savedDocumentId)
      && (
        job.status !== "claimed"
        || Number(job.claimedAtMs || 0) + SIGNATURE_BRIDGE_CLAIM_TTL_MS <= now
      )
    ))
    .sort((a, b) => Number(a.createdAtMs || 0) - Number(b.createdAtMs || 0));

  const job = jobs[0] || null;
  if (!job) {
    return null;
  }

  job.status = "claimed";
  job.claimedAtMs = now;
  return job;
}

function getRequestPublicBaseUrl(request) {
  const configured = canonicalAppOrigin || publicAppUrl;
  if (configured) {
    return configured.replace(/\/+$/, "");
  }

  const forwardedProto = String(request.headers["x-forwarded-proto"] || "").split(",")[0].trim();
  const host = String(request.headers["x-forwarded-host"] || request.headers.host || "").split(",")[0].trim();
  if (host) {
    return `${forwardedProto || "https"}://${host}`.replace(/\/+$/, "");
  }

  return "https://safe-nexus.org";
}

function isSignatureBridgeDocumentSigned(document = {}) {
  const fieldNames = getSignatureBridgeDocumentFieldNames(document);
  if (fieldNames.length > 0) {
    const signedFields = getSignatureBridgeDocumentSignedFieldNames(document);
    if (signedFields.size === 0) {
      return fieldNames.length === 1 && /\bpotpisano\b/i.test(String(document?.description || ""));
    }
    return fieldNames.every((fieldName) => signedFields.has(fieldName));
  }
  return /\bpotpisano\b/i.test(String(document?.description || ""));
}

function isSignatureBridgeDocumentRejected(document = {}) {
  return String(document?.signatureReviewStatus || "").trim() === "rejected_with_comment";
}

function normalizeSignatureBridgeFieldName(value = "") {
  return String(value || "").trim();
}

function parseSignatureBridgeJsonArray(value = "") {
  if (!value || typeof value !== "string") {
    return [];
  }
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function getSignatureBridgeDocumentFieldNames(document = {}) {
  const fields = parseSignatureBridgeJsonArray(document?.signatureFieldsJson)
    .map((entry) => normalizeSignatureBridgeFieldName(entry?.fieldName || entry?.preferredField))
    .filter(Boolean);
  if (fields.length > 0) {
    return Array.from(new Set(fields));
  }
  const preferredField = normalizeSignatureBridgeFieldName(document?.preferredField);
  return preferredField ? [preferredField] : [];
}

function getSignatureBridgeDocumentSignedFieldNames(document = {}) {
  const names = parseSignatureBridgeJsonArray(document?.signedFieldsJson)
    .map((entry) => normalizeSignatureBridgeFieldName(typeof entry === "string" ? entry : (entry?.fieldName || entry?.preferredField)))
    .filter(Boolean);
  return new Set(names);
}

function buildSignatureBridgeSignedFieldsJson(document = {}, fieldName = "") {
  const signedFields = getSignatureBridgeDocumentSignedFieldNames(document);
  const normalizedFieldName = normalizeSignatureBridgeFieldName(fieldName);
  if (normalizedFieldName) {
    signedFields.add(normalizedFieldName);
  }
  return JSON.stringify(Array.from(signedFields).map((name) => ({
    fieldName: name,
    signedAt: new Date().toISOString(),
  })));
}

function normalizeSignatureFieldRole(value = "ZNR") {
  const normalized = String(value || "ZNR")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return normalized || "ZNR";
}

function normalizeSignatureFieldOib(value = "") {
  const digits = String(value || "").replace(/\D/g, "");
  return /^\d{11}$/.test(digits) ? digits : "";
}

function buildSignatureFieldName(role = "ZNR", oib = "") {
  const normalizedOib = normalizeSignatureFieldOib(oib);
  if (!normalizedOib) {
    return "";
  }
  return `SIGN_${normalizeSignatureFieldRole(role)}_${normalizedOib}`;
}

function resolveSignatureBridgeFieldMetadata(body = {}, document = {}, workOrder = {}, user = {}) {
  const documentId = String(document?.id || "").trim();
  const preferredFieldsByDocumentId = body?.preferredFieldsByDocumentId && typeof body.preferredFieldsByDocumentId === "object"
    ? body.preferredFieldsByDocumentId
    : {};
  const fieldMetadataByDocumentId = body?.signatureFieldsByDocumentId && typeof body.signatureFieldsByDocumentId === "object"
    ? body.signatureFieldsByDocumentId
    : {};
  const explicitMetadata = fieldMetadataByDocumentId[documentId] && typeof fieldMetadataByDocumentId[documentId] === "object"
    ? fieldMetadataByDocumentId[documentId]
    : {};

  const signatureFieldRole = normalizeSignatureFieldRole(
    explicitMetadata.role
      || body?.signatureFieldRole
      || document?.signatureFieldRole
      || workOrder?.signatureFieldRole
      || "ZNR",
  );
  const signatureFieldOib = normalizeSignatureFieldOib(
    explicitMetadata.oib
      || body?.signatureFieldOib
      || body?.signerOib
      || document?.signatureFieldOib
      || document?.signerOib
      || workOrder?.signatureFieldOib
      || workOrder?.signerOib
      || user?.oib
      || "",
  );
  const preferredField = String(
    preferredFieldsByDocumentId[documentId]
      || explicitMetadata.preferredField
      || body?.preferredField
      || document?.preferredField
      || buildSignatureFieldName(signatureFieldRole, signatureFieldOib)
      || "",
  ).trim();

  return {
    signatureFieldRole,
    signatureFieldOib,
    preferredField,
    signatureFieldStandard: "SIGN_{ROLE}_{OIB}",
  };
}

function buildSignatureBridgeSignedDescription(document = {}, job = {}) {
  const currentDescription = String(document?.description || "").trim();
  const baseDescription = currentDescription && !isSignatureBridgeDocumentSigned(document)
    ? currentDescription
    : `Zapisnik za digitalni potpis.`;
  const signedAt = new Date().toISOString();
  const signerLabel = String(job?.user?.fullName || job?.user?.email || job?.createdByLabel || "lokalni signer").trim();
  return `${baseDescription.replace(/\s*Potpisano digitalno preko SafeNexus Signer bridgea.*$/i, "").trim()} Potpisano digitalno preko SafeNexus Signer bridgea ${signedAt}${signerLabel ? ` (${signerLabel})` : ""}.`.trim();
}

function buildSignatureBridgeProtocolUrl(job = {}) {
  const apiBase = encodeURIComponent(job.apiBase || "https://safe-nexus.org");
  const origin = encodeURIComponent(job.origin || job.apiBase || "https://safe-nexus.org");
  return `safenexus-signer://sign?token=${encodeURIComponent(job.token)}&api=${apiBase}&origin=${origin}`;
}

async function buildSignatureBridgeCandidateDocuments(scopedSnapshot = {}, requestedDocumentIds = []) {
  const scopedWorkOrders = Array.isArray(scopedSnapshot.workOrders) ? scopedSnapshot.workOrders : [];
  const workOrderIds = scopedWorkOrders.map((workOrder) => String(workOrder?.id || "").trim()).filter(Boolean);
  const requestedIds = new Set(
    (Array.isArray(requestedDocumentIds) ? requestedDocumentIds : [])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  );
  const allDocuments = typeof domainRepository.listWorkOrderDocuments === "function"
    ? await domainRepository.listWorkOrderDocuments(workOrderIds, {
      sourceType: "pdf",
      limit: 5000,
      includeDataUrl: false,
    })
    : (await Promise.all(workOrderIds.map((workOrderId) => domainRepository.getWorkOrderDocuments(workOrderId, { includeDataUrl: false }))))
      .flat()
      .filter((document) => (
        SIGNATURE_PDF_DOCUMENT_CATEGORIES.includes(String(document?.documentCategory || "").trim())
        && String(document?.sourceType || "").toLowerCase() === "pdf"
      ));

  return allDocuments
    .filter((document) => (
      String(document?.id || "").trim()
      && String(document?.workOrderId || "").trim()
      && SIGNATURE_PDF_DOCUMENT_CATEGORIES.includes(String(document?.documentCategory || "").trim())
      && (!requestedIds.size || requestedIds.has(String(document.id)))
      && !isSignatureBridgeDocumentSigned(document)
      && !isSignatureBridgeDocumentRejected(document)
    ))
    .slice(0, SIGNATURE_BRIDGE_MAX_ITEMS);
}

function buildSignatureBridgeJobResponse(job = {}) {
  cleanupSignatureBridgeLocks();
  if (Array.isArray(job.items)) {
    job.items.forEach((item) => refreshSignatureBridgeItemLock(item));
  }
  return {
    ok: true,
    token: job.token,
    apiBase: job.apiBase,
    origin: job.origin,
    status: job.status || "pending",
    bridgeKey: job.bridgeKey || "",
    expiresAt: new Date(job.expiresAtMs).toISOString(),
    protocolUrl: buildSignatureBridgeProtocolUrl(job),
    engineHint: "PotpisPDF.exe",
    items: job.items.map((item) => ({
      id: item.id,
      workOrderId: item.workOrderId,
      documentId: item.documentId,
      workOrderNumber: item.workOrderNumber,
      companyName: item.companyName,
      locationName: item.locationName,
      fileName: item.fileName,
      fileType: item.fileType || "application/pdf",
      fileSize: item.fileSize || 0,
      preferredField: item.preferredField || "",
      signatureFieldRole: item.signatureFieldRole || "ZNR",
      signatureFieldOib: item.signatureFieldOib || "",
      signatureFieldStandard: item.signatureFieldStandard || "SIGN_{ROLE}_{OIB}",
      signatureFieldsJson: item.signatureFieldsJson || "",
      signatureLabel: item.signatureLabel || "",
      signatureSigner: item.signatureSigner || "",
      signerName: item.signerName || item.signatureSigner || "",
      signerTitle: item.signerTitle || "",
      signerUserId: item.signerUserId || "",
      signerEmail: item.signerEmail || "",
      signerOrganization: item.signerOrganization || "",
      signingStatus: item.signingStatus || "",
      signingLockByUserId: item.signingLockByUserId || "",
      signingLockByUserName: item.signingLockByUserName || "",
      signingLockUntil: item.signingLockUntil || "",
      signingLockToken: item.lockedByOther ? "" : (item.signingLockToken || ""),
      lockToken: item.lockedByOther ? "" : (item.signingLockToken || ""),
      signedAt: item.signedAt || "",
      savedDocumentId: item.savedDocumentId || "",
      downloadUrl: `${job.apiBase}/api/signature-bridge/jobs/${encodeURIComponent(job.token)}/items/${encodeURIComponent(item.id)}/download`,
      uploadUrl: `${job.apiBase}/api/signature-bridge/jobs/${encodeURIComponent(job.token)}/items/${encodeURIComponent(item.id)}/signed?lockToken=${encodeURIComponent(item.lockedByOther ? "" : (item.signingLockToken || ""))}`,
    })),
  };
}

async function handleSignatureBridgeJobDownload(request, response, token = "", itemId = "") {
  const job = getSignatureBridgeJob(token);
  if (!job) {
    sendError(response, 404, "Potpisni paket je istekao ili nije pronađen.");
    return true;
  }

  const item = job.items.find((entry) => String(entry.id) === String(itemId));
  if (!item) {
    sendError(response, 404, "Dokument za potpis nije pronađen.");
    return true;
  }

  const documents = await domainRepository.getWorkOrderDocuments(item.workOrderId);
  const document = documents.find((entry) => String(entry.id) === String(item.documentId));
  if (!document) {
    sendError(response, 404, "Dokument vise nije dostupan.");
    return true;
  }

  const stored = await readStoredDocumentBuffer(document);
  sendBinary(response, 200, stored.buffer, {
    contentType: stored.mimeType || document.fileType || "application/pdf",
    fileName: document.fileName || item.fileName || "zapisnik.pdf",
  });
  return true;
}

async function handleSignatureBridgeSignedUpload(request, response, token = "", itemId = "") {
  const job = getSignatureBridgeJob(token);
  if (!job) {
    sendError(response, 404, "Potpisni paket je istekao ili nije pronađen.");
    return true;
  }

  const item = job.items.find((entry) => String(entry.id) === String(itemId));
  if (!item) {
    sendError(response, 404, "Dokument za potpis nije pronađen.");
    return true;
  }

  const body = await readJsonBody(request);
  const requestUrl = new URL(request.url, "http://localhost");
  let providedLockToken = String(
    body?.lockToken
    || requestUrl.searchParams.get("lockToken")
    || request.headers["x-safenexus-lock-token"]
    || "",
  ).trim();
  if (!providedLockToken && item.signingLockToken && !item.lockedByOther) {
    // Older native signer builds upload through the short-lived job token but do not echo lockToken.
    providedLockToken = item.signingLockToken;
  }
  if (item.signingLockToken && providedLockToken !== item.signingLockToken) {
    sendJson(response, 423, {
      ok: false,
      code: "SIGNING_LOCK_MISMATCH",
      message: "Ovaj potpis nije zaključan za trenutni signing token.",
      itemId: item.id,
      documentId: item.documentId,
      fileName: item.fileName,
    });
    return true;
  }

  const dataUrl = String(body?.dataUrl || "").trim();
  if (!dataUrl.startsWith("data:application/pdf;base64,")) {
    sendError(response, 400, "Potpisani dokument mora biti PDF data URL.");
    return true;
  }

  const documents = await domainRepository.getWorkOrderDocuments(item.workOrderId);
  const currentDocument = documents.find((entry) => String(entry.id) === String(item.documentId));
  if (!currentDocument) {
    sendError(response, 404, "Izvorni dokument vise nije dostupan.");
    return true;
  }
  if (item.signedAt || item.savedDocumentId || isSignatureBridgeDocumentSigned(currentDocument)) {
    sendJson(response, 409, {
      ok: false,
      code: "ALREADY_SIGNED",
      message: "Dokument je već potpisan.",
      itemId: item.id,
      documentId: item.documentId,
      fileName: item.fileName,
    });
    return true;
  }

  const originalStored = await readStoredDocumentBuffer(currentDocument);
  const base64 = dataUrl.split(",", 2)[1] || "";
  const signedBuffer = Buffer.from(base64, "base64");
  const bufferSize = Buffer.byteLength(base64, "base64");
  const signedFieldName = String(body?.signedField || body?.fieldName || item.preferredField || "").trim();
  const filePayload = {
    fileName: String(body?.fileName || currentDocument.fileName || item.fileName || "zapisnik.pdf").trim(),
    fileType: "application/pdf",
    fileSize: Number(body?.fileSize || 0) || bufferSize,
    documentCategory: currentDocument.documentCategory || GENERATED_DOCUMENT_TEMPLATE_PDF_CATEGORY,
    sourceType: "pdf",
    description: buildSignatureBridgeSignedDescription(currentDocument, job),
    signatureFieldRole: currentDocument.signatureFieldRole || item.signatureFieldRole || "",
    signatureFieldOib: currentDocument.signatureFieldOib || item.signatureFieldOib || "",
    preferredField: currentDocument.preferredField || item.preferredField || "",
    signatureFieldsJson: currentDocument.signatureFieldsJson || "",
    signedFieldsJson: buildSignatureBridgeSignedFieldsJson(currentDocument, signedFieldName),
    dataUrl,
  };

  const saved = typeof domainRepository.upsertWorkOrderGeneratedPdfDocument === "function"
    ? await domainRepository.upsertWorkOrderGeneratedPdfDocument(item.workOrderId, filePayload, job.user)
    : (await domainRepository.addWorkOrderDocuments(item.workOrderId, [filePayload], job.user, { sourceType: "pdf" }))[0] ?? null;

  item.signedAt = new Date().toISOString();
  item.savedDocumentId = saved?.id || "";
  item.signingStatus = "signed";
  signatureBridgeAuditLog.push({
    id: randomUUID(),
    workOrderId: item.workOrderId,
    workOrderNumber: item.workOrderNumber,
    documentId: item.documentId,
    documentName: item.fileName,
    signatureItemId: item.id,
    fieldName: signedFieldName || item.preferredField || "",
    placeholderKey: signedFieldName || item.preferredField || "",
    label: item.signatureLabel || "",
    servicePart: item.servicePart || "",
    personLevel: item.personLevel || "",
    signerUserId: item.signerUserId || job.user?.id || "",
    signerName: item.signerName || item.signatureSigner || job.user?.fullName || "",
    signerOib: item.signatureFieldOib || "",
    signerTitle: item.signerTitle || "",
    certificateSubject: String(body?.certificateSubject || body?.certificate?.subject || "").trim(),
    certificateOib: String(body?.certificateOib || body?.certificate?.oib || "").trim(),
    certificateSerialNumber: String(body?.certificateSerialNumber || body?.certificate?.serialNumber || "").trim(),
    provider: String(body?.provider || body?.certificateProvider || "").trim(),
    signedAt: item.signedAt,
    originalDocumentHash: hashSignatureBridgeBuffer(originalStored.buffer),
    signedDocumentHash: hashSignatureBridgeBuffer(signedBuffer),
    status: "signed",
    errorCode: "",
    errorMessage: "",
  });
  releaseSignatureBridgeItemLock(item);
  markSignatureBridgeJobProgress(job);
  sendJson(response, 200, {
    ok: true,
    item: stripStoredDocumentPayloadForResponse(saved),
  });
  return true;
}

function logDocumentTemplateExportTiming(event = "", details = {}) {
  try {
    console.info("[document-template-export]", JSON.stringify({
      event,
      ...details,
    }));
  } catch {
    console.info("[document-template-export]", event);
  }
}

async function saveGeneratedDocumentTemplatePdfDocuments(entries = [], scopedSnapshot = {}, user = null, options = {}) {
  const startedAt = Date.now();
  const workOrders = scopedSnapshot.workOrders ?? [];
  const generateStartedAt = Date.now();
  const generatedBundles = await generateTemplateDocumentFilesForEntries(entries, scopedSnapshot, {
    signatureSettings: options.signatureSettings,
    documentStampSettings: options.documentStampSettings,
  });
  const generateMs = Date.now() - generateStartedAt;
  const savedItems = [];
  const saveStartedAt = Date.now();

  for (const bundle of generatedBundles) {
    const workOrderId = String(bundle?.entry?.workOrderId || "").trim();
    const workOrder = assertInScope(workOrders, workOrderId, "Radni nalog nije pronaden.");
    const savedDocuments = [];
    let primaryPdfItem = null;

    for (const file of bundle.files) {
      if (file.kind !== "pdf") {
        continue;
      }

      const filePayload = buildGeneratedDocumentTemplatePdfDocumentPayload({
        workOrder,
        template: bundle.template,
        pdfBuffer: file.buffer,
        fileName: file.fileName,
        entry: bundle.entry,
      });
      const pdfItem = typeof domainRepository.upsertWorkOrderGeneratedPdfDocument === "function"
        ? await domainRepository.upsertWorkOrderGeneratedPdfDocument(workOrderId, filePayload, user)
        : (await domainRepository.addWorkOrderDocuments(
          workOrderId,
          [filePayload],
          user,
          { sourceType: "pdf" },
        ))[0] ?? null;
      if (pdfItem) {
        const strippedPdfItem = stripStoredDocumentPayloadForResponse(pdfItem);
        savedDocuments.push(strippedPdfItem);
        primaryPdfItem = strippedPdfItem;
      }
    }

    let documentRecord = null;
    try {
      documentRecord = await ensureGeneratedDocumentTemplateRecord({
        entry: bundle.entry,
        workOrder,
        template: bundle.template,
        scopedSnapshot,
        user,
      });
    } catch (recordError) {
      console.warn("Generated document was saved, but periodics record could not be persisted.", recordError);
    }

    savedItems.push({
      workOrderId,
      workOrderNumber: String(workOrder.workOrderNumber || "").trim(),
      companyId: String(workOrder.companyId || "").trim(),
      companyName: String(workOrder.companyName || "").trim(),
      locationName: String(workOrder.locationName || "").trim(),
      templateId: String(bundle?.entry?.templateId || bundle?.template?.id || "").trim(),
      templateTitle: String(
        bundle?.entry?.documentRecord?.templateTitle
        || bundle?.template?.title
        || bundle?.template?.documentType
        || "Zapisnik",
      ).trim(),
      exportKind: String(bundle?.entry?.exportKind || "").trim(),
      fileName: primaryPdfItem?.fileName || savedDocuments[0]?.fileName || "",
      item: primaryPdfItem || savedDocuments[0] || null,
      documents: savedDocuments,
      record: documentRecord,
    });
  }

  logDocumentTemplateExportTiming("save-documents", {
    entries: Array.isArray(entries) ? entries.length : 0,
    bundles: generatedBundles.length,
    generatedFiles: generatedBundles.reduce((total, bundle) => total + (bundle.files?.length || 0), 0),
    savedItems: savedItems.length,
    savedDocuments: savedItems.reduce((total, item) => total + (item.documents?.length || 0), 0),
    generateMs,
    saveMs: Date.now() - saveStartedAt,
    totalMs: Date.now() - startedAt,
  });

  if (savedItems.some((entry) => entry?.item || entry?.record)) {
    invalidateSnapshotCaches();
  }

  const savedByWorkOrderId = savedItems
    .filter((entry) => entry?.item)
    .reduce((map, entry) => {
      const key = String(entry.workOrderId || "").trim();
      if (!key) {
        return map;
      }
      const current = map.get(key) ?? [];
      current.push(entry);
      map.set(key, current);
      return map;
    }, new Map());

  savedByWorkOrderId.forEach((items, workOrderId) => {
    const workOrder = workOrders.find((entry) => String(entry.id) === String(workOrderId));
    if (!workOrder) {
      return;
    }
    const recipientIds = resolveWorkOrderPushUserIds(workOrder, scopedSnapshot);
    if (recipientIds.length === 0) {
      return;
    }
    const firstItem = items[0] ?? {};
    const workOrderNumber = String(firstItem.workOrderNumber || workOrder.workOrderNumber || "").trim() || "-";
    queuePushToUserIds(recipientIds, {
      title: "Dokumentacija spremna",
      body: items.length > 1
        ? `RN ${workOrderNumber}: spremljeno je ${items.length} dokumenata.`
        : `RN ${workOrderNumber}: ${firstItem.fileName || "dokument"} je spremljen.`,
      data: {
        type: "document_ready",
        workOrderId,
        workOrderNumber,
        documentId: String(firstItem.item?.id || "").trim(),
      },
    });
  });

  return savedItems.filter((entry) => entry?.item);
}

function buildOfferTemplatePlaceholderPayload(offer = {}) {
  const normalizedOffer = offer && typeof offer === "object" ? offer : {};
  const currency = String(normalizedOffer.currency || "EUR").trim() || "EUR";
  const items = Array.isArray(normalizedOffer.items) ? normalizedOffer.items : [];
  const planType = normalizeCommercialOfferPlanType(normalizedOffer.serviceLine || "");
  const itemsFallbackTitle = planType === "Per Employee Plan"
    ? "Cijena po zaposleniku"
    : "Opis stavke";
  const suppressItemTotals = planType === "Hybrid Plan"
    || items.some((item) => hasCommercialBreakdownRows(item));
  const itemsSummary = items
    .map((item, index) => `${index + 1}. ${item.description || "Stavka"}${item.unit ? ` · ${item.quantity || 0} ${item.unit}` : ""}${item?.isIncludedService ? " · Uključeno" : (Number(item.totalPrice || 0) > 0 ? ` · ${formatOfferTemplateMoney(item.totalPrice || 0, currency)}` : "")}`)
    .join("\n");
  const itemsTableText = items
    .map((item, index) => {
      const breakdownText = Array.isArray(item.breakdowns) && item.breakdowns.length > 0
        ? `\n${item.breakdowns.map((entry) => `   - ${formatCommercialBreakdownLabel(entry)}: ${formatOfferTemplateMoney(entry.amount || 0, currency)}`).join("\n")}`
        : "";
      const amountText = item?.isIncludedService
        ? "Uključeno"
        : suppressItemTotals
        ? formatOfferTemplateMoney(item.unitPrice || 0, currency)
        : formatOfferTemplateMoney(item.totalPrice || 0, currency);
      return `${index + 1}. ${item.description || "Stavka"} | ${item.quantity || 0} ${item.unit || ""} | ${amountText}${breakdownText}`;
    })
    .join("\n");
  const itemsTable = buildCommercialItemsTablePlaceholder(items, currency, {
    fallbackTitle: itemsFallbackTitle,
    offerType: normalizedOffer.serviceLine || "",
    showTotalAmount: normalizedOffer.showTotalAmount !== false,
    totals: normalizedOffer,
  });
  const monthlyItems = getCommercialOfferMonthlyItems(items, normalizedOffer.serviceLine || "");
  const servicePricingItems = getCommercialOfferServicePricingItems(items, normalizedOffer.serviceLine || "");
  const monthlyFeesTable = monthlyItems.length > 0
    ? buildCommercialItemsTablePlaceholder(items, currency, {
      fallbackTitle: "Mjesečne naknade",
      offerType: normalizedOffer.serviceLine || "",
      showTotalAmount: normalizedOffer.showTotalAmount !== false,
      section: "monthly",
      includeHeader: false,
      emptyMessage: "",
    })
    : "";
  const servicePricingTable = servicePricingItems.length > 0
    ? buildCommercialItemsTablePlaceholder(items, currency, {
      fallbackTitle: "Cjenik usluga",
      offerType: normalizedOffer.serviceLine || "",
      showTotalAmount: normalizedOffer.showTotalAmount !== false,
      section: "services",
      includeHeader: false,
      emptyMessage: "",
    })
    : "";
  const preparedBy = String(normalizedOffer.preparedByLabel || normalizedOffer.preparedBy || normalizedOffer.createdByLabel || "").trim();
  const offerItemsSummary = items
    .map((item, index) => {
      const summaryParts = [
        `${index + 1}. ${item.description || "Stavka"}`,
        getCommercialQuantityText(item),
      ].filter(Boolean);
      if (item?.isIncludedService) {
        summaryParts.push("Uključeno");
      } else if (!suppressItemTotals && Number(item.totalPrice || 0) > 0) {
        summaryParts.push(formatOfferTemplateMoney(item.totalPrice || 0, currency));
      }
      return summaryParts.join(" | ");
    })
    .join("\n");

  return {
    OFFER_NUMBER: normalizedOffer.offerNumber || "Dodijeljen nakon spremanja",
    OFFER_TITLE: normalizedOffer.title || "",
    OFFER_STATUS: getOfferStatusLabel(normalizedOffer.status || "draft"),
    OFFER_DATE: normalizedOffer.offerDate ? formatOfferDocumentDate(normalizedOffer.offerDate) : "",
    VALID_UNTIL: normalizedOffer.validUntil ? formatOfferDocumentDate(normalizedOffer.validUntil) : "",
    COMPANY_NAME: normalizedOffer.companyName || "",
    COMPANY_OIB: normalizedOffer.companyOib || "",
    COMPANY_HEADQUARTERS: normalizedOffer.headquarters || "",
    LOCATION_SUMMARY: normalizedOffer.locationName || "Bez lokacije",
    LOCATION_LIST: Array.isArray(normalizedOffer.selectedLocationNames) && normalizedOffer.selectedLocationNames.length > 0
      ? normalizedOffer.selectedLocationNames.join("\n")
      : "Bez lokacije",
    CONTACT_NAME: normalizedOffer.contactName || "",
    CONTACT_PHONE: normalizedOffer.contactPhone || "",
    CONTACT_EMAIL: normalizedOffer.contactEmail || "",
    OFFER_PREPARED_BY: preparedBy,
    PREPARED_BY: preparedBy,
    CREATED_BY: preparedBy,
    SERVICE_LINE: normalizedOffer.serviceLine || "",
    OFFER_TYPE: normalizedOffer.serviceLine || "",
    OFFER_TEXT_1: normalizedOffer.textBlock1 || "",
    OFFER_TEXT_2: normalizedOffer.textBlock2 || "",
    ITEMS_TABLE: itemsTable,
    MONTHLY_FEES_TABLE: monthlyFeesTable,
    SERVICE_PRICING_TABLE: servicePricingTable,
    ITEMS_TABLE_TEXT: itemsTableText,
    ITEMS_SUMMARY: offerItemsSummary || itemsSummary,
    NOTE: normalizedOffer.note || "",
    SUBTOTAL: formatOfferTemplateMoney(normalizedOffer.subtotal || 0, currency),
    DISCOUNT_RATE: Number(normalizedOffer.discountRate || 0) > 0 ? `${normalizedOffer.discountRate}%` : "",
    DISCOUNT_TOTAL: formatOfferTemplateMoney(normalizedOffer.discountTotal || 0, currency),
    TAX_RATE: `${normalizedOffer.taxRate || 0}%`,
    TAX_TOTAL: formatOfferTemplateMoney(normalizedOffer.taxTotal || 0, currency),
    TOTAL: formatOfferTemplateMoney(normalizedOffer.total || 0, currency),
  };
}

