    OdgovornaOVLOIB: "",
    OdgovornaOVLKlasa: "",
    OdgovornaOVLUrbroj: "",
    OdgovornaOVLEbroj: "",
    AktivnostEv: serviceName || serviceCode,
    BrojOdlukeEv: "",
    DatumOdlukeEv: "",
    RokOdlukeEv: "",
    BrojZapisnikaEv: itemRecordNumber,
    DatumZapisnikaEv: formatPeopleTrainingTemplateDate(itemDate),
    RokZapisnikaEv: formatPeopleTrainingTemplateDate(itemValidUntil),
