    DatumPolaganjaPGP: formatPeopleTrainingTemplateDate(getPeopleTrainingTemplateItemDate(pgpItem ?? {})),
    PGPCheck: hasPeopleTrainingTemplateEvidence(pgpItem ?? {}) ? "X" : "",
