async function generateWorkOrderTrainingRecordDocument({
  user,
  workOrder = {},
  scopedSnapshot = {},
} = {}) {
  const rows = getWorkOrderTrainingRecordRows(workOrder, scopedSnapshot);
  if (rows.length === 0) {
    const error = new Error("Nema položenih ili važećih osposobljavanja za izradu zapisnika.");
    error.statusCode = 400;
    throw error;
  }
  const signer = getWorkOrderTrainingRecordSigner(user, scopedSnapshot);
  const signatureFields = buildWorkOrderTrainingRecordSignatureFields(signer);
  const workOrderNumber = normalizeInputValue(workOrder.workOrderNumber || workOrder.number || workOrder.id || "RN");
  const html = buildWorkOrderTrainingRecordHtml({ workOrder, rows, signer });
  const fileName = sanitizeGeneratedDocumentFileName(`Zapisnik-osposobljavanje-${workOrderNumber}`, {
    fallback: "zapisnik-osposobljavanje",
    extension: "pdf",
  });
  const pdfBuffer = await convertHtmlToPdfBuffer(html, {
    fileName,
    title: `Zapisnik osposobljavanja ${workOrderNumber}`,
  });
  const pdfWithSignatureFields = signatureFields.length > 0
    ? await addPdfSignatureFieldsToBuffer(pdfBuffer, signatureFields, {
      appearance: {
        showQualifiedLabel: false,
        showName: false,
        showTitle: false,
        showRole: false,
        showOib: false,
        border: false,
        transparentBackground: true,
      },
    })
    : pdfBuffer;
  const metadata = buildWorkOrderTrainingRecordSignatureMetadata(signatureFields);
  const saved = typeof domainRepository.upsertWorkOrderGeneratedPdfDocument === "function"
    ? await domainRepository.upsertWorkOrderGeneratedPdfDocument(workOrder.id, {
      fileName,
      fileType: "application/pdf",
      fileSize: pdfWithSignatureFields.length,
      documentCategory: GENERATED_DOCUMENT_TEMPLATE_PDF_CATEGORY,
      description: signatureFields.length > 0
        ? `Zapisnik osposobljavanja za RN ${workOrderNumber}. Dokument je spreman za digitalni potpis.`
        : `Zapisnik osposobljavanja za RN ${workOrderNumber}. Dodaj OIB potpisnika za signature field.`,
      sourceType: "pdf",
      ...metadata,
      dataUrl: `data:application/pdf;base64,${pdfWithSignatureFields.toString("base64")}`,
    }, user)
    : (await domainRepository.addWorkOrderDocuments(workOrder.id, [{
      fileName,
      fileType: "application/pdf",
      fileSize: pdfWithSignatureFields.length,
      documentCategory: GENERATED_DOCUMENT_TEMPLATE_PDF_CATEGORY,
      description: `Zapisnik osposobljavanja za RN ${workOrderNumber}.`,
      sourceType: "pdf",
      ...metadata,
      dataUrl: `data:application/pdf;base64,${pdfWithSignatureFields.toString("base64")}`,
    }], user, { sourceType: "pdf" }))[0] ?? null;
  return {
    ok: true,
    item: stripStoredDocumentPayloadForResponse(saved),
    passedCount: rows.length,
    peopleCount: new Set(rows.map((row) => row.oib || row.personName).filter(Boolean)).size,
    signatureFieldCount: signatureFields.length,
    message: signatureFields.length > 0
      ? `Zapisnik osposobljavanja je spremljen u Dokumente i spreman za potpis (${rows.length} polaganja).`
      : `Zapisnik osposobljavanja je spremljen u Dokumente (${rows.length} polaganja). Potpisnik nema OIB za signature field.`,
  };
}

function normalizeMobileDocumentWizardArray(value = []) {
  const source = Array.isArray(value)
    ? value
    : String(value ?? "")
      .split(",")
      .map((entry) => entry.trim())
      .filter(Boolean);

  return Array.from(new Set(source.map((entry) => normalizeInputValue(entry)).filter(Boolean)));
}

function normalizeMobileDocumentSignatureMode(value = "") {
  const normalized = normalizeInputValue(value).toLowerCase();
  if (normalized === "scan" || normalized === "manual" || normalized === "none") {
    return normalized;
  }
  return "digital";
}

function normalizeMobileDocumentValidityMonths(value = "", fallback = "") {
  const raw = normalizeInputValue(value);
  if (!raw) {
    return normalizeInputValue(fallback);
  }
  const number = Number.parseInt(raw, 10);
  return Number.isFinite(number) && number > 0 ? String(number) : normalizeInputValue(fallback);
}

function addMonthsToMobileDate(value = "", monthsValue = "") {
  const normalizedDate = normalizeDateOnlyValue(value);
  const months = Number.parseInt(String(monthsValue ?? "").trim(), 10);
  if (!normalizedDate || !Number.isFinite(months) || months <= 0) {
    return "";
  }

  const [year, month, day] = normalizedDate.split("-").map((part) => Number.parseInt(part, 10));
  const date = new Date(year, month - 1, day, 12, 0, 0, 0);
  const originalDay = date.getDate();
  date.setMonth(date.getMonth() + months);
  if (date.getDate() !== originalDay) {
    date.setDate(0);
  }
  return date.toISOString().slice(0, 10);
}

function normalizeMobileDocumentationAttachments(value = []) {
  return (Array.isArray(value) ? value : [])
    .slice(0, 8)
    .map((entry, index) => {
      const item = entry && typeof entry === "object" ? entry : {};
      const fileName = normalizeInputValue(item.fileName || item.name || `Prilog ${index + 1}`);
      const dataUrl = normalizeInputValue(item.dataUrl || item.contentDataUrl);
      const fileType = normalizeInputValue(item.fileType || item.type).toLowerCase();
      const fileSize = Number(item.fileSize || item.size || 0) || 0;
      const isPdf = fileType === "application/pdf" || /^data:application\/pdf;base64,/i.test(dataUrl) || /\.pdf$/i.test(fileName);
      const isPng = fileType === "image/png" || /^data:image\/png;base64,/i.test(dataUrl) || /\.png$/i.test(fileName);
      const isJpg = fileType === "image/jpeg" || fileType === "image/jpg" || /^data:image\/jpe?g;base64,/i.test(dataUrl) || /\.jpe?g$/i.test(fileName);
      if (!fileName || !dataUrl) {
        return null;
      }
      const normalizedType = isPdf ? "application/pdf" : isPng ? "image/png" : isJpg ? "image/jpeg" : (fileType || "application/octet-stream");
      return {
        id: normalizeInputValue(item.id) || `mobile-attachment-${index + 1}`,
        fileName,
        name: fileName,
        fileType: normalizedType,
        type: normalizedType,
        fileSize,
        size: fileSize,
        dataUrl,
      };
    })
    .filter(Boolean);
}

function normalizeMobileDocumentationTemplateAttachments(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return Object.fromEntries(Object.entries(value)
    .map(([templateId, attachments]) => [
      normalizeInputValue(templateId),
      normalizeMobileDocumentationAttachments(attachments),
    ])
    .filter(([templateId, attachments]) => templateId && attachments.length > 0));
}

function getMobileDocumentationTemplateAttachments(templateAttachments = {}, templateId = "", fallback = []) {
  const normalizedTemplateId = normalizeInputValue(templateId);
  const scopedAttachments = normalizeMobileDocumentationTemplateAttachments(templateAttachments);
  if (normalizedTemplateId && Array.isArray(scopedAttachments[normalizedTemplateId])) {
    return scopedAttachments[normalizedTemplateId];
  }
  return normalizeMobileDocumentationAttachments(fallback);
}

function resolveMobileDocumentationAttachmentsForTemplate(common = {}, templateId = "") {
  const scopedAttachments = normalizeMobileDocumentationTemplateAttachments(common.templateAttachments);
  const hasScopedAttachments = Object.keys(scopedAttachments).length > 0;
  return getMobileDocumentationTemplateAttachments(
    scopedAttachments,
    templateId,
    hasScopedAttachments ? [] : common.attachments,
  );
}

function normalizeMobileWorkOrderDocumentWizardInput(input = {}) {
  const source = input?.common && typeof input.common === "object" && !Array.isArray(input.common)
    ? input.common
    : (input && typeof input === "object" && !Array.isArray(input) ? input : {});
  const todayIso = new Date().toISOString().slice(0, 10);
  const inspectorUserIds = normalizeMobileDocumentWizardArray(source.inspectorUserIds);
  const electricalInspectorUserIds = normalizeMobileDocumentWizardArray(source.electricalInspectorUserIds);
  const tipkaloInspectorUserIds = normalizeMobileDocumentWizardArray(source.tipkaloInspectorUserIds);
  const workEquipmentInspectorUserIds = normalizeMobileDocumentWizardArray(
    source.radna_opremaInspectorUserIds || source.workEquipmentInspectorUserIds,
  );
  const workEnvironmentInspectorUserIds = normalizeMobileDocumentWizardArray(
    source.radni_okolisInspectorUserIds || source.workEnvironmentInspectorUserIds,
  );
  const selectedEquipmentIds = normalizeMobileDocumentWizardArray(source.selectedEquipmentIds || source.measurementEquipmentIds);
  const selectedLegalFrameworkIds = normalizeMobileDocumentWizardArray(source.selectedLegalFrameworkIds || source.legalFrameworkIds);
  const selectedRulebookIds = normalizeMobileDocumentWizardArray(source.selectedRulebookIds || source.rulebookIds);
  const selectedWorkEquipmentRecords = Array.isArray(source.selectedWorkEquipmentRecords)
    ? source.selectedWorkEquipmentRecords
      .map((entry) => (entry && typeof entry === "object" ? {
        id: normalizeInputValue(entry.id),
        label: normalizeInputValue(entry.label || entry.title || entry.name),
        subtitle: normalizeInputValue(entry.subtitle),
        status: normalizeInputValue(entry.status),
        meta: entry.meta && typeof entry.meta === "object"
          ? Object.fromEntries(Object.entries(entry.meta)
            .map(([key, value]) => [normalizeInputValue(key), normalizeInputValue(value)])
            .filter(([key, value]) => key && value))
          : {},
      } : null))
      .filter((entry) => entry && (entry.id || entry.label))
    : [];
  const selectedWorkEnvironmentRecords = Array.isArray(source.selectedWorkEnvironmentRecords)
    ? source.selectedWorkEnvironmentRecords
      .map((entry) => (entry && typeof entry === "object" ? {
        id: normalizeInputValue(entry.id),
        label: normalizeInputValue(entry.label || entry.title || entry.name),
        subtitle: normalizeInputValue(entry.subtitle),
        status: normalizeInputValue(entry.status),
        meta: entry.meta && typeof entry.meta === "object"
          ? Object.fromEntries(Object.entries(entry.meta)
            .map(([key, value]) => [normalizeInputValue(key), normalizeInputValue(value)])
            .filter(([key, value]) => key && value))
          : {},
      } : null))
      .filter((entry) => entry && (entry.id || entry.label))
    : [];
  const manualWorkEquipments = normalizeIsznrRoManualEquipmentPayloads(
    source.manualWorkEquipments || source.manualWorkEquipment || source.manualEquipments || [],
  );
  const workEquipmentSubmitSource = source.workEquipmentSubmitResult && typeof source.workEquipmentSubmitResult === "object"
    ? source.workEquipmentSubmitResult
    : {};
  const workEquipmentSubmitResult = {
    isznrId: normalizeInputValue(workEquipmentSubmitSource.isznrId || workEquipmentSubmitSource.submittedRecordId),
    recordNumber: normalizeInputValue(workEquipmentSubmitSource.recordNumber || workEquipmentSubmitSource.submittedRecordNumber),
    pdfUrl: normalizeInputValue(workEquipmentSubmitSource.pdfUrl || workEquipmentSubmitSource.isznrPdfUrl),
    pdfBridgeUrl: normalizeInputValue(workEquipmentSubmitSource.pdfBridgeUrl || workEquipmentSubmitSource.isznrPdfBridgeUrl),
  };
  const workEnvironmentSubmitSource = source.workEnvironmentSubmitResult && typeof source.workEnvironmentSubmitResult === "object"
    ? source.workEnvironmentSubmitResult
    : {};
  const workEnvironmentSubmitResult = {
    isznrId: normalizeInputValue(workEnvironmentSubmitSource.isznrId || workEnvironmentSubmitSource.submittedRecordId),
    recordNumber: normalizeInputValue(workEnvironmentSubmitSource.recordNumber || workEnvironmentSubmitSource.submittedRecordNumber),
    pdfUrl: normalizeInputValue(workEnvironmentSubmitSource.pdfUrl || workEnvironmentSubmitSource.isznrPdfUrl),
    pdfBridgeUrl: normalizeInputValue(workEnvironmentSubmitSource.pdfBridgeUrl || workEnvironmentSubmitSource.isznrPdfBridgeUrl),
  };
  const executors = normalizeMobileDocumentWizardArray(source.executors);
  const additionalRecords = Array.isArray(source.additionalRecords)
    ? source.additionalRecords.map((entry, index) => ({
      serviceKey: normalizeInputValue(entry?.serviceKey),
      serviceIndex: Number.isFinite(Number(entry?.serviceIndex)) ? Number(entry.serviceIndex) : -1,
      serviceCode: normalizeInputValue(entry?.serviceCode),
      serviceName: normalizeInputValue(entry?.serviceName),
      objectId: normalizeInputValue(entry?.objectId || entry?.locationObjectId),
      objectName: normalizeInputValue(entry?.objectName || entry?.locationObjectName),
      objectSequence: Number.isFinite(Number(entry?.objectSequence)) ? Number(entry.objectSequence) : index + 2,
    })).filter((entry) => entry.objectId || entry.objectName)
    : [];
  const addAllObjects = source.addAllObjects === true
    || source.addAllLocationObjects === true
    || source.createAllObjectReports === true;
  const addAllObjectsServiceIndex = Number.isFinite(Number(source.addAllObjectsServiceIndex ?? source.activeServiceIndex))
    ? Number(source.addAllObjectsServiceIndex ?? source.activeServiceIndex)
    : -1;
  const addAllObjectsServiceCode = normalizeInputValue(source.addAllObjectsServiceCode || source.activeServiceCode);
  const fieldValues = source.fieldValues && typeof source.fieldValues === "object" && !Array.isArray(source.fieldValues)
    ? Object.fromEntries(Object.entries(source.fieldValues)
      .map(([key, value]) => [normalizeInputValue(key), value])
      .filter(([key]) => key))
    : {};
  const templateFieldValues = source.templateFieldValues
    && typeof source.templateFieldValues === "object"
    && !Array.isArray(source.templateFieldValues)
    ? Object.fromEntries(Object.entries(source.templateFieldValues)
      .map(([templateId, values]) => {
        if (!values || typeof values !== "object" || Array.isArray(values)) {
          return null;
        }
        const normalizedValues = Object.fromEntries(Object.entries(values)
          .map(([key, value]) => [normalizeInputValue(key), value])
          .filter(([key]) => key));
        return [normalizeInputValue(templateId), normalizedValues];
      })
      .filter(Boolean))
    : {};
  const fieldSheets = source.fieldSheets && typeof source.fieldSheets === "object" && !Array.isArray(source.fieldSheets)
    ? Object.fromEntries(Object.entries(source.fieldSheets)
      .map(([key, value]) => [normalizeInputValue(key), normalizeWorkOrderMeasurementSheet(value)])
      .filter(([key, value]) => key && value))
    : {};
  const templateFieldSheets = source.templateFieldSheets
    && typeof source.templateFieldSheets === "object"
    && !Array.isArray(source.templateFieldSheets)
    ? Object.fromEntries(Object.entries(source.templateFieldSheets)
      .map(([templateId, values]) => {
        if (!values || typeof values !== "object" || Array.isArray(values)) {
          return null;
        }
        const normalizedValues = Object.fromEntries(Object.entries(values)
          .map(([key, value]) => [normalizeInputValue(key), normalizeWorkOrderMeasurementSheet(value)])
          .filter(([key, value]) => key && value));
        return [normalizeInputValue(templateId), normalizedValues];
      })
      .filter(Boolean))
    : {};
  const hasIncludedMeasurementTableKeys = Object.prototype.hasOwnProperty.call(source, "includedMeasurementTableKeys");
  const includedMeasurementTableKeys = hasIncludedMeasurementTableKeys && Array.isArray(source.includedMeasurementTableKeys)
    ? source.includedMeasurementTableKeys
      .map((value) => normalizeInputValue(value))
      .filter(Boolean)
    : null;
  const attachments = normalizeMobileDocumentationAttachments(source.attachments || source.documentAttachments || []);
  const templateAttachments = normalizeMobileDocumentationTemplateAttachments(
    source.templateAttachments
      || source.attachmentsByTemplate
      || source.documentAttachmentsByTemplate
      || source.serviceAttachments
      || {},
  );
  return {
    objectId: normalizeInputValue(source.objectId || source.locationObjectId || source.selectedObjectId),
    objectName: normalizeInputValue(source.objectName || source.locationObjectName),
    inspectionDate: normalizeDateOnlyValue(source.inspectionDate) || todayIso,
    issuedDate: normalizeDateOnlyValue(source.issuedDate) || normalizeDateOnlyValue(source.inspectionDate) || todayIso,
    issuedPlace: normalizeInputValue(source.issuedPlace),
    testingLocation: normalizeInputValue(source.testingLocation || source.inspectionPlace || source.inspectionLocation),
    note: normalizeInputValue(source.note),
    inspectionType: normalizeInputValue(source.inspectionType),
    completedBy: normalizeInputValue(source.completedBy || source.completedByLabel),
    handoverVerifierUserId: normalizeInputValue(
      source.handoverVerifierUserId
        || source.handoverExecutorVerifierUserId
        || source.handoverPreparedByUserId
        || source.currentUserId,
    ),
    handoverVerifierLabel: normalizeInputValue(
      source.handoverVerifierLabel
        || source.handoverExecutorVerifierLabel
        || source.handoverPreparedByLabel
        || source.currentUserLabel,
    ),
    outsideTemperature: normalizeInputValue(source.outsideTemperature),
    relativeHumidity: normalizeInputValue(source.relativeHumidity),
    airflowSpeed: normalizeInputValue(source.airflowSpeed),
    weather: normalizeInputValue(source.weather),
    groundCondition: normalizeInputValue(source.groundCondition),
    groundResistance: normalizeInputValue(source.groundResistance),
    measurementEquipmentGroup: normalizeInputValue(source.measurementEquipmentGroup),
    selectedEquipmentIds,
    selectedLegalFrameworkIds,
    selectedRulebookIds,
    selectedWorkEquipmentRecords,
    selectedWorkEnvironmentRecords,
    manualWorkEquipments,
    workEquipmentSubmitResult,
    workEquipmentRecordNumber: workEquipmentSubmitResult.recordNumber,
    workEnvironmentSubmitResult,
    workEnvironmentRecordNumber: workEnvironmentSubmitResult.recordNumber,
    signatureMode: normalizeMobileDocumentSignatureMode(source.signatureMode),
    validityMonths: normalizeMobileDocumentValidityMonths(source.validityMonths, "12"),
    electricalValidityMonths: normalizeMobileDocumentValidityMonths(source.electricalValidityMonths, source.validityMonths || "12"),
    tipkaloValidityMonths: normalizeMobileDocumentValidityMonths(source.tipkaloValidityMonths, source.validityMonths || "12"),
    includeHandoverProtocol: source.includeHandoverProtocol !== false,
    serviceValidityMonths: source.serviceValidityMonths && typeof source.serviceValidityMonths === "object" && !Array.isArray(source.serviceValidityMonths)
      ? Object.fromEntries(Object.entries(source.serviceValidityMonths)
        .map(([key, value]) => [normalizeInputValue(key), normalizeMobileDocumentValidityMonths(value)])
        .filter(([key, value]) => key && value))
      : {},
    executors,
    additionalRecords,
    inspectorUserIds,
    inspectorUserId: normalizeInputValue(source.inspectorUserId) || inspectorUserIds[0] || "",
    authorizationHolderUserId: normalizeInputValue(source.authorizationHolderUserId),
    electricalInspectorUserIds,
    electricalInspectorUserId: normalizeInputValue(source.electricalInspectorUserId) || electricalInspectorUserIds[0] || "",
    electricalAuthorizationHolderUserId: normalizeInputValue(source.electricalAuthorizationHolderUserId),
    tipkaloInspectorUserIds,
    tipkaloInspectorUserId: normalizeInputValue(source.tipkaloInspectorUserId) || tipkaloInspectorUserIds[0] || "",
    tipkaloAuthorizationHolderUserId: normalizeInputValue(source.tipkaloAuthorizationHolderUserId),
    radna_opremaInspectorUserIds: workEquipmentInspectorUserIds,
    radna_opremaInspectorUserId: normalizeInputValue(source.radna_opremaInspectorUserId || source.workEquipmentInspectorUserId) || workEquipmentInspectorUserIds[0] || "",
    radna_opremaAuthorizationHolderUserId: normalizeInputValue(source.radna_opremaAuthorizationHolderUserId || source.workEquipmentAuthorizationHolderUserId),
    radni_okolisInspectorUserIds: workEnvironmentInspectorUserIds,
    radni_okolisInspectorUserId: normalizeInputValue(source.radni_okolisInspectorUserId || source.workEnvironmentInspectorUserId) || workEnvironmentInspectorUserIds[0] || "",
    radni_okolisAuthorizationHolderUserId: normalizeInputValue(source.radni_okolisAuthorizationHolderUserId || source.workEnvironmentAuthorizationHolderUserId),
    fieldValues,
    templateFieldValues,
    fieldSheets,
    templateFieldSheets,
    includedMeasurementTableKeys,
    attachments,
    templateAttachments,
    addAllObjects,
    addAllObjectsServiceIndex,
    addAllObjectsServiceCode,
  };
}

function findMobileScopedUserById(scopedSnapshot = {}, userId = "") {
  const normalizedId = normalizeInputValue(userId);
  if (!normalizedId) {
    return null;
  }
  return (scopedSnapshot.users ?? []).find((user) => String(user?.id || "") === normalizedId) || null;
}

function getMobileUserDocumentName(user = {}) {
  return normalizeInputValue(
    user?.displayName
    || user?.fullName
    || [user?.firstName, user?.lastName].filter(Boolean).join(" ")
    || user?.username
    || user?.email,
  );
}

function getMobileUserDocumentTitle(user = {}) {
  return normalizeInputValue(
    user?.title
    || user?.professionalTitle
    || user?.academicTitle
    || user?.degreeTitle
    || user?.qualificationTitle,
  );
}

function getMobileUserDocumentOib(user = {}, signatureArea = "elektro", scopedSnapshot = {}) {
  const normalizeOib = (value = "") => {
    const digits = normalizeInputValue(value).replace(/\D/g, "");
    return /^\d{11}$/.test(digits) ? digits : "";
  };
  const qualification = getMobileUserQualificationForArea(user, signatureArea);
  const directOib = normalizeOib(
    user?.oib
    || user?.oibNumber
    || user?.taxId
    || user?.personalOib
    || user?.personalIdentificationNumber
    || user?.identificationNumber
    || user?.nationalId
    || qualification.oib,
  );
  if (directOib) {
    return directOib;
  }

  const lookupValues = new Set(getMobileUserLookupValues(user));
  if (lookupValues.size === 0) {
    return "";
  }
  const matchedRecord = (Array.isArray(scopedSnapshot.peopleTrainingRecords) ? scopedSnapshot.peopleTrainingRecords : [])
    .find((record) => [
      record?.fullName,
      [record?.firstName, record?.lastName].filter(Boolean).join(" "),
      record?.email,
    ].some((value) => lookupValues.has(normalizeMobilePersonLookupValue(value))));
  return normalizeOib(matchedRecord?.oib);
}

function formatMobileUserWithTitle(user = {}) {
  const name = getMobileUserDocumentName(user);
  const title = getMobileUserDocumentTitle(user);
  return [title, name].filter(Boolean).join(" ").trim();
}

function getMobileUserQualificationValue(user = {}, field = "") {
  const qualification = user?.electricalQualification && typeof user.electricalQualification === "object"
    ? user.electricalQualification
    : {};
  const normalizedField = normalizeInputValue(field);
  return normalizeInputValue(user?.[normalizedField] || qualification?.[normalizedField]);
}

function buildMobileQualifiedUserPlaceholders(prefix = "", user = null) {
  if (!prefix || !user) {
    return {};
  }
  return {
    [`${prefix}_NAME`]: getMobileUserDocumentName(user),
    [`${prefix}_TYPE`]: getMobileUserQualificationValue(user, "type"),
    [`${prefix}_DATA_1`]: getMobileUserQualificationValue(user, "data1"),
    [`${prefix}_DATA_2`]: getMobileUserQualificationValue(user, "data2"),
    [`${prefix}_DATA_3`]: getMobileUserQualificationValue(user, "data3"),
    [`${prefix}_PASSED_ON`]: formatOfferDocumentDate(getMobileUserQualificationValue(user, "passedOn")),
    [`${prefix}_CLASS_CODE`]: getMobileUserQualificationValue(user, "classCode"),
    [`${prefix}_URBROJ`]: getMobileUserQualificationValue(user, "urbroj"),
    [`${prefix}_E_BROJ`]: getMobileUserQualificationValue(user, "eBroj"),
    [`${prefix}_SUMMARY`]: [
      getMobileUserQualificationValue(user, "type"),
      getMobileUserQualificationValue(user, "data1"),
      getMobileUserQualificationValue(user, "data2"),
      getMobileUserQualificationValue(user, "data3"),
    ].filter(Boolean).join(", "),
  };
}

const MOBILE_DOCUMENT_TEMPLATE_DEFAULT_SIGNATURE_META_FIELDS = [
  "title",
  "oib",
  "type",
  "data1",
  "data2",
  "data3",
  "passedOn",
];

const MOBILE_DOCUMENT_TEMPLATE_SIGNATURE_META_FIELD_ALIASES = new Map([
  ["classcode", "data1"],
  ["class_code", "data1"],
  ["urbroj", "data2"],
  ["e_broj", "data3"],
  ["ebroj", "data3"],
  ["passedon", "passedOn"],
  ["passed_on", "passedOn"],
  ["passed-on", "passedOn"],
]);

function normalizeMobileDocumentTemplateSignatureMetaFields(values = undefined) {
  if (!Array.isArray(values)) {
    return [...MOBILE_DOCUMENT_TEMPLATE_DEFAULT_SIGNATURE_META_FIELDS];
  }
  const allowedValues = new Set(MOBILE_DOCUMENT_TEMPLATE_DEFAULT_SIGNATURE_META_FIELDS);
  return Array.from(new Set(values
    .map((value) => {
      const raw = normalizeInputValue(value);
      if (allowedValues.has(raw)) {
        return raw;
      }
      return MOBILE_DOCUMENT_TEMPLATE_SIGNATURE_META_FIELD_ALIASES.get(raw.toLowerCase()) || "";
    })
    .filter(Boolean)));
}

function getMobileUsersByIds(scopedSnapshot = {}, ids = []) {
  const seen = new Set();
  return normalizeMobileDocumentWizardArray(ids)
    .map((id) => findMobileScopedUserById(scopedSnapshot, id))
    .filter((user) => {
      const key = normalizeInputValue(user?.id || user?.email || user?.oib || getMobileUserDocumentName(user));
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function getMobileUsersByExecutorLabels(scopedSnapshot = {}, executors = []) {
  const executorLookup = new Set(
    normalizeMobileDocumentWizardArray(executors)
      .map((value) => normalizeMobilePersonLookupValue(value))
      .filter(Boolean),
  );
  if (executorLookup.size === 0) {
    return [];
  }
  return (Array.isArray(scopedSnapshot.users) ? scopedSnapshot.users : [])
    .filter((user) => getMobileUserLookupValues(user).some((candidate) => executorLookup.has(candidate)));
}

function uniqueMobileUsers(users = []) {
  const seen = new Set();
  return (Array.isArray(users) ? users : [])
    .filter((user) => {
      const key = normalizeInputValue(user?.id || user?.email || user?.oib || getMobileUserDocumentName(user));
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function uniqueMobileSignatureEntries(entries = []) {
  const seen = new Set();
  return (Array.isArray(entries) ? entries : [])
    .filter((entry) => {
      const user = entry?.user;
      const key = normalizeInputValue(user?.id || user?.email || user?.oib || getMobileUserDocumentName(user));
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function getMobileDocumentSignatureInspectorIds(common = {}, signatureArea = "elektro") {
  const area = normalizeMobileQualificationAreaKey(signatureArea);
  if (area === "radna_oprema" || area === "ro") {
    const ids = normalizeMobileDocumentWizardArray(common.radna_opremaInspectorUserIds?.length > 0
      ? common.radna_opremaInspectorUserIds
      : [common.radna_opremaInspectorUserId || common.workEquipmentInspectorUserId]);
    if (ids.length > 0) {
      return ids;
    }
  }
  if (area === "radni_okolis" || area === "fc") {
    const ids = normalizeMobileDocumentWizardArray(common.radni_okolisInspectorUserIds?.length > 0
      ? common.radni_okolisInspectorUserIds
      : [common.radni_okolisInspectorUserId || common.workEnvironmentInspectorUserId]);
    if (ids.length > 0) {
      return ids;
    }
  }
  if (area === "tipkalo" || area === "tzin") {
    const ids = normalizeMobileDocumentWizardArray(common.tipkaloInspectorUserIds?.length > 0
      ? common.tipkaloInspectorUserIds
      : [common.tipkaloInspectorUserId]);
    if (ids.length > 0) {
      return ids;
    }
  }
  if (area === "elektro") {
    const ids = normalizeMobileDocumentWizardArray(common.electricalInspectorUserIds?.length > 0
      ? common.electricalInspectorUserIds
      : [common.electricalInspectorUserId]);
    if (ids.length > 0) {
      return ids;
    }
  }
  return normalizeMobileDocumentWizardArray(common.inspectorUserIds?.length > 0
    ? common.inspectorUserIds
    : [common.inspectorUserId]);
}

function getMobileDocumentSignatureAuthorizationIds(common = {}, signatureArea = "elektro") {
  const area = normalizeMobileQualificationAreaKey(signatureArea);
  if (area === "radna_oprema" || area === "ro") {
    const id = normalizeInputValue(common.radna_opremaAuthorizationHolderUserId || common.workEquipmentAuthorizationHolderUserId);
    if (id) {
      return [id];
    }
  }
  if (area === "radni_okolis" || area === "fc") {
    const id = normalizeInputValue(common.radni_okolisAuthorizationHolderUserId || common.workEnvironmentAuthorizationHolderUserId);
    if (id) {
      return [id];
    }
  }
  if (area === "tipkalo" || area === "tzin") {
    const id = normalizeInputValue(common.tipkaloAuthorizationHolderUserId);
    if (id) {
      return [id];
    }
  }
  if (area === "elektro") {
    const id = normalizeInputValue(common.electricalAuthorizationHolderUserId);
    if (id) {
      return [id];
    }
  }
  return normalizeMobileDocumentWizardArray([common.authorizationHolderUserId]);
}

function getMobileQualifiedUserDocumentMetaLines(user = null, signatureArea = "elektro", metaFields = undefined, scopedSnapshot = {}) {
  if (!user) {
    return [];
  }
  const qualification = getMobileUserQualificationForArea(user, signatureArea);
  const visibleFields = new Set(normalizeMobileDocumentTemplateSignatureMetaFields(metaFields));
  const userOib = getMobileUserDocumentOib(user, signatureArea, scopedSnapshot);
  return [
    visibleFields.has("title") ? getMobileUserDocumentTitle(user) : "",
    visibleFields.has("oib") && userOib ? `OIB ${userOib}` : "",
    visibleFields.has("type") ? qualification.type : "",
    (visibleFields.has("data1") || visibleFields.has("classCode")) ? qualification.data1 : "",
    (visibleFields.has("data2") || visibleFields.has("urbroj")) ? qualification.data2 : "",
    (visibleFields.has("data3") || visibleFields.has("eBroj")) ? qualification.data3 : "",
    visibleFields.has("passedOn") ? formatOfferDocumentDate(qualification.passedOn) : "",
  ].map(normalizeInputValue).filter(Boolean);
}

function getMobileDocumentTemplateSignatureUsers(field = {}, common = {}, scopedSnapshot = {}, capability = "inspect") {
  const { signatureArea } = getMobileDocumentTemplateSignatureFieldConfig(field);
  const explicitIds = capability === "authorize"
    ? getMobileDocumentSignatureAuthorizationIds(common, signatureArea)
    : getMobileDocumentSignatureInspectorIds(common, signatureArea);
  const explicitUsers = getMobileUsersByIds(scopedSnapshot, explicitIds);
  if (explicitUsers.length > 0) {
    return explicitUsers;
  }
  if (capability === "inspect") {
    const qualifiedExecutorUsers = getMobileQualifiedExecutorUsers(
      scopedSnapshot,
      { executors: common.executors },
      "inspect",
      signatureArea,
    );
    if (qualifiedExecutorUsers.length > 0) {
      return qualifiedExecutorUsers;
    }
    return getMobileUsersByExecutorLabels(scopedSnapshot, common.executors);
  }
  return [];
}

function buildMobileDocumentTemplateSignatureEntries(field = {}, common = {}, scopedSnapshot = {}) {
  const config = getMobileDocumentTemplateSignatureFieldConfig(field);
  const mode = normalizeMobileDocumentSignatureMode(common.signatureMode);
  const entries = [];
  const pushUsers = (capability) => {
    const roleLabel = capability === "authorize" ? "Odgovorna osoba" : "Ispitivač";
    getMobileDocumentTemplateSignatureUsers(field, common, scopedSnapshot, capability)
      .forEach((user) => {
        entries.push({
          role: roleLabel,
          capability,
          user,
        });
      });
  };

  if (config.signatureRole === "authorize") {
    pushUsers("authorize");
  } else if (config.signatureRole === "all") {
    pushUsers("inspect");
    pushUsers("authorize");
  } else if (config.signatureRole !== "company_responsible") {
    pushUsers("inspect");
  }

  const uniqueEntries = uniqueMobileSignatureEntries(entries);
  const visibleEntries = config.signatureMultiple ? uniqueEntries : uniqueEntries.slice(0, 1);

  return visibleEntries.map((entry, index) => {
    const user = entry.user;
    const signerOib = getMobileUserDocumentOib(user, config.signatureArea, scopedSnapshot);
    const signatureFieldRole = index === 0 ? "ZNR" : `ZNR_${index + 1}`;
    return {
      name: getMobileUserDocumentName(user),
      role: entry.role,
      metaLines: getMobileQualifiedUserDocumentMetaLines(user, config.signatureArea, config.signatureMetaFields, scopedSnapshot),
      signatureImageUrl: mode === "scan" ? getMobileUserSignatureScanDataUrl(user) : "",
      signatureMode: mode,
      signerUserId: normalizeInputValue(user?.id),
      signerEmail: normalizeInputValue(user?.email),
      signerOib,
      signerTitle: getMobileUserDocumentTitle(user),
      signerOrganization: normalizeInputValue(scopedSnapshot.currentOrganization?.name || ""),
      signatureFieldRole,
      signatureFieldOib: signerOib,
      preferredField: signerOib ? buildSignatureFieldName(signatureFieldRole, signerOib) : "",
      digitalAnchor: signerOib || normalizeInputValue(user?.email) || getMobileUserDocumentName(user),
    };
  });
}

function buildMobileDocumentTemplateSignaturePlaceholder(field = {}, common = {}, scopedSnapshot = {}) {
  const entries = buildMobileDocumentTemplateSignatureEntries(field, common, scopedSnapshot);
  if (entries.length === 0) {
    return "";
  }
  return {
    type: "signature_group",
    __docxBlockType: "signature_group",
    title: normalizeInputValue(field?.label || field?.wordLabel || "Potpisi"),
    items: entries,
  };
}

function buildMobileInspectionPersonPlaceholders(common = {}, scopedSnapshot = {}) {
  const executorLabels = normalizeMobileDocumentWizardArray(common.executors);
  const executorNames = executorLabels.join(", ");
  const generalInspectorUsers = getMobileUsersByIds(scopedSnapshot, common.inspectorUserIds?.length > 0
    ? common.inspectorUserIds
    : [common.inspectorUserId]);
  const electricalInspectorUsers = getMobileUsersByIds(scopedSnapshot, common.electricalInspectorUserIds?.length > 0
    ? common.electricalInspectorUserIds
    : [common.electricalInspectorUserId]);
  const tipkaloInspectorUsers = getMobileUsersByIds(scopedSnapshot, common.tipkaloInspectorUserIds?.length > 0
    ? common.tipkaloInspectorUserIds
    : [common.tipkaloInspectorUserId]);
  const workEquipmentInspectorUsers = getMobileUsersByIds(scopedSnapshot, common.radna_opremaInspectorUserIds?.length > 0
    ? common.radna_opremaInspectorUserIds
    : [common.radna_opremaInspectorUserId || common.workEquipmentInspectorUserId]);
  const workEnvironmentInspectorUsers = getMobileUsersByIds(scopedSnapshot, common.radni_okolisInspectorUserIds?.length > 0
    ? common.radni_okolisInspectorUserIds
    : [common.radni_okolisInspectorUserId || common.workEnvironmentInspectorUserId]);
  const selectedInspectorUsers = uniqueMobileUsers([
    ...generalInspectorUsers,
    ...electricalInspectorUsers,
    ...tipkaloInspectorUsers,
    ...workEquipmentInspectorUsers,
    ...workEnvironmentInspectorUsers,
  ]);
  const inspectorUsers = selectedInspectorUsers.length > 0
    ? selectedInspectorUsers
    : getMobileUsersByExecutorLabels(scopedSnapshot, executorLabels);
  const primaryInspector = generalInspectorUsers[0] || inspectorUsers[0] || findMobileScopedUserById(scopedSnapshot, common.inspectorUserId);
  const authorizationHolder = findMobileScopedUserById(scopedSnapshot, common.authorizationHolderUserId);
  const electricalInspector = electricalInspectorUsers[0] || primaryInspector;
  const electricalAuthorizationHolder = findMobileScopedUserById(scopedSnapshot, common.electricalAuthorizationHolderUserId);
  const tipkaloInspector = tipkaloInspectorUsers[0] || primaryInspector;
  const tipkaloAuthorizationHolder = findMobileScopedUserById(scopedSnapshot, common.tipkaloAuthorizationHolderUserId);
  const workEquipmentInspector = workEquipmentInspectorUsers[0] || primaryInspector;
  const workEquipmentAuthorizationHolder = findMobileScopedUserById(
    scopedSnapshot,
    common.radna_opremaAuthorizationHolderUserId || common.workEquipmentAuthorizationHolderUserId,
  );
  const workEnvironmentInspector = workEnvironmentInspectorUsers[0] || primaryInspector;
  const workEnvironmentAuthorizationHolder = findMobileScopedUserById(
    scopedSnapshot,
    common.radni_okolisAuthorizationHolderUserId || common.workEnvironmentAuthorizationHolderUserId,
  );
  const inspectorNames = inspectorUsers.map(getMobileUserDocumentName).filter(Boolean).join(", ") || executorNames;
  const inspectorNamesWithTitles = inspectorUsers.map(formatMobileUserWithTitle).filter(Boolean).join(", ") || inspectorNames;
  const firstInspectorName = getMobileUserDocumentName(primaryInspector)
    || inspectorNames.split(",").map((item) => item.trim()).filter(Boolean)[0]
    || "";
  const firstInspectorWithTitle = formatMobileUserWithTitle(primaryInspector) || firstInspectorName;

  return {
    ...(executorNames ? { WORK_ORDER_EXECUTORS: executorNames, IZVRSITELJI: executorNames } : {}),
    QUALIFIED_INSPECTORS_LIST: inspectorNamesWithTitles || inspectorNames,
    QUALIFIED_INSPECTORS_LIST_WITH_TITLES: inspectorNamesWithTitles || inspectorNames,
    QUALIFIED_INSPECTORS_NAMES: inspectorNames,
    QUALIFIED_INSPECTORS_LIST_NAMES: inspectorNames,
    ISPITIVAC: firstInspectorName,
    ISPITIVAC_S_TITULOM: firstInspectorWithTitle,
    ISPITIVACI_POPIS: inspectorNames,
    ISPITIVACI_POPIS_S_TITULAMA: inspectorNamesWithTitles || inspectorNames,
    ISPITIVACI_POPIS_IMENA: inspectorNames,
    OVLASTENIK: getMobileUserDocumentName(authorizationHolder),
    NOSITELJ_OVLASTENJA: getMobileUserDocumentName(authorizationHolder),
    ELEKTRO_ISPITIVAC: getMobileUserDocumentName(electricalInspector),
    ELEKTRO_OVLASTENIK: getMobileUserDocumentName(electricalAuthorizationHolder),
    TIPKALO_ISPITIVAC: getMobileUserDocumentName(tipkaloInspector),
    TIPKALO_OVLASTENIK: getMobileUserDocumentName(tipkaloAuthorizationHolder),
    RADNA_OPREMA_ISPITIVAC: getMobileUserDocumentName(workEquipmentInspector),
    RADNA_OPREMA_OVLASTENIK: getMobileUserDocumentName(workEquipmentAuthorizationHolder),
    RADNI_OKOLIS_ISPITIVAC: getMobileUserDocumentName(workEnvironmentInspector),
    RADNI_OKOLIS_OVLASTENIK: getMobileUserDocumentName(workEnvironmentAuthorizationHolder),
    ...buildMobileQualifiedUserPlaceholders("QUALIFIED_INSPECTOR", primaryInspector),
    ...buildMobileQualifiedUserPlaceholders("QUALIFIED_AUTHORIZATION_HOLDER", authorizationHolder),
  };
}

function getMobileUserSignatureScanDataUrl(user = {}) {
  const qualification = user?.electricalQualification && typeof user.electricalQualification === "object"
    ? user.electricalQualification
    : {};
  return normalizeInputValue(
    user?.signatureDataUrl
    || user?.signatureImageUrl
    || qualification.signatureDataUrl
    || qualification.signatureImageUrl
    || "",
  );
}

function buildMobileSignatureGroup(common = {}, scopedSnapshot = {}) {
  const mode = normalizeMobileDocumentSignatureMode(common.signatureMode);
  if (mode === "none" || mode === "manual") {
    return "";
  }

  const candidateIds = normalizeMobileDocumentWizardArray([
    ...(common.inspectorUserIds || []),
    common.inspectorUserId,
    common.authorizationHolderUserId,
    ...(common.electricalInspectorUserIds || []),
    common.electricalInspectorUserId,
    common.electricalAuthorizationHolderUserId,
    ...(common.tipkaloInspectorUserIds || []),
    common.tipkaloInspectorUserId,
    common.tipkaloAuthorizationHolderUserId,
    ...(common.radna_opremaInspectorUserIds || []),
    common.radna_opremaInspectorUserId,
    common.radna_opremaAuthorizationHolderUserId,
    ...(common.radni_okolisInspectorUserIds || []),
    common.radni_okolisInspectorUserId,
    common.radni_okolisAuthorizationHolderUserId,
  ]);
  const selectedUsers = getMobileUsersByIds(scopedSnapshot, candidateIds);
  const users = selectedUsers.length > 0
    ? selectedUsers
    : getMobileUsersByExecutorLabels(scopedSnapshot, common.executors);
  const seen = new Set();
  const items = users
    .filter((user) => {
      const key = normalizeInputValue(user?.id || user?.email || user?.oib);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map((user, index) => {
      const signerOib = getMobileUserDocumentOib(user, "elektro", scopedSnapshot);
      const signatureImageUrl = mode === "scan" ? getMobileUserSignatureScanDataUrl(user) : "";
      return {
        name: getMobileUserDocumentName(user),
        signerUserId: normalizeInputValue(user?.id),
        signerEmail: normalizeInputValue(user?.email),
        signerOib,
        signerTitle: getMobileUserDocumentTitle(user),
        signerOrganization: normalizeInputValue(scopedSnapshot.currentOrganization?.name || ""),
        signatureMode: mode,
        signatureFieldRole: index === 0 ? "ZNR" : `ZNR_${index + 1}`,
        signatureFieldOib: signerOib,
        signatureImageUrl,
        preferredField: signerOib ? buildSignatureFieldName(index === 0 ? "ZNR" : `ZNR_${index + 1}`, signerOib) : "",
        role: index === 0 ? "Ovlaštena osoba" : "Potpisnik",
      };
    })
    .filter((item) => mode === "digital" || item.signatureImageUrl);

  return items.length > 0
    ? {
      type: "signature_group",
      __docxBlockType: "signature_group",
      title: "Potpisi",
      items,
    }
    : "";
}

function findMobileHandoverVerifierUser(common = {}, scopedSnapshot = {}) {
  const explicitUser = findMobileScopedUserById(scopedSnapshot, common.handoverVerifierUserId);
  if (explicitUser) {
    return explicitUser;
  }
  const label = normalizeLookupKey(common.handoverVerifierLabel);
  if (!label) {
    return null;
  }
  return (scopedSnapshot.users ?? []).find((user) => {
    const candidates = [
      user?.displayName,
      user?.fullName,
      [user?.firstName, user?.lastName].filter(Boolean).join(" "),
      user?.username,
      user?.email,
    ];
    return candidates.some((candidate) => normalizeLookupKey(candidate) === label);
  }) || null;
}

function buildMobileHandoverSignatureGroup(common = {}, scopedSnapshot = {}) {
  const mode = normalizeMobileDocumentSignatureMode(common.signatureMode);
  if (mode === "none" || mode === "manual") {
    return "";
  }

  const user = findMobileHandoverVerifierUser(common, scopedSnapshot);
  if (!user) {
    return "";
  }

  const signerOib = getMobileUserDocumentOib(user, "elektro", scopedSnapshot);
  const signatureImageUrl = mode === "scan" ? getMobileUserSignatureScanDataUrl(user) : "";
  const signatureFieldRole = "IZVRSITELJ";
  const item = {
    name: getMobileUserDocumentName(user),
    signerUserId: normalizeInputValue(user?.id),
    signerEmail: normalizeInputValue(user?.email),
    signerOib,
    signerTitle: getMobileUserDocumentTitle(user),
    signerOrganization: normalizeInputValue(scopedSnapshot.currentOrganization?.name || ""),
    signatureMode: mode,
    signatureFieldRole,
    signatureFieldOib: signerOib,
    signatureImageUrl,
    preferredField: signerOib ? buildSignatureFieldName(signatureFieldRole, signerOib) : "",
    role: "Ovjerio izvršitelj",
    roleLabel: "Ovjerio izvršitelj",
    anchorText: "Ovjerio izvršitelj",
    positioning: {
      anchor: "bottom",
      offsetY: -10,
      width: 180,
      height: 52,
    },
  };

  if (mode !== "digital" && !item.signatureImageUrl) {
    return "";
  }

  return {
    type: "signature_group",
    __docxBlockType: "signature_group",
    title: "Ovjerio izvršitelj",
    items: [item],
  };
}

function findMobileServiceCatalogItem(service = {}, scopedSnapshot = {}) {
  const serviceId = normalizeInputValue(service?.serviceId || service?.catalogItemId || service?.catalogId || service?.id);
  const serviceCode = normalizeInputValue(service?.serviceCode || service?.code).toLowerCase();
  const serviceName = normalizeInputValue(service?.name || service?.serviceName || service?.title).toLowerCase();
  return (scopedSnapshot.serviceCatalog ?? []).find((catalogItem) => {
    const catalogId = normalizeInputValue(catalogItem?.id);
    const catalogCode = normalizeInputValue(catalogItem?.serviceCode || catalogItem?.code).toLowerCase();
    const catalogName = normalizeInputValue(catalogItem?.name || catalogItem?.title).toLowerCase();
    return (serviceId && catalogId === serviceId)
      || (serviceCode && catalogCode === serviceCode)
      || (serviceName && catalogName === serviceName);
  }) || null;
}

function resolveMobileServiceValidityMonths(service = {}, scopedSnapshot = {}, common = {}) {
  const catalogItem = findMobileServiceCatalogItem(service, scopedSnapshot);
  const validityMap = common.serviceValidityMonths || {};
  const candidateKeys = [
    service?.serviceId,
    service?.catalogItemId,
    service?.catalogId,
    service?.id,
    service?.serviceCode,
    service?.code,
    service?.name,
    service?.serviceName,
    catalogItem?.id,
    catalogItem?.serviceCode,
    catalogItem?.code,
    catalogItem?.name,
  ].map(normalizeInputValue).filter(Boolean);
  const mappedValue = candidateKeys
    .map((key) => validityMap[key])
    .map((value) => normalizeMobileDocumentValidityMonths(value))
    .find(Boolean);
  return mappedValue
    || normalizeMobileDocumentValidityMonths(service?.validityMonths || catalogItem?.validityMonths, common.validityMonths)
    || common.validityMonths
    || "12";
}

function getMobileDocumentTemplateSubmittedFieldSheet(field = {}, template = {}, common = {}, index = 0) {
  const templateId = normalizeInputValue(template?.id);
  const templateSheets = templateId && common.templateFieldSheets?.[templateId]
    ? common.templateFieldSheets[templateId]
    : {};
  const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
  const keys = [
    field?.id,
    field?.key,
    field?.wordLabel,
    field?.label,
    tokenKey,
  ].map(normalizeInputValue).filter(Boolean);

  for (const key of keys) {
    const sheet = normalizeWorkOrderMeasurementSheet(templateSheets?.[key]);
    if (sheet) {
      return sheet;
    }
  }
  for (const key of keys) {
    const sheet = normalizeWorkOrderMeasurementSheet(common.fieldSheets?.[key]);
    if (sheet) {
      return sheet;
    }
  }
  return null;
}

function buildMobileFallbackMeasurementSheet(field = {}) {
  const sourceColumns = Array.isArray(field?.columns) && field.columns.length > 0
    ? field.columns
    : ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"];
  const columns = sourceColumns.slice(0, 12).map((column, index) => {
    const label = column && typeof column === "object" && !Array.isArray(column)
      ? normalizeInputValue(column.label || column.id)
      : normalizeInputValue(column);
    return {
      id: column && typeof column === "object" && !Array.isArray(column)
        ? (normalizeInputValue(column.id) || `measurement-column-${index + 1}`)
        : `measurement-column-${index + 1}`,
      label: label || `Kolona ${index + 1}`,
      placeholder: "",
      width: index === 0 ? 180 : 140,
      computed: null,
      readonly: false,
      validation: { type: "none", options: [], allowCustom: true },
      aiMapping: {},
    };
  });
  const rowCount = Math.max(6, Math.min(30, Number.parseInt(field?.rowCount || field?.rowsCount || "12", 10) || 12));
  return {
    columns,
    rows: Array.from({ length: rowCount }, (_, index) => ({
      id: `measurement-row-${index + 1}`,
      cells: Object.fromEntries(columns.map((column) => [column.id, ""])),
      formats: Object.fromEntries(columns.map((column) => [column.id, {}])),
    })),
    merges: [],
    headerRows: [],
  };
}

function resolveMobileDocumentTemplateFieldSheet(template = {}, workOrder = {}, service = {}, scopedSnapshot = {}, common = {}, field = {}, index = 0) {
  const submittedSheet = getMobileDocumentTemplateSubmittedFieldSheet(field, template, common, index);
  if (submittedSheet) {
    return submittedSheet;
  }
  const catalogItem = findMobileServiceCatalogItem(service, scopedSnapshot);
  const serviceSheet = normalizeWorkOrderMeasurementSheet(
    service?.measurementSheet
    || service?.sheet
    || catalogItem?.measurementSheet
    || catalogItem?.sheet,
  );
  const workOrderSheet = normalizeWorkOrderMeasurementSheet(workOrder?.measurementSheet);
  return normalizeWorkOrderMeasurementSheet(field?.sheet || field?.measurementSheet)
    || serviceSheet
    || workOrderSheet
    || normalizeWorkOrderMeasurementSheet(buildMobileFallbackMeasurementSheet(field));
}

function buildMobileDocumentTemplateFieldSheets(template = {}, workOrder = {}, service = {}, scopedSnapshot = {}, common = {}) {
  return Object.fromEntries(
    (Array.isArray(template?.customFields) ? template.customFields : [])
      .map((field, index) => {
        if (normalizeInputValue(field?.type).toLowerCase() !== "measurement_table") {
          return null;
        }
        const fieldKey = normalizeInputValue(field?.key || field?.id);
        if (!fieldKey) {
          return null;
        }
        const sheet = resolveMobileDocumentTemplateFieldSheet(template, workOrder, service, scopedSnapshot, common, field, index);
        return sheet ? [fieldKey, sheet] : null;
      })
      .filter(Boolean),
  );
}

function normalizeMobileDocumentTemplateFieldTokenKey(value = "", fallback = "FIELD_1") {
  const normalized = String(value ?? "")
    .trim()
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return normalized || fallback;
}

function getMobileDocumentTemplateFieldTokenKey(field = {}, index = 0) {
  return normalizeMobileDocumentTemplateFieldTokenKey(
    field?.key || field?.wordLabel || field?.label,
    `FIELD_${index + 1}`,
  );
}

function getMobileMeasurementSheetFormulaLookupKey(value = "") {
  return normalizeInputValue(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function getMobileMeasurementFormulaReferenceSheetName(reference = "") {
  if (reference && typeof reference === "object" && !Array.isArray(reference)) {
    return normalizeInputValue(reference.sheetName || reference.sheet);
  }
  return "";
}

function buildMobileMeasurementSheetFormulaEntries(template = {}, fieldSheets = {}) {
  const entries = [];
  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field, index) => {
    if (normalizeInputValue(field?.type).toLowerCase() !== "measurement_table") {
      return;
    }
    const recordKey = normalizeInputValue(field?.key || field?.id);
    const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
    const sheet = recordKey ? normalizeWorkOrderMeasurementSheet(fieldSheets[recordKey]) : null;
    if (!sheet) {
      return;
    }
    entries.push({
      key: recordKey || tokenKey || `measurement-${index + 1}`,
      sheet,
      aliases: [
        recordKey,
        tokenKey,
        field?.id,
        field?.key,
        field?.label,
        field?.wordLabel,
        field?.sourceSheet,
        field?.sheetName,
        field?.measurementTable?.sourceSheet,
      ].map(normalizeInputValue).filter(Boolean),
    });
  });
  (Array.isArray(template?.formulaSheets) ? template.formulaSheets : []).forEach((formulaSheet, index) => {
    const sheet = normalizeWorkOrderMeasurementSheet(formulaSheet?.sheet);
    if (!sheet?.columns?.length) {
      return;
    }
    const recordKey = normalizeInputValue(formulaSheet?.key || formulaSheet?.id || formulaSheet?.sourceSheet || `formula-sheet-${index + 1}`);
    entries.push({
      key: recordKey || `formula-sheet-${index + 1}`,
      sheet,
      aliases: [
        recordKey,
        formulaSheet?.id,
        formulaSheet?.key,
        formulaSheet?.tokenKey,
        formulaSheet?.label,
        formulaSheet?.summary,
        formulaSheet?.sourceSheet,
        formulaSheet?.sheetName,
      ].map(normalizeInputValue).filter(Boolean),
      formulaOnly: true,
    });
  });
  const lookup = new Map();
  entries.forEach((entry) => {
    entry.aliases.forEach((alias) => {
      const lookupKey = getMobileMeasurementSheetFormulaLookupKey(alias);
      if (lookupKey && !lookup.has(lookupKey)) {
        lookup.set(lookupKey, entry);
      }
    });
  });
  return { entries, lookup };
}

function parseMobileMeasurementNumber(value) {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  const normalized = String(value ?? "").trim().replace(",", ".");
  if (!normalized) {
    return null;
  }
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

function getMobileMeasurementAverageValue(row = {}) {
  const preferredKeys = ["reading1", "reading2", "reading3"];
  const preferredValues = preferredKeys
    .map((key) => parseMobileMeasurementNumber(row?.cells?.[key]))
    .filter((value) => value !== null);
  const values = preferredValues.length > 0
    ? preferredValues
    : Object.entries(row?.cells ?? {})
      .filter(([key]) => !String(key || "").toLowerCase().includes("average"))
      .map(([, value]) => parseMobileMeasurementNumber(value))
      .filter((value) => value !== null)
      .slice(0, 3);
  if (values.length === 0) {
    return "";
  }
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function resolveMobileMeasurementFormulaSheetEntry(reference = "", formulaContext = null, currentEntry = null) {
  const sheetName = getMobileMeasurementFormulaReferenceSheetName(reference);
  if (!sheetName) {
    return currentEntry || formulaContext?.current || null;
  }
  const lookupKey = getMobileMeasurementSheetFormulaLookupKey(sheetName);
  return formulaContext?.lookup?.get(lookupKey) || currentEntry || formulaContext?.current || null;
}

function getMobileMeasurementCellComputedRawValue(
  sheet = null,
  rowIndex = 0,
  columnIndex = 0,
  stack = new Set(),
  formulaContext = null,
  sheetEntry = null,
) {
  const currentSheet = sheet || sheetEntry?.sheet || null;
  const currentEntry = sheetEntry || formulaContext?.current || { key: "current", sheet: currentSheet };
  const row = currentSheet?.rows?.[rowIndex];
  const column = currentSheet?.columns?.[columnIndex];
  if (!row || !column) {
    return "";
  }

  if (column.computed === "average") {
    return getMobileMeasurementAverageValue(row);
  }

  const rawValue = row.cells?.[column.id] ?? "";
  if (!isMeasurementFormula(rawValue)) {
    return rawValue;
  }

  const cellKey = `${currentEntry?.key || "current"}:${rowIndex}:${columnIndex}`;
  if (stack.has(cellKey)) {
    throw new Error("Kruzna referenca u formuli.");
  }
  stack.add(cellKey);

  try {
    return evaluateMeasurementFormula(rawValue, {
      resolveCellReference(reference) {
        const targetEntry = resolveMobileMeasurementFormulaSheetEntry(reference, formulaContext, currentEntry);
        const targetSheet = targetEntry?.sheet || currentSheet;
        const { rowIndex: referenceRowIndex, columnIndex: referenceColumnIndex } =
          parseMeasurementCellReference(reference);
        if (
          referenceRowIndex < 0
          || referenceColumnIndex < 0
          || referenceRowIndex >= (targetSheet?.rows?.length || 0)
          || referenceColumnIndex >= (targetSheet?.columns?.length || 0)
        ) {
          throw new Error("Referenca nije valjana.");
        }
        return getMobileMeasurementCellComputedRawValue(
          targetSheet,
          referenceRowIndex,
          referenceColumnIndex,
          stack,
          formulaContext,
          targetEntry || currentEntry,
        );
      },
      resolveRange(startReference, endReference) {
        const startEntry = resolveMobileMeasurementFormulaSheetEntry(startReference, formulaContext, currentEntry);
        const endEntry = resolveMobileMeasurementFormulaSheetEntry(endReference, formulaContext, currentEntry);
        const targetEntry = startEntry || currentEntry;
        if ((startEntry?.key || currentEntry?.key) !== (endEntry?.key || currentEntry?.key)) {
          throw new Error("Raspon kroz vise Excel tablica nije podrzan.");
        }
        const targetSheet = targetEntry?.sheet || currentSheet;
        const start = parseMeasurementCellReference(startReference);
        const end = parseMeasurementCellReference(endReference);
        const startRowIndex = Math.max(0, Math.min(start.rowIndex, end.rowIndex));
        const endRowIndex = Math.max(start.rowIndex, end.rowIndex);
        const startColumnIndex = Math.max(0, Math.min(start.columnIndex, end.columnIndex));
        const endColumnIndex = Math.max(start.columnIndex, end.columnIndex);
        const matrix = [];
        for (let referenceRowIndex = startRowIndex; referenceRowIndex <= endRowIndex; referenceRowIndex += 1) {
          const rowValues = [];
          for (let referenceColumnIndex = startColumnIndex; referenceColumnIndex <= endColumnIndex; referenceColumnIndex += 1) {
            if (
              referenceRowIndex < 0
              || referenceColumnIndex < 0
              || referenceRowIndex >= (targetSheet?.rows?.length || 0)
              || referenceColumnIndex >= (targetSheet?.columns?.length || 0)
            ) {
              rowValues.push("");
              continue;
            }
            rowValues.push(getMobileMeasurementCellComputedRawValue(
              targetSheet,
              referenceRowIndex,
              referenceColumnIndex,
              stack,
              formulaContext,
              targetEntry,
            ));
          }
          matrix.push(rowValues);
        }
        return matrix;
      },
    });
  } finally {
    stack.delete(cellKey);
  }
}

function getMobileMeasurementCellDisplayText(sheet = null, rowIndex = 0, columnIndex = 0, formulaContext = null, sheetEntry = null) {
  const normalizedSheet = normalizeWorkOrderMeasurementSheet(sheet);
  const row = normalizedSheet?.rows?.[rowIndex];
  const column = normalizedSheet?.columns?.[columnIndex];
  if (!row || !column) {
    return "";
  }
  const rawValue = row.cells?.[column.id] ?? "";
  const format = row?.formats?.[column.id] && typeof row.formats[column.id] === "object"
    ? row.formats[column.id]
    : {};
  if (column.computed === "average" || isMeasurementFormula(rawValue)) {
    try {
      return formatMeasurementComputedDisplayValue(
        getMobileMeasurementCellComputedRawValue(normalizedSheet, rowIndex, columnIndex, new Set(), formulaContext, sheetEntry),
        format,
      );
    } catch {
      return "#ERROR";
    }
  }
  return formatMeasurementLiteralDisplayValue(rawValue, format);
}

function normalizeMobileMeasurementColumnLookupText(column = {}, columnIndex = 0) {
  return [
    column?.label,
    column?.placeholder,
    column?.id,
    `column-${columnIndex + 1}`,
  ].map(normalizeInputValue)
    .filter(Boolean)
    .join(" ")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function isMobileMeasurementIndexColumn(column = {}, columnIndex = 0) {
  if (columnIndex !== 0) {
    return false;
  }
  const lookup = normalizeMobileMeasurementColumnLookupText(column, columnIndex);
  return lookup === "r br"
    || lookup === "rbr"
    || lookup.includes("redni broj")
    || lookup.includes("r br")
    || lookup === "pozicija"
    || lookup === "broj";
}

function isMobileMeasurementDescriptorColumn(column = {}, columnIndex = 0) {
  if (isMobileMeasurementIndexColumn(column, columnIndex)) {
    return true;
  }
  const lookup = normalizeMobileMeasurementColumnLookupText(column, columnIndex);
  return [
    "opis",
    "napomena",
    "pozicija",
    "lokacija",
    "mjesto",
    "oznaka",
    "element",
    "uredaj",
    "prostor",
  ].some((term) => lookup === term || lookup.includes(term));
}

function isMobileMeasurementResultColumn(column = {}, columnIndex = 0) {
  if (!column || isMobileMeasurementDescriptorColumn(column, columnIndex)) {
    return false;
  }
  if (column.computed) {
    return true;
  }
  const lookup = normalizeMobileMeasurementColumnLookupText(column, columnIndex);
  return [
    "rezultat",
    "result",
    "vrijednost",
    "value",
    "izmjeren",
    "mjeren",
    "ocjena",
    "status",
    "stanje",
    "ispravno",
    "neispravno",
    "napon",
    "struja",
    "otpor",
    "impedanc",
    "izolacij",
    "kontinuitet",
    "vrijeme",
    "lux",
    "ohm",
    "mohm",
    "ma",
    "riso",
  ].some((term) => lookup === term || lookup.includes(term));
}

function isMobileMeasurementPrintableValuePresent(value = "") {
  const normalized = normalizeInputValue(value).replace(/\u00a0/g, " ").trim();
  return Boolean(normalized && normalized !== "-" && normalized !== "—");
}

function doesMobileMeasurementTableRowHaveVisibleResult(row = {}, columns = []) {
  const cells = Array.isArray(row?.cells) ? row.cells : [];
  const resultColumnIndexes = columns
    .map((column, columnIndex) => (isMobileMeasurementResultColumn(column, columnIndex) ? columnIndex : -1))
    .filter((columnIndex) => columnIndex >= 0);
  const candidateIndexes = resultColumnIndexes.length > 0
    ? resultColumnIndexes
    : columns
      .map((column, columnIndex) => (!isMobileMeasurementIndexColumn(column, columnIndex) ? columnIndex : -1))
      .filter((columnIndex) => columnIndex >= 0);

  return candidateIndexes.some((columnIndex) => {
    const cell = cells[columnIndex];
    const value = cell && typeof cell === "object" && !Array.isArray(cell)
      ? cell.text ?? cell.value ?? ""
      : cell;
    return isMobileMeasurementPrintableValuePresent(value);
  });
}

function normalizeMobileMeasurementConclusionValue(value = "") {
  return normalizeInputValue(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function isMobileMeasurementConclusionNegativeValue(value = "") {
  const normalized = normalizeMobileMeasurementConclusionValue(value);
  if (!normalized) {
    return false;
  }
  if ([
    "ne",
    "no",
    "fail",
    "failed",
    "negativno",
    "negativan",
    "negativna",
    "neispravno",
    "neispravan",
    "neispravna",
  ].includes(normalized)) {
    return true;
  }
  return normalized.includes("ne zadovoljava")
    || normalized.includes("nije ispravno")
    || normalized.includes("nije sukladno")
    || normalized.includes("ne odgovara")
    || normalized.includes("neisprav");
}

function isMobileMeasurementConclusionPositiveValue(value = "") {
  const normalized = normalizeMobileMeasurementConclusionValue(value);
  if (!normalized) {
    return false;
  }
  return [
    "da",
    "yes",
    "ok",
    "pass",
    "passed",
    "pozitivno",
    "pozitivan",
    "pozitivna",
    "ispravno",
    "ispravan",
    "ispravna",
    "zadovoljava",
    "sukladno",
  ].includes(normalized);
}

function updateMobileMeasurementConclusionAnalysis(analysis = {}, table = null) {
  if (!table?.columns?.length || !Array.isArray(table.rows)) {
    return analysis;
  }
  const resultColumnIndexes = table.columns
    .map((column, columnIndex) => (isMobileMeasurementResultColumn(column, columnIndex) ? columnIndex : -1))
    .filter((columnIndex) => columnIndex >= 0);
  const candidateIndexes = resultColumnIndexes.length > 0
    ? resultColumnIndexes
    : table.columns
      .map((column, columnIndex) => (!isMobileMeasurementIndexColumn(column, columnIndex) ? columnIndex : -1))
      .filter((columnIndex) => columnIndex >= 0);
  const headerRowIds = new Set((Array.isArray(table.headerRows) ? table.headerRows : []).map(normalizeInputValue));

  table.rows.forEach((row) => {
    if (row?.header || headerRowIds.has(normalizeInputValue(row?.id))) {
      return;
    }
    const cells = Array.isArray(row?.cells) ? row.cells : [];
    candidateIndexes.forEach((columnIndex) => {
      const cell = cells[columnIndex];
      const value = cell && typeof cell === "object" && !Array.isArray(cell)
        ? cell.text ?? cell.value ?? ""
        : cell;
      if (!isMobileMeasurementPrintableValuePresent(value)) {
        return;
      }
      analysis.hasResult = true;
      if (isMobileMeasurementConclusionNegativeValue(value)) {
        analysis.hasNegative = true;
      }
      if (isMobileMeasurementConclusionPositiveValue(value)) {
        analysis.hasPositive = true;
      }
    });
  });
  return analysis;
}

function buildMobileMeasurementConclusionPlaceholderValues(analysis = {}) {
  const isNegative = Boolean(analysis.hasNegative);
  const sentence = isNegative
    ? DOCUMENT_TEMPLATE_CONCLUSION_NEGATIVE_SENTENCE
    : DOCUMENT_TEMPLATE_CONCLUSION_POSITIVE_SENTENCE;
  const shortValue = isNegative ? "Ne zadovoljava" : "Zadovoljava";
  const statusValue = isNegative ? "Negativno" : "Pozitivno";
  const yesNoValue = isNegative ? "Ne" : "Da";

  return {
    ZAKLJUCNA_OCJENA: sentence,
    ZAKLJUCNA_OCJENA_RECENICA: sentence,
    ZAKLJUCAK_OCJENE: sentence,
    ZAKLJUCAK_ISPITIVANJA: sentence,
    OCJENA_REZULTATA_ISPITIVANJA: yesNoValue,
    OCJENA_REZULTATA_ISPITIVANJA_STATUS: yesNoValue,
    OCJENA_REZULTATA: statusValue,
    OCJENA_REZULTATA_KRATKO: shortValue,
    ZAKLJUCNA_OCJENA_STATUS: statusValue,
    ZAKLJUCNA_OCJENA_KRATKO: shortValue,
    ZAKLJUCNA_OCJENA_DA_NE: yesNoValue,
  };
}

function buildMobileMeasurementTablePlaceholderFromSheet(sheet = null, field = {}, index = 0, formulaContext = null, sheetEntry = null) {
  const normalizedSheet = normalizeWorkOrderMeasurementSheet(sheet);
  const fallbackColumns = Array.isArray(field?.columns) && field.columns.length > 0
    ? field.columns
    : ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"];

  if (!normalizedSheet?.columns?.length) {
    const pageOrientation = normalizeInputValue(field?.pageOrientation || field?.orientation || "").toLowerCase() === "landscape"
      || fallbackColumns.length > 5
      ? "landscape"
      : "";
    return {
      __docxBlockType: "table",
      pageOrientation,
      columns: fallbackColumns.map((column, columnIndex) => {
        const label = column && typeof column === "object" && !Array.isArray(column)
          ? normalizeInputValue(column.label || column.id)
          : normalizeInputValue(column);
        return {
          id: `column-${columnIndex + 1}`,
          label: label || `Kolona ${columnIndex + 1}`,
          width: 140,
        };
      }),
      rows: [{
        id: "row-1",
        header: true,
        cells: fallbackColumns.map((column, columnIndex) => {
          const label = column && typeof column === "object" && !Array.isArray(column)
            ? normalizeInputValue(column.label || column.id)
            : normalizeInputValue(column);
          return {
            text: label || `Kolona ${columnIndex + 1}`,
            format: {
              bold: true,
              fillColor: "#F1F7F4",
              border: "all",
            },
          };
        }),
      }],
      headerRows: ["row-1"],
      merges: [],
    };
  }

  const columns = normalizedSheet.columns.map((column, columnIndex) => ({
    id: normalizeInputValue(column?.id) || `column-${columnIndex + 1}`,
    label: normalizeInputValue(column?.label || column?.id) || `Kolona ${columnIndex + 1}`,
    width: Math.max(32, Number(column?.width) || 140),
    computed: column?.computed || null,
  }));
  const sourceRows = Array.isArray(normalizedSheet.rows) && normalizedSheet.rows.length > 0
    ? normalizedSheet.rows
    : [{ id: "row-1", cells: {} }];
  const headerRows = Array.isArray(normalizedSheet.headerRows)
    ? normalizedSheet.headerRows.map(normalizeInputValue).filter(Boolean)
    : [];
  const allRows = sourceRows.slice(0, 120).map((row, rowIndex) => ({
    id: normalizeInputValue(row?.id) || `row-${rowIndex + 1}`,
    header: headerRows.includes(normalizeInputValue(row?.id)),
    cells: columns.map((column, columnIndex) => ({
      text: getMobileMeasurementCellDisplayText(normalizedSheet, rowIndex, columnIndex, formulaContext, sheetEntry),
      format: row?.formats?.[column.id] && typeof row.formats[column.id] === "object"
        ? row.formats[column.id]
        : {},
    })),
  }));
  const bodyRows = allRows.filter((row) => (
    row.header || doesMobileMeasurementTableRowHaveVisibleResult(row, columns)
  ));
  const syntheticHeaderRow = headerRows.length === 0
    ? {
        id: "column-labels",
        header: true,
        cells: columns.map((column) => ({
          text: column.label,
          format: {
            bold: true,
            fillColor: "#F1F7F4",
            border: "all",
          },
        })),
      }
    : null;
  const rows = syntheticHeaderRow ? [syntheticHeaderRow, ...bodyRows] : bodyRows;
  const visibleRowIds = new Set(rows.map((row) => normalizeInputValue(row.id)).filter(Boolean));
  const pageOrientation = normalizeInputValue(
    normalizedSheet.pageOrientation
    || field?.pageOrientation
    || field?.orientation
    || "",
  ).toLowerCase() === "landscape" || columns.length > 5
    ? "landscape"
    : "";

  return {
    __docxBlockType: "table",
    columns,
    rows,
    headerRows: syntheticHeaderRow ? [syntheticHeaderRow.id] : headerRows,
    merges: (Array.isArray(normalizedSheet.merges) ? normalizedSheet.merges : []).map((merge) => ({
      rowId: normalizeInputValue(merge?.rowId),
      columnId: normalizeInputValue(merge?.columnId),
      rowSpan: Math.max(1, Number(merge?.rowSpan) || 1),
      colSpan: Math.max(1, Number(merge?.colSpan) || 1),
    })).filter((merge) => merge.rowId && merge.columnId && visibleRowIds.has(merge.rowId)),
    title: normalizeInputValue(field?.label || field?.wordLabel) || `Excel tablica ${index + 1}`,
    pageOrientation,
  };
}

function buildMobileDocumentTemplateMeasurementPlaceholders(template = {}, fieldSheets = {}) {
  const placeholders = {};
  const conclusionAnalysis = {
    hasResult: false,
    hasPositive: false,
    hasNegative: false,
  };
  const formulaContextBase = buildMobileMeasurementSheetFormulaEntries(template, fieldSheets);
  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field, index) => {
    if (normalizeInputValue(field?.type).toLowerCase() !== "measurement_table") {
      return;
    }
    const recordKey = normalizeInputValue(field?.key || field?.id);
    const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
    const sheet = recordKey ? fieldSheets[recordKey] : null;
    const sheetEntry = formulaContextBase.entries.find((entry) => entry.key === recordKey)
      || { key: recordKey || tokenKey || `measurement-${index + 1}`, sheet: normalizeWorkOrderMeasurementSheet(sheet) };
    const placeholder = buildMobileMeasurementTablePlaceholderFromSheet(
      sheet,
      field,
      index,
      { ...formulaContextBase, current: sheetEntry },
      sheetEntry,
    );
    updateMobileMeasurementConclusionAnalysis(conclusionAnalysis, placeholder);
    [recordKey, tokenKey, normalizeInputValue(field?.id)]
      .filter(Boolean)
      .forEach((key) => {
        placeholders[key] = placeholder;
      });
  });
  Object.assign(placeholders, buildMobileMeasurementConclusionPlaceholderValues(conclusionAnalysis));
  return placeholders;
}

function normalizeMobileSystemDescriptionLineCount(value = 1) {
  const numeric = Number(value);
  return Math.max(1, Math.min(8, Math.round(Number.isFinite(numeric) ? numeric : 1)));
}

function isMobileSystemDescriptionValue(value = null) {
  return Boolean(
    value
    && typeof value === "object"
    && !Array.isArray(value)
    && (Array.isArray(value.blocks) || Array.isArray(value.rows)),
  );
}

function normalizeMobileSystemDescriptionRows(rows = []) {
  const normalizedRows = (Array.isArray(rows) ? rows : [])
    .slice(0, 16)
    .map((row, index) => ({
      id: normalizeInputValue(row?.id) || `system-description-row-${index + 1}`,
      subtitle: normalizeInputValue(row?.subtitle ?? row?.label).slice(0, 160),
      description: String(row?.description ?? row?.value ?? row?.text ?? row?.content ?? "")
        .replace(/\r\n/g, "\n")
        .trim()
        .slice(0, 4000),
      lineCount: normalizeMobileSystemDescriptionLineCount(row?.lineCount ?? row?.line_count ?? row?.rows),
      placeholder: normalizeInputValue(row?.placeholder).slice(0, 220),
    }));

  return normalizedRows.length > 0
    ? normalizedRows
    : [{
      id: "system-description-row-1",
      subtitle: "",
      description: "",
      lineCount: 1,
      placeholder: "",
    }];
}

function getMobileSystemDescriptionTemplateRows(field = {}) {
  return normalizeMobileSystemDescriptionRows(field?.systemRows ?? field?.rows ?? []);
}

function getMobileSystemDescriptionRowValueKeys(row = {}) {
  const subtitle = normalizeInputValue(row?.subtitle || row?.label).toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  const keys = [
    row?.id,
    row?.key,
    row?.subtitle,
    row?.label,
    row?.placeholder,
  ].map(normalizeInputValue).filter(Boolean);
  if (subtitle.includes("proizvodac") || subtitle.includes("manufacturer")) {
    keys.push("proizvodac", "proizvođač", "manufacturer", "producer", "make");
  }
  if (subtitle === "tip" || subtitle.includes("model")) {
    keys.push("tip", "type", "model", "tipModel", "tip_model");
  }
  if (subtitle.includes("teh") || subtitle.includes("podat")) {
    keys.push("tehPodaci", "teh_podaci", "tehnickiPodaci", "tehnički podaci", "technicalData", "technical_data");
  }
  if (!subtitle || subtitle.includes("opis")) {
    keys.push("opis", "description", "systemDescription", "system_description", "napomena", "note");
  }
  return Array.from(new Set(keys.map(normalizeInputValue).filter(Boolean)));
}

function getMobileSystemDescriptionValueByKeys(source = {}, keys = []) {
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    return "";
  }
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(source, key)) {
      return source[key];
    }
  }
  const normalizedLookup = new Map(Object.entries(source).map(([key, value]) => [
    normalizeMobileTemplateFieldLookup(key),
    value,
  ]));
  for (const key of keys) {
    const value = normalizedLookup.get(normalizeMobileTemplateFieldLookup(key));
    if (value !== undefined) {
      return value;
    }
  }
  return "";
}

function normalizeMobileSystemDescriptionRowsFromStructuredValue(field = {}, value = null) {
  if (!value || typeof value !== "object") {
    return null;
  }

  if (Array.isArray(value)) {
    const objectRows = value
      .filter((entry) => entry && typeof entry === "object" && !Array.isArray(entry))
      .map((entry, index) => ({
        id: normalizeInputValue(entry?.id) || `system-description-row-${index + 1}`,
        subtitle: normalizeInputValue(entry?.subtitle ?? entry?.label ?? entry?.title),
        description: normalizeInputValue(entry?.description ?? entry?.value ?? entry?.text ?? entry?.content),
        lineCount: normalizeMobileSystemDescriptionLineCount(entry?.lineCount ?? entry?.line_count ?? entry?.rows),
        placeholder: normalizeInputValue(entry?.placeholder),
      }))
      .filter((row) => normalizeInputValue(row.subtitle || row.description));
    if (objectRows.length > 0) {
      return objectRows;
    }

    const textRows = value.map((entry) => normalizeInputValue(entry)).filter(Boolean);
    return textRows.length > 0
      ? [{
        id: "system-description-row-1",
        subtitle: "",
        description: textRows.join("\n"),
        lineCount: 2,
        placeholder: "",
      }]
      : null;
  }

  const explicitRows = Array.isArray(value.rows)
    ? value.rows
    : Array.isArray(value.items)
      ? value.items
      : null;
  if (explicitRows) {
    return normalizeMobileSystemDescriptionRowsFromStructuredValue(field, explicitRows);
  }

  const templateRows = getMobileSystemDescriptionTemplateRows(field);
  let hasMappedValue = false;
  const rows = templateRows.map((row, index) => {
    const rawValue = getMobileSystemDescriptionValueByKeys(value, getMobileSystemDescriptionRowValueKeys(row));
    const description = Array.isArray(rawValue)
      ? rawValue.map((entry) => normalizeInputValue(entry)).filter(Boolean).join("\n")
      : rawValue && typeof rawValue === "object"
        ? normalizeInputValue(rawValue.value ?? rawValue.text ?? rawValue.description ?? rawValue.content)
        : normalizeInputValue(rawValue);
    if (description) {
      hasMappedValue = true;
    }
    return {
      ...row,
      id: row.id || `system-description-row-${index + 1}`,
      description,
    };
  });

  return hasMappedValue ? rows : null;
}

function normalizeMobileSystemDescriptionBlock(field = {}, block = {}, index = 0) {
  const title = normalizeInputValue(block?.title || block?.label || field?.label || field?.wordLabel || "Opis sustava");
  const sectionSubtitle = normalizeInputValue(
    block?.sectionSubtitle
    || block?.section_subtitle
    || block?.subtitle
    || (index === 0 ? field?.sectionSubtitle : ""),
  );
  return {
    id: normalizeInputValue(block?.id) || `system-description-block-${index + 1}`,
    title,
    sectionSubtitle,
    rows: normalizeMobileSystemDescriptionRows(block?.rows),
  };
}

function normalizeMobileSystemDescriptionRuntimeValue(field = {}, value = null) {
  if (typeof value === "string") {
    const trimmedValue = value.trim();
    if ((trimmedValue.startsWith("{") && trimmedValue.endsWith("}")) || (trimmedValue.startsWith("[") && trimmedValue.endsWith("]"))) {
      try {
        return normalizeMobileSystemDescriptionRuntimeValue(field, JSON.parse(trimmedValue));
      } catch {
        // Fall through and treat it as normal text.
      }
    }
  }

  if (!isMobileSystemDescriptionValue(value) && value && typeof value === "object") {
    const mappedRows = normalizeMobileSystemDescriptionRowsFromStructuredValue(field, value);
    if (mappedRows?.length) {
      return {
        blocks: [{
          id: "system-description-block-1",
          title: normalizeInputValue(value.title || value.label || field?.label || field?.wordLabel || "Opis sustava"),
          sectionSubtitle: normalizeInputValue(value.sectionSubtitle || value.section_subtitle || value.subtitle),
          rows: mappedRows,
        }],
      };
    }
  }

  if (!isMobileSystemDescriptionValue(value) && normalizeInputValue(value)) {
    const templateRows = getMobileSystemDescriptionTemplateRows(field);
    const [firstRow = { id: "system-description-row-1", subtitle: "", lineCount: 1, placeholder: "" }, ...restRows] = templateRows;
    return {
      blocks: [{
        id: "system-description-block-1",
        title: normalizeInputValue(field?.label || field?.wordLabel || "Opis sustava"),
        sectionSubtitle: normalizeInputValue(field?.sectionSubtitle),
        rows: [
          {
            ...firstRow,
            description: normalizeInputValue(value),
          },
          ...restRows,
        ],
      }],
    };
  }

  if (isMobileSystemDescriptionValue(value) && Array.isArray(value.blocks)) {
    return {
      blocks: value.blocks.slice(0, 24).map((block, index) => normalizeMobileSystemDescriptionBlock(field, block, index)),
    };
  }

  if (isMobileSystemDescriptionValue(value) && Array.isArray(value.rows)) {
    return {
      blocks: [normalizeMobileSystemDescriptionBlock(field, {
        title: value.title || field?.label || field?.wordLabel || "Opis sustava",
        sectionSubtitle: value.sectionSubtitle || value.section_subtitle || value.subtitle || field?.sectionSubtitle,
        rows: value.rows,
      }, 0)],
    };
  }

  return {
    blocks: [normalizeMobileSystemDescriptionBlock(field, {
      title: field?.label || field?.wordLabel || "Opis sustava",
      sectionSubtitle: field?.sectionSubtitle,
      rows: getMobileSystemDescriptionTemplateRows(field),
    }, 0)],
  };
}

function buildMobileSystemDescriptionWordPlaceholder(field = {}, value = null) {
  const model = normalizeMobileSystemDescriptionRuntimeValue(field, value);
  return {
    __docxBlockType: "system_description",
    blocks: model.blocks.map((block, blockIndex) => ({
      id: block.id || `system-description-block-${blockIndex + 1}`,
      title: block.title || field?.label || field?.wordLabel || "Opis sustava",
      subtitle: block.sectionSubtitle || "",
      rows: (Array.isArray(block.rows) ? block.rows : []).map((row, rowIndex) => ({
        id: row.id || `system-description-row-${blockIndex + 1}-${rowIndex + 1}`,
        subtitle: row.subtitle || "",
        description: row.description || "",
        lineCount: normalizeMobileSystemDescriptionLineCount(row.lineCount),
      })),
    })),
  };
}

function hasMobileSystemDescriptionContent(value = null) {
  const model = isMobileSystemDescriptionValue(value)
    ? normalizeMobileSystemDescriptionRuntimeValue({}, value)
    : value;
  return Boolean(
    model
    && typeof model === "object"
    && Array.isArray(model.blocks)
    && model.blocks.some((block) => (
      normalizeInputValue(block?.sectionSubtitle)
      || (Array.isArray(block?.rows) && block.rows.some((row) => normalizeInputValue(row?.description)))
    )),
  );
}

const MOBILE_DOCUMENT_TEMPLATE_PROMPT_FIELD_TYPES = new Set([
  "text",
  "longtext",
  "number",
  "date",
  "dropdown",
  "checkbox",
  "toggle",
  "spr_voice",
]);

function isMobileDocumentTemplatePromptField(field = {}) {
  if (!field || typeof field !== "object") {
    return false;
  }
  const type = normalizeInputValue(field?.type || "text").toLowerCase();
  if (!MOBILE_DOCUMENT_TEMPLATE_PROMPT_FIELD_TYPES.has(type)) {
    return false;
  }
  if (field.hidden === true || field.mobileHidden === true || field.excludeFromMobile === true) {
    return false;
  }
  return true;
}

function buildMobileDocumentTemplateFieldOptions(field = {}) {
  const candidates = [
    field?.options,
    field?.choices,
    field?.items,
    field?.values,
    field?.dropdownOptions,
  ].find((value) => Array.isArray(value));

  return (Array.isArray(candidates) ? candidates : [])
    .map((option) => {
      if (option && typeof option === "object" && !Array.isArray(option)) {
        const value = normalizeInputValue(option.value || option.id || option.key || option.label || option.name || option.title);
        const label = normalizeInputValue(option.label || option.name || option.title || option.value || option.id || option.key);
        return value || label ? { value: value || label, label: label || value } : null;
      }
      const value = normalizeInputValue(option);
      return value ? { value, label: value } : null;
    })
    .filter(Boolean);
}

function normalizeMobileTemplateFieldLookup(value = "") {
  return normalizeInputValue(value)
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function normalizeMobileTemplateConclusionLookup(value = "") {
  return normalizeMobileTemplateFieldLookup(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function isMobileDocumentTemplateConclusionAssessmentField(field = {}) {
  const type = normalizeInputValue(field?.type || "text").toLowerCase();
  if (type !== "toggle" && type !== "checkbox") {
    return false;
  }
  const lookup = normalizeMobileTemplateConclusionLookup([
    field?.key,
    field?.wordLabel,
    field?.label,
    field?.helpText,
  ].map(normalizeInputValue).filter(Boolean).join(" "));
  return Boolean(
    (lookup.includes("zakljuc") && lookup.includes("ocjen"))
    || lookup.includes("ocjena rezultata")
    || lookup.includes("ocjena ispitivanja")
    || lookup.includes("zakljucak ispitivanja"),
  );
}

function getMobileTemplateBooleanDisplayValue(field = {}, value = false) {
  const selected = coerceMobileTemplateFieldDocumentValue(value, field);
  return selected
    ? (normalizeInputValue(field?.toggleTrueLabel) || "Da")
    : (normalizeInputValue(field?.toggleFalseLabel) || "Ne");
}

function getMobileTemplateToggleConditionalText(field = {}, value = false) {
  const selected = coerceMobileTemplateFieldDocumentValue(value, field);
  return selected
    ? normalizeInputValue(field?.toggleTrueText ?? field?.toggleTrueDetailText)
    : normalizeInputValue(field?.toggleFalseText ?? field?.toggleFalseDetailText);
}

function resolveMobileTemplateInlinePlaceholders(text = "", placeholders = {}) {
  const source = normalizeInputValue(text);
  if (!source) {
    return "";
  }
  const lookup = new Map(Object.entries(placeholders || {}).map(([key, value]) => [
    normalizeMobileDocumentTemplateFieldTokenKey(key, ""),
    value,
  ]));
  return source.replace(/\{\{\s*([^{}]+?)\s*\}\}/g, (match, tokenName) => {
    const key = normalizeMobileDocumentTemplateFieldTokenKey(tokenName, "");
    if (!key || !lookup.has(key)) {
      return match;
    }
    const value = lookup.get(key);
    if (value && typeof value === "object") {
      return "";
    }
    return normalizeInputValue(value);
  });
}

function buildMobileTemplateToggleDerivedValues(value, field = {}, placeholders = {}) {
  const selected = coerceMobileTemplateFieldDocumentValue(value, field);
  const statusText = getMobileTemplateBooleanDisplayValue(field, selected);
  const extraText = resolveMobileTemplateInlinePlaceholders(
    getMobileTemplateToggleConditionalText(field, selected),
    placeholders,
  );
  const fullText = [statusText, extraText].filter(Boolean).join(" ");
  return {
    selected,
    statusText,
    extraText,
    fullText,
  };
}

function getMobileDocumentTemplateConclusionFieldAutoValue(field = {}, placeholders = {}) {
  if (!isMobileDocumentTemplateConclusionAssessmentField(field)) {
    return undefined;
  }
  const candidate = normalizeMobileTemplateConclusionLookup(
    placeholders?.ZAKLJUCNA_OCJENA_DA_NE
    || placeholders?.OCJENA_REZULTATA_ISPITIVANJA
    || placeholders?.OCJENA_REZULTATA_ISPITIVANJA_STATUS
    || "",
  );
  if (!candidate) {
    return undefined;
  }
  return candidate === "ne" || candidate.includes("negativ") || candidate.includes("ne zadovoljava")
    ? "false"
    : "true";
}

function isMobileInspectionTypeTemplateField(field = {}, index = 0) {
  const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
  return [
    field?.id,
    field?.key,
    field?.wordLabel,
    field?.label,
    tokenKey,
  ]
    .map(normalizeMobileTemplateFieldLookup)
    .some((value) => (
      value === "vrsta ispitivanja"
      || value === "inspection type"
      || value === "work order inspection type"
      || value.includes("vrsta ispitivanja")
      || value.includes("inspection type")
    ));
}

function getMobileDocumentTemplateFieldDefaultValue(field = {}) {
  const candidate = field?.defaultValue
    ?? field?.value
    ?? field?.initialValue
    ?? field?.placeholderValue
    ?? "";
  if (typeof candidate === "boolean") {
    return candidate ? "true" : "false";
  }
  return normalizeInputValue(candidate);
}

function normalizeMobileTemplatePromptInputValue(value, field = {}) {
  const type = normalizeInputValue(field?.type || "text").toLowerCase();
  if (type === "checkbox" || type === "toggle") {
    return coerceMobileTemplateFieldDocumentValue(value, field) ? "true" : "false";
  }
  if (type === "date") {
    return normalizeDateOnlyValue(value) || normalizeInputValue(value);
  }
  return normalizeInputValue(value);
}

function resolveMobileTemplatePromptDefaultValue(field = {}, index = 0, placeholders = {}, template = {}, common = {}) {
  const submittedValue = getMobileDocumentTemplateSubmittedFieldValue(field, template, common, index);
  if (submittedValue !== undefined && submittedValue !== null && typeof submittedValue !== "object") {
    return normalizeMobileTemplatePromptInputValue(submittedValue, field);
  }

  const conclusionAutoValue = getMobileDocumentTemplateConclusionFieldAutoValue(field, placeholders);
  if (conclusionAutoValue !== undefined) {
    return normalizeMobileTemplatePromptInputValue(conclusionAutoValue, field);
  }

  const explicitValue = getMobileDocumentTemplateFieldDefaultValue(field);
  if (explicitValue) {
    return explicitValue;
  }

  const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
  const candidateKeys = [
    field?.key,
    field?.id,
    field?.wordLabel,
    field?.label,
    tokenKey,
    normalizeMobileDocumentTemplateFieldTokenKey(field?.label || field?.wordLabel || "", ""),
  ].map(normalizeInputValue).filter(Boolean);
  const normalizedLookup = new Map(Object.entries(placeholders || {}).map(([key, value]) => [
    normalizeMobileDocumentTemplateFieldTokenKey(key, ""),
    value,
  ]));

  for (const key of candidateKeys) {
    const directValue = placeholders?.[key];
    if (directValue !== undefined && directValue !== null && typeof directValue !== "object") {
      return normalizeMobileTemplatePromptInputValue(directValue, field);
    }
    const normalizedValue = normalizedLookup.get(normalizeMobileDocumentTemplateFieldTokenKey(key, ""));
    if (normalizedValue !== undefined && normalizedValue !== null && typeof normalizedValue !== "object") {
      return normalizeMobileTemplatePromptInputValue(normalizedValue, field);
    }
  }
  return "";
}

const MOBILE_DOCUMENT_TEMPLATE_SIGNATURE_FIELD_TYPES = new Set([
  "qualified_inspectors",
  "inspector_signature",
  "authorization_holder_signature",
  "digital_signature",
]);

function normalizeMobileDocumentSignatureRole(value = "inspect") {
  const normalized = normalizeInputValue(value || "inspect")
    .toLowerCase()
    .replace(/[_-]+/g, " ");
  if (normalized === "all" || normalized.includes("svi") || normalized.includes("ispitivaci + odgovorna")) {
    return "all";
  }
  if (normalized.includes("company") || normalized.includes("klijent") || normalized.includes("narucitelj")) {
    return "company_responsible";
  }
  if (normalized.includes("authorize") || normalized.includes("ovlast") || normalized.includes("nositelj") || normalized.includes("odgovorn")) {
    return "authorize";
  }
  return "inspect";
}

function getMobileDocumentTemplateSignatureFieldConfig(field = {}) {
  const type = normalizeInputValue(field?.type || "text").toLowerCase();
  const role = normalizeMobileDocumentSignatureRole(
    field?.signatureRole || (type === "authorization_holder_signature" ? "authorize" : "inspect"),
  );
  const allowMultiple = type === "authorization_holder_signature" || type === "inspector_signature"
    ? false
    : Boolean(field?.signatureMultiple ?? true);
  return {
    signatureArea: normalizeMobileQualificationAreaKey(field?.signatureArea || "elektro"),
    signatureRole: role,
    signatureMultiple: role === "authorize" || role === "company_responsible" ? false : allowMultiple,
    signatureMetaFields: normalizeMobileDocumentWizardArray(field?.signatureMetaFields),
  };
}

function buildMobileDocumentTemplatePromptFields(template = {}, placeholders = {}, common = {}) {
  return (Array.isArray(template?.customFields) ? template.customFields : [])
    .map((field, index) => {
      if (!isMobileDocumentTemplatePromptField(field)) {
        return null;
      }
      const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
      const id = normalizeInputValue(field?.id || field?.key || tokenKey);
      const key = normalizeInputValue(field?.key);
      const label = normalizeInputValue(field?.label || field?.wordLabel || key || tokenKey);
      if (!id || !label) {
        return null;
      }
      return {
        id,
        key,
        tokenKey,
        label,
        type: normalizeInputValue(field?.type || "text").toLowerCase(),
        required: Boolean(field?.required || field?.isRequired),
        helpText: normalizeInputValue(field?.helpText || field?.description || field?.hint),
        defaultValue: resolveMobileTemplatePromptDefaultValue(field, index, placeholders, template, common),
        options: buildMobileDocumentTemplateFieldOptions(field),
        ...getMobileDocumentTemplateSignatureFieldConfig(field),
      };
    })
    .filter(Boolean);
}

function normalizeMobileAiConfigList(value = [], maxItems = 120) {
  const source = Array.isArray(value)
    ? value
    : String(value || "")
      .split(/\r?\n|,/);
  return source
    .map((entry) => normalizeInputValue(entry).slice(0, 240))
    .filter(Boolean)
    .slice(0, maxItems);
}

function normalizeMobileAiFieldType(value = "", fallback = "text") {
  const normalized = normalizeInputValue(value || fallback).toLowerCase();
  const allowed = new Set(["text", "number", "date", "enum", "boolean", "list", "table", "system_description"]);
  return allowed.has(normalized) ? normalized : fallback;
}

function normalizeMobileAiConfidence(value = "", fallback = "medium") {
  const normalized = normalizeInputValue(value || fallback).toLowerCase();
  return ["low", "medium", "high"].includes(normalized) ? normalized : fallback;
}

const MOBILE_DOCUMENT_TEMPLATE_AI_SOURCE_PRIORITY_DEFAULT = Object.freeze([
  "previous_report",
  "older_previous_report",
  "uploaded_file",
  "template",
]);
const MOBILE_DOCUMENT_TEMPLATE_AI_NO_SOURCE_BEHAVIORS = new Set(["leave_empty", "use_template", "ask_user"]);
const MOBILE_DOCUMENT_TEMPLATE_AI_DEFAULT_AVOID = "Ne izmisljaj vrijednosti. Ako podatak nije vidljiv u izvoru, ostavi prazno ili oznaci da nije moguce utvrditi.";

function normalizeMobileDocumentTemplateAiSourcePriority(value = []) {
  const source = Array.isArray(value)
    ? value
    : String(value ?? "").split(/[,;\n]/);
  const normalized = source
    .map((entry) => normalizeInputValue(entry).toLowerCase())
    .filter(Boolean)
    .slice(0, 8);
  return normalized.length > 0
    ? Array.from(new Set(normalized))
    : [...MOBILE_DOCUMENT_TEMPLATE_AI_SOURCE_PRIORITY_DEFAULT];
}

function normalizeMobileDocumentTemplateAiNoSourceBehavior(value = "") {
  const normalized = normalizeInputValue(value).toLowerCase();
  return MOBILE_DOCUMENT_TEMPLATE_AI_NO_SOURCE_BEHAVIORS.has(normalized) ? normalized : "leave_empty";
}

function getMobileDocumentTemplateAiSettings(scopedSnapshot = {}) {
  return normalizeDocumentTemplateAiSettings(scopedSnapshot?.documentTemplateAiSettings ?? {});
}

function formatMobileDocumentTemplateAiInstruction(template = "", values = {}) {
  return normalizeInputValue(template)
    .replaceAll("{label}", normalizeInputValue(values.label))
    .replaceAll("{column}", normalizeInputValue(values.label))
    .replaceAll("{field}", normalizeInputValue(values.fieldLabel));
}

function shouldMobileDocumentTemplateAiInheritSettings(source = {}) {
  const raw = source?.inheritSettings ?? source?.inherit_settings;
  if (raw === undefined || raw === null || raw === "") {
    return true;
  }
  if (raw === false || raw === 0) {
    return false;
  }
  const normalized = normalizeInputValue(raw).toLowerCase();
  return !["false", "0", "no", "ne"].includes(normalized);
}

function normalizeMobileDocumentTemplateFieldAiConfig(input = {}, field = {}) {
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
  const fallbackType = fieldType === "dropdown"
    ? "enum"
    : fieldType === "measurement_table"
      ? "list"
      : fieldType === "date"
        ? "date"
        : "text";
  const aiDescription = normalizeInputValue(source?.aiDescription ?? source?.ai_description ?? source?.description).slice(0, 2000);
  const aiLookFor = normalizeMobileAiConfigList(source?.aiLookFor ?? source?.ai_look_for, 160);
  const aiAvoid = normalizeInputValue(source?.aiAvoid ?? source?.ai_avoid).slice(0, 1000);
  return {
    key: normalizeInputValue(source?.key ?? field?.key).slice(0, 120),
    label: normalizeInputValue(source?.label ?? field?.label ?? field?.wordLabel).slice(0, 160),
    description: normalizeInputValue(source?.description ?? field?.helpText).slice(0, 2000),
    type: normalizeMobileAiFieldType(source?.type || fallbackType, fallbackType),
    required: Boolean(source?.required || field?.required || field?.isRequired),
    placeholder: normalizeInputValue(source?.placeholder).slice(0, 400),
    helpText: normalizeInputValue(source?.helpText ?? source?.help_text ?? field?.helpText).slice(0, 1000),
    enabled: Boolean(source?.enabled ?? source?.aiEnabled ?? source?.ai_enabled),
    aiDescription,
    aiLookFor,
    aiAvoid,
    allowedValues: normalizeMobileAiConfigList(source?.allowedValues ?? source?.allowed_values, 160),
    commonValues: normalizeMobileAiConfigList(source?.commonValues ?? source?.common_values, 80),
    examples: normalizeMobileAiConfigList(source?.examples, 80),
    format: normalizeInputValue(source?.format).slice(0, 1200),
    unit: normalizeInputValue(source?.unit).slice(0, 40),
    defaultValue: normalizeInputValue(source?.defaultValue ?? source?.default_value ?? field?.defaultValue).slice(0, 500),
    fallbackValue: normalizeInputValue(source?.fallbackValue ?? source?.fallback_value).slice(0, 500),
    confidenceRequired: normalizeMobileAiConfidence(source?.confidenceRequired ?? source?.confidence_required, "medium"),
    sourceTracking: Boolean(source?.sourceTracking ?? source?.source_tracking ?? true),
    validationRules: normalizeInputValue(source?.validationRules ?? source?.validation_rules).slice(0, 1600),
    displayOrder: Number.isFinite(Number(source?.displayOrder ?? source?.display_order))
      ? Number(source?.displayOrder ?? source?.display_order)
      : null,
    group: normalizeInputValue(source?.group).slice(0, 120),
    instructions: normalizeInputValue(source?.instructions ?? source?.aiInstructions ?? source?.ai_instruction).slice(0, 3000),
    locked: Boolean(source?.locked ?? source?.readonly ?? source?.readOnly),
    inheritSettings: Boolean(source?.inheritSettings ?? source?.inherit_settings ?? true),
    sourcePriority: normalizeMobileDocumentTemplateAiSourcePriority(source?.sourcePriority ?? source?.source_priority),
    noSourceBehavior: normalizeMobileDocumentTemplateAiNoSourceBehavior(source?.noSourceBehavior ?? source?.no_source_behavior),
  };
}

function hasMobileDocumentTemplateFieldAiConfig(input = {}, field = {}) {
  const config = normalizeMobileDocumentTemplateFieldAiConfig(input, field);
  return Boolean(
    config.enabled
    || config.aiDescription
    || config.aiLookFor.length
    || config.aiAvoid
    || config.allowedValues.length
    || config.commonValues.length
    || config.examples.length
    || config.fallbackValue
    || config.validationRules
    || config.group
    || config.instructions
    || config.locked
  );
}

function normalizeMobileMeasurementColumnAiMapping(input = {}) {
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const format = normalizeMobileAiFieldType(source?.format || source?.type || "text", "text");
  const aiDescription = normalizeInputValue(source?.aiDescription ?? source?.ai_description ?? source?.description).slice(0, 4000);
  const aiLookFor = normalizeMobileAiConfigList(source?.aiLookFor ?? source?.ai_look_for ?? source?.synonyms, 160);
  const aiAvoid = normalizeInputValue(source?.aiAvoid ?? source?.ai_avoid ?? source?.avoid).slice(0, 1000);
  return {
    key: normalizeInputValue(source?.key).slice(0, 120),
    label: normalizeInputValue(source?.label).slice(0, 160),
    description: normalizeInputValue(source?.description ?? source?.aiDescription ?? source?.ai_description).slice(0, 2000),
    type: normalizeMobileAiFieldType(source?.type || format, format),
    required: Boolean(source?.required),
    placeholder: normalizeInputValue(source?.placeholder).slice(0, 400),
    helpText: normalizeInputValue(source?.helpText ?? source?.help_text).slice(0, 1000),
    enabled: Boolean(source?.enabled ?? source?.aiEnabled ?? source?.ai_enabled),
    aiDescription,
    aiLookFor,
    aiAvoid,
    synonyms: normalizeMobileAiConfigList(source?.synonyms ?? aiLookFor, 80),
    allowedValues: normalizeMobileAiConfigList(source?.allowedValues ?? source?.allowed_values, 160),
    commonValues: normalizeMobileAiConfigList(source?.commonValues ?? source?.common_values, 80),
    examples: normalizeMobileAiConfigList(source?.examples, 80),
    avoid: aiAvoid,
    format,
    unit: normalizeInputValue(source?.unit).slice(0, 40),
    defaultValue: normalizeInputValue(source?.defaultValue ?? source?.default_value).slice(0, 500),
    fallbackValue: normalizeInputValue(source?.fallbackValue ?? source?.fallback_value).slice(0, 500),
    confidenceRequired: normalizeMobileAiConfidence(source?.confidenceRequired ?? source?.confidence_required, "medium"),
    sourceTracking: Boolean(source?.sourceTracking ?? source?.source_tracking ?? true),
    validationRules: normalizeInputValue(source?.validationRules ?? source?.validation_rules).slice(0, 1600),
    displayOrder: Number.isFinite(Number(source?.displayOrder ?? source?.display_order))
      ? Number(source?.displayOrder ?? source?.display_order)
      : null,
    group: normalizeInputValue(source?.group).slice(0, 120),
    instructions: normalizeInputValue(source?.instructions ?? source?.aiInstructions ?? source?.ai_instructions ?? source?.ai_instruction).slice(0, 3000),
    locked: Boolean(source?.locked ?? source?.readonly ?? source?.readOnly),
    inheritSettings: Boolean(source?.inheritSettings ?? source?.inherit_settings ?? true),
    sourcePriority: normalizeMobileDocumentTemplateAiSourcePriority(source?.sourcePriority ?? source?.source_priority),
    noSourceBehavior: normalizeMobileDocumentTemplateAiNoSourceBehavior(source?.noSourceBehavior ?? source?.no_source_behavior),
  };
}

function hasMobileMeasurementColumnAiMapping(input = {}) {
  const mapping = normalizeMobileMeasurementColumnAiMapping(input);
  return Boolean(
    mapping.description
    || mapping.key
    || mapping.label
    || mapping.synonyms.length
    || mapping.aiDescription
    || mapping.aiLookFor.length
    || mapping.allowedValues.length
    || mapping.commonValues.length
    || mapping.examples.length
    || mapping.avoid
    || mapping.aiAvoid
    || mapping.format !== "text"
    || mapping.type !== "text"
    || mapping.required
    || mapping.enabled
    || mapping.placeholder
    || mapping.helpText
    || mapping.unit
    || mapping.defaultValue
    || mapping.fallbackValue
    || mapping.validationRules
    || mapping.instructions
    || mapping.locked
    || mapping.displayOrder
    || mapping.group
  );
}

function getMobileDocumentTemplateDefaultAiTypeForField(field = {}) {
  const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
  if (fieldType === "dropdown") {
    return "enum";
  }
  if (fieldType === "date") {
    return "date";
  }
  if (fieldType === "number") {
    return "number";
  }
  if (fieldType === "checkbox" || fieldType === "toggle") {
    return "boolean";
  }
  if (fieldType === "measurement_table" || fieldType === "gridline") {
    return "list";
  }
  if (fieldType === "system_description") {
    return "system_description";
  }
  return "text";
}

function shouldMobileDocumentTemplateFieldUseDefaultAi(field = {}) {
  const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
  return [
    "system_description",
    "text",
    "longtext",
    "dropdown",
    "date",
    "number",
    "checkbox",
    "toggle",
    "measurement_table",
    "gridline",
  ].includes(fieldType);
}

function mergeMobileAiConfigList(sourceValue, defaultValue, maxItems = 160) {
  const sourceList = normalizeMobileAiConfigList(sourceValue, maxItems);
  return sourceList.length > 0 ? sourceList : normalizeMobileAiConfigList(defaultValue, maxItems);
}

function buildMobileDocumentTemplateDefaultAiFieldInput(field = {}, index = 0, aiSettings = {}) {
  const settings = normalizeDocumentTemplateAiSettings(aiSettings);
  const label = normalizeInputValue(field?.label || field?.wordLabel || `Polje ${index + 1}`) || `Polje ${index + 1}`;
  const key = getMobileDocumentTemplateFieldTokenKey(field, index);
  const lookFor = Array.from(new Set([
    label,
    field?.wordLabel,
    field?.placeholder,
    key,
  ].map((value) => normalizeInputValue(value)).filter(Boolean)));
  return {
    key,
    label,
    description: normalizeInputValue(field?.helpText),
    type: getMobileDocumentTemplateDefaultAiTypeForField(field),
    required: Boolean(field?.required || field?.isRequired),
    enabled: shouldMobileDocumentTemplateFieldUseDefaultAi(field),
    aiDescription: `Popuni polje "${label}" iz prethodnog zapisnika, starijeg prethodnog zapisnika, uploadanog izvora ili templatea.`,
    aiLookFor: lookFor,
    aiAvoid: settings.defaultAvoid || MOBILE_DOCUMENT_TEMPLATE_AI_DEFAULT_AVOID,
    confidenceRequired: settings.confidenceRequired || "medium",
    sourceTracking: true,
    inheritSettings: true,
    instructions: formatMobileDocumentTemplateAiInstruction(settings.fieldInstruction, { label }),
    sourcePriority: normalizeMobileDocumentTemplateAiSourcePriority(settings.sourcePriority),
    noSourceBehavior: normalizeMobileDocumentTemplateAiNoSourceBehavior(settings.noSourceBehavior),
  };
}

function getMobileDocumentTemplateFieldAiConfigForRuntime(field = {}, index = 0, aiSettings = {}) {
  const source = (field?.ai ?? field?.aiConfig) && typeof (field.ai ?? field.aiConfig) === "object"
    ? (field.ai ?? field.aiConfig)
    : {};
  if (!shouldMobileDocumentTemplateFieldUseDefaultAi(field) && !hasMobileDocumentTemplateFieldAiConfig(source, field)) {
    return normalizeMobileDocumentTemplateFieldAiConfig(source, field);
  }
  const defaults = buildMobileDocumentTemplateDefaultAiFieldInput(field, index, aiSettings);
  const inheritSettings = shouldMobileDocumentTemplateAiInheritSettings(source);
  return normalizeMobileDocumentTemplateFieldAiConfig({
    ...defaults,
    ...source,
    inheritSettings,
    enabled: source.enabled ?? source.aiEnabled ?? source.ai_enabled ?? defaults.enabled,
    aiDescription: source.aiDescription ?? source.ai_description ?? source.description ?? defaults.aiDescription,
    aiLookFor: mergeMobileAiConfigList(source.aiLookFor ?? source.ai_look_for, defaults.aiLookFor),
    aiAvoid: inheritSettings ? defaults.aiAvoid : (source.aiAvoid ?? source.ai_avoid ?? defaults.aiAvoid),
    confidenceRequired: inheritSettings ? defaults.confidenceRequired : (source.confidenceRequired ?? source.confidence_required ?? defaults.confidenceRequired),
    instructions: inheritSettings ? defaults.instructions : (source.instructions ?? source.aiInstructions ?? source.ai_instruction ?? defaults.instructions),
    sourcePriority: inheritSettings ? defaults.sourcePriority : (source.sourcePriority ?? source.source_priority ?? defaults.sourcePriority),
    noSourceBehavior: inheritSettings ? defaults.noSourceBehavior : (source.noSourceBehavior ?? source.no_source_behavior ?? defaults.noSourceBehavior),
  }, field);
}

function inferMobileMeasurementColumnAiType(column = {}) {
  const identity = normalizeInputValue([
    column?.label,
    column?.placeholder,
    column?.id,
  ].filter(Boolean).join(" ")).toLowerCase();
  if (/\b(datum|date|vrijedi)\b/.test(identity)) {
    return "date";
  }
  if (/\b(da\/ne|zadovoljava|ispravno|ok)\b/.test(identity)) {
    return "enum";
  }
  if (/[[(](a|ma|v|kv|ohm|Ω|ms|s|hz|kw|w|lux|mΩ)[\])]/i.test(identity)
    || /\b(broj|r\.br|rbr|otpor|struja|napon|vrijednost|isk|idn|tisk|u0)\b/i.test(identity)) {
    return "number";
  }
  return "text";
}

function buildMobileMeasurementColumnDefaultAiMappingInput(column = {}, columnIndex = 0, field = {}, aiSettings = {}) {
  const settings = normalizeDocumentTemplateAiSettings(aiSettings);
  const label = normalizeInputValue(column?.label || column?.placeholder || `Kolona ${columnIndex + 1}`) || `Kolona ${columnIndex + 1}`;
  const key = normalizeMobileDocumentTemplateFieldTokenKey(column?.id || label, `COLUMN_${columnIndex + 1}`);
  const lookFor = Array.from(new Set([
    label,
    column?.placeholder,
    column?.id,
    key,
    getMobileSpreadsheetColumnLabel(columnIndex),
  ].map((value) => normalizeInputValue(value)).filter(Boolean)));
  const inferredType = inferMobileMeasurementColumnAiType(column);
  const allowedValues = inferredType === "enum" ? ["DA", "NE", "ZADOVOLJAVA", "NE ZADOVOLJAVA"] : [];
  return {
    key,
    label,
    description: normalizeInputValue(field?.label || field?.wordLabel || "Gridline tablica"),
    instructions: formatMobileDocumentTemplateAiInstruction(settings.columnInstruction, {
      label,
      fieldLabel: normalizeInputValue(field?.label || field?.wordLabel || "Gridline tablica"),
    }),
    type: inferredType,
    format: inferredType,
    required: false,
    enabled: !column?.computed,
    aiDescription: `Vrijednost za gridline kolonu "${label}".`,
    aiLookFor: lookFor,
    synonyms: lookFor,
    allowedValues,
    aiAvoid: settings.defaultAvoid || MOBILE_DOCUMENT_TEMPLATE_AI_DEFAULT_AVOID,
    confidenceRequired: settings.confidenceRequired || "medium",
    sourceTracking: true,
    inheritSettings: true,
    sourcePriority: normalizeMobileDocumentTemplateAiSourcePriority(settings.sourcePriority),
    noSourceBehavior: normalizeMobileDocumentTemplateAiNoSourceBehavior(settings.noSourceBehavior),
  };
}

function getMobileMeasurementColumnAiMappingForRuntime(column = {}, columnIndex = 0, field = {}, aiSettings = {}) {
  const source = (column?.aiMapping ?? column?.ai) && typeof (column.aiMapping ?? column.ai) === "object"
    ? (column.aiMapping ?? column.ai)
    : {};
  const defaults = buildMobileMeasurementColumnDefaultAiMappingInput(column, columnIndex, field, aiSettings);
  const inheritSettings = shouldMobileDocumentTemplateAiInheritSettings(source);
  return normalizeMobileMeasurementColumnAiMapping({
    ...defaults,
    ...source,
    inheritSettings,
    enabled: source.enabled ?? source.aiEnabled ?? source.ai_enabled ?? defaults.enabled,
    aiDescription: source.aiDescription ?? source.ai_description ?? source.description ?? defaults.aiDescription,
    aiLookFor: mergeMobileAiConfigList(source.aiLookFor ?? source.ai_look_for ?? source.synonyms, defaults.aiLookFor),
    synonyms: mergeMobileAiConfigList(source.synonyms ?? source.aiLookFor ?? source.ai_look_for, defaults.synonyms, 80),
    allowedValues: mergeMobileAiConfigList(source.allowedValues ?? source.allowed_values, defaults.allowedValues),
    aiAvoid: inheritSettings ? defaults.aiAvoid : (source.aiAvoid ?? source.ai_avoid ?? source.avoid ?? defaults.aiAvoid),
    confidenceRequired: inheritSettings ? defaults.confidenceRequired : (source.confidenceRequired ?? source.confidence_required ?? defaults.confidenceRequired),
    instructions: inheritSettings ? defaults.instructions : (source.instructions ?? source.aiInstructions ?? source.ai_instructions ?? source.ai_instruction ?? defaults.instructions),
    sourcePriority: inheritSettings ? defaults.sourcePriority : (source.sourcePriority ?? source.source_priority ?? defaults.sourcePriority),
    noSourceBehavior: inheritSettings ? defaults.noSourceBehavior : (source.noSourceBehavior ?? source.no_source_behavior ?? defaults.noSourceBehavior),
  });
}

function getMobileSpreadsheetColumnLabel(index = 0) {
  let value = Number(index) + 1;
  let label = "";
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

function buildMobileDocumentTemplateAiFields(template = {}, aiSettings = {}) {
  return (Array.isArray(template?.customFields) ? template.customFields : [])
    .map((field, index) => {
      if (!field || typeof field !== "object" || Array.isArray(field)) {
        return null;
      }
      if (field.hidden === true || field.mobileHidden === true || field.excludeFromMobile === true) {
        return null;
      }
      const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
      const isSystemDescription = fieldType === "system_description";
      const config = getMobileDocumentTemplateFieldAiConfigForRuntime(field, index, aiSettings);
      if (!isSystemDescription && !hasMobileDocumentTemplateFieldAiConfig(config, field)) {
        return null;
      }
      const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
      const id = normalizeInputValue(field?.id || field?.key || tokenKey || `field-${index + 1}`);
      const key = normalizeInputValue(config.key || field?.key || tokenKey);
      const label = normalizeInputValue(config.label || field?.label || field?.wordLabel || key || `Polje ${index + 1}`);
      if (!id && !key) {
        return null;
      }
      const runtimeField = {
        id: id || key,
        key,
        label,
        type: isSystemDescription
          ? "system_description"
          : (fieldType === "measurement_table" || fieldType === "gridline" ? fieldType : (config.type || fieldType || "text")),
        fieldType,
        required: Boolean(config.required || field?.required || field?.isRequired),
        ai: config,
      };
      if (isSystemDescription) {
        runtimeField.valueShape = "system_description_blocks";
        runtimeField.sectionSubtitle = normalizeInputValue(field?.sectionSubtitle || field?.section_subtitle);
        runtimeField.systemRows = getMobileSystemDescriptionTemplateRows(field).map((row, rowIndex) => ({
          id: normalizeInputValue(row?.id) || `system-description-row-${rowIndex + 1}`,
          subtitle: normalizeInputValue(row?.subtitle),
          lineCount: normalizeMobileSystemDescriptionLineCount(row?.lineCount),
          placeholder: normalizeInputValue(row?.placeholder),
        }));
      }
      return runtimeField;
    })
    .filter(Boolean);
}

function buildMobileDocumentTemplateAiMeasurementColumns(template = {}, workOrder = {}, service = {}, scopedSnapshot = {}, common = {}, fieldSheets = {}, aiSettings = {}) {
  const columns = [];
  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field, fieldIndex) => {
    if (field?.hidden === true || field?.mobileHidden === true || field?.excludeFromMobile === true) {
      return;
    }
    if (normalizeInputValue(field?.type).toLowerCase() !== "measurement_table") {
      return;
    }
    const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, fieldIndex);
    const recordKey = normalizeInputValue(field?.key || field?.id || tokenKey);
    const sheet = normalizeWorkOrderMeasurementSheet(fieldSheets?.[recordKey])
      || resolveMobileDocumentTemplateFieldSheet(template, workOrder, service, scopedSnapshot, common, field, fieldIndex);
    if (!sheet?.columns?.length) {
      return;
    }
    const fieldAi = getMobileDocumentTemplateFieldAiConfigForRuntime(field, fieldIndex, aiSettings);
    sheet.columns
      .filter((column) => !column?.computed)
      .forEach((column, columnIndex) => {
        const aiMapping = getMobileMeasurementColumnAiMappingForRuntime(column, columnIndex, field, aiSettings);
        if (!hasMobileMeasurementColumnAiMapping(aiMapping)) {
          return;
        }
        columns.push({
          fieldId: normalizeInputValue(field?.id || recordKey || tokenKey),
          fieldKey: recordKey,
          fieldLabel: normalizeInputValue(field?.label || field?.wordLabel || recordKey || "Mjerenje"),
          fieldDescription: fieldAi.aiDescription || fieldAi.description || normalizeInputValue(field?.helpText),
          columnId: normalizeInputValue(column?.id || `measurement-column-${columnIndex + 1}`),
          columnIndex,
          columnLetter: getMobileSpreadsheetColumnLabel(columnIndex),
          key: aiMapping.key || normalizeInputValue(column?.id),
          label: aiMapping.label || normalizeInputValue(column?.label || column?.placeholder || column?.id || "Kolona"),
          type: aiMapping.type || aiMapping.format || "text",
          required: Boolean(aiMapping.required),
          placeholder: normalizeInputValue(column?.placeholder || aiMapping.placeholder),
          helpText: aiMapping.helpText || aiMapping.description || aiMapping.aiDescription || "",
          aiMapping,
        });
      });
  });
  return columns;
}

const MOBILE_DOCUMENT_TEMPLATE_FIELD_TYPE_LABELS = {
  chapter: "Poglavlje",
  system_description: "Opis sustava",
  page_break: "Nova A4 stranica",
  text: "Tekst",
  longtext: "Dugi tekst",
  dropdown: "Padajuci izbor",
  date: "Datum",
  number: "Broj",
  checkbox: "Checkbox",
  toggle: "Toggle",
  spr_voice: "Glasovni unos",
  qualified_inspectors: "Ispitivaci",
  sketch_upload: "Dodaj dokumente",
  image_upload: "Slika",
  legal_list: "Popis propisa",
  equipment_list: "Popis opreme",
  measurement_table: "Excel tablica",
  inspector_signature: "Potpis ispitivaca",
  authorization_holder_signature: "Potpis nositelja",
  digital_signature: "Digitalni potpis",
};

function getMobileDocumentTemplateFieldTypeLabel(type = "text") {
  const normalizedType = normalizeInputValue(type || "text").toLowerCase();
  return MOBILE_DOCUMENT_TEMPLATE_FIELD_TYPE_LABELS[normalizedType] || normalizedType || "Polje";
}

function getMobileDocumentTemplateFieldBlockGroup(type = "text") {
  const normalizedType = normalizeInputValue(type || "text").toLowerCase();
  if (MOBILE_DOCUMENT_TEMPLATE_PROMPT_FIELD_TYPES.has(normalizedType)) {
    return "Rucna polja";
  }
  if (normalizedType === "measurement_table") {
    return "Excel / mjerenja";
  }
  if (normalizedType === "equipment_list") {
    return "Mjerna i ispitna oprema";
  }
  if (normalizedType === "legal_list") {
    return "Propisi";
  }
  if (
    normalizedType === "qualified_inspectors"
    || normalizedType === "inspector_signature"
    || normalizedType === "authorization_holder_signature"
    || normalizedType === "digital_signature"
  ) {
    return "Osobe i potpisi";
  }
  if (normalizedType === "sketch_upload" || normalizedType === "image_upload") {
    return "Prilozi";
  }
  if (normalizedType === "system_description") {
    return "Opis sustava";
  }
  return "Struktura predloska";
}

function buildMobileDocumentTemplateFieldBlockSummary(field = {}, template = {}, scopedSnapshot = {}, common = {}, fieldSheets = {}) {
  const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
  const options = buildMobileDocumentTemplateFieldOptions(field);
  if (fieldType === "dropdown") {
    return options.length > 0
      ? `${options.length} opcija iz predloska`
      : "Padajuci izbor bez upisanih opcija";
  }
  if (fieldType === "measurement_table") {
    const recordKey = normalizeInputValue(field?.key || field?.id || getMobileDocumentTemplateFieldTokenKey(field, 0));
    const sheet = normalizeWorkOrderMeasurementSheet(fieldSheets?.[recordKey] || field?.sheet || field?.measurementSheet);
    return getMobileMeasurementSheetSummary(sheet);
  }
  if (fieldType === "legal_list") {
    const legalItems = getMobileDocumentTemplateLegalFrameworksForField(template, field, scopedSnapshot, common);
    return legalItems.length > 0 ? `${legalItems.length} propisa iz web predloska` : "Propisi se biraju u bloku Propisi";
  }
  if (fieldType === "equipment_list") {
    const equipmentItems = getMobileDocumentTemplateEquipmentItemsForField(template, field, scopedSnapshot, common);
    return equipmentItems.length > 0 ? `${equipmentItems.length} uredaja dostupno` : "Oprema se bira u bloku Mjerna i ispitna oprema";
  }
  if (fieldType === "system_description") {
    const rows = Array.isArray(field?.systemRows) ? field.systemRows : [];
    const sectionSubtitle = normalizeInputValue(field?.sectionSubtitle);
    return [sectionSubtitle, rows.length > 0 ? `${rows.length} redova opisa` : "Opis sustava iz predloska"]
      .filter(Boolean)
      .join(" | ");
  }
  if (fieldType === "qualified_inspectors") {
    return "Ispitivaci i nositelji ovlastenja popunjavaju se u bloku Osobe i potpis";
  }
  if (fieldType === "inspector_signature" || fieldType === "authorization_holder_signature" || fieldType === "digital_signature") {
    return "Potpisni blok iz web templatea";
  }
  if (fieldType === "sketch_upload") {
    return "Dokumenti i prilozi uz zapisnik";
  }
  if (fieldType === "image_upload") {
    return "Fotografije uz zapisnik";
  }
  if (fieldType === "chapter") {
    return normalizeInputValue(field?.sectionSubtitle || field?.defaultValue || field?.helpText) || "Naslovni blok";
  }
  if (fieldType === "page_break") {
    return "Prekid stranice iz web templatea";
  }
  const defaultValue = getMobileDocumentTemplateFieldDefaultValue(field);
  return defaultValue ? `Zadano: ${defaultValue}` : getMobileDocumentTemplateFieldTypeLabel(fieldType);
}

function buildMobileDocumentTemplateFieldBlocks(template = {}, workOrder = {}, service = {}, scopedSnapshot = {}, common = {}, fieldSheets = {}) {
  return (Array.isArray(template?.customFields) ? template.customFields : [])
    .map((field, index) => {
      if (!field || typeof field !== "object") {
        return null;
      }
      const fieldType = normalizeInputValue(field?.type || "text").toLowerCase();
      const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
      const id = normalizeInputValue(field?.id || field?.key || tokenKey || `field-${index + 1}`);
      const key = normalizeInputValue(field?.key);
      const label = normalizeInputValue(field?.label || field?.wordLabel || key || tokenKey || `Polje ${index + 1}`);
      if (!id || !label) {
        return null;
      }
      return {
        id,
        key,
        tokenKey,
        label,
        type: fieldType,
        typeLabel: getMobileDocumentTemplateFieldTypeLabel(fieldType),
        group: getMobileDocumentTemplateFieldBlockGroup(fieldType),
        required: Boolean(field?.required || field?.isRequired),
        editable: isMobileDocumentTemplatePromptField(field),
        helpText: normalizeInputValue(field?.helpText || field?.description || field?.hint),
        summary: buildMobileDocumentTemplateFieldBlockSummary(field, template, scopedSnapshot, common, fieldSheets),
        options: buildMobileDocumentTemplateFieldOptions(field),
        ...getMobileDocumentTemplateSignatureFieldConfig(field),
      };
    })
    .filter(Boolean);
}

function buildMobileDocumentTemplateInspectionTypeOptions(template = {}) {
  return (Array.isArray(template?.customFields) ? template.customFields : [])
    .flatMap((field, index) => {
      if (!isMobileInspectionTypeTemplateField(field, index)) {
        return [];
      }
      const options = buildMobileDocumentTemplateFieldOptions(field);
      if (options.length > 0) {
        return options;
      }
      const defaultValue = getMobileDocumentTemplateFieldDefaultValue(field);
      return defaultValue ? [{ value: defaultValue, label: defaultValue }] : [];
    })
    .filter((option) => normalizeInputValue(option?.value || option?.label))
    .filter((option, index, items) => {
      const value = normalizeInputValue(option?.value || option?.label).toLowerCase();
      return items.findIndex((item) => normalizeInputValue(item?.value || item?.label).toLowerCase() === value) === index;
    });
}

function getMobileMeasurementSheetSummary(sheet = null) {
  const normalized = normalizeWorkOrderMeasurementSheet(sheet);
  if (!normalized?.columns?.length) {
    return "Prazna Excel tablica";
  }
  const populatedRows = normalized.rows.filter((row) => (
    normalized.columns
      .filter((column) => !column.computed)
      .some((column) => normalizeInputValue(row?.cells?.[column.id]))
  )).length;
  return [
    `${normalized.columns.length} kolona`,
    populatedRows > 0 ? `${populatedRows} popunjenih redova` : "spremno za unos",
  ].join(" · ");
}

const MOBILE_NATIVE_MEASUREMENT_SERVICE_CODES = new Set(
  getDocumentationNativeTemplateSeedPresets()
    .map((preset) => normalizeInputValue(preset?.serviceCode).toUpperCase())
    .filter(Boolean),
);

function normalizeMobileNativeMeasurementServiceCode(value = "") {
  const code = normalizeInputValue(value).toUpperCase();
  return MOBILE_NATIVE_MEASUREMENT_SERVICE_CODES.has(code) ? code : "";
}

function getMobileMeasurementTableIdentity(table = {}) {
  return normalizeInputValue(table?.key || table?.id || table?.tokenKey || table?.label).toLowerCase();
}

function mobileMeasurementTableLooksLikeOtherNativeService(table = {}, serviceCode = "") {
  const identity = getMobileMeasurementTableIdentity(table);
  const ownCode = normalizeMobileNativeMeasurementServiceCode(serviceCode);
  if (!identity || !ownCode) {
    return false;
  }
  const prefixesByCode = Object.fromEntries(
    [...MOBILE_NATIVE_MEASUREMENT_SERVICE_CODES].map((code) => [code, [`${code.toLowerCase()}-`]]),
  );
  return Object.entries(prefixesByCode).some(([code, prefixes]) => (
    code !== ownCode && prefixes.some((prefix) => identity.startsWith(prefix))
  ));
}

function getMobileDefaultMeasurementTablesForNativeService(service = {}, template = {}) {
  const serviceCode = normalizeMobileNativeMeasurementServiceCode(
    getMobileDocumentTemplateServiceCode(service, Number(template?.serviceIndex) || 0)
      || template?.serviceCode,
  );
  return {
    serviceCode,
    tables: serviceCode ? createDocumentationMeasurementTablesForService(serviceCode) : [],
  };
}

function buildMobileDocumentTemplateMeasurementTables(template = {}, workOrder = {}, service = {}, scopedSnapshot = {}, common = {}) {
  const generatedTables = (Array.isArray(template?.customFields) ? template.customFields : [])
    .map((field, index) => {
      if (normalizeInputValue(field?.type).toLowerCase() !== "measurement_table") {
        return null;
      }
      const tokenKey = getMobileDocumentTemplateFieldTokenKey(field, index);
      const recordKey = normalizeInputValue(field?.key || field?.id || tokenKey);
      const sheet = resolveMobileDocumentTemplateFieldSheet(template, workOrder, service, scopedSnapshot, common, field, index);
      if (!recordKey || !sheet) {
        return null;
      }
      return {
        id: normalizeInputValue(field?.id || recordKey),
        key: recordKey,
        tokenKey,
        label: normalizeInputValue(field?.label || field?.wordLabel || recordKey) || "Excel tablica",
        helpText: normalizeInputValue(field?.helpText || field?.description || field?.hint),
        summary: getMobileMeasurementSheetSummary(sheet),
        sourceSheet: normalizeInputValue(field?.sourceSheet || field?.sheetName || field?.measurementTable?.sourceSheet),
        includeInReport: field?.includeInReport !== false,
        formulaOnly: field?.formulaOnly === true,
        sheet,
      };
    })
    .filter(Boolean);
  const nativeDefaults = getMobileDefaultMeasurementTablesForNativeService(service, template);
  if (!nativeDefaults.tables.length) {
    return generatedTables;
  }
  if (!generatedTables.length) {
    return nativeDefaults.tables;
  }
  if (generatedTables.some((table) => mobileMeasurementTableLooksLikeOtherNativeService(table, nativeDefaults.serviceCode))) {
    return nativeDefaults.tables;
  }
  return generatedTables;
}

function getMobileWorkOrderLocationObjectId(workOrder = {}) {
  const locationObject = workOrder?.locationObject && typeof workOrder.locationObject === "object" && !Array.isArray(workOrder.locationObject)
    ? workOrder.locationObject
    : {};
  const object = workOrder?.object && typeof workOrder.object === "object" && !Array.isArray(workOrder.object)
    ? workOrder.object
    : {};
  return normalizeInputValue(
    workOrder?.objectId
    || workOrder?.locationObjectId
    || workOrder?.selectedObjectId
    || locationObject?.id
    || locationObject?.objectId
    || object?.id,
  );
}

function getMobileWorkOrderLocationObjectName(workOrder = {}) {
  const locationObject = workOrder?.locationObject && typeof workOrder.locationObject === "object" && !Array.isArray(workOrder.locationObject)
    ? workOrder.locationObject
    : {};
  const object = workOrder?.object && typeof workOrder.object === "object" && !Array.isArray(workOrder.object)
    ? workOrder.object
    : {};
  return normalizeInputValue(
    workOrder?.objectName
    || workOrder?.locationObjectName
    || locationObject?.name
    || locationObject?.objectName
    || object?.name,
  );
}

function applyMobileSelectedObjectToWorkOrder(workOrder = {}, scopedSnapshot = {}, source = {}) {
  const normalizedSource = source?.common && typeof source.common === "object" && !Array.isArray(source.common)
    ? source.common
    : (source && typeof source === "object" && !Array.isArray(source) ? source : {});
  const requestedObjectId = normalizeInputValue(
    normalizedSource.objectId
    || normalizedSource.locationObjectId
    || normalizedSource.selectedObjectId,
  );
  const executors = normalizeMobileDocumentWizardArray(normalizedSource.executors);
  let nextWorkOrder = workOrder;

  if (requestedObjectId) {
    const locationObject = assertLocationObjectPayloadInScope(scopedSnapshot, {
      companyId: workOrder.companyId,
      locationId: workOrder.locationId,
      objectId: requestedObjectId,
    });

    nextWorkOrder = {
      ...nextWorkOrder,
      objectId: normalizeInputValue(locationObject?.id || requestedObjectId),
      locationObjectId: normalizeInputValue(locationObject?.id || requestedObjectId),
      objectName: normalizeInputValue(locationObject?.name || normalizedSource.objectName),
      locationObjectName: normalizeInputValue(locationObject?.name || normalizedSource.objectName),
      locationObject,
    };
  }

  if (executors.length > 0) {
    nextWorkOrder = {
      ...nextWorkOrder,
      executors,
      executor1: executors[0] || "",
      executor2: executors[1] || "",
    };
  }

  return nextWorkOrder;
}

function getMobileDocumentRecordTemplateScore(record = {}, template = {}) {
  const templateId = normalizeInputValue(template?.id);
  const recordTemplateId = normalizeInputValue(record?.templateId);
  if (templateId && recordTemplateId === templateId) {
    return 100;
  }
  const templateNativeCode = getMobileTemplateNativeDocumentationServiceCode(template);
  const recordNativeCode = getMobileDocumentRecordNativeDocumentationServiceCode(record);
  if (templateNativeCode && recordNativeCode && templateNativeCode === recordNativeCode) {
    return 90;
  }

  const genericKeys = new Set(["zapisnik", "izvjestaj", "izvještaj", "document", "template"]);
  const templateKeys = [
    template?.title,
    template?.documentType,
  ]
    .map(normalizeMobileTemplateLookupKey)
    .filter((value) => value && !genericKeys.has(value));
  if (templateKeys.length === 0) {
    return 0;
  }

  const recordKeys = [
    record?.templateTitle,
    record?.documentType,
    record?.title,
    record?.documentTitle,
  ]
    .map(normalizeMobileTemplateLookupKey)
    .filter(Boolean);

  return templateKeys.some((key) => recordKeys.includes(key)) ? 60 : 0;
}

function inferMobileNativeDocumentationServiceCode(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  if (!lookup) {
    return "";
  }
  const compactLookup = lookup.replace(/\s+/gu, "");
  const directCode = [...MOBILE_NATIVE_MEASUREMENT_SERVICE_CODES]
    .sort((left, right) => right.length - left.length)
    .find((code) => {
      const normalizedCode = normalizeMobileSprLookupText(code);
      return compactLookup === normalizedCode
        || lookup === normalizedCode
        || lookup.startsWith(`${normalizedCode} `)
        || lookup.includes(` ${normalizedCode} `)
        || lookup.endsWith(` ${normalizedCode}`);
    });
  if (directCode) {
    return directCode;
  }
  const semanticMatch = MOBILE_NATIVE_DOCUMENTATION_SEMANTIC_MATCHERS.find((matcher) => matcher.matches(lookup));
  if (semanticMatch?.code) {
    return semanticMatch.code;
  }
  if (/\bstrojevi\b/u.test(lookup) || lookup.includes("nadzor opreme") || lookup.includes("nadzor strojeva")) {
    return "STROJEVI";
  }
  if (/\bno\b/u.test(lookup)) {
    return "NO";
  }
  if (/\btzin\b/u.test(lookup) || lookup.includes("tipkalo") || lookup.includes("isklop elektric")) {
    return "TZIN";
  }
  if (/\bszomv\b/u.test(lookup) || (lookup.includes("vizual") && lookup.includes("munj"))) {
    return "SZOMV";
  }
  if (
    /\bszom\b/u.test(lookup)
    || lookup.includes("zastitu od djelovanja munje")
    || lookup.includes("zastite od djelovanja munje")
  ) {
    return "SZOM";
  }
  if (/\bspr\b/u.test(lookup) || lookup.includes("panik rasvjet") || lookup.includes("sigurnosna rasvjet")) {
    return "SPR";
  }
  if (/\bsvz\b/u.test(lookup) || (lookup.includes("dojav") && lookup.includes("pozar")) || lookup.includes("vatrodojav")) {
    return "SVZ";
  }
  if (/\beiz\b/u.test(lookup) || lookup.includes("elektricn")) {
    return "EIZ";
  }
  if (/\bves\b/u.test(lookup) || lookup.includes("evakuacij")) {
    return "VES";
  }
  return "";
}

function inferMobileNativeDocumentationServiceCodeFromExplicitToken(value = "") {
  const directCode = normalizeMobileNativeMeasurementServiceCode(value);
  if (directCode) {
    return directCode;
  }
  const lookup = normalizeMobileSprLookupText(value);
  if (!lookup) {
    return "";
  }
  const tokens = lookup.split(/\s+/u).filter(Boolean);
  return [...MOBILE_NATIVE_MEASUREMENT_SERVICE_CODES]
    .sort((left, right) => right.length - left.length)
    .find((code) => {
      const normalizedCode = normalizeMobileSprLookupText(code);
      if (!normalizedCode) {
        return false;
      }
      return tokens.some((token) => (
        token === normalizedCode
        || (token.startsWith(normalizedCode) && /^\d+(?:\d*)$/u.test(token.slice(normalizedCode.length)))
      ));
    }) || "";
}

function getMobileDocumentRecordNativeDocumentationServiceCode(record = {}) {
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  const directCode = normalizeMobileNativeMeasurementServiceCode(
    record?.serviceCode
    || record?.code
    || fieldValues.SERVICE_CODE
    || fieldValues.SIFRA_USLUGE
    || "",
  );
  if (directCode) {
    return directCode;
  }
  return inferMobileNativeDocumentationServiceCodeFromExplicitToken([
    record?.serviceName,
    record?.templateTitle,
    record?.documentType,
    record?.documentTitle,
    record?.documentName,
    record?.title,
    record?.fileName,
    fieldValues.SERVICE_SUMMARY,
    fieldValues.USLUGA,
    fieldValues.NAZIV_USLUGE,
    fieldValues.INSPECTION_TYPE,
    fieldValues.VRSTA_ISPITIVANJA,
  ].filter(Boolean).join(" "));
}

function getMobileDocumentRecordTitleNativeDocumentationServiceCode(record = {}) {
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  return inferMobileNativeDocumentationServiceCodeFromExplicitToken([
    record?.templateTitle,
    record?.documentType,
    record?.documentTitle,
    record?.documentName,
    record?.title,
    record?.fileName,
    fieldValues.INSPECTION_TYPE,
    fieldValues.VRSTA_ISPITIVANJA,
  ].filter(Boolean).join(" "));
}

function getMobileTemplateNativeDocumentationServiceCode(template = {}) {
  const directCode = normalizeMobileNativeMeasurementServiceCode(template?.serviceCode || template?.code || "");
  if (directCode) {
    return directCode;
  }
  return inferMobileNativeDocumentationServiceCodeFromExplicitToken([
    template?.serviceName,
    template?.documentType,
    template?.title,
    template?.documentName,
    template?.dataSourceTitle,
  ].filter(Boolean).join(" "));
}

function getMobileTemplateNativeDocumentationServiceCodes(template = {}) {
  const codes = new Set();
  [
    template?.serviceCode,
    template?.code,
    template?.serviceBinding?.serviceCode,
    template?.model?.serviceCode,
    template?.model?.serviceBinding?.serviceCode,
  ].forEach((value) => {
    const code = normalizeMobileNativeMeasurementServiceCode(value);
    if (code) {
      codes.add(code);
    }
  });
  [
    template?.serviceName,
    template?.documentType,
    template?.title,
    template?.documentName,
    template?.dataSourceTitle,
    template?.model?.serviceName,
    template?.model?.templateCode,
    template?.model?.reportTitle,
    template?.model?.coverSubtitle,
  ].forEach((value) => {
    const code = inferMobileNativeDocumentationServiceCodeFromExplicitToken(value);
    if (code) {
      codes.add(code);
    }
  });
  return codes;
}

function mobileDocumentTemplateMatchesNativeServiceCode(template = {}, serviceCode = "") {
  const normalizedServiceCode = normalizeMobileNativeMeasurementServiceCode(serviceCode);
  if (!normalizedServiceCode) {
    return true;
  }
  return getMobileTemplateNativeDocumentationServiceCodes(template).has(normalizedServiceCode);
}

function mobileDocumentRecordMatchesTemplateService(record = {}, template = {}) {
  const templateNativeCode = getMobileTemplateNativeDocumentationServiceCode(template);
  if (!templateNativeCode) {
    return true;
  }
  const recordTitleNativeCode = getMobileDocumentRecordTitleNativeDocumentationServiceCode(record);
  if (recordTitleNativeCode && recordTitleNativeCode !== templateNativeCode) {
    return false;
  }
  const recordNativeCode = getMobileDocumentRecordNativeDocumentationServiceCode(record);
  if (recordNativeCode) {
    return recordNativeCode === templateNativeCode;
  }
  const templateId = normalizeInputValue(template?.id);
  const recordTemplateId = normalizeInputValue(record?.templateId);
  return Boolean(templateId && recordTemplateId && templateId === recordTemplateId);
}

function getMobileDocumentRecordObjectScore(record = {}, workOrder = {}) {
  const objectId = getMobileWorkOrderLocationObjectId(workOrder);
  const objectName = normalizeMobileTemplateLookupKey(getMobileWorkOrderLocationObjectName(workOrder));
  const recordObjectId = normalizeInputValue(record?.objectId || record?.locationObjectId);
  const recordObjectName = normalizeMobileTemplateLookupKey(record?.objectName || record?.locationObjectName);

  if (objectId) {
    if (recordObjectId) {
      return recordObjectId === objectId ? 100 : 0;
    }
    return objectName && recordObjectName && recordObjectName === objectName ? 80 : 0;
  }

  if (objectName && recordObjectName) {
    return recordObjectName === objectName ? 80 : 0;
  }

  return !recordObjectId && !recordObjectName ? 60 : 0;
}

function getMobileDocumentRecordSortKey(record = {}) {
  return String(record?.updatedAt || record?.inspectionDate || record?.issuedDate || record?.createdAt || "");
}

function findLatestMobileDocumentRecordForTemplate(template = {}, workOrder = {}, scopedSnapshot = {}) {
  const companyId = normalizeInputValue(workOrder?.companyId);
  const locationId = normalizeInputValue(workOrder?.locationId);
  if (!locationId) {
    return null;
  }
  const records = Array.isArray(scopedSnapshot.documentRecords) ? scopedSnapshot.documentRecords : [];
  return records
    .map((record) => ({
      record,
      templateScore: getMobileDocumentRecordTemplateScore(record, template),
      objectScore: getMobileDocumentRecordObjectScore(record, workOrder),
      draftScore: mobileDocumentationDraftMatchesWorkOrder(record, workOrder) ? 1000 : 0,
    }))
    .filter((candidate) => {
      const record = candidate.record;
      return candidate.templateScore > 0
        && candidate.objectScore > 0
        && mobileDocumentRecordMatchesTemplateService(record, template)
        && (!companyId || normalizeInputValue(record?.companyId) === companyId)
        && normalizeInputValue(record?.locationId) === locationId;
    })
    .sort((left, right) => (
      right.draftScore - left.draftScore
      || right.templateScore - left.templateScore
      || right.objectScore - left.objectScore
      || getMobileDocumentRecordSortKey(right.record).localeCompare(getMobileDocumentRecordSortKey(left.record))
    ))
    [0]?.record || null;
}

function getMobileDocumentRecordFieldValue(record = {}, keys = []) {
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  return normalizeInputValue(getGeneratedDocumentRecordValue(fieldValues, keys));
}

function getMobileDocumentRecordArrayValue(record = {}, keys = []) {
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  const normalizedKeys = keys.map((key) => normalizeLookupKey(key)).filter(Boolean);
  const candidates = [];

  keys.forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(fieldValues, key)) {
      candidates.push(fieldValues[key]);
    }
  });

  Object.entries(fieldValues).forEach(([key, value]) => {
    if (normalizedKeys.includes(normalizeLookupKey(key))) {
      candidates.push(value);
    }
  });

  for (const value of candidates) {
    const normalized = normalizeMobileDocumentWizardArray(value);
    if (normalized.length > 0) {
      return normalized;
    }
  }

  return [];
}

function buildMobileDocumentRecordWizardDefaults(record = null, workOrder = {}) {
  if (!record) {
    return {};
  }
  const fieldValues = record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
  const savedAttachments = normalizeMobileDocumentationAttachments(
    fieldValues[MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY]
      || record?.attachments
      || record?.documentAttachments
      || [],
  );
  const savedTemplateAttachments = normalizeMobileDocumentationTemplateAttachments(
    fieldValues[MOBILE_DOCUMENTATION_RECORD_TEMPLATE_ATTACHMENTS_KEY],
  );
  const normalizedRecordTemplateId = normalizeInputValue(record?.templateId);
  if (normalizedRecordTemplateId && savedAttachments.length > 0 && !savedTemplateAttachments[normalizedRecordTemplateId]) {
    savedTemplateAttachments[normalizedRecordTemplateId] = savedAttachments;
  }
  const {
    [MOBILE_DOCUMENTATION_RECORD_ATTACHMENTS_KEY]: _savedDocumentationAttachments,
    [MOBILE_DOCUMENTATION_RECORD_TEMPLATE_ATTACHMENTS_KEY]: _savedDocumentationTemplateAttachments,
    ...rawFieldValuesForDefaults
  } = fieldValues;
  const fieldValuesForDefaults = stripMobileDocumentationDraftFields(rawFieldValuesForDefaults);
  const fieldSheets = record?.fieldSheets && typeof record.fieldSheets === "object" && !Array.isArray(record.fieldSheets)
    ? record.fieldSheets
    : {};
  const inspectionDate = normalizeDateOnlyValue(
    record.inspectionDate
    || getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_INSPECTION_DATE", "DATUM_ISPITIVANJA", "INSPECTION_DATE"]),
  );
  const issuedDate = normalizeDateOnlyValue(
    record.issuedDate
    || getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_ISSUED_DATE", "DATUM_IZDAVANJA", "ISSUED_DATE"]),
  );
  const testingLocation = getMobileDocumentRecordFieldValue(record, [
    "WORK_ORDER_TESTING_LOCATION",
    "TESTING_LOCATION",
    "WORK_ORDER_INSPECTION_LOCATION",
    "INSPECTION_LOCATION",
    "MJESTO_ISPITIVANJA",
    "LOKACIJA_ISPITIVANJA",
    "MJESTO_PREGLEDA",
    "LOCATION_NAME",
    "LOKACIJA",
  ]);

  return {
    inspectionDate,
    issuedDate,
    issuedPlace: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_ISSUED_PLACE", "MJESTO_IZDAVANJA"]),
    testingLocation: testingLocation || resolveMobileWorkOrderTestingLocation(workOrder, {}),
    note: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_DOCUMENT_NOTE", "NAPOMENA_ZAPISNIKA"]),
    inspectionType: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_INSPECTION_TYPE", "INSPECTION_TYPE", "VRSTA_ISPITIVANJA"]),
    outsideTemperature: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_OUTSIDE_TEMPERATURE", "TEMPERATURA", "VANJSKA_TEMPERATURA"]),
    relativeHumidity: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_RELATIVE_HUMIDITY", "VLAGA", "RELATIVNA_VLAZNOST"]),
    airflowSpeed: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_AIRFLOW_SPEED", "STRUJANJE_ZRAKA"]),
    weather: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_WEATHER", "VRIJEME"]),
    groundCondition: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_GROUND_CONDITION", "STANJE_TLA"]),
    groundResistance: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_GROUND_RESISTANCE", "OTPOR_TLA"]),
    measurementEquipmentGroup: getMobileDocumentRecordFieldValue(record, ["MEASUREMENT_EQUIPMENT_GROUP", "MJERNA_OPREMA_GRUPA"]),
    selectedEquipmentIds: getMobileDocumentRecordArrayValue(record, ["MEASUREMENT_EQUIPMENT_IDS", "MJERNA_OPREMA_IDS", "selectedEquipmentIds"]),
    selectedLegalFrameworkIds: getMobileDocumentRecordArrayValue(record, ["LEGAL_FRAMEWORK_IDS", "PROPISI_IDS", "selectedLegalFrameworkIds"]),
    signatureMode: normalizeMobileDocumentSignatureMode(getMobileDocumentRecordFieldValue(record, ["SIGNATURE_MODE", "NACIN_POTPISA"])),
    validityMonths: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_VALIDITY_MONTHS", "WORK_ORDER_SERVICE_VALIDITY_MONTHS", "VRIJEDI_MJESECI"]),
    electricalValidityMonths: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_PANIC_VALIDITY_MONTHS"]),
    tipkaloValidityMonths: getMobileDocumentRecordFieldValue(record, ["WORK_ORDER_TIPKALO_VALIDITY_MONTHS"]),
    fieldValues: fieldValuesForDefaults,
    fieldSheets,
    attachments: savedAttachments,
    templateAttachments: savedTemplateAttachments,
  };
}

function getMobileDocumentRecordSourceDate(record = {}) {
  return normalizeDateOnlyValue(
    record?.inspectionDate
    || record?.issuedDate
    || record?.validUntil
    || record?.expirationDate
    || record?.updatedAt
    || record?.createdAt,
  );
}

function buildMobileDocumentTemplateDataSource(template = {}, latestRecord = null) {
  const templateTitle = normalizeInputValue(template?.title || template?.documentType || "Zapisnik") || "Zapisnik";
  if (latestRecord) {
    return {
      dataSourceType: "previous_inspection",
      dataSourceTitle: normalizeInputValue(
        latestRecord.templateTitle
        || latestRecord.documentTitle
        || latestRecord.title
        || templateTitle,
      ) || templateTitle,
      dataSourceDate: getMobileDocumentRecordSourceDate(latestRecord),
      dataSourceWorkOrderNumber: normalizeInputValue(latestRecord.workOrderNumber || latestRecord.recordNumber),
    };
  }

  return {
    dataSourceType: "template",
    dataSourceTitle: templateTitle,
    dataSourceDate: "",
    dataSourceWorkOrderNumber: "",
  };
}

function isMobileDocumentationObject(value) {
  return value && typeof value === "object" && !Array.isArray(value);
}

function mobileDocumentationObjectEntries(value) {
  return isMobileDocumentationObject(value) ? Object.entries(value) : [];
}

function hasMobileDocumentWizardDefaults(defaults = {}) {
  if (!isMobileDocumentationObject(defaults)) {
    return false;
  }

  const scalarKeys = [
    "inspectionDate",
    "issuedDate",
    "issuedPlace",
    "testingLocation",
    "note",
    "inspectionType",
    "completedBy",
    "outsideTemperature",
    "relativeHumidity",
    "airflowSpeed",
    "weather",
    "groundCondition",
    "groundResistance",
    "measurementEquipmentGroup",
    "signatureMode",
    "validityMonths",
    "electricalValidityMonths",
    "tipkaloValidityMonths",
  ];
  if (scalarKeys.some((key) => normalizeInputValue(defaults[key]))) {
    return true;
  }

  const arrayKeys = [
    "selectedEquipmentIds",
    "selectedLegalFrameworkIds",
    "selectedRulebookIds",
    "executors",
    "inspectorUserIds",
    "electricalInspectorUserIds",
    "tipkaloInspectorUserIds",
    "attachments",
    "includedMeasurementTableKeys",
  ];
  if (arrayKeys.some((key) => Array.isArray(defaults[key]) && defaults[key].length > 0)) {
    return true;
  }

  return [
    "fieldValues",
    "templateFieldValues",
    "fieldSheets",
    "templateFieldSheets",
    "serviceValidityMonths",
    "templateAttachments",
  ].some((key) => mobileDocumentationObjectEntries(defaults[key]).length > 0);
}

function mergeMobileDocumentationObject(target = {}, source = {}) {
  return {
    ...(isMobileDocumentationObject(target) ? target : {}),
    ...(isMobileDocumentationObject(source) ? source : {}),
  };
}

function mergeMobileDocumentWizardDefaultsForTemplate(currentDefaults = null, recordDefaults = {}, template = {}) {
  if (!hasMobileDocumentWizardDefaults(recordDefaults)) {
    return currentDefaults;
  }

  const next = isMobileDocumentationObject(currentDefaults) ? { ...currentDefaults } : {};
  const templateId = normalizeInputValue(template?.id);
  const scalarKeys = [
    "inspectionDate",
    "issuedDate",
    "issuedPlace",
    "testingLocation",
    "note",
    "inspectionType",
    "completedBy",
    "outsideTemperature",
    "relativeHumidity",
    "airflowSpeed",
    "weather",
    "groundCondition",
    "groundResistance",
    "measurementEquipmentGroup",
    "signatureMode",
    "validityMonths",
    "electricalValidityMonths",
    "tipkaloValidityMonths",
    "inspectorUserId",
    "authorizationHolderUserId",
    "electricalInspectorUserId",
    "electricalAuthorizationHolderUserId",
    "tipkaloInspectorUserId",
    "tipkaloAuthorizationHolderUserId",
  ];

  scalarKeys.forEach((key) => {
    if (!normalizeInputValue(next[key]) && normalizeInputValue(recordDefaults[key])) {
      next[key] = recordDefaults[key];
    }
  });

  [
    "selectedEquipmentIds",
    "selectedLegalFrameworkIds",
    "selectedRulebookIds",
    "executors",
    "inspectorUserIds",
    "electricalInspectorUserIds",
    "tipkaloInspectorUserIds",
  ].forEach((key) => {
    if ((!Array.isArray(next[key]) || next[key].length === 0) && Array.isArray(recordDefaults[key]) && recordDefaults[key].length > 0) {
      next[key] = [...recordDefaults[key]];
    }
  });

  if (Array.isArray(recordDefaults.attachments) && recordDefaults.attachments.length > 0) {
    if (templateId) {
      next.templateAttachments = mergeMobileDocumentationObject(next.templateAttachments);
      if (!Array.isArray(next.templateAttachments[templateId]) || next.templateAttachments[templateId].length === 0) {
        next.templateAttachments[templateId] = [...recordDefaults.attachments];
      }
    } else if (!Array.isArray(next.attachments) || next.attachments.length === 0) {
      next.attachments = [...recordDefaults.attachments];
    }
  }

  mobileDocumentationObjectEntries(recordDefaults.templateAttachments).forEach(([sourceTemplateId, attachments]) => {
    const normalizedTemplateId = normalizeInputValue(sourceTemplateId);
    const normalizedAttachments = normalizeMobileDocumentationAttachments(attachments);
    if (!normalizedTemplateId || normalizedAttachments.length === 0) {
      return;
    }
    next.templateAttachments = mergeMobileDocumentationObject(next.templateAttachments);
    if (!Array.isArray(next.templateAttachments[normalizedTemplateId]) || next.templateAttachments[normalizedTemplateId].length === 0) {
      next.templateAttachments[normalizedTemplateId] = normalizedAttachments;
    }
  });

  next.serviceValidityMonths = mergeMobileDocumentationObject(next.serviceValidityMonths, recordDefaults.serviceValidityMonths);

  const fieldValues = isMobileDocumentationObject(recordDefaults.fieldValues) ? recordDefaults.fieldValues : {};
  if (mobileDocumentationObjectEntries(fieldValues).length > 0) {
    if (!isMobileDocumentationObject(next.fieldValues) || mobileDocumentationObjectEntries(next.fieldValues).length === 0) {
      next.fieldValues = { ...fieldValues };
    }
    if (templateId) {
      next.templateFieldValues = mergeMobileDocumentationObject(next.templateFieldValues);
      next.templateFieldValues[templateId] = mergeMobileDocumentationObject(next.templateFieldValues[templateId], fieldValues);
    }
  }

  mobileDocumentationObjectEntries(recordDefaults.templateFieldValues).forEach(([sourceTemplateId, values]) => {
    const normalizedTemplateId = normalizeInputValue(sourceTemplateId);
    if (!normalizedTemplateId || !isMobileDocumentationObject(values)) {
      return;
    }
    next.templateFieldValues = mergeMobileDocumentationObject(next.templateFieldValues);
    next.templateFieldValues[normalizedTemplateId] = mergeMobileDocumentationObject(next.templateFieldValues[normalizedTemplateId], values);
  });

  const fieldSheets = isMobileDocumentationObject(recordDefaults.fieldSheets) ? recordDefaults.fieldSheets : {};
  if (mobileDocumentationObjectEntries(fieldSheets).length > 0) {
    if (!isMobileDocumentationObject(next.fieldSheets) || mobileDocumentationObjectEntries(next.fieldSheets).length === 0) {
      next.fieldSheets = { ...fieldSheets };
    }
    if (templateId) {
      next.templateFieldSheets = mergeMobileDocumentationObject(next.templateFieldSheets);
      next.templateFieldSheets[templateId] = mergeMobileDocumentationObject(next.templateFieldSheets[templateId], fieldSheets);
    }
  }

  mobileDocumentationObjectEntries(recordDefaults.templateFieldSheets).forEach(([sourceTemplateId, sheets]) => {
    const normalizedTemplateId = normalizeInputValue(sourceTemplateId);
    if (!normalizedTemplateId || !isMobileDocumentationObject(sheets)) {
      return;
    }
    next.templateFieldSheets = mergeMobileDocumentationObject(next.templateFieldSheets);
    next.templateFieldSheets[normalizedTemplateId] = mergeMobileDocumentationObject(next.templateFieldSheets[normalizedTemplateId], sheets);
  });

  if (Array.isArray(recordDefaults.includedMeasurementTableKeys) && recordDefaults.includedMeasurementTableKeys.length > 0) {
    next.includedMeasurementTableKeys = Array.from(new Set([
      ...(Array.isArray(next.includedMeasurementTableKeys) ? next.includedMeasurementTableKeys : []),
      ...recordDefaults.includedMeasurementTableKeys,
    ].map(normalizeInputValue).filter(Boolean)));
  }

  return next;
}

function mergeMobileDocumentContextRecords(scopedSnapshot = {}, freshRecords = []) {
  const existingRecords = Array.isArray(scopedSnapshot.documentRecords) ? scopedSnapshot.documentRecords : [];
  const mergedRecords = [];
  const seenKeys = new Set();

  [...(Array.isArray(freshRecords) ? freshRecords : []), ...existingRecords].forEach((record) => {
    if (!record || typeof record !== "object" || Array.isArray(record)) {
      return;
    }
    const key = normalizeInputValue(record.id)
      || [
        record.templateId,
        record.companyId,
        record.locationId,
        record.objectId,
        record.objectName,
        record.inspectionDate,
        record.issuedDate,
        record.createdAt,
      ].map(normalizeInputValue).join("::");
    if (!key || seenKeys.has(key)) {
      return;
    }
    seenKeys.add(key);
    mergedRecords.push(record);
  });

  return {
    ...scopedSnapshot,
    documentRecords: mergedRecords,
  };
}

async function buildMobileDocumentationContextSnapshot(workOrder = {}, scopedSnapshot = {}) {
  if (typeof domainRepository.listDocumentRecords !== "function") {
    return scopedSnapshot;
  }

  const organizationId = normalizeInputValue(scopedSnapshot.activeOrganizationId || workOrder.organizationId);
  const companyId = normalizeInputValue(workOrder.companyId);
  const locationId = normalizeInputValue(workOrder.locationId);
  if (!organizationId || !companyId || !locationId) {
    return scopedSnapshot;
  }

  try {
    const freshRecords = await domainRepository.listDocumentRecords({
      organizationId,
      companyId,
      locationId,
      limit: 500,
      periodics: true,
    });
    return mergeMobileDocumentContextRecords(scopedSnapshot, freshRecords);
  } catch (error) {
    console.warn("[mobile-documentation-context] Ne mogu ucitati svjeze zapise dokumentacije.", error?.message || error);
    return scopedSnapshot;
  }
}

function getMobileLinkedServiceIdsFromItem(item = {}) {
  const sources = [
    item?.linkedServiceIds,
    item?.serviceIds,
    item?.serviceCatalogIds,
    item?.linkedServices,
    item?.services,
  ];
  return Array.from(new Set(sources.flatMap((source) => {
    if (!Array.isArray(source)) {
      return [];
    }
    return source.map((entry) => {
      if (entry && typeof entry === "object" && !Array.isArray(entry)) {
        return normalizeInputValue(entry.id || entry.serviceId || entry.catalogItemId || entry.value);
      }
      return normalizeInputValue(entry);
    });
  }).filter(Boolean)));
}

function getMobileTemplateLinkedServiceCatalogIds(templateId = "", scopedSnapshot = {}) {
  const normalizedTemplateId = normalizeInputValue(templateId);
  if (!normalizedTemplateId) {
    return [];
  }
  return (scopedSnapshot.serviceCatalog ?? [])
    .filter((service) => normalizeMobileDocumentWizardArray(service?.linkedTemplateIds).includes(normalizedTemplateId))
    .map((service) => normalizeInputValue(service?.id))
    .filter(Boolean);
}

function getMobileServiceDerivedLegalFrameworkIdsForTemplate(templateId = "", scopedSnapshot = {}) {
  const linkedServiceIds = new Set(getMobileTemplateLinkedServiceCatalogIds(templateId, scopedSnapshot));
  if (linkedServiceIds.size === 0) {
    return [];
  }
  return (scopedSnapshot.legalFrameworks ?? [])
    .filter((item) => getMobileLinkedServiceIdsFromItem(item).some((serviceId) => linkedServiceIds.has(serviceId)))
    .map((item) => normalizeInputValue(item?.id))
    .filter(Boolean);
}

function getMobileServiceDerivedMeasurementEquipmentItemsForTemplate(templateId = "", scopedSnapshot = {}) {
  const linkedServiceIds = new Set(getMobileTemplateLinkedServiceCatalogIds(templateId, scopedSnapshot));
  if (linkedServiceIds.size === 0) {
    return [];
  }
  return (scopedSnapshot.measurementEquipment ?? [])
    .filter((item) => getMobileLinkedServiceIdsFromItem(item).some((serviceId) => linkedServiceIds.has(serviceId)));
}

function getMobileDocumentTemplateEquipmentDeviceCode(item = {}) {
  return normalizeInputValue(item?.deviceCode || item?.device_code || item?.oznaka || item?.code);
}

function buildMobileDocumentationOption(id = "", label = "", subtitle = "", status = "", meta = {}) {
  const normalizedId = normalizeInputValue(id);
  const normalizedLabel = normalizeInputValue(label);
  if (!normalizedId || !normalizedLabel) {
    return null;
  }
  return {
    id: normalizedId,
    label: normalizedLabel,
    subtitle: normalizeInputValue(subtitle),
    status: normalizeInputValue(status),
    meta: Object.fromEntries(Object.entries(meta)
      .map(([key, value]) => [key, normalizeInputValue(value)])
      .filter(([, value]) => value)),
  };
}

function normalizeMobileQualificationAreaKey(value = "") {
  const normalized = normalizeInputValue(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return normalized || "elektro";
}

function normalizeMobileQualificationKeyList(value = []) {
  const entries = Array.isArray(value)
    ? value
    : normalizeInputValue(value).split(",");
  return Array.from(new Set(entries
    .map((entry) => normalizeMobileQualificationAreaKey(entry))
    .filter(Boolean)));
}

function getMobileQualificationAreaLabel(signatureArea = "elektro") {
  const key = normalizeMobileQualificationAreaKey(signatureArea);
  if (key === "elektro") {
    return "Elektro usluga";
  }
  if (key === "tipkalo" || key === "tzin") {
    return "Tipkalo za isklop napona";
  }
  if (key === "radna_oprema" || key === "ro") {
    return "Radna oprema";
  }
  if (key === "radni_okolis" || key === "fc") {
    return "Radni okoliš";
  }
  return key
    .split(/[_-]+/g)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(" ") || key;
}

function getMobileServiceQualificationKeys(service = {}, scopedSnapshot = {}) {
  const catalogItem = findMobileServiceCatalogItemForWorkOrderService(service, scopedSnapshot);
  const keys = new Set([
    ...normalizeMobileQualificationKeyList(service?.linkedQualificationKeys ?? service?.linkedQualificationExamKeys ?? service?.qualificationKeys ?? []),
    ...normalizeMobileQualificationKeyList(catalogItem?.linkedQualificationKeys ?? catalogItem?.linkedQualificationExamKeys ?? catalogItem?.qualificationKeys ?? []),
  ]);
  const text = normalizeInputValue([
    service?.serviceCode,
    service?.code,
    service?.name,
    service?.serviceName,
    service?.title,
    catalogItem?.serviceCode,
    catalogItem?.name,
  ].filter(Boolean).join(" ")).toLowerCase();

  if (/\b(tzin|tipkalo)\b/.test(text) || text.includes("isklop napona")) {
    keys.add("tipkalo");
  }
  if (/\b(spr|panik)\b/.test(text) || text.includes("panik rasvjet") || text.includes("panic")) {
    keys.add("elektro");
  }
  if (/\bro\b/.test(text) || text.includes("radna oprema") || text.includes("radne opreme")) {
    keys.add("radna_oprema");
  }
  if (
    /\bfc\b/.test(text)
    || text.includes("radni okolis")
    || text.includes("radnog okolisa")
    || text.includes("fizikalni cimbenici")
    || text.includes("fizikalnih cimbenika")
  ) {
    keys.add("radni_okolis");
  }

  return [...keys].filter(Boolean);
}

function getMobileDocumentTemplateSignatureAreas(template = {}, service = {}, scopedSnapshot = {}) {
  const areas = new Set(getMobileServiceQualificationKeys(service, scopedSnapshot));
  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field) => {
    const type = normalizeInputValue(field?.type).toLowerCase();
    if (!["qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature"].includes(type)) {
      return;
    }
    areas.add(normalizeMobileQualificationAreaKey(field?.signatureArea || "elektro"));
  });
  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getMobileUserQualificationForArea(user = {}, signatureArea = "elektro") {
  const area = normalizeMobileQualificationAreaKey(signatureArea);
  const rootQualification = user?.electricalQualification && typeof user.electricalQualification === "object"
    ? user.electricalQualification
    : {};
  const qualification = area === "elektro"
    ? rootQualification
    : (rootQualification.additionalAreas && typeof rootQualification.additionalAreas === "object"
      ? rootQualification.additionalAreas[area]
      : null) || {};
  return {
    discipline: normalizeMobileQualificationAreaKey(qualification.discipline || area),
    examTitle: normalizeInputValue(qualification.examTitle || qualification.title),
    type: normalizeInputValue(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind),
    examType: normalizeInputValue(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind),
    oib: normalizeInputValue(qualification.oib || qualification.oibNumber || qualification.taxId),
    data1: normalizeInputValue(qualification.data1 || qualification.classCode),
    data2: normalizeInputValue(qualification.data2 || qualification.urbroj),
    data3: normalizeInputValue(qualification.data3 || qualification.eBroj),
    classCode: normalizeInputValue(qualification.data1 || qualification.classCode),
    urbroj: normalizeInputValue(qualification.data2 || qualification.urbroj),
    eBroj: normalizeInputValue(qualification.data3 || qualification.eBroj),
    passedOn: normalizeDateOnlyValue(qualification.passedOn || qualification.examDate),
    validUntil: normalizeDateOnlyValue(qualification.validUntil),
    canInspect: Boolean(qualification.canInspect),
    canAuthorize: Boolean(qualification.canAuthorize),
  };
}

function buildMobileQualifiedUserOption(user = {}, capability = "inspect", signatureArea = "elektro") {
  const qualification = getMobileUserQualificationForArea(user, signatureArea);
  const label = getMobileUserDocumentName(user) || normalizeInputValue(user?.email);
  const subtitle = [
    qualification.type ? `Vrsta ispita ${qualification.type}` : "",
    qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
    qualification.data2 ? `Podatak 2 ${qualification.data2}` : "",
    qualification.data3 ? `Podatak 3 ${qualification.data3}` : "",
    qualification.passedOn ? `Položeno ${formatOfferDocumentDate(qualification.passedOn)}` : "",
    qualification.validUntil ? `Vrijedi do ${formatOfferDocumentDate(qualification.validUntil)}` : "",
  ].filter(Boolean).join(" · ");
  return buildMobileDocumentationOption(
    user?.id,
    label,
    subtitle || getMobileQualificationAreaLabel(signatureArea),
    capability === "authorize" ? "Odgovorna osoba" : "Ispitivač",
    {
      signatureArea: normalizeMobileQualificationAreaKey(signatureArea),
      capability,
      email: user?.email,
    },
  );
}

function getMobileQualifiedUsersForArea(scopedSnapshot = {}, capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const area = normalizeMobileQualificationAreaKey(signatureArea);
  return (scopedSnapshot.users ?? [])
    .filter((user) => user && user.isActive !== false && normalizeInputValue(user.status).toLowerCase() !== "inactive")
    .filter((user) => {
      const qualification = getMobileUserQualificationForArea(user, area);
      return normalizedCapability === "authorize"
        ? qualification.canAuthorize
        : qualification.canInspect;
    })
    .sort((left, right) => getMobileUserDocumentName(left).localeCompare(getMobileUserDocumentName(right), "hr"));
}

function normalizeMobilePersonLookupValue(value = "") {
  return normalizeInputValue(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function getMobileWorkOrderExecutorLabels(workOrder = {}) {
  const source = Array.isArray(workOrder?.executors)
    ? workOrder.executors
    : [workOrder?.executor1, workOrder?.executor2];
  return Array.from(new Set(source
    .map((entry) => {
      if (entry && typeof entry === "object") {
        return normalizeInputValue(
          entry.fullName || entry.name || entry.label || entry.email || entry.username || entry.id,
        );
      }
      return normalizeInputValue(entry);
    })
    .filter(Boolean)));
}

function getMobileUserLookupValues(user = {}) {
  return [
    getMobileUserDocumentName(user),
    user?.fullName,
    [user?.firstName, user?.lastName].filter(Boolean).join(" "),
    user?.displayName,
    user?.username,
    user?.legacyUsername,
    user?.email,
  ]
    .map((value) => normalizeMobilePersonLookupValue(value))
    .filter(Boolean);
}

function getMobileQualifiedExecutorUsers(scopedSnapshot = {}, workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const executorNames = getMobileWorkOrderExecutorLabels(workOrder)
    .map((value) => normalizeMobilePersonLookupValue(value))
    .filter(Boolean);
  if (executorNames.length === 0) {
    return [];
  }
  const executorSet = new Set(executorNames);
  return getMobileQualifiedUsersForArea(scopedSnapshot, capability, signatureArea)
    .filter((user) => getMobileUserLookupValues(user).some((candidate) => executorSet.has(candidate)));
}

function findMobilePreferredSignatureUser(
  scopedSnapshot = {},
  workOrder = {},
  capability = "inspect",
  signatureArea = "elektro",
  fallbackIds = [],
  { allowFirstQualifiedFallback = true } = {},
) {
  const executorMatch = getMobileQualifiedExecutorUsers(scopedSnapshot, workOrder, capability, signatureArea)[0];
  if (executorMatch) {
    return executorMatch;
  }
  const fallbackMatch = normalizeMobileDocumentWizardArray(fallbackIds)
    .map((id) => findMobileScopedUserById(scopedSnapshot, id))
    .find((user) => {
      if (!user) return false;
      const qualification = getMobileUserQualificationForArea(user, signatureArea);
      return capability === "authorize" ? qualification.canAuthorize : qualification.canInspect;
    });
  if (fallbackMatch) {
    return fallbackMatch;
  }
  return allowFirstQualifiedFallback
    ? getMobileQualifiedUsersForArea(scopedSnapshot, capability, signatureArea)[0] || null
    : null;
}

function buildMobileSignaturePersonOptions(scopedSnapshot = {}, signatureAreas = [], workOrder = {}) {
  const areaSet = new Set(normalizeMobileQualificationKeyList(signatureAreas));
  (scopedSnapshot.users ?? []).forEach((user) => {
    const rootQualification = user?.electricalQualification && typeof user.electricalQualification === "object"
      ? user.electricalQualification
      : {};
    if (rootQualification.canInspect || rootQualification.canAuthorize) {
      areaSet.add("elektro");
    }
    Object.entries(rootQualification.additionalAreas || {}).forEach(([area, qualification]) => {
      if (qualification?.canInspect || qualification?.canAuthorize) {
        areaSet.add(normalizeMobileQualificationAreaKey(area));
      }
    });
  });
  if (areaSet.size === 0) {
    areaSet.add("elektro");
  }

  return [...areaSet].map((area) => {
    const defaultInspectorIds = getMobileQualifiedExecutorUsers(scopedSnapshot, workOrder, "inspect", area)
      .map((user) => normalizeInputValue(user?.id))
      .filter(Boolean);
    const defaultAuthorizationUser = findMobilePreferredSignatureUser(
      scopedSnapshot,
      workOrder,
      "authorize",
      area,
      defaultInspectorIds,
      { allowFirstQualifiedFallback: false },
    );
    return {
      key: area,
      label: getMobileQualificationAreaLabel(area),
      inspectorOptions: getMobileQualifiedUsersForArea(scopedSnapshot, "inspect", area)
        .map((user) => buildMobileQualifiedUserOption(user, "inspect", area))
        .filter(Boolean),
      authorizationOptions: getMobileQualifiedUsersForArea(scopedSnapshot, "authorize", area)
        .map((user) => buildMobileQualifiedUserOption(user, "authorize", area))
        .filter(Boolean),
      defaultInspectorIds,
      defaultAuthorizationHolderId: normalizeInputValue(defaultAuthorizationUser?.id),
    };
  });
}

function buildMobileMeasurementEquipmentOptions(scopedSnapshot = {}) {
  return (scopedSnapshot.measurementEquipment ?? [])
    .map((item) => {
      const code = getMobileDocumentTemplateEquipmentDeviceCode(item);
      const name = normalizeInputValue(item?.name || item?.title || item?.deviceName || "Mjerna oprema");
      const inventoryNumber = normalizeInputValue(item?.inventoryNumber || item?.inventoryNo || item?.serialNumber);
      const validUntil = normalizeDateOnlyValue(item?.validUntil || item?.calibrationValidUntil || item?.calibrationDueDate);
      return buildMobileDocumentationOption(
        item?.id,
        code ? `${code} - ${name}` : name,
        [
          item?.deviceType || item?.type || item?.kind,
          inventoryNumber ? `Inv. ${inventoryNumber}` : "",
          validUntil ? `Vrijedi do ${formatOfferDocumentDate(validUntil)}` : "",
        ].map(normalizeInputValue).filter(Boolean).join(" · "),
        item?.status,
        {
          deviceCode: code,
          code,
          deviceType: item?.deviceType || item?.type,
          inventoryNumber,
          serialNumber: item?.serialNumber,
          manufacturer: item?.manufacturer,
          validUntil,
        },
      );
    })
    .filter(Boolean)
    .sort((left, right) => left.label.localeCompare(right.label, "hr", { numeric: true, sensitivity: "base" }));
}

function buildMobileLegalFrameworkOptions(scopedSnapshot = {}) {
  return (scopedSnapshot.legalFrameworks ?? [])
    .map((item) => buildMobileDocumentationOption(
      item?.id,
      item?.referenceCode
        ? `${normalizeInputValue(item?.title || "Propis")} | ${normalizeInputValue(item.referenceCode)}`
        : normalizeInputValue(item?.title || "Propis"),
      [item?.category, item?.source, item?.scope].map(normalizeInputValue).filter(Boolean).join(" · "),
      item?.status,
      {
        referenceCode: item?.referenceCode,
        category: item?.category,
        source: item?.source,
      },
    ))
    .filter(Boolean)
    .sort((left, right) => left.label.localeCompare(right.label, "hr", { numeric: true, sensitivity: "base" }));
}

function buildMobileRulebookOptions(scopedSnapshot = {}) {
  return (scopedSnapshot.rulebooks ?? [])
    .map((item) => buildMobileDocumentationOption(
      item?.id,
      item?.title || "Pravilnik",
      [item?.rulebookType, item?.scope, item?.owner].map(normalizeInputValue).filter(Boolean).join(" · "),
      item?.status,
      {
        rulebookType: item?.rulebookType,
        effectiveFrom: item?.effectiveFrom,
        reviewDate: item?.reviewDate,
        owner: item?.owner,
      },
    ))
    .filter(Boolean)
    .sort((left, right) => left.label.localeCompare(right.label, "hr", { numeric: true, sensitivity: "base" }));
}

