function escapeMobileSprRegexValue(value = "") {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function parseMobileSprVoiceCount(value = "") {
  const raw = normalizeInputValue(value);
  if (/^\d{1,4}$/.test(raw)) {
    return raw;
  }
  const lookup = normalizeMobileSprLookupText(raw);
  if (Object.prototype.hasOwnProperty.call(MOBILE_SPR_VOICE_NUMBER_WORDS, lookup)) {
    return String(MOBILE_SPR_VOICE_NUMBER_WORDS[lookup]);
  }
  return "";
}

function cleanMobileSprVoicePlace(value = "") {
  return normalizeInputValue(value)
    .replace(/^(?:i|pa|te|onda|zatim)\s+/i, "")
    .replace(/\b(?:dodaj|unesi|upisi|upisi mi|stavi)\b/gi, "")
    .replace(/^(?:mjesto|lokacija)\s+/i, "")
    .replace(/\b(?:mjesto|lokacija)\s*[:\-]\s*/gi, "")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
}

function cleanMobileSprVoiceFloor(value = "") {
  const floor = normalizeInputValue(value)
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
  if (!floor) {
    return "";
  }
  return floor.toLowerCase().startsWith("eta") ? floor : `Etaža ${floor}`;
}

function isMobileSprVoiceUnitToken(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  return lookup.startsWith("panik")
    || lookup.startsWith("lamp")
    || lookup.startsWith("svjetilj")
    || lookup.startsWith("kom");
}

function isMobileTzinVoiceUnitToken(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  return lookup.startsWith("tipkal")
    || lookup.startsWith("gljiv")
    || lookup.startsWith("isklop")
    || lookup.startsWith("kom");
}

function isMobileEizIpkVoiceUnitToken(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  return lookup.startsWith("utic")
    || lookup.startsWith("uticnic")
    || lookup.startsWith("uti")
    || lookup.startsWith("suko")
    || lookup === "v"
    || lookup === "230v"
    || lookup === "230 v"
    || lookup === "400v"
    || lookup === "400 v"
    || lookup.startsWith("kom");
}

function cleanMobileEizIpkVoicePoint(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  if (lookup.includes("400")) {
    return "Utičnica 400 V";
  }
  if (lookup.includes("rasvjet")) {
    return "Rasvjetno mjesto";
  }
  return "Utičnica 230 V";
}

function cleanMobileEizIpkSectionTitle(value = "") {
  return cleanMobileSprVoicePlace(value)
    .replace(/^(?:prostorija|prostor|prostorije|lokacija|mjesto)\s+/i, "")
    .replace(/\b(?:uticnica|uticnice|utiÄŤnica|utiÄŤnice|suko|komada|kom)\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function parseMobileEizIpkNumericToken(value = "") {
  const raw = normalizeInputValue(value)
    .replace(/[^\d,.-]/g, "")
    .replace(/\.(?=\d{3}\b)/g, "")
    .replace(",", ".");
  if (!raw || raw === "-" || raw === ".") {
    return null;
  }
  const parsed = Number.parseFloat(raw);
  if (!Number.isFinite(parsed)) {
    return null;
  }
  if (/^\d{2,3}$/.test(raw) && parsed > 9) {
    return parsed / 100;
  }
  return parsed;
}

function formatMobileEizIpkNumericValue(value = null) {
  if (!Number.isFinite(value)) {
    return "";
  }
  return value
    .toFixed(2)
    .replace(".", ",")
    .replace(/,00$/u, "")
    .replace(/,(\d)0$/u, ",$1");
}

function formatMobileEizIpkRandBetweenFormula(value = null, spread = 0.05) {
  if (!Number.isFinite(value)) {
    return "";
  }
  const low = Math.max(0, Math.round(value * (1 - spread) * 100));
  const high = Math.max(low, Math.round(value * (1 + spread) * 100));
  return `=RANDBETWEEN(${low},${high})/100`;
}

function mobileEizIpkDeterministicUnit(seed = "") {
  const text = normalizeInputValue(seed);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return ((hash >>> 0) % 10000) / 10000;
}

function expandMobileEizIpkValues(values = [], count = 1, seed = "") {
  const numericValues = (Array.isArray(values) ? values : [])
    .map(parseMobileEizIpkNumericToken)
    .filter((value) => Number.isFinite(value));
  const safeCount = Math.max(1, Math.min(200, Number.parseInt(count, 10) || 1));
  if (!numericValues.length) {
    return [];
  }
  if (numericValues.length === 1) {
    const base = numericValues[0];
    return Array.from({ length: safeCount }, () => formatMobileEizIpkRandBetweenFormula(base));
  }
  if (safeCount === 1) {
    return [formatMobileEizIpkRandBetweenFormula(numericValues[0])];
  }
  return Array.from({ length: safeCount }, (_item, index) => {
    const position = (index / (safeCount - 1)) * (numericValues.length - 1);
    const leftIndex = Math.floor(position);
    const rightIndex = Math.min(numericValues.length - 1, Math.ceil(position));
    const ratio = position - leftIndex;
    const value = numericValues[leftIndex] + ((numericValues[rightIndex] - numericValues[leftIndex]) * ratio);
    return formatMobileEizIpkRandBetweenFormula(value);
  });
}

function getMobileEizIpkValueAlias(value = "") {
  const lookup = normalizeMobileSprLookupText(value).replace(/\s+/g, "");
  if (["zlp", "zlpe", "zl-pe", "z-lpe", "z-l-pe"].includes(lookup) || lookup.includes("zlpe")) {
    return "zLpe";
  }
  if (["zln", "zl-n", "zl1", "zlone", "z-l-n"].includes(lookup) || lookup.includes("zln")) {
    return "zLn";
  }
  if (["zll", "zl-l", "z-l-l"].includes(lookup) || lookup.includes("zll")) {
    return "zLl";
  }
  return "";
}

function isMobileEizIpkModifierToken(value = "") {
  const lookup = normalizeMobileSprLookupText(value);
  return Boolean(getMobileEizIpkValueAlias(value))
    || lookup === "between"
    || lookup === "izmedu"
    || lookup === "izmedju"
    || lookup === "izmeÄ‘u"
    || /^[bcd]?\d{1,3}$/iu.test(lookup)
    || lookup.startsWith("rcd")
    || lookup.startsWith("zuds");
}

function parseMobileEizIpkModifiers(tokens = [], count = 1, seed = "", previousProfile = {}) {
  const profile = {
    point: cleanMobileEizIpkVoicePoint(tokens.join(" ")),
    protectionType: "",
    zLpe: [],
    zLn: [],
    zLl: [],
  };
  const protectionParts = [];
  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    const lookup = normalizeMobileSprLookupText(token);
    const alias = getMobileEizIpkValueAlias(token);
    if (alias) {
      const values = [];
      let valueIndex = index + 1;
      while (valueIndex < tokens.length) {
        const nextToken = tokens[valueIndex];
        if (
          getMobileEizIpkValueAlias(nextToken)
          || (isMobileEizIpkModifierToken(nextToken) && parseMobileEizIpkNumericToken(nextToken) === null)
        ) {
          break;
        }
        if (Number.isFinite(parseMobileEizIpkNumericToken(nextToken))) {
          values.push(nextToken);
        }
        valueIndex += 1;
      }
      profile[alias] = expandMobileEizIpkValues(values, count, `${seed}:${alias}`);
      index = Math.max(index, valueIndex - 1);
      continue;
    }
    if (/^[bcd]\d{1,3}$/iu.test(lookup)) {
      protectionParts.push(token.toUpperCase());
      continue;
    }
    if (lookup.startsWith("rcd") || lookup.startsWith("zuds")) {
      const first = normalizeInputValue(tokens[index + 1]);
      const second = normalizeInputValue(tokens[index + 2]);
      const rating = first && parseMobileEizIpkNumericToken(first) !== null
        ? (second && parseMobileEizIpkNumericToken(second) !== null ? `${first}/${second}` : first)
        : "";
      protectionParts.push(`RCD${rating ? ` ${rating}` : ""}`);
      if (rating && second) {
        index += 2;
      } else if (rating) {
        index += 1;
      }
    }
  }
  profile.protectionType = protectionParts.join(", ");
  return {
    point: profile.point || previousProfile.point || "UtiÄŤnica 230 V",
    protectionType: profile.protectionType || previousProfile.protectionType || "",
    zLpe: profile.zLpe.length ? profile.zLpe : (previousProfile.zLpe || []),
    zLn: profile.zLn.length ? profile.zLn : (previousProfile.zLn || []),
    zLl: profile.zLl.length ? profile.zLl : (previousProfile.zLl || []),
  };
}

function parseMobileSprVoiceLooseRows(transcript = "") {
  const tokens = normalizeInputValue(transcript)
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, " ")
    .replace(/[,;:]+/g, " ")
    .split(/\s+/g)
    .map((token) => normalizeInputValue(token).replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, ""))
    .filter(Boolean);
  if (!tokens.length) {
    return [];
  }
  const rows = [];
  const seen = new Set();
  const placeTokens = [];
  let lastWasCount = false;
  tokens.forEach((token) => {
    if (lastWasCount && isMobileSprVoiceUnitToken(token)) {
      return;
    }
    const lampCount = parseMobileSprVoiceCount(token);
    if (lampCount) {
      const place = cleanMobileSprVoicePlace(placeTokens.join(" "));
      const key = normalizeMobileSprLookupText(place);
      if (place && key) {
        if (seen.has(key)) {
          const existing = rows.find((row) => row.key === key);
          if (existing) {
            existing.lampCount = lampCount;
          }
        } else {
          seen.add(key);
          rows.push({ key, place, lampCount, kind: "measurement" });
        }
      }
      placeTokens.length = 0;
      lastWasCount = true;
      return;
    }
    if (!isMobileSprVoiceUnitToken(token)) {
      placeTokens.push(token);
      lastWasCount = false;
    }
  });
  return rows;
}

function parseMobileSprVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const numberWords = Object.keys(MOBILE_SPR_VOICE_NUMBER_WORDS);
  const numberPattern = [
    "\\d{1,4}",
    ...numberWords
      .sort((left, right) => right.length - left.length)
      .map(escapeMobileSprRegexValue),
  ].join("|");
  const unitPattern = "(?:panik\\w*|lamp\\w*|svjetilj\\w*|kom\\w*)";
  const itemPattern = new RegExp(`(.+?)\\s+(${numberPattern})(?:\\s*${unitPattern})?(?=\\s+\\S|$)`, "giu");
  const floorPattern = /\beta\S*\s+((?:-?\d+\.?\s*)?(?:kat|katu)|prizemlje|podrum|suteren|galerija|(?:prvi|drugi|tre[cć]i|[cč]etvrti|peti|[sš]esti|sedmi|osmi|deveti|deseti)\s+kat)/giu;
  const rows = [];
  const seen = new Set();
  const normalizedSource = source
    .replace(floorPattern, (_match, floor) => `\n§FLOOR§${cleanMobileSprVoiceFloor(floor)}\n`)
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, "\n")
    .replace(/[;,]+/g, "\n");

  normalizedSource
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment) => {
      if (segment.startsWith("§FLOOR§")) {
        const place = segment.replace(/^§FLOOR§/, "").trim();
        const key = normalizeMobileSprLookupText(place);
        if (place && key && !seen.has(key)) {
          seen.add(key);
          rows.push({ key, place, lampCount: "", kind: "section" });
        }
        return;
      }
      Array.from(segment.matchAll(itemPattern)).forEach((match) => {
        const place = cleanMobileSprVoicePlace(match[1]);
        const lampCount = parseMobileSprVoiceCount(match[2]);
        const key = normalizeMobileSprLookupText(place);
        if (!place || !lampCount || !key) {
          return;
        }
        if (seen.has(key)) {
          const existing = rows.find((row) => row.key === key);
          if (existing) {
            existing.lampCount = lampCount;
          }
          return;
        }
        seen.add(key);
        rows.push({ key, place, lampCount, kind: "measurement" });
      });
    });
  return rows.length ? rows : parseMobileSprVoiceLooseRows(source);
}

function parseMobileTzinVoiceLooseRows(transcript = "") {
  const tokens = normalizeInputValue(transcript)
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, " ")
    .replace(/[,;:]+/g, " ")
    .split(/\s+/g)
    .map((token) => normalizeInputValue(token).replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, ""))
    .filter(Boolean);
  if (!tokens.length) {
    return [];
  }
  const rows = [];
  const seen = new Set();
  const placeTokens = [];
  let lastWasCount = false;
  tokens.forEach((token) => {
    if (lastWasCount && isMobileTzinVoiceUnitToken(token)) {
      return;
    }
    const buttonCount = parseMobileSprVoiceCount(token);
    if (buttonCount) {
      const place = cleanMobileSprVoicePlace(placeTokens.join(" "));
      const key = normalizeMobileSprLookupText(place);
      if (place && key) {
        if (seen.has(key)) {
          const existing = rows.find((row) => row.key === key);
          if (existing) {
            existing.lampCount = buttonCount;
          }
        } else {
          seen.add(key);
          rows.push({ key, place, lampCount: buttonCount, kind: "measurement" });
        }
      }
      placeTokens.length = 0;
      lastWasCount = true;
      return;
    }
    if (!isMobileTzinVoiceUnitToken(token)) {
      placeTokens.push(token);
      lastWasCount = false;
    }
  });
  return rows;
}

function parseMobileTzinVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const numberWords = Object.keys(MOBILE_SPR_VOICE_NUMBER_WORDS);
  const numberPattern = [
    "\\d{1,4}",
    ...numberWords
      .sort((left, right) => right.length - left.length)
      .map(escapeMobileSprRegexValue),
  ].join("|");
  const unitPattern = "(?:tipkal\\w*|gljiv\\w*|isklop\\w*|kom\\w*)";
  const itemPattern = new RegExp(`(.+?)\\s+(${numberPattern})(?:\\s*${unitPattern})?(?=\\s+\\S|$)`, "giu");
  const rows = [];
  const seen = new Set();
  source
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, "\n")
    .replace(/[;,]+/g, "\n")
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment) => {
      Array.from(segment.matchAll(itemPattern)).forEach((match) => {
        const place = cleanMobileSprVoicePlace(match[1]);
        const buttonCount = parseMobileSprVoiceCount(match[2]);
        const key = normalizeMobileSprLookupText(place);
        if (!place || !buttonCount || !key) {
          return;
        }
        if (seen.has(key)) {
          const existing = rows.find((row) => row.key === key);
          if (existing) {
            existing.lampCount = buttonCount;
          }
          return;
        }
        seen.add(key);
        rows.push({ key, place, lampCount: buttonCount, kind: "measurement" });
      });
    });
  return rows.length ? rows : parseMobileTzinVoiceLooseRows(source);
}

function cleanMobileSzomVoicePlace(value = "") {
  return cleanMobileSprVoicePlace(value)
    .replace(/\b(?:riz|rdop|ohm|oma|mjerenje|otpor)\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function getMobileSzomVoiceTarget(segment = "") {
  const lookup = normalizeMobileSprLookupText(segment);
  if (
    lookup.includes("povezanostmasa")
    || lookup.includes("metalnemase")
    || lookup.includes("izjednacavanjepotencijala")
  ) {
    return "metalMassBonding";
  }
  if (
    lookup.includes("skrivenispoj")
    || lookup.includes("skrivenespoj")
    || lookup.includes("kontrolnispoj")
    || lookup.includes("mjernispoj")
  ) {
    return "hiddenJoint";
  }
  return "grounding";
}

function removeMobileSzomVoiceTargetWords(value = "") {
  return normalizeInputValue(value)
    .replace(/\b(?:elektricna|elektri[cč]na)?\s*povezanost\s+(?:metalnih\s+)?masa\b/giu, " ")
    .replace(/\bmetalne\s+mase\b/giu, " ")
    .replace(/\bizjedna[cč]avanje\s+potencijala\b/giu, " ")
    .replace(/\bskriveni\s+spojevi?\b/giu, " ")
    .replace(/\bkontrolni\s+spojevi?\b/giu, " ")
    .replace(/\bmjerni\s+spojevi?\b/giu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function parseMobileSzomVoiceValue(value = "") {
  const text = normalizeInputValue(value);
  const matches = Array.from(text.matchAll(/(?:^|\s)(\d{1,3}(?:[,.]\d{1,3})?)(?:\s*(?:ohm|oma|Ω))?(?=\s*$)/giu));
  const last = matches[matches.length - 1];
  if (!last) {
    return { placeText: text, value: "" };
  }
  return {
    placeText: normalizeInputValue(text.slice(0, last.index)).trim(),
    value: normalizeInputValue(last[1]).replace(".", ","),
  };
}

function parseMobileSzomVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const rows = [];
  source
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, "\n")
    .replace(/[;]+/g, "\n")
    .replace(/(?<!\d),(?!\d)/gu, "\n")
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment, index) => {
      const target = getMobileSzomVoiceTarget(segment);
      const withoutTarget = removeMobileSzomVoiceTargetWords(segment);
      const parsed = parseMobileSzomVoiceValue(withoutTarget);
      const place = cleanMobileSzomVoicePlace(parsed.placeText);
      const key = normalizeMobileSprLookupText(`${target} ${place} ${parsed.value} ${index + 1}`);
      if (!place || !key) {
        return;
      }
      rows.push({
        key,
        place,
        value: parsed.value,
        lampCount: parsed.value,
        target,
        partLabel: target === "metalMassBonding"
          ? "Povezanost masa"
          : target === "hiddenJoint"
            ? "Skriveni spojevi"
            : "Riz",
        kind: "measurement",
      });
    });
  return rows;
}

function parseMobileExseVoiceNumber(value = "") {
  const text = normalizeInputValue(value)
    .replace(/[^\d,.-]/g, "")
    .replace(/\.(?=\d{3}\b)/g, "")
    .replace(".", ",")
    .trim();
  if (!text || text === "-" || text === ",") {
    return "";
  }
  return text;
}

function extractMobileExseVoiceValue(segment = "", patterns = []) {
  const source = normalizeInputValue(segment);
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match?.[1]) {
      return parseMobileExseVoiceNumber(match[1]);
    }
  }
  return "";
}

function normalizeMobileExseFuelLabel(value = "") {
  const raw = normalizeInputValue(value)
    .replace(/\b(?:otpor|cijevi?|istakacka|istakacke|istakanje|za)\b/giu, " ")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();
  const lookup = normalizeMobileSprLookupText(raw);
  if (!lookup) {
    return "";
  }
  if (lookup.includes("eurosuper") || lookup.includes("euro super") || lookup.includes("es 95")) {
    return lookup.includes("100") ? "Eurosuper 100" : "Eurosuper 95";
  }
  if (lookup.includes("eurodiesel") || lookup.includes("euro diesel") || lookup === "ed" || lookup.includes("ed bs")) {
    return "Eurodiesel";
  }
  if (lookup.includes("lpg") || lookup.includes("unp") || lookup.includes("plin")) {
    return "LPG";
  }
  return raw
    .replace(/\bes\b/giu, "ES")
    .replace(/\bed\b/giu, "ED")
    .replace(/\bbs\b/giu, "BS")
    .replace(/\blpg\b/giu, "LPG")
    .replace(/\bunp\b/giu, "UNP");
}

function cleanMobileExseVoicePlace(segment = "") {
  let text = normalizeInputValue(segment)
    .replace(/\botpor\s+uzemljenja\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?\s*(?:ohm|oma)?/giu, " ")
    .replace(/\botpor\s+cijevi\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?\s*(?:k\s*ohm|kohm|kilooma)?/giu, " ")
    .replace(/\belektrostaticko\s+polje\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?\s*(?:kv\/m)?/giu, " ")
    .replace(/\bstaticko\s+polje\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?\s*(?:kv\/m)?/giu, " ")
    .replace(/\bdozvoljeni\s+otpor\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?/giu, " ")
    .replace(/\bdopusteni\s+otpor\s*[=:]?\s*[<>]?\s*\d{1,4}(?:[,.]\d{1,4})?/giu, " ")
    .replace(/\bocjena\s+(?:da|ne|zadovoljava|ne\s+zadovoljava)\b/giu, " ")
    .replace(/\b(?:izmjereno|izmjeri|dodaj|unesi|upisi|stavi)\b/giu, " ")
    .replace(/\s+/g, " ")
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .trim();

  const aggregateMatch = text.match(/\bagregat\s+(\d{1,2})(?:\s*(?:\/|i|-)\s*(\d{1,2}))?/iu);
  const hasHose = /(?:cijev|crijev|istakanj|istakack)/iu.test(text);
  if (aggregateMatch && hasHose) {
    const aggregate = aggregateMatch[2] ? `${aggregateMatch[1]}/${aggregateMatch[2]}` : aggregateMatch[1];
    const afterHose = text.split(/\b(?:cijev|crijev|istakanje|istakacka|istakacke)\b/iu).pop() || "";
    const fuel = normalizeMobileExseFuelLabel(afterHose);
    return `Agregat ${aggregate} - cijev za istakanje${fuel ? ` ${fuel}` : ""}`;
  }

  return cleanMobileSprVoicePlace(text);
}

function parseMobileExseVoicePass(segment = "") {
  const lookup = normalizeMobileSprLookupText(segment);
  if (lookup.includes("ne zadovoljava") || lookup.includes("neispravno") || lookup.includes("ocjena ne")) {
    return "NE";
  }
  if (lookup.includes("zadovoljava") || lookup.includes("ispravno") || lookup.includes("ocjena da")) {
    return "DA";
  }
  return "";
}

function inferMobileExseVoiceTarget(segment = "", values = {}) {
  const lookup = normalizeMobileSprLookupText(segment);
  if (
    values.pipeResistance
    || lookup.includes("otporcijevi")
    || lookup.includes("cijev")
    || lookup.includes("crijev")
    || lookup.includes("agregat")
    || lookup.includes("istak")
    || lookup.includes("static")
    || lookup.includes("statick")
  ) {
    return "static";
  }
  return "earthing";
}

function parseMobileExseVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const rows = [];
  const seen = new Set();
  source
    .replace(/\b(?:i onda|pa onda|zatim|onda|sljedece|sljedece)\b/giu, "\n")
    .replace(/[;]+/g, "\n")
    .replace(/(?<!\d),(?!\d)/gu, "\n")
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment, index) => {
      const values = {
        earthResistance: extractMobileExseVoiceValue(segment, [
          /\botpor\s+uzemljenja\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
          /\buzemljenj\w*\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
        ]),
        pipeResistance: extractMobileExseVoiceValue(segment, [
          /\botpor\s+cijevi\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
          /\bcijev\w*\s+otpor\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
        ]),
        electrostaticField: extractMobileExseVoiceValue(segment, [
          /\belektrostaticko\s+polje\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
          /\bstaticko\s+polje\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
        ]),
        allowedResistance: extractMobileExseVoiceValue(segment, [
          /\bdozvoljeni\s+otpor\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
          /\bdopusteni\s+otpor\s*[=:]?\s*([<>]?\s*\d{1,4}(?:[,.]\d{1,4})?)/iu,
        ]),
        pass: parseMobileExseVoicePass(segment),
      };
      const place = cleanMobileExseVoicePlace(segment);
      const target = inferMobileExseVoiceTarget(segment, values);
      const key = normalizeMobileSprLookupText(`${target} ${place} ${index + 1}`);
      if (!place || !key || seen.has(key)) {
        return;
      }
      seen.add(key);
      rows.push({
        key,
        target,
        place,
        ...values,
        kind: "measurement",
      });
    });
  return rows;
}

function cleanMobileEmmVoicePoint(value = "") {
  return cleanMobileSprVoicePlace(value)
    .replace(/\b(?:ispitno|mjesto|mjerenje|povezanost|kontinuitet|metalnih|masa)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function splitMobileEmmVoicePair(segment = "") {
  const text = normalizeInputValue(segment)
    .replace(/\b(?:ispitno\s*mjesto\s*1|mjesto\s*1|prvo\s*mjesto)\b/giu, " ")
    .replace(/\b(?:ispitno\s*mjesto\s*2|mjesto\s*2|drugo\s*mjesto)\b/giu, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) {
    return null;
  }
  const delimiterMatch = text.match(/^(.+?)\s+(?:do|prema|sa|s|na|i|\/|-|->|:)\s+(.+)$/iu);
  if (delimiterMatch) {
    return {
      point1: cleanMobileEmmVoicePoint(delimiterMatch[1]),
      point2: cleanMobileEmmVoicePoint(delimiterMatch[2]),
    };
  }
  const knownFirstPoint = text.match(/^(pe\s+sabirnica|sabirnica\s+pe|glavna\s+sabirnica|gro|pe)\s+(.+)$/iu);
  if (knownFirstPoint) {
    return {
      point1: cleanMobileEmmVoicePoint(knownFirstPoint[1]),
      point2: cleanMobileEmmVoicePoint(knownFirstPoint[2]),
    };
  }
  const tokens = text.split(/\s+/g).filter(Boolean);
  if (tokens.length >= 4) {
    const splitIndex = Math.ceil(tokens.length / 2);
    return {
      point1: cleanMobileEmmVoicePoint(tokens.slice(0, splitIndex).join(" ")),
      point2: cleanMobileEmmVoicePoint(tokens.slice(splitIndex).join(" ")),
    };
  }
  if (tokens.length >= 2) {
    return {
      point1: cleanMobileEmmVoicePoint(tokens[0]),
      point2: cleanMobileEmmVoicePoint(tokens.slice(1).join(" ")),
    };
  }
  return null;
}

function parseMobileEmmVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const rows = [];
  const segments = source
    .replace(/\b(?:i onda|pa onda|zatim|onda|sljedece|sljedeće)\b/giu, "\n")
    .replace(/[;]+/g, "\n")
    .replace(/(?<!\d),(?!\d)/gu, "\n")
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean);
  segments.forEach((segment, index) => {
    const pair = splitMobileEmmVoicePair(segment);
    if (!pair?.point1 || !pair?.point2) {
      return;
    }
    const key = normalizeMobileSprLookupText(`${pair.point1} ${pair.point2} ${index + 1}`);
    rows.push({
      key,
      place1: pair.point1,
      place2: pair.point2,
      point1: pair.point1,
      point2: pair.point2,
      place: `${pair.point1} - ${pair.point2}`,
      lampCount: "",
      kind: "measurement",
    });
  });
  return rows;
}

function parseMobileEizIpkVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript);
  if (!source) {
    return [];
  }
  const floorPattern = /\beta\S*\s+((?:-?\d+\.?\s*)?(?:kat|katu)|prizemlje|podrum|suteren|galerija|(?:prvi|drugi|tre[cć]i|[cč]etvrti|peti|[sš]esti|sedmi|osmi|deveti|deseti)\s+kat)/giu;
  const normalizedSource = source
    .replace(floorPattern, (_match, floor) => `\n§FLOOR§${cleanMobileSprVoiceFloor(floor)}\n`)
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, "\n")
    .replace(/[;]+/g, "\n")
    .replace(/(?<!\d),(?!\d)/gu, "\n");
  const rows = [];
  const seenSections = new Set();
  let lastProfile = {
    point: "Utičnica 230 V",
    protectionType: "",
    zLpe: [],
    zLn: [],
    zLl: [],
  };
  const addSection = (place = "") => {
    const cleanedPlace = cleanMobileEizIpkSectionTitle(place);
    const key = normalizeMobileSprLookupText(cleanedPlace);
    if (!cleanedPlace || !key || seenSections.has(key)) {
      return;
    }
    seenSections.add(key);
    rows.push({ key: `section-${key}`, place: cleanedPlace, lampCount: "", kind: "section" });
  };
  const addMeasurementRows = (section = "", countValue = "", modifierTokens = []) => {
    const count = Number.parseInt(parseMobileSprVoiceCount(countValue), 10);
    if (!Number.isFinite(count) || count <= 0) {
      return;
    }
    addSection(section);
    const safeCount = Math.min(count, 200);
    const sectionKey = normalizeMobileSprLookupText(section);
    const profile = parseMobileEizIpkModifiers(modifierTokens, safeCount, sectionKey, lastProfile);
    lastProfile = profile;
    for (let index = 0; index < safeCount; index += 1) {
      rows.push({
        key: `ipk-${sectionKey}-${rows.length + 1}`,
        place: profile.point || "Utičnica 230 V",
        lampCount: "1",
        kind: "measurement",
        protectionType: profile.protectionType || "",
        zLpe: profile.zLpe[index] || "",
        zLn: profile.zLn[index] || "",
        zLl: profile.zLl[index] || "",
      });
    }
  };
  normalizedSource
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment) => {
      if (segment.startsWith("§FLOOR§")) {
        const place = segment.replace(/^§FLOOR§/, "").trim();
        addSection(place);
        return;
      }
      const tokens = segment
        .replace(/[:]+/g, " ")
        .split(/\s+/g)
        .map((token) => normalizeInputValue(token).replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, ""))
        .filter(Boolean);
      const placeTokens = [];
      for (let index = 0; index < tokens.length; index += 1) {
        const token = tokens[index];
        const count = parseMobileSprVoiceCount(token);
        if (!count) {
          placeTokens.push(token);
          continue;
        }
        const section = placeTokens.join(" ");
        const modifierTokens = tokens.slice(index + 1);
        addMeasurementRows(section, count, modifierTokens);
        placeTokens.length = 0;
        break;
      }
    });
  return rows;
}

function normalizeMobileEizElectricalLabel(value = "") {
  const raw = normalizeInputValue(value)
    .replace(/^[,.;:\s-]+|[,.;:\s-]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!raw) {
    return "";
  }
  if (/^[A-Za-z0-9ČĆŠĐŽčćšđž_.\-\/ ]{1,28}$/.test(raw)) {
    return raw.toUpperCase();
  }
  return raw;
}

function normalizeMobileEizZudsRating(value = "", idnValue = "") {
  const raw = normalizeInputValue(value)
    .replace(/\\/g, "/")
    .replace(/\b(?:kroz|slash|kosa\s+crta|crta)\b/giu, "/")
    .replace(/\s+/g, " ")
    .trim();
  const match = raw.match(/(\d{1,3})\s*(?:a)?\s*\/\s*(\d{1,4})\s*(?:m\s*a|ma)?/i);
  if (match) {
    return `${match[1]}/${match[2]}`;
  }
  const inOnly = normalizeInputValue(value).match(/\d{1,3}/)?.[0] || "";
  const idnOnly = normalizeInputValue(idnValue).match(/\d{1,4}/)?.[0] || "";
  return inOnly && idnOnly ? `${inOnly}/${idnOnly}` : "";
}

function parseMobileEizZudsVoiceRows(transcript = "") {
  const source = normalizeInputValue(transcript)
    .replace(/\\/g, "/")
    .replace(/\b(?:kroz|slash|kosa\s+crta|crta)\b/giu, "/")
    .replace(/\s*\/\s*/g, "/");
  if (!source) {
    return [];
  }
  const rows = [];
  let lastBoard = "";
  const addRow = (prefix = "", rating = "") => {
    const cleanedPrefix = normalizeInputValue(prefix)
      .replace(/\b(?:razvodni|razdjelnik|razdelnik|ormar|oznaka|strujni|strujnog|krug|kruga|pid|fid|rcd|zuds|sklopka|karakteristika)\b/giu, " ")
      .replace(/\s+/g, " ")
      .trim();
    const parts = cleanedPrefix
      .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, " ")
      .split(/[,;]+/g)
      .map((part) => normalizeInputValue(part))
      .filter(Boolean);
    let board = "";
    let circuit = "";
    if (parts.length >= 2) {
      board = parts.slice(0, -1).join(" ");
      circuit = parts[parts.length - 1];
    } else {
      const tokens = cleanedPrefix
        .replace(/[,;]+/g, " ")
        .split(/\s+/g)
        .map((token) => normalizeInputValue(token))
        .filter(Boolean);
      if (tokens.length >= 2) {
        board = tokens.slice(0, -1).join(" ");
        circuit = tokens[tokens.length - 1];
      } else if (tokens.length === 1) {
        board = lastBoard;
        circuit = tokens[0];
      }
    }
    board = normalizeMobileEizElectricalLabel(board || lastBoard);
    circuit = normalizeMobileEizElectricalLabel(circuit);
    const rcdRating = normalizeMobileEizZudsRating(rating);
    if (!board || !circuit || !rcdRating) {
      return;
    }
    lastBoard = board;
    rows.push({
      key: `zuds-${normalizeMobileSprLookupText(board)}-${normalizeMobileSprLookupText(circuit)}-${rows.length + 1}`,
      board,
      circuit,
      rcdRating,
      kind: "measurement",
    });
  };
  source
    .replace(/\b(?:i onda|pa onda|zatim|onda)\b/giu, "\n")
    .replace(/[;]+/g, "\n")
    .split(/\r?\n/g)
    .map((segment) => normalizeInputValue(segment))
    .filter(Boolean)
    .forEach((segment) => {
      const ratingRegex = /(\d{1,3}\s*(?:a)?\s*(?:\/|\\)\s*\d{1,4}\s*(?:m\s*a|ma)?)/giu;
      let cursor = 0;
      let match = ratingRegex.exec(segment);
      while (match) {
        const prefix = segment.slice(cursor, match.index);
        addRow(prefix, match[1]);
        cursor = ratingRegex.lastIndex;
        match = ratingRegex.exec(segment);
      }
    });
  return rows;
}

function normalizeMobileSprVoiceRows(rows = []) {
  const normalizedRows = [];
  const seen = new Set();
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const rawKind = normalizeInputValue(row?.kind || row?.type || row?.rowType || "").toLowerCase();
    const rawPlace = normalizeInputValue(
      row?.place
      || row?.mjesto
      || row?.location
      || row?.room
      || row?.name
      || "",
    );
    const isSection = rawKind === "section"
      || rawKind === "floor"
      || rawKind === "etaza"
      || rawKind.startsWith("eta")
      || row?.isSection === true;
    const place = isSection ? cleanMobileSprVoiceFloor(rawPlace) : cleanMobileSprVoicePlace(rawPlace);
    const lampCount = parseMobileSprVoiceCount(
      row?.lampCount
      || row?.brojLampi
      || row?.count
      || row?.quantity
      || row?.value
      || "",
    ) || normalizeInputValue(
      row?.lampCount
      || row?.brojLampi
      || row?.count
      || row?.quantity
      || row?.value
      || "",
    );
    const key = normalizeMobileSprLookupText(place);
    if (!place || (!isSection && !lampCount) || !key) {
      return;
    }
    if (seen.has(key)) {
      const existing = normalizedRows.find((entry) => entry.key === key);
      if (existing) {
        existing.lampCount = isSection ? "" : lampCount;
        existing.kind = isSection ? "section" : (rawKind || existing.kind || "measurement");
      }
      return;
    }
    seen.add(key);
    normalizedRows.push({
      key,
      place,
      lampCount: isSection ? "" : lampCount,
      kind: isSection ? "section" : (rawKind || "measurement"),
    });
  });
  return normalizedRows;
}

function normalizeMobileEizIpkVoiceRows(rows = []) {
  const normalizedRows = [];
  const seenSections = new Set();
  (Array.isArray(rows) ? rows : []).forEach((row, index) => {
    const rawKind = normalizeInputValue(row?.kind || row?.type || row?.rowType || "").toLowerCase();
    const isSection = rawKind === "section"
      || rawKind === "floor"
      || rawKind === "etaza"
      || rawKind.startsWith("eta")
      || row?.isSection === true;
    const rawPlace = normalizeInputValue(row?.place || row?.mjesto || row?.location || row?.room || row?.name || "");
    const rawSection = normalizeInputValue(row?.section || row?.floor || row?.group || row?.prostor || row?.prostorija || "");
    const quantity = parseMobileSprVoiceCount(
      row?.lampCount
      || row?.brojLampi
      || row?.count
      || row?.quantity
      || row?.value
      || "",
    ) || "1";
    const count = Math.max(1, Number.parseInt(quantity, 10) || 1);
    const rawPlaceLookup = normalizeMobileSprLookupText(rawPlace);
    const rawLooksLikePoint = rawPlaceLookup.includes("utic")
      || rawPlaceLookup.includes("uti")
      || rawPlaceLookup.includes("suko")
      || rawPlaceLookup.includes("rasvjet")
      || rawPlaceLookup.includes("svjet")
      || rawPlaceLookup.includes("230")
      || rawPlaceLookup.includes("400");
    const inferredSectionPlace = !isSection
      ? cleanMobileEizIpkSectionTitle(rawSection || ((rawPlace && !rawLooksLikePoint) ? rawPlace : ""))
      : "";
    const place = isSection
      ? cleanMobileEizIpkSectionTitle(rawPlace || rawSection)
      : cleanMobileEizIpkVoicePoint([rawLooksLikePoint ? rawPlace : "", row?.point || row?.device || row?.mjernoMjesto || ""].join(" "));
    const key = normalizeMobileSprLookupText(place);
    if (!place || !key) {
      return;
    }
    if (isSection) {
      if (seenSections.has(key)) {
        return;
      }
      seenSections.add(key);
      normalizedRows.push({ key, place, lampCount: "", kind: "section" });
      return;
    }
    if (inferredSectionPlace) {
      const sectionKey = normalizeMobileSprLookupText(inferredSectionPlace);
      if (sectionKey && !seenSections.has(sectionKey)) {
        seenSections.add(sectionKey);
        normalizedRows.push({
          key: sectionKey,
          place: inferredSectionPlace,
          lampCount: "",
          kind: "section",
        });
      }
    }
    for (let repeatedIndex = 0; repeatedIndex < count; repeatedIndex += 1) {
      normalizedRows.push({
        key: `${key}-${index + 1}-${repeatedIndex + 1}`,
        place,
        lampCount: "1",
        kind: rawKind || "measurement",
        protectionType: normalizeInputValue(row?.protectionType || row?.protection || row?.zastita || ""),
        zLpe: normalizeInputValue(row?.zLpe || row?.zlpe || row?.zlp || row?.["ZL-PE"] || row?.["Z(L-PE)"] || ""),
        zLn: normalizeInputValue(row?.zLn || row?.zln || row?.["ZL-N"] || row?.["Z(L-N)"] || ""),
        zLl: normalizeInputValue(row?.zLl || row?.zll || row?.["ZL-L"] || row?.["Z(L-L)"] || ""),
      });
    }
  });
  return normalizedRows;
}

function getMobileSprVoiceResultRows(result = {}) {
  const directRows = Array.isArray(result?.rows) ? result.rows : [];
  const measurementRows = Array.isArray(result?.measurementRows) ? result.measurementRows : [];
  const items = Array.isArray(result?.items) ? result.items : [];
  const nestedRows = Array.isArray(result?.result?.rows) ? result.result.rows : [];
  const rows = directRows.length ? directRows : (measurementRows.length ? measurementRows : (items.length ? items : nestedRows));
  return normalizeMobileSprVoiceRows(rows);
}

