async function buildMobileMeasurementVoiceStructuredRows(body = {}, user = null) {
  if (isMobileEizZudsVoiceRequest(body)) {
    return buildMobileEizZudsVoiceLocalPayload(body);
  }
  if (isMobileEizIpkVoiceRequest(body)) {
    return buildMobileEizIpkVoiceLocalPayload(body);
  }
  if (isMobileTzinVoiceRequest(body)) {
    return buildMobileTzinVoiceLocalPayload(body);
  }
  if (isMobileSzomVoiceRequest(body)) {
    return buildMobileSzomVoiceLocalPayload(body);
  }
  if (isMobileExseVoiceRequest(body)) {
    return buildMobileExseVoiceLocalPayload(body);
  }
  if (isMobileEmmVoiceRequest(body)) {
    return buildMobileEmmVoiceLocalPayload(body);
  }
  return buildMobileSprVoiceStructuredRows(body, user);
}

async function buildMobileSprVoiceStructuredRows(body = {}, user = null) {
  const transcript = normalizeInputValue(body?.transcript || body?.text || "");
  if (!transcript) {
    return { ok: true, provider: "local", rows: [], message: "Diktat je prazan." };
  }

  const config = getOpenAiRuntimeConfig();
  const canCallOpenAi = canUseOpenAiIntegration(user) && config.liveCallsEnabled && !config.dryRun;
  if (!canCallOpenAi) {
    return buildMobileSprVoiceLocalPayload(body, "NexAI nije uključen na serveru, korišten je lokalni parser.");
  }

  try {
    const plan = await buildOpenAiLivePlan({
      purpose: "mobile_spr_voice_measurement_rows",
      templateId: normalizeInputValue(body.templateId),
      workOrderId: normalizeInputValue(body.workOrderId),
      workOrderNumber: normalizeInputValue(body.workOrderNumber),
      modelTier: normalizeInputValue(body.modelTier) || "fast",
      dryRun: false,
      context: {
        transcript,
        serviceCode: normalizeInputValue(body.serviceCode) || "SPR",
        templateTitle: normalizeInputValue(body.templateTitle),
        measurementTable: body.measurementTable && typeof body.measurementTable === "object" ? body.measurementTable : {},
        columns: Array.isArray(body.columns) ? body.columns : [],
      },
      settings: {
        language: "hr-HR",
        task: "Iz diktata izdvoji mjerna mjesta sigurnosne protupanične rasvjete i broj lampi/svjetiljki.",
        rules: [
          "Ako korisnik kaze 'etaza 1. kat', vrati poseban red kind='section', place='Etaza 1. kat', lampCount=''.",
          "Section/etaza red nema broj lampi i mora se prikazati kao puni red u tablici.",
          "Vrati jedan red za svako mjesto ispitivanja.",
          "Podrži diktat oblika 'prodajni prostor 6 skladište 7 hodnik 2', bez riječi komada.",
          "Ako se mjesto ponovi, zadnja izrečena brojčana vrijednost vrijedi.",
          "Ne izmišljaj mjerna mjesta ni brojeve.",
          "Ne vraćaj ostale kolone tablice.",
        ],
      },
      expectedJsonShape: {
        rows: [
          {
            place: "naziv mjesta ispitivanja, npr. Prodajni prostor",
            lampCount: "broj lampi kao string, npr. 7",
            kind: "measurement | section",
            confidence: "high | medium | low",
          },
        ],
        warnings: ["kratke napomene ako diktat nije jasan"],
        summary: "kratak sažetak",
      },
    }, user);
    const rows = getMobileSprVoiceResultRows(plan?.result || {});
    if (!rows.length) {
      return buildMobileSprVoiceLocalPayload(body, "NexAI nije vratio jasne retke, korišten je lokalni parser.");
    }
    return {
      ok: true,
      provider: "openai",
      rows,
      message: `NexAI je strukturirao ${rows.length} redaka.`,
      model: plan?.model || "",
      warnings: Array.isArray(plan?.result?.warnings) ? plan.result.warnings : [],
    };
  } catch (error) {
    return buildMobileSprVoiceLocalPayload(
      body,
      `${buildOpenAiSafeErrorMessage(error)} Korišten je lokalni parser.`,
    );
  }
}

function findMobileSprSheetColumn(sheet = {}, candidates = [], fallbackIndex = -1) {
  const columns = (Array.isArray(sheet?.columns) ? sheet.columns : [])
    .map((column, sourceIndex) => ({ ...column, sourceIndex }))
    .filter((column) => column?.id && !column.computed);
  const candidateKeys = candidates.map(normalizeMobileSprLookupText).filter(Boolean);
  const matchingColumn = columns.find((column) => {
    const key = normalizeMobileSprSheetColumnKey(column, column.sourceIndex);
    return candidateKeys.some((candidate) => key === candidate || key.includes(candidate));
  });
  if (matchingColumn?.id) {
    return matchingColumn;
  }
  return fallbackIndex >= 0 ? columns[fallbackIndex] : null;
}

function applyMobileSprVoiceRowsToSheet(sheet = null, voiceRows = [], options = {}) {
  const normalized = normalizeWorkOrderMeasurementSheet(sheet);
  if (!normalized?.columns?.length || !Array.isArray(voiceRows) || voiceRows.length === 0) {
    return normalized || sheet;
  }
  const numberColumn = findMobileSprSheetColumn(normalized, ["r br", "redni broj", "broj", "rb"], 0);
  const placeColumn = findMobileSprSheetColumn(normalized, ["mjesto ispitivanja", "prostorija", "prostor", "lokacija", "opis"], 1);
  const quantityColumn = findMobileSprSheetColumn(
    normalized,
    Array.isArray(options.quantityCandidates) && options.quantityCandidates.length
      ? options.quantityCandidates
      : ["broj lampi", "lampi", "svjetiljki", "broj svjetiljki"],
    Number.isInteger(options.quantityFallbackIndex) ? options.quantityFallbackIndex : 2,
  );
  const defaultColumnSpecs = Array.isArray(options.defaultColumnSpecs)
    ? options.defaultColumnSpecs
    : [
      { candidates: ["ei", "izmjereno", "izmjerena vrijednost"], fallbackIndex: 3, value: ">2" },
      { candidates: ["eimin", "emin", "minimalno", "zahtijevano"], fallbackIndex: 4, value: "1" },
      { candidates: ["zadovoljava", "ocjena", "ispravno", "pass"], fallbackIndex: 5, value: "DA" },
    ];
  const defaultColumns = defaultColumnSpecs
    .map((spec) => ({
      column: findMobileSprSheetColumn(
        normalized,
        Array.isArray(spec.candidates) ? spec.candidates : [],
        Number.isInteger(spec.fallbackIndex) ? spec.fallbackIndex : -1,
      ),
      value: normalizeInputValue(spec.value),
    }))
    .filter((entry) => entry.column?.id && entry.value);
  if (!placeColumn?.id || !quantityColumn?.id) {
    return normalized;
  }
  const rows = (Array.isArray(normalized.rows) ? normalized.rows : []).map((row, index) => ({
    id: normalizeInputValue(row?.id) || `measurement-row-${index + 1}`,
    cells: { ...(row?.cells || {}) },
    formats: { ...(row?.formats || {}) },
  }));
  const ensureNumbering = (row, index) => {
    if (numberColumn?.id && !normalizeInputValue(row.cells[numberColumn.id])) {
      row.cells[numberColumn.id] = String(index + 1);
    }
  };
  rows.forEach(ensureNumbering);
  const sectionMerges = [];
  const createRow = () => {
    const targetRow = {
      id: `measurement-row-${rows.length + 1}`,
      cells: Object.fromEntries(normalized.columns.map((column) => [column.id, ""])),
      formats: {},
    };
    rows.push(targetRow);
    defaultColumns.forEach((entry) => {
      if (!normalizeInputValue(targetRow.cells[entry.column.id])) {
        targetRow.cells[entry.column.id] = entry.value;
      }
    });
    return targetRow;
  };
  const applyDefaultCells = (row) => {
    defaultColumns.forEach((entry) => {
      if (!normalizeInputValue(row.cells[entry.column.id])) {
        row.cells[entry.column.id] = entry.value;
      }
    });
  };

  voiceRows.forEach((entry) => {
    const placeKey = normalizeMobileSprLookupText(entry?.place);
    const lampCount = normalizeInputValue(entry?.lampCount);
    const kind = normalizeInputValue(entry?.kind).toLowerCase();
    const isSection = kind === "section" || kind === "floor" || !lampCount;
    if (!placeKey || (!isSection && !lampCount)) {
      return;
    }
    let targetRow = isSection
      ? null
      : rows.find((row) => normalizeMobileSprLookupText(row.cells?.[placeColumn.id]) === placeKey);
    if (!targetRow) {
      targetRow = rows.find((row) => (
        !normalizeInputValue(row.cells?.[placeColumn.id])
        && !normalizeInputValue(row.cells?.[quantityColumn.id])
      ));
    }
    if (!targetRow) {
      targetRow = createRow();
    }
    if (isSection) {
      if (numberColumn?.id) targetRow.cells[numberColumn.id] = "";
      targetRow.cells[placeColumn.id] = entry.place;
      targetRow.cells[quantityColumn.id] = "";
      const placeIndex = normalized.columns.findIndex((column) => column.id === placeColumn.id);
      sectionMerges.push({
        rowId: targetRow.id,
        columnId: placeColumn.id,
        rowSpan: 1,
        colSpan: Math.max(1, normalized.columns.length - Math.max(0, placeIndex)),
      });
      return;
    }
    ensureNumbering(targetRow, rows.indexOf(targetRow));
    applyDefaultCells(targetRow);
    if (!normalizeInputValue(targetRow.cells[placeColumn.id])) {
      targetRow.cells[placeColumn.id] = entry.place;
    }
    targetRow.cells[quantityColumn.id] = lampCount;
  });

  return {
    ...normalized,
    rows,
    merges: [
      ...(Array.isArray(normalized.merges) ? normalized.merges.filter((merge) => (
        !sectionMerges.some((sectionMerge) => sectionMerge.rowId === merge?.rowId && sectionMerge.columnId === merge?.columnId)
      )) : []),
      ...sectionMerges,
    ],
  };
}

