function buildMobileDocumentationSprSignatureGroup(model = {}, scopedSnapshot = {}) {
  const signatureMode = normalizeMobileDocumentSignatureMode(model.signatureMode);
  const oib = normalizeSignatureFieldOib(model.signatureFieldOib);
  if (signatureMode !== "digital" || !oib) {
    return null;
  }
  const responsibleUser = findMobileScopedUserById(scopedSnapshot, model.responsiblePersonUserId);
  const fieldCode = normalizeInputValue(model.serviceCode || "SPR") || "SPR";
  const fieldName = buildSignatureFieldName(fieldCode, oib);
  return {
    __docxBlockType: "signature_group",
    type: "signature_group",
    items: [{
      name: getMobileUserDocumentName(responsibleUser) || model.responsiblePerson || `Ispitivač ${fieldCode}`,
      signerUserId: normalizeInputValue(responsibleUser?.id || model.responsiblePersonUserId),
      signerEmail: normalizeInputValue(responsibleUser?.email),
      signerOib: oib,
      signerTitle: getMobileUserDocumentTitle(responsibleUser),
      signerOrganization: normalizeInputValue(model.providerName || model.companyName),
      signatureMode: "digital",
      signatureFieldRole: fieldCode,
      signatureFieldOib: oib,
      preferredField: fieldName,
      fieldName,
      roleLabel: `Ispitivač ${fieldCode}`,
      anchorText: fieldName,
      drawPlaceholder: false,
    }],
  };
}

function prepareMobileDocumentationSprEntry(entry = {}, model = {}, scopedSnapshot = {}) {
  const signatureGroup = buildMobileDocumentationSprSignatureGroup(model, scopedSnapshot);
  if (!signatureGroup) {
    return {
      ...entry,
      exportKind: "documentation_spr",
      signatureGroup: null,
      placeholders: {
        ...(entry.placeholders || {}),
      },
    };
  }
  return {
    ...entry,
    exportKind: "documentation_spr",
    signatureGroup,
    placeholders: {
      ...(entry.placeholders || {}),
      SIGNATURES: signatureGroup,
      POTPISI: signatureGroup,
      DIGITAL_SIGNATURES: signatureGroup,
      DIGITALNI_POTPISI: signatureGroup,
    },
  };
}

async function buildMobileDocumentationSprPdfFile({
  entry = {},
  template = {},
  workOrder = {},
  scopedSnapshot = {},
  common = {},
  fileName = "",
  options = {},
} = {}) {
  const effectiveCommon = common && Object.keys(common).length > 0
    ? common
    : (entry.mobileCommon && typeof entry.mobileCommon === "object" ? entry.mobileCommon : {});
  const model = buildMobileDocumentationSprModel({
    entry,
    template,
    workOrder,
    scopedSnapshot,
    common: effectiveCommon,
  });
  const rows = getMobileSprRows(entry, template, effectiveCommon);
  const preparedEntry = prepareMobileDocumentationSprEntry(entry, model, scopedSnapshot);
  const requestedFileName = fileName
    || entry.fileName
    || model.recordNumber
    || `${normalizeInputValue(model.serviceCode || entry.serviceCode || template.serviceCode || "zapisnik")}-zapisnik.pdf`;
  if (shouldUseMobileDocumentationNativeHtmlPdf(model)) {
    const html = buildDocumentationNativeHtml({
      model,
      rows,
    });
    const htmlFileName = sanitizeGeneratedDocumentFileName(
      requestedFileName.replace(/\.(pdf|docx?|dotx|html?)$/i, "") || model.recordNumber || "zapisnik",
      { fallback: "zapisnik", extension: "html" },
    );
    const pdfBuffer = await convertHtmlToPdfBuffer(html, {
      fileName: htmlFileName,
      title: model.recordNumber || model.reportTitle || model.serviceName || "Zapisnik",
      preferWarmChromium: true,
    });
    const htmlEntry = {
      ...preparedEntry,
      templateReferenceKind: "html",
    };
    return {
      kind: "pdf",
      fileName: sanitizeGeneratedDocumentFileName(requestedFileName, {
        fallback: "zapisnik",
        extension: "pdf",
      }),
      buffer: await finalizeGeneratedTemplatePdfBuffer(pdfBuffer, htmlEntry, options),
      entry: htmlEntry,
    };
  }
  const result = await generateDocumentationSprPdfBlob({
    model,
    rows,
    fileName: requestedFileName,
  });
  const pdfBuffer = Buffer.from(result.bytes ?? []);
  const stampedPdfBuffer = await addPdfDocumentStampToBuffer(
    pdfBuffer,
    getDocumentStampExportSettings(preparedEntry, options.documentStampSettings || options.stampSettings),
  );
  return {
    kind: "pdf",
    fileName: result.fileName || requestedFileName,
    buffer: stampedPdfBuffer,
    entry: preparedEntry,
  };
}

function setMobileGeneratedDocumentEntryNumber(entry = {}, documentNumber = "") {
  const normalizedDocumentNumber = normalizeInputValue(documentNumber);
  if (!entry || !normalizedDocumentNumber) {
    return;
  }
  const baseFileName = buildMobileDocumentTemplateFileBaseName({}, {}, normalizedDocumentNumber);
  const outputFileName = `${baseFileName}.pdf`;
  entry.documentNumber = normalizedDocumentNumber;
  entry.fileName = baseFileName;
  entry.baseFileName = baseFileName;
  if (entry.pdfFileName) {
    entry.pdfFileName = outputFileName;
  }
  if (entry.htmlFileName) {
    entry.htmlFileName = `${baseFileName}.html`;
  }
  if (entry.placeholders && typeof entry.placeholders === "object" && !Array.isArray(entry.placeholders)) {
    Object.assign(entry.placeholders, {
      WORK_ORDER_DOCUMENT_NUMBER: normalizedDocumentNumber,
      DOCUMENT_NUMBER: normalizedDocumentNumber,
      BROJ_DOKUMENTA: normalizedDocumentNumber,
      BROJ_ZAPISNIKA: normalizedDocumentNumber,
      ZAPISNIK_BROJ: normalizedDocumentNumber,
      WORK_ORDER_DOCUMENT_NAME: outputFileName,
      DOCUMENT_NAME: outputFileName,
      NAZIV_DOKUMENTA: outputFileName,
    });
  }
  if (entry.documentRecord && typeof entry.documentRecord === "object" && !Array.isArray(entry.documentRecord)) {
    entry.documentRecord.documentNumber = normalizedDocumentNumber;
    entry.documentRecord.fileName = outputFileName;
    if (entry.documentRecord.fieldValues && typeof entry.documentRecord.fieldValues === "object" && !Array.isArray(entry.documentRecord.fieldValues)) {
      Object.assign(entry.documentRecord.fieldValues, {
        WORK_ORDER_DOCUMENT_NUMBER: normalizedDocumentNumber,
        DOCUMENT_NUMBER: normalizedDocumentNumber,
        BROJ_DOKUMENTA: normalizedDocumentNumber,
        BROJ_ZAPISNIKA: normalizedDocumentNumber,
        ZAPISNIK_BROJ: normalizedDocumentNumber,
        WORK_ORDER_DOCUMENT_NAME: outputFileName,
        DOCUMENT_NAME: outputFileName,
        NAZIV_DOKUMENTA: outputFileName,
      });
    }
  }
}

function applyMobileGeneratedDocumentNumberSequences(entries = []) {
  const groupedEntries = new Map();
  entries.forEach((entry, index) => {
    const groupKey = normalizeInputValue(entry?.numberGroupKey);
    const baseDocumentNumber = normalizeInputValue(entry?.baseDocumentNumber);
    if (!groupKey || !baseDocumentNumber || entry?.exportKind === "handover") {
      return;
    }
    if (!groupedEntries.has(groupKey)) {
      groupedEntries.set(groupKey, []);
    }
    groupedEntries.get(groupKey).push({
      entry,
      index,
      objectSequence: Math.max(0, Number.parseInt(entry?.objectSequence, 10) || 0),
    });
  });

  groupedEntries.forEach((group) => {
    if (group.length <= 1) {
      return;
    }
    group
      .slice()
      .sort((left, right) => (left.objectSequence || 9999) - (right.objectSequence || 9999) || left.index - right.index)
      .forEach((item, itemIndex) => {
        const sequence = item.objectSequence > 0 ? item.objectSequence : itemIndex + 1;
        setMobileGeneratedDocumentEntryNumber(item.entry, `${item.entry.baseDocumentNumber}-${sequence}`);
      });
  });

  entries.forEach((entry) => {
    if (!entry || entry.exportKind === "handover") {
      return;
    }
    delete entry.numberGroupKey;
    delete entry.baseDocumentNumber;
    delete entry.objectSequence;
  });
}

function isMobileAdditionalRecordForService(record = {}, service = {}, serviceIndex = -1) {
  const recordServiceIndex = Number.isFinite(Number(record.serviceIndex)) ? Number(record.serviceIndex) : -1;
  if (recordServiceIndex >= 0 && recordServiceIndex === serviceIndex) {
    return true;
  }
  const recordServiceCode = normalizeInputValue(record.serviceCode).toLowerCase();
  const recordServiceName = normalizeInputValue(record.serviceName).toLowerCase();
  const serviceCode = normalizeInputValue(service?.serviceCode || service?.code).toLowerCase();
  const serviceName = normalizeInputValue(service?.name || service?.serviceName || service?.title).toLowerCase();
  return Boolean(
    (recordServiceCode && serviceCode && recordServiceCode === serviceCode)
    || (recordServiceName && serviceName && recordServiceName === serviceName),
  );
}

function buildMobileGeneratedDocumentPlaceholders(workOrder = {}, service = {}, scopedSnapshot = {}, common = {}) {
  const todayIso = new Date().toISOString().slice(0, 10);
  const inspectionDateIso = normalizeDateOnlyValue(common.inspectionDate) || todayIso;
  const issuedDateIso = normalizeDateOnlyValue(common.issuedDate) || inspectionDateIso;
  const inspectionDateLabel = formatOfferDocumentDate(inspectionDateIso);
  const issuedDateLabel = formatOfferDocumentDate(issuedDateIso);
  const validityMonths = resolveMobileServiceValidityMonths(service, scopedSnapshot, common);
  const validUntilIso = addMonthsToMobileDate(inspectionDateIso, validityMonths);
  const electricalValidUntilIso = addMonthsToMobileDate(inspectionDateIso, common.electricalValidityMonths);
  const tipkaloValidUntilIso = addMonthsToMobileDate(inspectionDateIso, common.tipkaloValidityMonths);
  const basePlaceholders = buildWorkOrderTemplatePlaceholderPayload({
    ...workOrder,
    issuedDate: issuedDateIso,
    inspectionDate: inspectionDateIso,
    issuedPlace: common.issuedPlace,
  }, scopedSnapshot);
  const serviceName = normalizeInputValue(service?.name || service?.serviceName || service?.title || service?.serviceCode);
  const serviceCode = normalizeInputValue(service?.serviceCode || service?.code || service?.shortCode);
  const serviceLabel = serviceName || serviceCode || normalizeInputValue(workOrder.serviceLine);
  const inspectionType = common.inspectionType || serviceLabel;
  const testingLocation = resolveMobileWorkOrderTestingLocation(workOrder, common);
  const signatureGroup = buildMobileSignatureGroup(common, scopedSnapshot);

  return {
    ...basePlaceholders,
    WORK_ORDER_INSPECTION_DATE: inspectionDateLabel,
    DATUM_ISPITIVANJA: inspectionDateLabel,
    INSPECTION_DATE: inspectionDateLabel,
    WORK_ORDER_TESTING_LOCATION: testingLocation,
    TESTING_LOCATION: testingLocation,
    WORK_ORDER_INSPECTION_LOCATION: testingLocation,
    INSPECTION_LOCATION: testingLocation,
    MJESTO_ISPITIVANJA: testingLocation,
    LOKACIJA_ISPITIVANJA: testingLocation,
    MJESTO_PREGLEDA: testingLocation,
    WORK_ORDER_ISSUED_DATE: issuedDateLabel,
    DATUM_IZDAVANJA: issuedDateLabel,
    ISSUED_DATE: issuedDateLabel,
    WORK_ORDER_ISSUED_PLACE: common.issuedPlace,
    MJESTO_IZDAVANJA: common.issuedPlace,
    WORK_ORDER_DOCUMENT_NOTE: common.note,
    NAPOMENA_ZAPISNIKA: common.note,
    WORK_ORDER_INSPECTION_TYPE: inspectionType,
    INSPECTION_TYPE: inspectionType,
    VRSTA_ISPITIVANJA: inspectionType,
    SERVICE_SUMMARY: serviceLabel,
    USLUGA: serviceLabel,
    NAZIV_USLUGE: serviceLabel,
    SERVICE_CODE: serviceCode,
    SIFRA_USLUGE: serviceCode,
    WORK_ORDER_OUTSIDE_TEMPERATURE: common.outsideTemperature,
    TEMPERATURA: common.outsideTemperature,
    VANJSKA_TEMPERATURA: common.outsideTemperature,
    WORK_ORDER_RELATIVE_HUMIDITY: common.relativeHumidity,
    VLAGA: common.relativeHumidity,
    RELATIVNA_VLAZNOST: common.relativeHumidity,
    WORK_ORDER_AIRFLOW_SPEED: common.airflowSpeed,
    STRUJANJE_ZRAKA: common.airflowSpeed,
    WORK_ORDER_WEATHER: common.weather,
    VRIJEME: common.weather,
    WORK_ORDER_GROUND_CONDITION: common.groundCondition,
    STANJE_TLA: common.groundCondition,
    WORK_ORDER_GROUND_RESISTANCE: common.groundResistance,
    OTPOR_TLA: common.groundResistance,
    MEASUREMENT_EQUIPMENT_GROUP: common.measurementEquipmentGroup,
    MJERNA_OPREMA_GRUPA: common.measurementEquipmentGroup,
    SIGNATURE_MODE: common.signatureMode,
    NACIN_POTPISA: common.signatureMode === "digital"
      ? "Digitalni potpis"
      : common.signatureMode === "scan"
        ? "Sken potpisa"
        : "Ručni potpis",
    WORK_ORDER_VALIDITY_MONTHS: validityMonths,
    WORK_ORDER_SERVICE_VALIDITY_MONTHS: validityMonths,
    VRIJEDI_MJESECI: validityMonths,
    WORK_ORDER_VALID_UNTIL: formatOfferDocumentDate(validUntilIso),
    WORK_ORDER_SERVICE_VALID_UNTIL: formatOfferDocumentDate(validUntilIso),
    VRIJEDI_DO: formatOfferDocumentDate(validUntilIso),
    DATUM_VRIJEDI_DO: formatOfferDocumentDate(validUntilIso),
    WORK_ORDER_PANIC_VALID_UNTIL: formatOfferDocumentDate(electricalValidUntilIso),
    WORK_ORDER_PANIC_VALIDITY_MONTHS: common.electricalValidityMonths,
    WORK_ORDER_TIPKALO_VALID_UNTIL: formatOfferDocumentDate(tipkaloValidUntilIso),
    WORK_ORDER_TIPKALO_VALIDITY_MONTHS: common.tipkaloValidityMonths,
    SIGNATURES: signatureGroup,
    POTPISI: signatureGroup,
    DIGITAL_SIGNATURES: signatureGroup,
    DIGITALNI_POTPISI: signatureGroup,
    ...buildMobileInspectionPersonPlaceholders(common, scopedSnapshot),
  };
}

function isMobileHandoverTemplate(template = {}) {
  const title = normalizeInputValue(template?.title || template?.documentType).toLowerCase();
  return isActiveMobileDocumentTemplate(template)
    && isWordTemplateFile(template?.referenceDocument)
    && (title.includes("primopredaj") || title.includes("handover"));
}

function isActiveMobileDocumentTemplate(template = {}) {
  if (!template || typeof template !== "object" || Array.isArray(template)) {
    return false;
  }
  const status = normalizeInputValue(template?.status || "active").toLowerCase();
  return template.isActive !== false
    && template.active !== false
    && !normalizeInputValue(template?.archivedAt)
    && !["archived", "inactive", "deleted", "disabled", "neaktivno", "arhivirano"].includes(status);
}

function findMobileHandoverTemplate(scopedSnapshot = {}) {
  return (Array.isArray(scopedSnapshot.documentTemplates) ? scopedSnapshot.documentTemplates : [])
    .filter(isMobileHandoverTemplate)
    .sort((left, right) => getTemplateTimestampValue(right) - getTemplateTimestampValue(left))
    .at(0) || null;
}

function buildMobileHandoverProtocol(workOrder = {}, scopedSnapshot = {}, common = {}) {
  const workOrderNumber = normalizeInputValue(workOrder.workOrderNumber || workOrder.number);
  const organization = getWorkOrderTemplateOrganization(scopedSnapshot);
  const verifierUser = findMobileHandoverVerifierUser(common, scopedSnapshot);
  const verifierName = getMobileUserDocumentName(verifierUser)
    || normalizeInputValue(common.handoverVerifierLabel)
    || normalizeInputValue(common.completedBy || workOrder.completedBy || workOrder.completedByLabel || workOrder.createdByLabel);
  const organizationAddress = [
    organization.address || "",
    [organization.postalCode, organization.city].filter(Boolean).join(" "),
  ].filter(Boolean).join(", ");
  const services = Array.isArray(workOrder.serviceItems) && workOrder.serviceItems.length > 0
    ? workOrder.serviceItems.map((item) => (item && typeof item === "object" ? item : { name: item }))
    : [{ name: workOrder.serviceLine || "" }];
  const hasAdditionalRecordForService = (service, serviceIndex) => (
    (common.additionalRecords || []).some((record) => isMobileAdditionalRecordForService(record, service, serviceIndex))
  );
  const baseRows = buildWorkOrderTemplateServiceRows(workOrder).map((row, index) => {
    const service = services[index] || {};
    const baseDocumentNumber = normalizeInputValue(row.BROJ_DOKUMENTA)
      || [workOrderNumber, normalizeInputValue(row.SIFRA)].filter(Boolean).join("-");
    const documentNumber = hasAdditionalRecordForService(service, index) && baseDocumentNumber
      ? `${baseDocumentNumber}-1`
      : baseDocumentNumber;
    return {
      id: normalizeInputValue(row.id) || `handover-service-${index + 1}`,
      service: normalizeInputValue(row.USLUGA || row.NAZIV),
      documentNumber,
      quantity: normalizeInputValue(row.KOLICINA || "1") || "1",
      note: normalizeInputValue(row.NAPOMENA || row.NAPOMENA_USLUGE),
      objectName: normalizeInputValue(row.OBJEKT || row.USLUGA_OBJEKT || workOrder.objectName),
    };
  }).filter((row) => row.service || row.documentNumber || row.note);
  const additionalRows = (common.additionalRecords || []).map((record, index) => {
    const serviceIndex = Number.isFinite(Number(record.serviceIndex)) ? Number(record.serviceIndex) : -1;
    const service = services[serviceIndex] || services.find((item) => (
      normalizeInputValue(item?.serviceCode || item?.code).toLowerCase() === normalizeInputValue(record.serviceCode).toLowerCase()
      || normalizeInputValue(item?.name || item?.serviceName || item?.title).toLowerCase() === normalizeInputValue(record.serviceName).toLowerCase()
    )) || {};
    const serviceName = normalizeInputValue(
      record.serviceName
      || service?.name
      || service?.serviceName
      || service?.title
      || service?.serviceCode
      || `Usluga ${serviceIndex + 1 || index + 1}`,
    );
    let objectName = normalizeInputValue(record.objectName);
    if (record.objectId) {
      try {
        const objectWorkOrder = applyMobileSelectedObjectToWorkOrder(workOrder, scopedSnapshot, {
          objectId: record.objectId,
          objectName: record.objectName,
        });
        objectName = normalizeInputValue(objectWorkOrder.objectName || objectWorkOrder.locationObjectName || objectName);
      } catch (error) {
        objectName = objectName || "";
      }
    }
    const sequence = Number.isFinite(Number(record.objectSequence)) ? Number(record.objectSequence) : index + 2;
    const serviceCode = normalizeInputValue(record.serviceCode || service?.serviceCode || service?.code);
    return {
      id: `handover-extra-${serviceIndex >= 0 ? serviceIndex : index}-${sequence}`,
      service: serviceName,
      documentNumber: [workOrderNumber, serviceCode || serviceName, sequence].filter(Boolean).join("-"),
      quantity: "1",
      note: objectName ? "Dodatni zapisnik za drugi objekt" : "Dodatni zapisnik",
      objectName,
    };
  }).filter((row) => row.service || row.documentNumber || row.objectName);
  const workEquipmentRows = buildMobileHandoverWorkEquipmentRows(workOrder, common);
  const hasWorkEquipmentRows = workEquipmentRows.length > 0;
  const workEnvironmentRows = buildMobileHandoverWorkEnvironmentRows(workOrder, common);
  const hasWorkEnvironmentRows = workEnvironmentRows.length > 0;
  const rows = [
    ...baseRows.filter((row) => (
      (!hasWorkEquipmentRows || !normalizeLookupKey(row.service).includes("radna oprema"))
      && (!hasWorkEnvironmentRows || !isMobileHandoverWorkEnvironmentServiceText(row.service))
    )),
    ...additionalRows,
    ...workEquipmentRows,
    ...workEnvironmentRows,
  ];

  return {
    type: "handover_protocol",
    __docxBlockType: "handover_protocol",
    title: "PRIMOPREDAJNI ZAPISNIK",
    subtitle: "O OBAVLJENIM USLUGAMA IZ PODRUČJA ZAŠTITE NA RADU I ZAŠTITE OD POŽARA",
    workOrderNumber,
    customerName: normalizeInputValue(workOrder.companyName),
    customerAddress: normalizeInputValue(workOrder.headquarters),
    customerOib: normalizeInputValue(workOrder.companyOib),
    executorName: normalizeInputValue(organization.name || "SafeNexus"),
    executorAddress: normalizeInputValue(organizationAddress),
    executorOib: normalizeInputValue(organization.oib),
    location: resolveMobileWorkOrderTestingLocation(workOrder, common),
    objectName: normalizeInputValue(workOrder.objectName),
    contractType: normalizeInputValue(workOrder.contractType),
    completedBy: normalizeInputValue(common.completedBy || workOrder.completedBy || workOrder.completedByLabel || workOrder.createdByLabel),
    preparedBy: verifierName,
    executorVerifierName: verifierName,
    issuedDate: normalizeDateOnlyValue(common.issuedDate || common.inspectionDate) || new Date().toISOString().slice(0, 10),
    issuedPlace: normalizeInputValue(common.issuedPlace),
    rows,
    customerSignatureLabel: "Ovjerio naručitelj:",
    executorSignatureLabel: "Ovjerio izvršitelj:",
  };
}

function buildMobileHandoverSpecificationPlaceholder(protocol = {}) {
  const rows = (Array.isArray(protocol.rows) ? protocol.rows : [])
    .map((row, index) => ({
      id: normalizeInputValue(row.id) || `specifikacija-${index + 1}`,
      service: normalizeInputValue(row.service),
      objectName: normalizeInputValue(row.objectName || protocol.objectName),
      documentNumber: normalizeInputValue(row.documentNumber),
      quantity: normalizeInputValue(row.quantity || "1") || "1",
      note: normalizeInputValue(row.note),
    }))
    .filter((row) => row.service || row.documentNumber || row.note);
  return rows.length > 0
    ? {
      type: "handover_specification",
      __docxBlockType: "handover_specification",
      rows,
    }
    : "";
}

function buildMobileHandoverTemplateRows(protocol = {}) {
  return (Array.isArray(protocol.rows) ? protocol.rows : []).map((row, index) => {
    const service = normalizeInputValue(row.service) || "Usluga";
    const objectName = normalizeInputValue(row.objectName || protocol.objectName);
    return {
      id: normalizeInputValue(row.id) || `handover-service-${index + 1}`,
      USLUGA: service,
      NAZIV: service,
      SIFRA: "",
      BROJ_DOKUMENTA: normalizeInputValue(row.documentNumber),
      KOLICINA: normalizeInputValue(row.quantity || "1") || "1",
      NAPOMENA: normalizeInputValue(row.note),
      NAPOMENA_USLUGE: normalizeInputValue(row.note),
      OBJEKT: objectName,
      USLUGA_OBJEKT: objectName,
      USLUGA_S_OBJEKTOM: formatWorkOrderTemplateServiceWithObject(service, objectName),
    };
  });
}

function normalizeMobileHandoverWorkEquipmentRecord(source = {}) {
  const record = source && typeof source === "object" ? source : {};
  const meta = record.meta && typeof record.meta === "object" ? record.meta : {};
  const equipment = record.equipment && typeof record.equipment === "object" ? record.equipment : {};
  const equipmentName = normalizeInputValue(
    meta.equipmentName
      || equipment.name
      || record.equipmentName
      || record.name
      || record.label
      || record.title
      || record.equipmentType,
  );
  const manufacturer = normalizeInputValue(meta.manufacturer || equipment.manufacturer || record.manufacturer);
  const model = normalizeInputValue(meta.model || equipment.model || record.model || record.type);
  const serialNumber = normalizeInputValue(meta.serialNumber || equipment.serialNumber || record.serialNumber);
  const inventoryNumber = normalizeInputValue(meta.inventoryNumber || equipment.inventoryNumber || record.inventoryNumber);
  const recordNumber = normalizeInputValue(meta.recordNumber || record.recordNumber || record.documentNumber);
  const sourceId = normalizeInputValue(
    record.id
      || meta.isznrWorkEquipmentId
      || meta.isznrRecordId
      || record.isznrId
      || record.relatedId
      || serialNumber
      || inventoryNumber
      || equipmentName,
  );
  return {
    id: sourceId,
    equipmentName,
    manufacturer,
    model,
    serialNumber,
    inventoryNumber,
    recordNumber,
  };
}

function formatMobileHandoverWorkEquipmentNote(equipment = {}) {
  return [
    equipment.equipmentName,
    equipment.manufacturer,
    equipment.model,
    equipment.serialNumber,
    equipment.inventoryNumber,
  ].map(normalizeInputValue).filter(Boolean).join("; ");
}

function flattenMobileHandoverManualWorkEquipmentRecords(records = []) {
  return (Array.isArray(records) ? records : []).flatMap((record) => {
    if (!record || typeof record !== "object") {
      return [];
    }
    const parts = Array.isArray(record.parts) ? record.parts : [];
    return [
      record,
      ...parts.map((part, index) => ({
        ...part,
        id: normalizeInputValue(part.id) || `${normalizeInputValue(record.id) || "manual-ro"}-part-${index + 1}`,
        recordNumber: normalizeInputValue(part.recordNumber || record.recordNumber),
      })),
    ];
  });
}

function buildMobileHandoverWorkEquipmentRows(workOrder = {}, common = {}) {
  const submittedRecordNumber = normalizeInputValue(
    common.workEquipmentSubmitResult?.recordNumber
      || common.workEquipmentRecordNumber
      || common.submittedWorkEquipmentRecordNumber,
  );
  const selectedRecords = Array.isArray(common.selectedWorkEquipmentRecords)
    ? common.selectedWorkEquipmentRecords
    : [];
  const manualRecords = Array.isArray(common.manualWorkEquipments)
    ? common.manualWorkEquipments
    : [];
  const rows = [
    ...selectedRecords.map(normalizeMobileHandoverWorkEquipmentRecord),
    ...flattenMobileHandoverManualWorkEquipmentRecords(manualRecords).map(normalizeMobileHandoverWorkEquipmentRecord),
  ].filter((equipment) => equipment.equipmentName || equipment.manufacturer || equipment.model || equipment.serialNumber || equipment.inventoryNumber);
  const seen = new Set();
  return rows.filter((equipment) => {
    const key = [
      equipment.recordNumber,
      equipment.equipmentName,
      equipment.manufacturer,
      equipment.model,
      equipment.serialNumber,
      equipment.inventoryNumber,
    ].map((value) => normalizeInputValue(value).toLowerCase()).join("|");
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  }).map((equipment, index) => ({
    id: `handover-ro-${equipment.id || index + 1}`,
    service: "Ispitivanje radne opreme",
    documentNumber: submittedRecordNumber || equipment.recordNumber || normalizeInputValue(workOrder.workOrderNumber || workOrder.number),
    quantity: "1",
    note: formatMobileHandoverWorkEquipmentNote(equipment),
    objectName: normalizeInputValue(workOrder.objectName),
  }));
}

function normalizeMobileHandoverWorkEnvironmentRecord(source = {}) {
  const record = source && typeof source === "object" ? source : {};
  const meta = record.meta && typeof record.meta === "object" ? record.meta : {};
  const recordNumber = normalizeInputValue(meta.recordNumber || record.recordNumber || record.documentNumber || record.label);
  const sourceLabel = normalizeInputValue(meta.isznrSourceLabel || record.sourceLabel || record.status);
  const environmentKind = normalizeInputValue(meta.environmentKind || record.environmentKind);
  const location = normalizeInputValue(meta.location || record.location);
  const spacesCount = normalizeInputValue(meta.spacesCount || record.spacesCount);
  const measurementsCount = normalizeInputValue(meta.measurementsCount || record.measurementsCount);
  const typesLabel = normalizeInputValue(meta.typesLabel || record.typesLabel);
  const sourceId = normalizeInputValue(
    record.id
      || meta.isznrWorkEnvironmentId
      || meta.isznrRecordId
      || record.isznrId
      || record.relatedId
      || recordNumber
      || sourceLabel,
  );
  return {
    id: sourceId,
    recordNumber,
    sourceLabel,
    environmentKind,
    location,
    spacesCount,
    measurementsCount,
    typesLabel,
  };
}

function formatMobileHandoverWorkEnvironmentNote(record = {}) {
  return [
    record.sourceLabel,
    record.location,
    record.spacesCount ? `${record.spacesCount} prostora` : "",
    record.measurementsCount ? `${record.measurementsCount} mjerenja` : "",
    record.typesLabel,
  ].map(normalizeInputValue).filter(Boolean).join("; ");
}

function isMobileHandoverWorkEnvironmentServiceText(value = "") {
  const normalized = normalizeIsznrWorkEnvironmentText(value);
  if (!normalized) {
    return false;
  }
  if (normalized.includes("radna oprema") || normalized.includes("radne opreme")) {
    return false;
  }
  return normalized.includes("radni okolis")
    || normalized.includes("radnog okolisa")
    || normalized.includes("fizikalni cimbenici")
    || normalized.includes("kemijski cimbenici")
    || normalized === "rok"
    || normalized.startsWith("rok ");
}

function buildMobileHandoverWorkEnvironmentRows(workOrder = {}, common = {}) {
  const selectedRecords = Array.isArray(common.selectedWorkEnvironmentRecords)
    ? common.selectedWorkEnvironmentRecords
    : [];
  const submittedRecordNumber = normalizeInputValue(
    common.workEnvironmentSubmitResult?.recordNumber
    || common.workEnvironmentRecordNumber
    || common.workEnvironmentSubmitResult?.submittedRecordNumber,
  );
  const seen = new Set();
  return selectedRecords
    .map(normalizeMobileHandoverWorkEnvironmentRecord)
    .filter((record) => record.recordNumber || record.sourceLabel || record.location)
    .filter((record) => {
      const key = [
        record.recordNumber,
        record.sourceLabel,
        record.location,
      ].map((value) => normalizeInputValue(value).toLowerCase()).join("|");
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .map((record, index) => ({
      id: `handover-rok-${record.id || index + 1}`,
      service: record.environmentKind === "chemical"
        ? "Ispitivanje kemijskih čimbenika radnog okoliša"
        : "Ispitivanje fizikalnih čimbenika radnog okoliša",
      documentNumber: submittedRecordNumber || record.recordNumber || normalizeInputValue(workOrder.workOrderNumber || workOrder.number),
      quantity: record.measurementsCount || record.spacesCount || "1",
      note: formatMobileHandoverWorkEnvironmentNote(record),
      objectName: normalizeInputValue(workOrder.objectName),
    }));
}

function buildMobileHandoverExportEntry(workOrder = {}, scopedSnapshot = {}, common = {}) {
  if (common.includeHandoverProtocol === false) {
    return null;
  }
  const template = findMobileHandoverTemplate(scopedSnapshot);
  if (!template) {
    return null;
  }
  const handoverProtocol = buildMobileHandoverProtocol(workOrder, scopedSnapshot, common);
  if (!handoverProtocol.rows.length) {
    return null;
  }
  const specificationPlaceholder = buildMobileHandoverSpecificationPlaceholder(handoverProtocol);
  const rows = buildMobileHandoverTemplateRows(handoverProtocol);
  const issuedDate = formatOfferDocumentDate(handoverProtocol.issuedDate);
  const servicesTableText = rows
    .map((row) => [row.USLUGA_S_OBJEKTOM || row.USLUGA, row.BROJ_DOKUMENTA, row.KOLICINA, row.NAPOMENA].filter(Boolean).join(" | "))
    .join("\n");
  const workOrderNumber = normalizeInputValue(handoverProtocol.workOrderNumber || workOrder.workOrderNumber || workOrder.number);
  const baseFileName = sanitizeGeneratedDocumentFileName(
    `Primopredaja ${workOrderNumber || workOrder.id || "RN"}`,
    { fallback: "primopredaja", extension: "" },
  ).replace(/\.$/, "");
  const signatureGroup = buildMobileHandoverSignatureGroup(common, scopedSnapshot)
    || buildMobileSignatureGroup(common, scopedSnapshot);
  const placeholders = {
    ...buildWorkOrderTemplatePlaceholderPayload({
      ...workOrder,
      completedBy: handoverProtocol.completedBy,
      issuedDate: handoverProtocol.issuedDate,
      issuedPlace: handoverProtocol.issuedPlace,
    }, scopedSnapshot),
    PRIMOPREDAJNI_ZAPISNIK: handoverProtocol,
    SPECIFIKACIJA: specificationPlaceholder,
    Specifikacija: specificationPlaceholder,
    specifikacija: specificationPlaceholder,
    PRIMOPREDAJA_RN_BROJ: workOrderNumber,
    RN_BROJ: workOrderNumber,
    BROJ_RADNOG_NALOGA: workOrderNumber,
    NARUCITELJ_NAZIV: handoverProtocol.customerName,
    NARUCITELJ_SJEDISTE: handoverProtocol.customerAddress,
    NARUCITELJ_OIB: handoverProtocol.customerOib,
    TVRTKA_NAZIV: handoverProtocol.customerName,
    TVRTKA: handoverProtocol.customerName,
    TVRTKA_SJEDISTE: handoverProtocol.customerAddress,
    SJEDISTE: handoverProtocol.customerAddress,
    TVRTKA_OIB: handoverProtocol.customerOib,
    OIB: handoverProtocol.customerOib,
    IZVRSITELJ_NAZIV: handoverProtocol.executorName,
    IZVRSITELJ_SJEDISTE: handoverProtocol.executorAddress,
    IZVRSITELJ_OIB: handoverProtocol.executorOib,
    LOKACIJA_ISPITIVANJA: handoverProtocol.location,
    LOKACIJA: handoverProtocol.location,
    OBJEKT: handoverProtocol.objectName,
    OBJEKT_ISPITIVANJA: handoverProtocol.objectName,
    OBJECT_NAME: handoverProtocol.objectName,
    VRSTA_UGOVORA: handoverProtocol.contractType,
    UGOVOR: handoverProtocol.contractType,
    DATUM_IZDAVANJA: issuedDate,
    MJESTO_IZDAVANJA: handoverProtocol.issuedPlace,
    ZAVRSIO_IME: handoverProtocol.completedBy,
    ZAVRSIO_RADNI_NALOG: handoverProtocol.completedBy,
    RN_ZAVRSIO: handoverProtocol.completedBy,
    IZRADIO_IME: handoverProtocol.preparedBy || handoverProtocol.completedBy,
    IZRADIO_ZAPISNIK: handoverProtocol.preparedBy || handoverProtocol.completedBy,
    PRIMOPREDAJU_IZRADIO: handoverProtocol.preparedBy || handoverProtocol.completedBy,
    OVJERIO_IZVRSITELJ_IME: handoverProtocol.executorVerifierName || handoverProtocol.preparedBy || handoverProtocol.completedBy,
    USLUGE_REDOVI: rows,
    USLUGE_TABLICA: servicesTableText,
    USLUGE: rows.map((row, index) => `${index + 1}. ${row.USLUGA}`).join("\n"),
    OVJERIO_NARUCITELJ: handoverProtocol.customerSignatureLabel,
    OVJERIO_IZVRSITELJ: handoverProtocol.executorSignatureLabel,
    MJESTO_DATUM: `${handoverProtocol.issuedPlace ? `U ${handoverProtocol.issuedPlace}, ` : "U Zagrebu, "}${issuedDate}`.trim(),
    SIGNATURES: signatureGroup,
    POTPISI: signatureGroup,
    DIGITAL_SIGNATURES: signatureGroup,
    DIGITALNI_POTPISI: signatureGroup,
  };
  const outputFileName = `${baseFileName}.pdf`;
  const objectId = getMobileWorkOrderLocationObjectId(workOrder);
  const objectName = normalizeInputValue(handoverProtocol.objectName || workOrder.objectName || workOrder.locationObjectName);

  return {
    templateId: normalizeInputValue(template.id),
    workOrderId: normalizeInputValue(workOrder.id),
    exportKind: "handover",
    forceRenderModel: false,
    baseFileName,
    fileName: baseFileName,
    templateReferenceKind: "word",
    signatureGroup,
    htmlFileName: `${baseFileName}.html`,
    pdfFileName: outputFileName,
    placeholders,
    appendBlocks: [],
    documentRecord: {
      templateId: normalizeInputValue(template.id),
      templateTitle: "Primopredajni zapisnik",
      documentType: "Primopredajni zapisnik",
      workOrderNumber,
      documentNumber: `${workOrderNumber}-PRIMOPREDAJA`,
      fileName: outputFileName,
      companyId: normalizeInputValue(workOrder.companyId),
      locationId: normalizeInputValue(workOrder.locationId),
      objectId,
      objectName,
      inspectionDate: common.inspectionDate,
      issuedDate: common.issuedDate,
      fieldValues: placeholders,
    },
    renderModel: {
      title: "PRIMOPREDAJNI ZAPISNIK",
      documentType: "Primopredajni zapisnik",
      workOrderNumber,
      serviceCode: "PRIMOPREDAJA",
      status: normalizeInputValue(workOrder.status),
      company: {
        name: handoverProtocol.customerName,
        headquarters: handoverProtocol.customerAddress,
        oib: handoverProtocol.customerOib,
      },
      location: {
        name: handoverProtocol.location,
        region: normalizeInputValue(workOrder.region),
        coordinates: normalizeInputValue(workOrder.coordinates),
      },
      object: {
        name: handoverProtocol.objectName,
        code: "",
        description: "",
      },
      blocks: [handoverProtocol],
    },
  };
}

function buildMobileWorkOrderGeneratedDocumentEntries(workOrder = {}, scopedSnapshot = {}, wizardInput = {}) {
  const common = normalizeMobileWorkOrderDocumentWizardInput(wizardInput);
  const documentTemplates = Array.isArray(scopedSnapshot.documentTemplates) ? scopedSnapshot.documentTemplates : [];
  const templateById = new Map(documentTemplates.map((template) => [String(template.id), template]));
  const services = Array.isArray(workOrder.serviceItems) && workOrder.serviceItems.length > 0
    ? workOrder.serviceItems.map((item) => (item && typeof item === "object" ? item : { name: item }))
    : [{ name: workOrder.serviceLine || "" }];
  const entries = [];
  const seenPairs = new Set();

  const appendEntriesForService = (service, serviceIndex, generationWorkOrder = workOrder, options = {}) => {
    const nativePreset = getMobileNativeDocumentationPresetForService(service, serviceIndex, scopedSnapshot);
    const nativeServiceCode = nativePreset?.serviceCode || "";
    const linkedTemplates = getMobileWorkOrderServiceTemplateIds(service, scopedSnapshot)
      .map((templateId) => templateById.get(String(templateId)))
      .filter(isActiveMobileDocumentTemplate)
      .filter((template) => mobileDocumentTemplateMatchesNativeServiceCode(template, nativeServiceCode));
    const nativeTemplate = linkedTemplates.length === 0
      ? buildMobileNativeDocumentationTemplate(service, serviceIndex, generationWorkOrder, scopedSnapshot)
      : null;
    const templatesForService = nativeTemplate ? [nativeTemplate] : linkedTemplates;

    templatesForService.forEach((template) => {
      const objectId = getMobileWorkOrderLocationObjectId(generationWorkOrder);
      const objectSequence = Number.isFinite(Number(options.objectSequence)) ? Number(options.objectSequence) : 1;
      const pairKey = `${String(workOrder.id)}::${serviceIndex}::${String(template.id)}::${objectId || "no-object"}::${objectSequence}`;
      if (seenPairs.has(pairKey)) {
        return;
      }
      seenPairs.add(pairKey);
      const basePlaceholders = buildMobileGeneratedDocumentPlaceholders(generationWorkOrder, service, scopedSnapshot, common);
      const fieldSheets = buildMobileDocumentTemplateFieldSheets(template, generationWorkOrder, service, scopedSnapshot, common);
      const measurementPlaceholders = buildMobileDocumentTemplateMeasurementPlaceholders(template, fieldSheets);
      const customFieldPayload = buildMobileDocumentTemplateCustomFieldPayload(template, common, {
        ...basePlaceholders,
        ...measurementPlaceholders,
      });
      const listPayload = buildMobileDocumentTemplateListPayload(template, scopedSnapshot, common);
      const placeholders = {
        ...basePlaceholders,
        ...measurementPlaceholders,
        ...customFieldPayload.placeholders,
        ...listPayload.placeholders,
      };
      const signatureGroup = basePlaceholders.SIGNATURES && typeof basePlaceholders.SIGNATURES === "object"
        ? basePlaceholders.SIGNATURES
        : null;
      const templateReferenceKind = template.referenceDocument && isWordTemplateFile(template.referenceDocument)
        ? "word"
        : template.referenceDocument && isHtmlTemplateFile(template.referenceDocument)
          ? "html"
          : "";
      const baseDocumentNumber = buildMobileDocumentTemplateDocumentNumber(service, generationWorkOrder, template, serviceIndex);
      const documentNumber = objectSequence > 1
        ? `${baseDocumentNumber}-${objectSequence}`
        : baseDocumentNumber;
      const baseFileName = buildMobileDocumentTemplateFileBaseName(template, generationWorkOrder, documentNumber);
      const outputFileName = `${baseFileName}.pdf`;
      const objectName = normalizeInputValue(
        generationWorkOrder.objectName
        || generationWorkOrder.locationObjectName
        || generationWorkOrder.locationObject?.name,
      );
      Object.assign(placeholders, {
        WORK_ORDER_DOCUMENT_NUMBER: documentNumber,
        DOCUMENT_NUMBER: documentNumber,
        BROJ_DOKUMENTA: documentNumber,
        BROJ_ZAPISNIKA: documentNumber,
        ZAPISNIK_BROJ: documentNumber,
        WORK_ORDER_DOCUMENT_NAME: outputFileName,
        DOCUMENT_NAME: outputFileName,
        NAZIV_DOKUMENTA: outputFileName,
      });
      const validityMonths = resolveMobileServiceValidityMonths(service, scopedSnapshot, common);
      const validUntilIso = addMonthsToMobileDate(common.inspectionDate, validityMonths);
      const entryAttachments = resolveMobileDocumentationAttachmentsForTemplate(common, template.id);
      const trackedDates = validUntilIso
        ? [{
          fieldId: "WORK_ORDER_VALID_UNTIL",
          fieldKey: "WORK_ORDER_VALID_UNTIL",
          label: "Vrijedi do",
          value: validUntilIso,
        }]
        : [];
      const fieldValues = {
        ...placeholders,
        ...customFieldPayload.fieldValues,
        ...listPayload.fieldValues,
        ...(trackedDates.length > 0 ? { [GENERATED_DOCUMENT_PERIODICS_TRACKED_DATES_KEY]: trackedDates } : {}),
      };
      entries.push({
        templateId: String(template.id),
        workOrderId: String(workOrder.id),
        numberGroupKey: `${String(workOrder.id)}::${serviceIndex}::${String(template.id)}`,
        baseDocumentNumber,
        objectSequence,
        serviceCode: getMobileDocumentTemplateServiceCode(service, serviceIndex),
        serviceName: normalizeInputValue(service?.name || service?.serviceName || service?.title || service?.serviceCode),
        mobileCommon: common,
        fileName: baseFileName,
        baseFileName,
        documentNumber,
        templateTitle: normalizeInputValue(template.title || template.documentType || "Zapisnik"),
        workOrderNumber: normalizeInputValue(generationWorkOrder.workOrderNumber || generationWorkOrder.number),
        companyName: normalizeInputValue(generationWorkOrder.companyName),
        locationName: normalizeInputValue(generationWorkOrder.locationName),
        objectId,
        objectName,
        templateReferenceKind,
        signatureGroup,
        placeholders,
        signatureMode: common.signatureMode,
        inspectionDate: common.inspectionDate,
        issuedDate: common.issuedDate,
        expirationDate: validUntilIso,
        documentRecord: {
          templateTitle: normalizeInputValue(template.title || template.documentType || "Zapisnik"),
          workOrderNumber: normalizeInputValue(generationWorkOrder.workOrderNumber || generationWorkOrder.number),
          documentNumber,
          fileName: outputFileName,
          companyId: normalizeInputValue(generationWorkOrder.companyId),
          locationId: normalizeInputValue(generationWorkOrder.locationId),
          objectId,
          objectName,
          inspectionDate: common.inspectionDate,
          issuedDate: common.issuedDate,
          expirationDate: validUntilIso,
          fieldValues,
          fieldSheets,
          attachments: entryAttachments,
        },
        attachments: entryAttachments,
      });
    });
  };

  services.forEach((service, serviceIndex) => {
    appendEntriesForService(service, serviceIndex, workOrder);
  });

  const additionalRecords = [...(common.additionalRecords || [])];
  if (common.addAllObjects) {
    const currentObjectId = getMobileWorkOrderLocationObjectId(workOrder);
    const allLocationObjects = buildMobileWorkOrderLocationObjectOptions(scopedSnapshot.locationObjects)
      .filter((object) => (
        (!workOrder.companyId || String(object.companyId) === String(workOrder.companyId))
        && (!workOrder.locationId || String(object.locationId) === String(workOrder.locationId))
        && String(object.id || "") !== String(currentObjectId || "")
      ));
    const targetServiceIndexes = [];
    if (common.addAllObjectsServiceIndex >= 0 && services[common.addAllObjectsServiceIndex]) {
      targetServiceIndexes.push(common.addAllObjectsServiceIndex);
    } else if (common.addAllObjectsServiceCode) {
      services.forEach((service, index) => {
        const code = normalizeInputValue(service?.serviceCode || service?.code || service?.shortCode).toLowerCase();
        if (code === common.addAllObjectsServiceCode.toLowerCase()) {
          targetServiceIndexes.push(index);
        }
      });
    }
    if (targetServiceIndexes.length === 0 && services.length > 0) {
      targetServiceIndexes.push(0);
    }
    const usedKeys = new Set(additionalRecords.map((record) => [
      String(record.serviceIndex),
      String(record.objectId || record.objectName || ""),
    ].join("::")));
    targetServiceIndexes.forEach((serviceIndex) => {
      const service = services[serviceIndex] || {};
      allLocationObjects.forEach((object, objectIndex) => {
        const key = [String(serviceIndex), String(object.id || object.name || "")].join("::");
        if (usedKeys.has(key)) {
          return;
        }
        usedKeys.add(key);
        additionalRecords.push({
          serviceIndex,
          serviceCode: normalizeInputValue(service.serviceCode || service.code || service.shortCode),
          serviceName: normalizeInputValue(service.name || service.serviceName || service.title),
          objectId: object.id,
          objectName: object.name,
          objectSequence: objectIndex + 2,
        });
      });
    });
  }

  additionalRecords.forEach((record, index) => {
    const serviceIndex = Number.isFinite(Number(record.serviceIndex)) ? Number(record.serviceIndex) : -1;
    const service = services[serviceIndex] || services.find((item) => (
      normalizeInputValue(item?.serviceCode || item?.code).toLowerCase() === normalizeInputValue(record.serviceCode).toLowerCase()
      || normalizeInputValue(item?.name || item?.serviceName || item?.title).toLowerCase() === normalizeInputValue(record.serviceName).toLowerCase()
    ));
    if (!service) {
      return;
    }
    try {
      const generationWorkOrder = applyMobileSelectedObjectToWorkOrder(workOrder, scopedSnapshot, {
        objectId: record.objectId,
        objectName: record.objectName,
        executors: common.executors,
      });
      appendEntriesForService(service, serviceIndex >= 0 ? serviceIndex : services.indexOf(service), generationWorkOrder, {
        objectSequence: Number.isFinite(Number(record.objectSequence)) ? Number(record.objectSequence) : index + 2,
      });
    } catch (error) {
      console.warn("Preskačem dodatni mobilni zapisnik za objekt.", error?.message || error);
    }
  });

  applyMobileGeneratedDocumentNumberSequences(entries);

  const handoverEntry = buildMobileHandoverExportEntry(workOrder, scopedSnapshot, common);
  if (handoverEntry) {
    entries.push(handoverEntry);
  }

  return entries.sort((left, right) => (
    normalizeInputValue(left.templateTitle || left.documentRecord?.templateTitle || left.exportKind || "")
      .localeCompare(
        normalizeInputValue(right.templateTitle || right.documentRecord?.templateTitle || right.exportKind || ""),
        "hr",
      )
  ));
}

function normalizePushLookupKey(value = "") {
  return normalizeInputValue(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function getWorkOrderPushNumber(workOrder = {}) {
  return normalizeInputValue(workOrder.workOrderNumber || workOrder.number || workOrder.id || "RN");
}

function getWorkOrderPushExecutorLabels(workOrder = {}) {
  const source = Array.isArray(workOrder.executors)
    ? workOrder.executors
    : [workOrder.executor1, workOrder.executor2];
  return [...new Set(source.map(normalizeInputValue).filter(Boolean))];
}

function buildPushUserLookup(scopedSnapshot = {}) {
  const lookup = new Map();
  const addCandidate = (candidate, userId) => {
    const key = normalizePushLookupKey(candidate);
    const id = normalizeInputValue(userId);
    if (!key || !id) return;
    if (!lookup.has(key)) {
      lookup.set(key, new Set());
    }
    lookup.get(key).add(id);
  };

  (scopedSnapshot.users ?? []).forEach((user) => {
    if (user?.isActive === false) return;
    const fullName = normalizeInputValue(user.fullName || [user.firstName, user.lastName].filter(Boolean).join(" "));
    const candidates = [
      user.id,
      user.email,
      user.username,
      user.legacyUsername,
      user.displayName,
      fullName,
      [user.firstName, user.lastName].filter(Boolean).join(" "),
    ];
    candidates.forEach((candidate) => {
      addCandidate(candidate, user.id);
    });
  });
  return lookup;
}

function resolveWorkOrderPushUserIds(workOrder = {}, scopedSnapshot = {}) {
  const lookup = buildPushUserLookup(scopedSnapshot);
  const ids = new Set();
  const activeUserIds = new Set((scopedSnapshot.users ?? [])
    .filter((user) => user?.isActive !== false)
    .map((user) => normalizeInputValue(user.id))
    .filter(Boolean));
  normalizeMobileDocumentWizardArray(workOrder.watcherIds || workOrder.watchers || workOrder.watcherUserIds)
    .forEach((watcherId) => {
      if (activeUserIds.has(watcherId)) {
        ids.add(watcherId);
      }
    });
  getWorkOrderPushExecutorLabels(workOrder).forEach((executorLabel) => {
    const matchingIds = lookup.get(normalizePushLookupKey(executorLabel));
    if (matchingIds instanceof Set) {
      matchingIds.forEach((id) => ids.add(id));
    } else if (matchingIds) {
      ids.add(matchingIds);
    }
  });
  return [...ids];
}

function resolveAddedWatcherPushUserIds(currentWorkOrder = {}, nextWorkOrder = {}, scopedSnapshot = {}) {
  const activeUserIds = new Set((scopedSnapshot.users ?? [])
    .filter((user) => user?.isActive !== false)
    .map((user) => normalizeInputValue(user.id))
    .filter(Boolean));
  const currentIds = new Set(normalizeMobileDocumentWizardArray(currentWorkOrder.watcherIds || currentWorkOrder.watchers || currentWorkOrder.watcherUserIds));
  return normalizeMobileDocumentWizardArray(nextWorkOrder.watcherIds || nextWorkOrder.watchers || nextWorkOrder.watcherUserIds)
    .filter((id) => activeUserIds.has(id) && !currentIds.has(id));
}

function resolveAdminPushUserIds(scopedSnapshot = {}) {
  return [...new Set((scopedSnapshot.users ?? [])
    .filter((user) => user?.isActive !== false)
    .filter((user) => ["super_admin", "admin"].includes(normalizeInputValue(user.role)))
    .map((user) => normalizeInputValue(user.id))
    .filter(Boolean))];
}

function resolveTodoTaskPushUserIds(todoTask = {}, scopedSnapshot = {}, excludedUserIds = []) {
  const ids = new Set();
  const excluded = new Set((Array.isArray(excludedUserIds) ? excludedUserIds : []).map((id) => String(id)).filter(Boolean));
  const assignedToUserId = normalizeInputValue(todoTask.assignedToUserId);
  if (assignedToUserId) {
    ids.add(assignedToUserId);
  }
  (Array.isArray(todoTask.invitedUsers) ? todoTask.invitedUsers : []).forEach((entry) => {
    const userId = normalizeInputValue(entry?.userId);
    if (userId) {
      ids.add(userId);
    }
  });
  const workOrderId = normalizeInputValue(todoTask.workOrderId);
  if (workOrderId) {
    const workOrder = (scopedSnapshot.workOrders ?? []).find((entry) => String(entry.id) === String(workOrderId));
    if (workOrder) {
      resolveWorkOrderPushUserIds(workOrder, scopedSnapshot).forEach((id) => ids.add(String(id)));
    }
  }
  excluded.forEach((id) => ids.delete(id));
  return [...ids];
}

function addLookupIdsToSet(lookup, key, ids) {
  const matchingIds = lookup.get(key);
  if (matchingIds instanceof Set) {
    matchingIds.forEach((id) => ids.add(id));
  } else if (matchingIds) {
    ids.add(matchingIds);
  }
}

function resolveAddedExecutorPushUserIds(currentWorkOrder = {}, nextWorkOrder = {}, scopedSnapshot = {}) {
  const lookup = buildPushUserLookup(scopedSnapshot);
  const currentKeys = new Set(getWorkOrderPushExecutorLabels(currentWorkOrder).map(normalizePushLookupKey));
  const ids = new Set();
  getWorkOrderPushExecutorLabels(nextWorkOrder).forEach((executorLabel) => {
    const key = normalizePushLookupKey(executorLabel);
    if (!key || currentKeys.has(key)) return;
    addLookupIdsToSet(lookup, key, ids);
  });
  return [...ids];
}

const PUSH_PREFERENCE_KEY_BY_TYPE = Object.freeze({
  work_order_assigned: "workOrderAssigned",
  work_order_executor_added: "workOrderAssigned",
  work_order_status_changed: "workOrderStatus",
  work_order_closed: "workOrderStatus",
  work_order_execution_due: "workOrderExecutionDue",
  work_order_due: "workOrderDue",
  document_ready: "documentReady",
  document_signature: "documentSignature",
  signature_rejected: "documentSignature",
  periodics_digest: "periodicsDigest",
  vehicle_reservation: "vehicleReservation",
  vehicle_return_due: "vehicleReturn",
  vehicle_due: "vehicleReturn",
  measurement_equipment_due: "measurementEquipment",
  safety_authorization_due: "safetyAuthorization",
  training_due: "training",
  reminder_due: "reminders",
  todo_comment: "todoComments",
  absence_request: "absence",
  absence_due: "absence",
  signup_request: "signupRequests",
  foundation_document_due: "foundationDocuments",
  public_procurement_due: "publicProcurements",
});

function resolvePushPreferenceKey(payload = {}, options = {}) {
  const explicitKey = normalizeInputValue(options.preferenceKey || payload?.data?.preferenceKey);
  if (explicitKey) {
    return explicitKey;
  }

  return PUSH_PREFERENCE_KEY_BY_TYPE[normalizeInputValue(payload?.data?.type)] || "";
}

function isPushPreferenceEnabled(preferences = {}, preferenceKey = "") {
  const normalized = normalizePushNotificationPreferences(preferences);
  if (!normalized.enabled) {
    return false;
  }
  if (!preferenceKey) {
    return true;
  }
  if (!Object.prototype.hasOwnProperty.call(normalized, preferenceKey)) {
    return true;
  }
  return Boolean(normalized[preferenceKey]);
}

async function filterPushUserIdsByPreferences(userIds = [], payload = {}, options = {}) {
  const ids = [...new Set((Array.isArray(userIds) ? userIds : []).map((id) => String(id)).filter(Boolean))];
  if (ids.length === 0 || options.bypassPreferences === true) {
    return ids;
  }

  const preferenceKey = resolvePushPreferenceKey(payload, options);
  if (!preferenceKey || typeof tenantRepository.getPushNotificationPreferencesForUserIds !== "function") {
    return ids;
  }

  const preferencesByUserId = await tenantRepository.getPushNotificationPreferencesForUserIds(ids);
  return ids.filter((id) => isPushPreferenceEnabled(preferencesByUserId.get(String(id)), preferenceKey));
}

async function sendPushToUserIds(userIds = [], payload = {}, options = {}) {
  const ids = [...new Set((Array.isArray(userIds) ? userIds : []).map((id) => String(id)).filter(Boolean))];
  if (ids.length === 0) {
    return { sent: 0, skipped: true, reason: "no-recipients" };
  }

  const filteredIds = await filterPushUserIdsByPreferences(ids, payload, options);
  if (filteredIds.length === 0) {
    return {
      sent: 0,
      skipped: true,
      reason: "preferences-disabled",
      preferenceKey: resolvePushPreferenceKey(payload, options),
    };
  }

  if (typeof tenantRepository.listPushTokensForUserIds !== "function") {
    return { sent: 0, skipped: true, reason: "token-store-unavailable" };
  }

  if (!(await isFirebasePushConfigured())) {
    return { sent: 0, skipped: true, reason: "firebase-not-configured" };
  }

  const tokens = await tenantRepository.listPushTokensForUserIds(filteredIds);
  const uniqueTokens = [...new Map(tokens.map((item) => [item.token, item])).values()].filter((item) => item.token);
  if (uniqueTokens.length === 0) {
    return { sent: 0, skipped: true, reason: "no-tokens" };
  }

  const results = await Promise.allSettled(
    uniqueTokens.map((item) => sendFirebasePushMessage(item.token, payload)),
  );
  const failed = results.filter((result) => result.status === "rejected");
  failed.slice(0, 3).forEach((result) => {
    console.warn("[push] Slanje push poruke nije uspjelo:", result.reason?.message || result.reason);
  });
  return {
    sent: results.filter((result) => result.status === "fulfilled").length,
    failed: failed.length,
  };
}

function queuePushToUserIds(userIds = [], payload = {}, options = {}) {
  void sendPushToUserIds(userIds, payload, options)
    .then((result) => {
      if (result?.skipped) {
        console.info("[push] preskoceno", JSON.stringify({
          reason: result.reason || "unknown",
          recipients: Array.isArray(userIds) ? userIds.length : 0,
          preferenceKey: result.preferenceKey || resolvePushPreferenceKey(payload, options),
          type: payload?.data?.type || "",
          workOrderId: payload?.data?.workOrderId || "",
          workOrderNumber: payload?.data?.workOrderNumber || "",
        }));
      } else if (result?.sent || result?.failed) {
        console.info("[push] poslano", JSON.stringify({
          sent: result.sent || 0,
          failed: result.failed || 0,
          recipients: Array.isArray(userIds) ? userIds.length : 0,
          preferenceKey: resolvePushPreferenceKey(payload, options),
          type: payload?.data?.type || "",
          workOrderId: payload?.data?.workOrderId || "",
          workOrderNumber: payload?.data?.workOrderNumber || "",
        }));
      }
    })
    .catch((error) => {
      console.warn("[push] Ne mogu poslati push poruku:", error.message);
    });
}

function queueWorkOrderCreatedPush(workOrder = {}, scopedSnapshot = {}) {
  const recipientIds = resolveWorkOrderPushUserIds(workOrder, scopedSnapshot);
  const workOrderNumber = getWorkOrderPushNumber(workOrder);
  queuePushToUserIds(recipientIds, {
    title: "Novi radni nalog",
    body: `Dodijeljen vam je novi radni nalog ${workOrderNumber}`,
    data: {
      type: "work_order_assigned",
      workOrderId: normalizeInputValue(workOrder.id),
      workOrderNumber,
      status: normalizeInputValue(workOrder.status),
      companyName: normalizeInputValue(workOrder.companyName),
      locationName: normalizeInputValue(workOrder.locationName),
    },
  });
}

function queueWorkOrderUpdatedPush(currentWorkOrder = {}, nextWorkOrder = {}, scopedSnapshot = {}) {
  const workOrderNumber = getWorkOrderPushNumber(nextWorkOrder);
  const addedExecutorIds = resolveAddedExecutorPushUserIds(currentWorkOrder, nextWorkOrder, scopedSnapshot);
  if (addedExecutorIds.length > 0) {
    queuePushToUserIds(addedExecutorIds, {
      title: "Dodani ste na radni nalog",
      body: `Dodani ste kao izvršitelj na radni nalog ${workOrderNumber}`,
      data: {
        type: "work_order_executor_added",
        workOrderId: normalizeInputValue(nextWorkOrder.id),
        workOrderNumber,
        status: normalizeInputValue(nextWorkOrder.status),
      },
    });
  }

  const addedWatcherIds = resolveAddedWatcherPushUserIds(currentWorkOrder, nextWorkOrder, scopedSnapshot);
  if (addedWatcherIds.length > 0) {
    queuePushToUserIds(addedWatcherIds, {
      title: "Pratite radni nalog",
      body: `Dodani ste kao watcher na radni nalog ${workOrderNumber}`,
      data: {
        type: "work_order_status_changed",
        workOrderId: normalizeInputValue(nextWorkOrder.id),
        workOrderNumber,
        status: normalizeInputValue(nextWorkOrder.status),
      },
    });
  }

  const currentStatus = normalizeInputValue(currentWorkOrder.status);
  const nextStatus = normalizeInputValue(nextWorkOrder.status);
  if (!nextStatus || normalizePushLookupKey(currentStatus) === normalizePushLookupKey(nextStatus)) {
    return;
  }

  const recipientIds = resolveWorkOrderPushUserIds(nextWorkOrder, scopedSnapshot);

  const isClosed = isMobileClosedWorkOrderStatus(nextStatus);
  queuePushToUserIds(recipientIds, {
    title: isClosed ? "Radni nalog završen" : "Promjena statusa RN-a",
    body: isClosed
      ? `Radni nalog ${workOrderNumber} je završen`
      : `Radni nalog ${workOrderNumber} promijenio je status u ${nextStatus}`,
    data: {
      type: isClosed ? "work_order_closed" : "work_order_status_changed",
      workOrderId: normalizeInputValue(nextWorkOrder.id),
      workOrderNumber,
      status: nextStatus,
    },
  });
}

async function writeMobileWorkOrders(response, user, request) {
  const { scopedSnapshot } = await getScopedState(user, request);
  const workOrders = sortMobileWorkOrdersByNumber((scopedSnapshot.workOrders ?? [])
    .map(buildMobileWorkOrderItem)
    .filter((item) => item.id));

  sendJson(response, 200, {
    ok: true,
    user,
    workOrders,
    total: workOrders.length,
  });
}

const MOBILE_BOOTSTRAP_RECORD_LIMIT = 350;
const MOBILE_CALENDAR_EVENT_LIMIT = 2500;
const MOBILE_BOOTSTRAP_DOCUMENT_LIMIT = 5000;

function firstMobileRecordValue(item = {}, keys = []) {
  for (const key of keys) {
    const value = normalizeInputValue(item?.[key]);
    if (value) {
      return value;
    }
  }
  return "";
}

function buildMobileRecordItem(item = {}, options = {}) {
  const {
    kind = "record",
    titleKeys = ["title", "name", "fullName", "companyName", "locationName", "plateNumber", "workOrderNumber", "number"],
    subtitleKeys = ["subtitle", "companyName", "locationName", "description", "summary", "note"],
    statusKeys = ["status", "activityStatus", "employmentStatus"],
    dateKeys = ["dueDate", "expirationDate", "validUntil", "reviewDate", "serviceDueDate", "registrationExpiresOn", "updatedAt", "createdAt"],
    relatedIdKeys = ["relatedId", "workOrderId", "companyId", "locationId", "vehicleId"],
    coordinateKeys = ["coordinates"],
    metaKeys = [],
    fallbackTitle = "Zapis",
  } = options;

  const meta = {};
  metaKeys.forEach((key) => {
    const value = normalizeInputValue(item?.[key]);
    if (value) {
      meta[key] = value;
    }
  });

  return {
    id: firstMobileRecordValue(item, ["id", ...relatedIdKeys]),
    title: firstMobileRecordValue(item, titleKeys) || fallbackTitle,
    subtitle: firstMobileRecordValue(item, subtitleKeys),
    status: firstMobileRecordValue(item, statusKeys),
    kind,
    date: firstMobileRecordValue(item, dateKeys),
    relatedId: firstMobileRecordValue(item, relatedIdKeys),
    coordinates: firstMobileRecordValue(item, coordinateKeys),
    meta,
  };
}

function firstMobileRecordDetailValue(details = {}, keys = []) {
  for (const key of keys) {
    const value = normalizeInputValue(details?.[key]);
    if (value) {
      return value;
    }
  }
  return "";
}

function buildMobileClientPortalRecord(item = {}) {
  const details = item?.details && typeof item.details === "object" ? item.details : {};
  const type = normalizeInputValue(item?.type);
  const record = buildMobileRecordItem(item, {
    kind: "client_portal",
    titleKeys: ["title"],
    subtitleKeys: ["companyName", "locationName", "note"],
    statusKeys: ["status"],
    dateKeys: ["dueDate", "updatedAt", "createdAt"],
    metaKeys: ["companyId", "companyName", "locationId", "locationName", "type", "dueDate"],
    fallbackTitle: "Klijentski zapis",
  });

  const detailMetaKeys = [
    "fullName",
    "riskWorkplaceKey",
    "jobTitle",
    "jobDescription",
    "email",
    "phone",
    "oib",
    "medicalReferralNumber",
    "medicalReferralValidUntil",
    "medicalCertificateNumber",
    "medicalCertificateValidUntil",
    "visionReferralNumber",
    "visionReferralValidUntil",
    "visionCertificateNumber",
    "visionCertificateValidUntil",
    "psychologicalCheckUntil",
    "medicalWorkplace",
    "medicalLoadWeights",
    "medicalWorkOrganization",
    "medicalBodyPositions",
    "medicalWorkConditions",
    "medicalEquipment",
    "medicalSubstances",
    "code",
    "locationText",
    "extinguisherType",
    "lastInspectionDate",
    "nextInspectionDate",
    "lastInternalInspectionDate",
    "nextInternalInspectionDate",
    "lastServiceDate",
    "nextServiceDate",
    "vehicleName",
    "plateNumber",
    "vehicleType",
    "responsibleWorkerRecordId",
    "responsibleWorkerName",
    "registrationDate",
    "insuranceDate",
    "serviceDate",
    "workerRecordId",
    "workerName",
    "ppeName",
    "quantity",
    "assignedDate",
    "dueDate",
    "returnedDate",
    "defectTitle",
    "priority",
    "category",
    "reportedDate",
    "reportedBy",
    "description",
    "action",
    "inspectionTitle",
    "area",
    "inspectionDate",
    "inspectorName",
    "result",
    "finding",
    "correctiveAction",
    "documentName",
    "testDate",
    "measuredValue",
    "testerName",
    "nextTestDate",
    "documentType",
    "fileName",
    "fileUrl",
    "documentDate",
    "validUntil",
    "ownerName",
    "deadlineType",
    "deadlineName",
    "note",
  ];

  detailMetaKeys.forEach((key) => {
    const value = normalizeInputValue(details?.[key]);
    if (value) {
      record.meta[key] = value;
    }
  });

  const attachments = Array.isArray(details.attachments) ? details.attachments : [];
  if (attachments.length > 0) {
    record.meta.attachmentCount = String(attachments.length);
    record.meta.attachmentNames = attachments
      .map((attachment, index) => firstMobileRecordDetailValue(attachment, ["fileName", "name", "title"]) || `Prilog ${index + 1}`)
      .filter(Boolean)
      .slice(0, 6)
      .join(", ");
  }

  if (type === "fire_extinguisher") {
    record.title = firstMobileRecordDetailValue(details, ["code", "extinguisherType"]) || record.title;
    record.subtitle = [
      firstMobileRecordDetailValue(details, ["locationText"]),
      firstMobileRecordDetailValue(details, ["extinguisherType"]),
    ].filter(Boolean).join(" · ") || record.subtitle;
  } else if (type === "vehicle") {
    record.title = [
      firstMobileRecordDetailValue(details, ["plateNumber"]),
      firstMobileRecordDetailValue(details, ["vehicleName"]),
    ].filter(Boolean).join(" · ") || record.title;
    record.subtitle = [
      firstMobileRecordDetailValue(details, ["vehicleType"]),
      firstMobileRecordDetailValue(details, ["responsibleWorkerName"]),
    ].filter(Boolean).join(" · ") || record.subtitle;
  }

  return record;
}

function limitMobileRecords(records = [], limit = MOBILE_BOOTSTRAP_RECORD_LIMIT) {
  return records
    .filter((item) => item && (item.id || item.title))
    .slice(0, limit);
}

function normalizeMobilePageNumber(value, fallback, min, max) {
  const parsed = Number.parseInt(String(value ?? ""), 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(min, Math.min(max, parsed));
}

function mobileRecordMatchesDirectoryQuery(record = {}, query = "") {
  const normalizedQuery = normalizeInputValue(query).toLowerCase();
  if (!normalizedQuery) return true;
  const values = [
    record.id,
    record.title,
    record.subtitle,
    record.status,
    record.kind,
    record.date,
    record.relatedId,
    record.coordinates,
    ...Object.values(record.meta || {}),
  ];
  return values.some((value) => normalizeInputValue(value).toLowerCase().includes(normalizedQuery));
}

function paginateMobileRecords(records = [], searchParams = new URLSearchParams()) {
  const offset = normalizeMobilePageNumber(searchParams.get("offset"), 0, 0, 1_000_000);
  const limit = normalizeMobilePageNumber(searchParams.get("limit"), 60, 20, 160);
  const total = records.length;
  const page = records.slice(offset, offset + limit);
  const nextOffset = offset + page.length;
  return {
    records: page,
    total,
    offset,
    nextOffset,
    hasMore: nextOffset < total,
  };
}

function buildMobileCompanyDirectoryRecord(company = {}, locations = []) {
  const record = buildMobileRecordItem(company, {
    kind: "company",
    titleKeys: ["name"],
    subtitleKeys: ["headquarters", "oib", "contactEmail", "contactPhone"],
    statusKeys: ["isActive"],
    dateKeys: ["updatedAt", "createdAt"],
    metaKeys: ["oib", "headquarters", "contactPhone", "contactEmail"],
    fallbackTitle: "Tvrtka",
  });
  const companyId = normalizeInputValue(company.id);
  const locationCount = (locations ?? []).filter((location) => normalizeInputValue(location.companyId) === companyId).length;
  return {
    ...record,
    meta: {
      ...record.meta,
      locationCount: String(locationCount),
    },
  };
}

function buildMobileLocationDirectoryRecord(location = {}) {
  return buildMobileRecordItem(location, {
    kind: "location",
    titleKeys: ["name", "locationName"],
    subtitleKeys: ["companyName", "region", "contactName1", "contactPhone1"],
    statusKeys: ["isActive"],
    dateKeys: ["updatedAt", "createdAt"],
    metaKeys: ["companyName", "companyId", "region", "contactName1", "contactPhone1", "contactEmail1"],
    fallbackTitle: "Lokacija",
  });
}

function buildMobileMeasurementEquipmentRecord(item = {}) {
  const isznrInstrumentId = getMeasurementEquipmentIsznrInstrumentId(item);
  const title = normalizeInputValue(item.name) || "Mjerna oprema";
  const subtitle = [
    normalizeInputValue(item.manufacturer),
    normalizeInputValue(item.deviceType),
    normalizeInputValue(item.serialNumber) ? `Ser. ${normalizeInputValue(item.serialNumber)}` : "",
    normalizeInputValue(item.inventoryNumber) ? `Inv. ${normalizeInputValue(item.inventoryNumber)}` : "",
  ].filter(Boolean).join(" - ");
  const validUntil = normalizeInputValue(item.validUntil);
  const calibrationDate = normalizeInputValue(item.calibrationDate);

  return {
    id: normalizeInputValue(item.id),
    title,
    subtitle,
    status: isznrInstrumentId ? "ISZNR" : (item.requiresCalibration ? "Umjerava se" : "Lokalno"),
    kind: "measurement_equipment",
    date: validUntil || calibrationDate || normalizeInputValue(item.updatedAt),
    relatedId: normalizeInputValue(item.id),
    coordinates: "",
    meta: {
      equipmentKind: normalizeInputValue(item.equipmentKind),
      manufacturer: normalizeInputValue(item.manufacturer),
      deviceType: normalizeInputValue(item.deviceType),
      deviceCode: normalizeInputValue(item.deviceCode),
      serialNumber: normalizeInputValue(item.serialNumber),
      inventoryNumber: normalizeInputValue(item.inventoryNumber),
      calibrationDate,
      validUntil,
      requiresCalibration: item.requiresCalibration ? "true" : "false",
      isznrInstrumentId,
      isznrSyncedAt: normalizeInputValue(item.isznrSyncedAt),
      isznrLinked: isznrInstrumentId ? "true" : "false",
    },
  };
}

function buildMobileIsznrInstrumentRecord(item = {}) {
  const instrument = normalizeIsznrInstrumentRecord(item);
  const isznrInstrumentId = normalizeInputValue(instrument.isznrId || instrument.id);
  const serialNumber = normalizeInputValue(instrument.serialNumber);
  const validUntil = normalizeInputValue(instrument.measurementDateTo).slice(0, 10);
  const calibrationDate = normalizeInputValue(instrument.measurementDateFrom).slice(0, 10);
  const removed = normalizeInputValue(instrument.removed).slice(0, 10);
  const title = normalizeInputValue(instrument.name) || (isznrInstrumentId ? `IS ZNR oprema ${isznrInstrumentId}` : "IS ZNR mjerna oprema");
  const subtitle = [
    serialNumber ? `Ser. ${serialNumber}` : "",
    validUntil ? `Vrijedi do ${validUntil}` : "",
    removed ? `Rashodovano ${removed}` : "",
  ].filter(Boolean).join(" - ");

  return {
    id: `isznr-instrument:${isznrInstrumentId || serialNumber || title}`,
    title,
    subtitle,
    status: removed ? "Rashodovano" : "IS ZNR",
    kind: "isznr_measurement_equipment",
    date: validUntil || calibrationDate || removed,
    relatedId: isznrInstrumentId,
    coordinates: "",
    meta: {
      isznrInstrumentId,
      serialNumber,
      calibrationDate,
      validUntil,
      removed,
      isznrLinked: "true",
      isznrSource: "live",
    },
  };
}

function isMobileTrainingBooleanTrue(value) {
  return value === true || ["true", "1", "yes", "da"].includes(normalizeInputValue(value).toLowerCase());
}

function getMobilePeopleTrainingItemDate(item = {}) {
  if (!item || typeof item !== "object") {
    return "";
  }
  return firstMobileRecordValue(item, ["validUntil", "certificateValidUntil", "passedOn", "issuedOn", "date", "trainingDate", "createdAt"]);
}

function getMobilePeopleTrainingItemStatus(item = {}) {
  if (!item || typeof item !== "object") {
    return "Nedostaje";
  }
  const rawStatus = normalizeInputValue(item.status || item.certificateStatus);
  if (rawStatus) {
    return rawStatus;
  }
  if (isMobileTrainingBooleanTrue(item.validForever)) {
    return "Trajno";
  }

  const validUntil = normalizeInputValue(item.validUntil || item.certificateValidUntil).slice(0, 10);
  if (validUntil) {
    const today = new Date().toISOString().slice(0, 10);
    const days = Math.ceil((Date.parse(validUntil) - Date.parse(today)) / (24 * 60 * 60 * 1000));
    if (Number.isFinite(days) && days < 0) {
      return "Isteklo";
    }
    if (Number.isFinite(days) && days <= 45) {
      return "Uskoro";
    }
    return "Vrijedi";
  }

  return normalizeInputValue(item.passedOn || item.issuedOn) ? "Vrijedi" : "Nedostaje";
}

function isMobilePeopleTrainingDoneStatus(status = "") {
  const statusKey = normalizeLookupKey(status);
  if (!statusKey) {
    return false;
  }
  if (
    statusKey.includes("missing")
    || statusKey.includes("nedost")
    || statusKey.includes("pending")
    || statusKey.includes("plan")
    || statusKey.includes("required")
    || statusKey.includes("potreb")
    || statusKey.includes("ceka")
    || statusKey.includes("nije")
    || statusKey.includes("invalid")
    || statusKey.includes("nevrijed")
  ) {
    return false;
  }
  return (
    statusKey.includes("valid")
    || statusKey.includes("vrijed")
    || statusKey.includes("expired")
    || statusKey.includes("istek")
    || statusKey.includes("expiring")
    || statusKey.includes("uskoro")
    || statusKey.includes("permanent")
    || statusKey.includes("trajno")
    || statusKey.includes("completed")
    || statusKey.includes("done")
    || statusKey.includes("poloz")
    || statusKey.includes("proved")
    || statusKey.includes("zavrs")
  );
}

function hasMobilePeopleTrainingEvidence(item = {}) {
  if (!item || typeof item !== "object") {
    return false;
  }
  const statusKey = normalizeLookupKey(item.status);
  if (
    statusKey.includes("missing")
    || statusKey.includes("nedost")
    || statusKey.includes("pending")
    || statusKey.includes("plan")
    || statusKey.includes("required")
    || statusKey.includes("potreb")
    || statusKey.includes("ceka")
    || statusKey.includes("nije")
    || statusKey.includes("invalid")
    || statusKey.includes("nevrijed")
  ) {
    return false;
  }
  return Boolean(
    item.passedOn
    || item.validUntil
    || item.validForever
    || item.certificateNumber
    || item.documentId
    || item.documentName
    || isMobilePeopleTrainingDoneStatus(item.status),
  );
}

function getPeopleTrainingAttachmentDocumentId(document = {}) {
  if (!document || typeof document !== "object") {
    return "";
  }
  return normalizeInputValue(document.id || document.documentId || document.sourceDocumentId);
}

function getPeopleTrainingAttachmentDocumentName(document = {}) {
  if (!document || typeof document !== "object") {
    return "";
  }
  return normalizeInputValue(document.fileName || document.name || document.title) || "Dokument";
}

function buildMobilePeopleTrainingDocument(document = {}) {
  if (!document || typeof document !== "object") {
    return null;
  }
  const id = getPeopleTrainingAttachmentDocumentId(document);
  const category = normalizeInputValue(document.documentCategory || document.category);
  return {
    id,
    fileName: getPeopleTrainingAttachmentDocumentName(document),
    fileType: normalizeInputValue(document.fileType || document.mimeType) || "application/octet-stream",
    fileSize: Number(document.fileSize || document.size || 0) || 0,
    documentCategory: category,
    description: normalizeInputValue(document.description),
    createdAt: normalizeInputValue(document.createdAt || document.updatedAt),
    isCertificate: String(category).toLowerCase().includes("certificate")
      || String(category).toLowerCase().includes("uvjeren")
      || String(document.sourceType || "").toLowerCase().includes("certificate"),
  };
}

function findPeopleTrainingAttachmentDocumentById(record = {}, documentId = "") {
  const normalizedDocumentId = normalizeInputValue(documentId);
  if (!normalizedDocumentId) {
    return null;
  }
  return (Array.isArray(record.attachments) ? record.attachments : []).find((document) => (
    document && typeof document === "object" && (
      getPeopleTrainingAttachmentDocumentId(document) === normalizedDocumentId
      || normalizeInputValue(document.sourceDocumentId) === normalizedDocumentId
    )
  )) || null;
}

function getMobilePeopleTrainingDocumentForItem(record = {}, item = {}, scopedSnapshot = {}) {
  if (!item || typeof item !== "object") {
    return null;
  }
  const certificateDocumentId = normalizeInputValue(item.certificateDocumentId || item.documentId);
  if (certificateDocumentId) {
    const matched = findPeopleTrainingAttachmentDocumentById(record, certificateDocumentId);
    if (matched) {
      return matched;
    }
  }

  const service = findPeopleTrainingServiceForItem(item, scopedSnapshot) ?? {};
  const activeGenerated = getActivePeopleTrainingGeneratedDocument(record, item, service);
  if (activeGenerated) {
    return activeGenerated;
  }

  const typeKey = normalizeLookupKey(item.type || item.trainingType || item.label || item.serviceName);
  const serviceId = normalizeInputValue(item.serviceId || item.serviceCatalogId);
  return (Array.isArray(record.attachments) ? record.attachments : []).find((attachment) => {
    if (!attachment || typeof attachment !== "object") {
      return false;
    }
    const categoryKey = normalizeLookupKey(attachment.documentCategory || attachment.category || "");
    const descriptionKey = normalizeLookupKey(attachment.description || attachment.fileName || "");
    return (
      (typeKey && (categoryKey.includes(typeKey) || descriptionKey.includes(typeKey)))
      || (serviceId && normalizeInputValue(attachment.serviceId || attachment.serviceCatalogId) === serviceId)
    );
  }) || null;
}

function formatMobileDateLabel(value = "") {
  const normalized = normalizeDateOnlyValue(value);
  if (!normalized) {
    return "";
  }
  const [year, month, day] = normalized.split("-");
  return `${day}.${month}.${year}.`;
}

function getMobilePeopleTrainingDeadlineLabel(item = {}) {
  if (isMobileTrainingBooleanTrue(item.validForever)) {
    return "Vrijedi trajno";
  }
  const validUntil = normalizeDateOnlyValue(item.validUntil || item.certificateValidUntil);
  if (validUntil) {
    return `Rok ${formatMobileDateLabel(validUntil)}`;
  }
  const passedOn = normalizeDateOnlyValue(item.passedOn || item.issuedOn || item.date || item.trainingDate);
  return passedOn ? `Datum ${formatMobileDateLabel(passedOn)}` : "";
}

function getMobilePeopleTrainingExamModeLabel(record = {}, item = {}, service = {}) {
  const details = item.details && typeof item.details === "object" ? item.details : {};
  const raw = normalizeLookupKey(
    details.examMode
      || details.trainingMode
      || item.examMode
      || item.trainingMode
      || item.learningMode
      || service.trainingMode
      || service.examMode,
  );
  if (!raw) {
    return "";
  }
  if (raw.includes("online") || raw.includes("remote") || raw.includes("elearning") || raw.includes("eucenje")) {
    return "Online";
  }
  if (raw.includes("uzivo") || raw.includes("teren") || raw.includes("live") || raw.includes("predav")) {
    return "Uživo";
  }
  return normalizeInputValue(details.examMode || details.trainingMode || item.examMode || item.trainingMode);
}

function getMobilePeopleTrainingDisplayLabel(item = {}, serviceName = "", serviceCode = "", index = 0) {
  const rawLabel = normalizeInputValue(item.label);
  const shortLabel = normalizeInputValue(item.shortLabel);
  const labelKey = normalizeLookupKey(rawLabel);
  const shortKey = normalizeLookupKey(shortLabel || serviceCode);
  const serviceCodeKey = normalizeLookupKey(serviceCode);
  if (rawLabel && labelKey && labelKey !== shortKey && labelKey !== serviceCodeKey && rawLabel.length > 3) {
    return rawLabel;
  }
  return serviceName || rawLabel || shortLabel || serviceCode || normalizeInputValue(item.type) || `Osposobljavanje ${index + 1}`;
}

function getMobileRiskAssessmentLocations(assessment = {}) {
  return Array.from(new Set([
    assessment.locationId,
    ...(Array.isArray(assessment.selectedLocationIds) ? assessment.selectedLocationIds : []),
    ...(Array.isArray(assessment.employerData?.selectedLocationIds) ? assessment.employerData.selectedLocationIds : []),
  ].map((value) => normalizeInputValue(value)).filter(Boolean)));
}

function findMobilePeopleTrainingRiskAssessment(record = {}, scopedSnapshot = {}) {
  const companyId = normalizeInputValue(record.companyId);
  if (!companyId) {
    return null;
  }
  const locationId = normalizeInputValue(record.locationId);
  const workKey = normalizeLookupKey(record.jobTitle || record.workPlace);
  const candidates = (Array.isArray(scopedSnapshot.riskAssessments) ? scopedSnapshot.riskAssessments : [])
    .filter((assessment) => normalizeInputValue(assessment?.companyId) === companyId)
    .map((assessment) => {
      const locationIds = getMobileRiskAssessmentLocations(assessment);
      const locationScore = !locationId
        ? 1
        : (locationIds.includes(locationId) ? 4 : (locationIds.length === 0 ? 2 : 0));
      const jobs = Array.isArray(assessment?.jobs) ? assessment.jobs : [];
      const jobScore = workKey && jobs.some((job) => normalizeLookupKey([
        job?.title,
        job?.jobTitle,
        job?.name,
        job?.description,
      ].filter(Boolean).join(" ")).includes(workKey)) ? 3 : 0;
      const statusKey = normalizeLookupKey(assessment?.status);
      const statusScore = statusKey.includes("odob") || statusKey.includes("aktiv") || statusKey.includes("gotov") ? 2 : 0;
      const dateScore = Date.parse(assessment?.assessmentDate || assessment?.updatedAt || assessment?.createdAt || "") || 0;
      return {
        assessment,
        score: locationScore + jobScore + statusScore,
        dateScore,
      };
    })
    .filter((entry) => entry.score > 0)
    .sort((left, right) => (right.score - left.score) || (right.dateScore - left.dateScore));
  return candidates[0]?.assessment ?? null;
}

function buildMobilePeopleTrainingItem(record = {}, item = {}, index = 0, scopedSnapshot = {}) {
  if (!item || typeof item !== "object") {
    item = {};
  }
  const service = findPeopleTrainingServiceForItem(item, scopedSnapshot) ?? {};
  const document = getMobilePeopleTrainingDocumentForItem(record, item, scopedSnapshot);
  const validUntil = normalizeDateOnlyValue(item.validUntil || item.certificateValidUntil);
  const passedOn = normalizeDateOnlyValue(item.passedOn || item.issuedOn || item.date || item.trainingDate);
  const status = getMobilePeopleTrainingItemStatus(item);
  const serviceName = normalizeInputValue(item.serviceName || service.name);
  const serviceCode = normalizeInputValue(item.serviceCode || service.serviceCode || item.code || item.shortLabel);
  const label = getMobilePeopleTrainingDisplayLabel(item, serviceName, serviceCode, index);
  return {
    id: normalizeInputValue(item.id || item.type || item.serviceId || `training-${index + 1}`),
    type: normalizeInputValue(item.type || item.trainingType),
    label,
    shortLabel: normalizeInputValue(item.shortLabel || serviceCode),
    serviceId: normalizeInputValue(item.serviceId || item.serviceCatalogId),
    serviceName,
    serviceCode,
    status,
    passedOn,
    validUntil,
    validForever: isMobileTrainingBooleanTrue(item.validForever),
    deadlineLabel: getMobilePeopleTrainingDeadlineLabel(item),
    examModeLabel: getMobilePeopleTrainingExamModeLabel(record, item, service),
    certificateNumber: normalizeInputValue(item.certificateNumber || item.recordNumber),
    provider: normalizeInputValue(item.provider || item.examMode || item.learningTestTitle),
    workOrderNumber: normalizeInputValue(item.workOrderNumber),
    documentId: getPeopleTrainingAttachmentDocumentId(document),
    documentName: document ? getPeopleTrainingAttachmentDocumentName(document) : "",
    documentFileType: normalizeInputValue(document?.fileType || document?.mimeType) || "application/octet-stream",
    documentCategory: normalizeInputValue(document?.documentCategory || document?.category),
  };
}

function getMobilePeopleTrainingRecordStatus(items = [], record = {}) {
  if (items.some((item) => normalizeLookupKey(item.status).includes("istek"))) {
    return "Isteklo";
  }
  if (items.some((item) => normalizeLookupKey(item.status).includes("uskoro"))) {
    return "Uskoro";
  }
  if (items.some((item) => normalizeLookupKey(item.status).includes("nedost"))) {
    return "Nedostaje";
  }
  return normalizeInputValue(record.activityStatus || record.employmentStatus) || (items.length ? "Aktivno" : "Evidencija");
}

function buildMobilePeopleTrainingRecord(record = {}, scopedSnapshot = {}) {
  if (!record || typeof record !== "object") {
    record = {};
  }
  const trainingItems = (Array.isArray(record.trainingItems) ? record.trainingItems : [])
    .map((item, index) => buildMobilePeopleTrainingItem(record, item, index, scopedSnapshot))
    .filter(hasMobilePeopleTrainingEvidence);
  const documents = (Array.isArray(record.attachments) ? record.attachments : [])
    .filter((document) => document && typeof document === "object")
    .map(buildMobilePeopleTrainingDocument)
    .filter((document) => document && (document.id || document.fileName))
    .slice(0, 30);
  const expiredCount = trainingItems.filter((item) => normalizeLookupKey(item.status).includes("istek")).length;
  const expiringCount = trainingItems.filter((item) => normalizeLookupKey(item.status).includes("uskoro")).length;
  const missingCount = trainingItems.filter((item) => normalizeLookupKey(item.status).includes("nedost")).length;
  const validCount = Math.max(0, trainingItems.length - expiredCount - expiringCount - missingCount);
  const nextDate = trainingItems
    .map((item) => item.validUntil || item.passedOn)
    .filter(Boolean)
    .sort()[0] || normalizeInputValue(record.arrivalDate || record.updatedAt || record.createdAt);
  const nextDeadline = trainingItems
    .map((item) => item.validUntil)
    .filter(Boolean)
    .sort()[0] || "";
  const title = normalizeInputValue(record.fullName || [record.firstName, record.lastName].filter(Boolean).join(" ")) || "Osoba";
  const subtitle = [
    normalizeInputValue(record.companyName),
    normalizeInputValue(record.jobTitle || record.workPlace),
    normalizeInputValue(record.locationName),
  ].filter(Boolean).join(" - ");

  return {
    id: normalizeInputValue(record.id),
    title,
    subtitle,
    status: getMobilePeopleTrainingRecordStatus(trainingItems, record),
    kind: "training",
    date: nextDate,
    relatedId: normalizeInputValue(record.id),
    coordinates: "",
    meta: {
      companyName: normalizeInputValue(record.companyName),
      locationName: normalizeInputValue(record.locationName),
      jobTitle: normalizeInputValue(record.jobTitle),
      workPlace: normalizeInputValue(record.workPlace),
      oib: normalizeInputValue(record.oib),
      email: normalizeInputValue(record.email),
      phone: normalizeInputValue(record.phone),
      nextDeadline,
      nextDeadlineLabel: nextDeadline ? `Rok ${formatMobileDateLabel(nextDeadline)}` : "",
      validCount: String(validCount),
      expiringCount: String(expiringCount),
      expiredCount: String(expiredCount),
      missingCount: String(missingCount),
      trainingCount: String(trainingItems.length),
      documentCount: String(documents.length),
      trainingItemsJson: JSON.stringify(trainingItems.slice(0, 24)),
      documentsJson: JSON.stringify(documents),
    },
  };
}

function normalizeIsznrPersonRecord(source = {}, resource = {}) {
  if (!source || typeof source !== "object") {
    return null;
  }
  const attributes = source.attributes && typeof source.attributes === "object" ? source.attributes : {};
  const record = { ...attributes, ...source };
  const id = extractIsznrId(record);
  const firstName = normalizeInputValue(pickIsznrValue(record, ["firstName", "givenName", "ime"]));
  const lastName = normalizeInputValue(pickIsznrValue(record, ["lastName", "familyName", "prezime"]));
  const fullName = normalizeInputValue(pickIsznrValue(record, ["name", "fullName", "displayName", "title", "naziv"]))
    || [firstName, lastName].filter(Boolean).join(" ");
  return {
    id,
    isznrId: id,
    role: resource.role,
    roleLabel: resource.label,
    oib: normalizeIsznrOib(pickIsznrValue(record, [
      "oib",
      "OIB",
      "personOib",
      "employeeOib",
      "personalIdentifier",
      "personalIdentificationNumber",
    ])),
    fullName,
    firstName,
    lastName,
    employerName: normalizeInputValue(pickIsznrValue(record, ["employerName", "companyName", "authorizedCompanyName", "company"])),
    rawStatus: normalizeInputValue(pickIsznrValue(record, ["status", "state"])),
  };
}

async function fetchIsznrPeopleMatchesByOib({
  baseUrl = "",
  username = "",
  password = "",
  oib = "",
} = {}) {
  const normalizedOib = normalizeIsznrOib(oib);
  if (!/^\d{11}$/.test(normalizedOib)) {
    return { oib: normalizedOib, matches: [], probes: [] };
  }

  const probes = await mapIsznrWithConcurrency(ISZNR_EMPLOYEE_RESOURCE_DEFS, 3, async (resource) => {
    const probe = await fetchIsznrResourceProbe({
      baseUrl,
      username,
      password,
      resourcePath: resource.path,
      searchParams: {
        oib: normalizedOib,
        pagination: false,
      },
      timeoutMs: ISZNR_PERSON_FETCH_TIMEOUT_MS,
      parseJson: true,
    });
    return { ...probe, resource };
  });

  if (probes.some((probe) => isIsznrAuthFailure(probe))) {
    const error = createRequestError(400, "ISZNR autentikacija nije uspjela. Provjeri OIB korisnika i lozinku.");
    error.isznrAuthFailure = true;
    throw error;
  }

  const matches = probes.flatMap((probe) => {
    if (!probe.ok) {
      return [];
    }
    const array = getIsznrPayloadArray(probe.payload);
    const rawItems = array.length > 0 ? array : (probe.payload && typeof probe.payload === "object" ? [probe.payload] : []);
    return rawItems
      .map((item) => normalizeIsznrPersonRecord(item, probe.resource))
      .filter((item) => item?.oib === normalizedOib);
  });

  const dedupedMatches = [];
  const seen = new Set();
  matches.forEach((match) => {
    const key = [match.role, match.isznrId, match.oib, normalizeLookupKey(match.fullName)].join("|");
    if (!seen.has(key)) {
      seen.add(key);
      dedupedMatches.push(match);
    }
  });

  return {
    oib: normalizedOib,
    matches: dedupedMatches,
    probes: probes.map((probe) => ({
      path: probe.path,
      status: probe.status,
      ok: Boolean(probe.ok),
      role: probe.resource.role,
      label: probe.resource.label,
      message: probe.ok ? "Dostupno" : getIsznrResourceProbeMessage(probe),
    })),
  };
}

function getIsznrUserCandidateOib(user = {}) {
  const qualification = user?.electricalQualification && typeof user.electricalQualification === "object"
    ? user.electricalQualification
    : {};
  return normalizeIsznrOib(
    user?.oib
    || user?.oibNumber
    || user?.taxId
    || user?.personalOib
    || user?.personalIdentificationNumber
    || user?.identificationNumber
    || user?.nationalId
    || qualification.oib,
  );
}

function buildIsznrPeopleCandidatesFromUsers(users = []) {
  const candidates = [];
  const seenOibs = new Set();
  (Array.isArray(users) ? users : []).forEach((user) => {
    if (!user || typeof user !== "object") {
      return;
    }
    const oib = getIsznrUserCandidateOib(user);
    if (!/^\d{11}$/.test(oib) || seenOibs.has(oib)) {
      return;
    }
    seenOibs.add(oib);
    candidates.push({
      id: normalizeInputValue(user.id),
      sourceType: "user",
      title: getMobileUserDocumentName(user) || "Osoba",
      subtitle: [
        normalizeInputValue(user.email),
        normalizeInputValue(user.profileRole || user.role),
        user.isActive === false ? "Neaktivan" : "Aktivan",
      ].filter(Boolean).join(" - "),
      email: normalizeInputValue(user.email),
      status: user.isActive === false ? "Neaktivan" : "Aktivan",
      oib,
    });
  });
  return candidates;
}

function normalizeIsznrPeopleTag(value = "") {
  const normalized = normalizeLookupKey(value)
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return normalized ? `IsZNR_${normalized}` : "";
}

function buildIsznrPeopleTags(matches = []) {
  const tags = new Set();
  (Array.isArray(matches) ? matches : []).forEach((match) => {
    const role = normalizeInputValue(match?.role);
    const roleTag = ISZNR_PEOPLE_ROLE_TAGS[role] || normalizeIsznrPeopleTag(role || match?.roleLabel);
    if (roleTag) {
      tags.add(roleTag);
    }
  });
  return [...tags];
}

function buildIsznrPeopleSyncPayload(entry = {}) {
  const matches = Array.isArray(entry.matches) ? entry.matches : [];
  const tags = buildIsznrPeopleTags(matches);
  return {
    isznrTags: tags,
    isznrSync: {
      linked: tags.length > 0,
      checkedAt: entry.checkedAt || new Date().toISOString(),
      roles: tags,
      roleLabels: [...new Set(matches.map((match) => normalizeInputValue(match.roleLabel)).filter(Boolean))],
      ids: matches.map((match) => [match.roleLabel, match.isznrId].filter(Boolean).join(" ")).filter(Boolean),
      error: normalizeInputValue(entry.error),
    },
  };
}

async function fetchMobileIsznrPeopleList({
  baseUrl = "",
  username = "",
  password = "",
  users = [],
  maxRecords = ISZNR_MOBILE_PEOPLE_MAX_RECORDS,
} = {}) {
  const normalizedBaseUrl = normalizeIsznrApiBaseUrl(baseUrl);
  const normalizedUsername = normalizeIsznrApiUsername(username);
  const safePassword = String(password ?? "");

  if (!/^\d{11}$/.test(normalizedUsername)) {
    throw createRequestError(400, "OIB korisnika za ISZNR mora imati 11 znamenki.");
  }
  if (!safePassword) {
    throw createRequestError(400, "ISZNR lozinka nije spremljena. Spremi ju u Settings prije dohvata zaposlenika.");
  }

  const candidates = buildIsznrPeopleCandidatesFromUsers(users);

  const limitedCandidates = candidates.slice(0, Math.max(1, Number(maxRecords) || ISZNR_MOBILE_PEOPLE_MAX_RECORDS));
  const checked = await mapIsznrWithConcurrency(limitedCandidates, 3, async (person) => {
    try {
      const result = await fetchIsznrPeopleMatchesByOib({
        baseUrl: normalizedBaseUrl,
        username: normalizedUsername,
        password: safePassword,
        oib: person.oib,
      });
      const item = { ...person, ...result, error: "", checkedAt: new Date().toISOString() };
      return { ...item, ...buildIsznrPeopleSyncPayload(item) };
    } catch (error) {
      if (error?.isznrAuthFailure) {
        throw error;
      }
      const item = {
        ...person,
        matches: [],
        probes: [],
        checkedAt: new Date().toISOString(),
        error: error?.message || "ISZNR provjera nije uspjela.",
      };
      return { ...item, ...buildIsznrPeopleSyncPayload(item) };
    }
  });

  return {
    ok: true,
    count: checked.length,
    totalPeopleWithOib: candidates.length,
    recordsLimited: candidates.length > limitedCandidates.length,
    checkedAt: new Date().toISOString(),
    items: checked,
  };
}

function buildMobileIsznrPersonRecord(entry = {}) {
  const matches = Array.isArray(entry.matches) ? entry.matches : [];
  const roleLabels = [...new Set(matches.map((match) => normalizeInputValue(match.roleLabel)).filter(Boolean))];
  const linked = matches.length > 0;
  const ids = matches.map((match) => [match.roleLabel, match.isznrId].filter(Boolean).join(" ")).filter(Boolean);
  const tags = Array.isArray(entry.isznrTags) ? entry.isznrTags : buildIsznrPeopleTags(matches);
  return {
    id: `isznr-person:${entry.oib || entry.id || entry.title}`,
    title: entry.title || "Osoba",
    subtitle: entry.subtitle || (entry.oib ? `OIB ${entry.oib}` : ""),
    status: linked ? roleLabels.join(" + ") : (entry.error ? "Greška" : "Nije u IS ZNR"),
    kind: "isznr_person",
    date: entry.checkedAt || "",
    relatedId: entry.id || "",
    coordinates: "",
    meta: {
      oib: normalizeInputValue(entry.oib),
      email: normalizeInputValue(entry.email),
      sourceType: normalizeInputValue(entry.sourceType || "user"),
      localStatus: normalizeInputValue(entry.status),
      isznrLinked: linked ? "true" : "false",
      isznrRoles: roleLabels.join(", "),
      isznrIds: ids.join(", "),
      isznrTags: tags.join(", "),
      isznrTagsJson: JSON.stringify(tags),
      isznrError: normalizeInputValue(entry.error),
      isznrProbeCount: String(Array.isArray(entry.probes) ? entry.probes.length : 0),
    },
  };
}

async function syncIsznrPeopleTagsToUsers(actor = {}, scopedSnapshot = {}, items = []) {
  const scopedActor = {
    ...actor,
    appPermissions: {
      ...(scopedSnapshot.appPermissions ?? {}),
    },
  };
  const usersById = new Map((scopedSnapshot.users ?? []).map((user) => [String(user.id), user]));
  const updatedUsers = [];

  for (const item of Array.isArray(items) ? items : []) {
    const userId = normalizeInputValue(item.id);
    const currentUser = usersById.get(userId);
    if (!currentUser || item.sourceType !== "user") {
      continue;
    }

    const currentTags = Array.isArray(currentUser.isznrTags) ? currentUser.isznrTags : [];
    const currentSync = currentUser.isznrSync && typeof currentUser.isznrSync === "object" ? currentUser.isznrSync : {};
    let syncPayload = buildIsznrPeopleSyncPayload(item);
    if (normalizeInputValue(item.error) && syncPayload.isznrTags.length === 0) {
      syncPayload = {
        isznrTags: currentTags,
        isznrSync: {
          ...syncPayload.isznrSync,
          linked: currentTags.length > 0,
          roles: currentTags,
        },
      };
    }
    const nextTagsSignature = JSON.stringify(syncPayload.isznrTags);
    const currentTagsSignature = JSON.stringify(currentTags);
    const nextSyncSignature = JSON.stringify(syncPayload.isznrSync);
    const currentSyncComparable = {
      linked: Boolean(currentSync.linked),
      checkedAt: currentSync.checkedAt || "",
      roles: Array.isArray(currentSync.roles) ? currentSync.roles : [],
      roleLabels: Array.isArray(currentSync.roleLabels) ? currentSync.roleLabels : [],
      ids: Array.isArray(currentSync.ids) ? currentSync.ids : [],
      error: normalizeInputValue(currentSync.error),
    };

    if (
      nextTagsSignature === currentTagsSignature
      && nextSyncSignature === JSON.stringify(currentSyncComparable)
    ) {
      continue;
    }

    try {
      const updated = typeof tenantRepository.updateUserIsznrSync === "function"
        ? await tenantRepository.updateUserIsznrSync(scopedActor, userId, syncPayload)
        : await tenantRepository.updateUser(scopedActor, userId, syncPayload);
      if (updated) {
        updatedUsers.push(updated);
      }
    } catch (error) {
      item.error = item.error || error?.message || "IS ZNR oznake nisu spremljene na People korisnika.";
    }
  }

  return updatedUsers;
}

function isMobileClosedWorkOrderStatus(status = "") {
  const normalized = normalizeInputValue(status)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  return normalized === "gotov rn"
    || normalized === "ovjeren rn"
    || normalized === "fakturiran rn"
    || normalized === "storno rn"
    || normalized === "storniran rn"
    || normalized === "zavrsen rn";
}

function buildMobileJobRecord(item = {}) {
  const title = normalizeInputValue(item.title) || "Posao";
  const description = normalizeInputValue(item.description);
  const status = normalizeInputValue(item.status) || "draft";
  const hazards = Array.isArray(item.hazards) ? item.hazards : [];
  const ppeItems = Array.isArray(item.ppeItems) ? item.ppeItems : [];
  const environment = item.environment && typeof item.environment === "object" ? item.environment : {};
  const conditions = item.conditions && typeof item.conditions === "object" ? item.conditions : {};
  const enabledEnvironmentCount = Object.keys(environment).filter((key) => key.endsWith("Enabled") && environment[key]).length;
  const activeConditionCount = Object.entries(conditions).filter(([, value]) => value === true).length;

  return {
    id: normalizeInputValue(item.id),
    title,
    subtitle: description || [
      hazards.length ? `${hazards.length} opasnosti` : "",
      ppeItems.length ? `${ppeItems.length} OZO` : "",
      enabledEnvironmentCount ? `${enabledEnvironmentCount} okruženje` : "",
    ].filter(Boolean).join(" - "),
    status,
    kind: "job",
    date: firstMobileRecordValue(item, ["reviewDate", "updatedAt", "createdAt"]),
    relatedId: normalizeInputValue(item.id),
    coordinates: "",
    meta: {
      description,
      hazardsCount: String(hazards.length),
      ppeCount: String(ppeItems.length),
      environmentCount: String(enabledEnvironmentCount),
      conditionCount: String(activeConditionCount),
    },
  };
}

function buildMobileVehicleRecord(item = {}) {
  const nowValue = new Date().toISOString();
  const availabilityStatus = getVehicleAvailabilityStatus(item, nowValue);
  const nextReservation = getVehicleNextReservation(item, nowValue);
  const openTrip = findOpenVehicleTrip(item, {}, null);
  const reservations = sortVehicleReservations(item?.reservations ?? [], nowValue)
    .filter((reservation) => {
      const endTimestamp = Date.parse(reservation?.endAt ?? "");
      return Number.isFinite(endTimestamp) && endTimestamp >= Date.now() - 24 * 60 * 60 * 1000;
    })
    .slice(0, 12)
    .map((reservation) => ({
      id: normalizeInputValue(reservation?.id),
      status: normalizeInputValue(reservation?.status || "reserved"),
      purpose: normalizeInputValue(reservation?.purpose || "Rezervacija"),
      startAt: normalizeInputValue(reservation?.startAt),
      endAt: normalizeInputValue(reservation?.endAt),
      destination: normalizeInputValue(reservation?.destination),
      reservedForLabel: normalizeInputValue(reservation?.reservedForLabel),
      reservedForLabels: Array.isArray(reservation?.reservedForLabels)
        ? reservation.reservedForLabels.map(normalizeInputValue).filter(Boolean)
        : [],
      reservedForUserId: normalizeInputValue(reservation?.reservedForUserId),
      reservedForUserIds: Array.isArray(reservation?.reservedForUserIds)
        ? reservation.reservedForUserIds.map(normalizeInputValue).filter(Boolean)
        : [],
    }));
  const mobileActivityItems = (Array.isArray(item?.activityItems) ? item.activityItems : [])
    .slice()
    .sort((left, right) => {
      const isLeftOpenTrip = isVehicleTripActivity(left)
        && normalizeInputValue(left?.tripStatus).toLowerCase() !== "completed"
        && !normalizeInputValue(left?.returnAt);
      const isRightOpenTrip = isVehicleTripActivity(right)
        && normalizeInputValue(right?.tripStatus).toLowerCase() !== "completed"
        && !normalizeInputValue(right?.returnAt);
      if (isLeftOpenTrip !== isRightOpenTrip) {
        return isLeftOpenTrip ? -1 : 1;
      }
      const leftTimestamp = Date.parse(left?.updatedAt || left?.returnAt || left?.departureAt || left?.createdAt || left?.performedOn || "") || 0;
      const rightTimestamp = Date.parse(right?.updatedAt || right?.returnAt || right?.departureAt || right?.createdAt || right?.performedOn || "") || 0;
      return rightTimestamp - leftTimestamp;
    })
    .slice(0, 30);
  const record = buildMobileRecordItem(item, {
    kind: "vehicle",
    titleKeys: ["plateNumber", "name", "vinNumber"],
    subtitleKeys: ["name", "make", "model", "category"],
    statusKeys: ["status"],
    dateKeys: ["serviceDueDate", "registrationExpiresOn", "updatedAt"],
    metaKeys: ["make", "model", "category", "odometerKm", "registrationExpiresOn", "serviceDueDate"],
    fallbackTitle: "Vozilo",
  });
  return {
    ...record,
    status: availabilityStatus,
    meta: {
      ...record.meta,
      baseStatus: normalizeInputValue(item?.status),
      availabilityStatus,
      availabilityLabel: openTrip
        ? "Aktivan put"
        : availabilityStatus === "reserved"
          ? "Rezervirano"
          : availabilityStatus === "service"
          ? "Servis"
          : "Dostupno",
      openTripId: normalizeInputValue(openTrip?.id),
      openTripDestination: normalizeInputValue(openTrip?.destination),
      openTripDrivers: Array.isArray(openTrip?.driverLabels)
        ? openTrip.driverLabels.map(normalizeInputValue).filter(Boolean).join(", ")
        : normalizeInputValue(openTrip?.performedBy),
      nextReservationId: normalizeInputValue(nextReservation?.id),
      nextReservationStatus: normalizeInputValue(nextReservation?.status),
      nextReservationPurpose: normalizeInputValue(nextReservation?.purpose),
      nextReservationStartAt: normalizeInputValue(nextReservation?.startAt),
      nextReservationEndAt: normalizeInputValue(nextReservation?.endAt),
      nextReservationUser: normalizeInputValue(nextReservation?.reservedForLabel),
      reservationsJson: JSON.stringify(reservations),
      activityItemsJson: JSON.stringify(mobileActivityItems),
    },
  };
}

